	[21204] = {
		soulid = 21204,
		valuation = "真是十分出色的实战，第一次看到可以将战斗和优雅联系起来的人，不过太注重优雅的话，反而会本末倒置，以后还请注意。",
		file_1 = "金百莉原先居住在尼格霍德，因一些原因被迫迁移到了耶梦加得；在那之后被同学恶意地带到地下擂台去赌拳，最后输掉了身上所有的钱。在危机关头，作为拳王女儿的布兰琪挺身而出，两人也以此为契机，得以认识。虽然不知道两人的关系到了什么地步，但金百莉确实有着牵制布兰琪的能力，为了不让布兰琪对任务造成不可挽回的损失，院方一般默认金百莉与布兰琪绑定在一起。当然目前院方并没有公开这一点。",
		level_3 = 0,
		level_4 = 0,
		resume = "金百莉是一位做事认真、有上进心的女孩，平时举止优雅，对己对人都较为苛刻。热爱社交，并对贵族的社交氛围表示向往，另外平时虽然自称贵族，但实际上并不是真正的贵族，又或者说只是曾经的贵族。关于这点，如果在本人面前说得太过直白的话，会让她恼怒，所以请不要做这样的事情。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "蒙蒂尼家族，尼格霍德鼎鼎有名的家族之一，历史上出现过数名军事家、科学家、历史学家等等，是相当有名的家族，现阶段因理财不善而导致破产，目前蒙蒂尼家族的大部分股份财产已被Alice财团收购，家族内大部分工作人员皆以不同的方式遭到解雇，但令人惊奇的是，作为公司CEO，金百莉的父亲，克劳德·蒙蒂尼的名誉并没有因此受损，所有员工，包括清洁工在内，所有人都认为那是最佳做法，并且有百分之六十的员工表示，如果他有东山再起的念头的话，自己依然愿意在他手下工作。",
		file_3 = "在金百莉内心深处，依然将自己当做贵族，她相信贵族并不只是身份的高低，更多应该是一种精神的延续，是蒙蒂尼家族流传至今的不变之物，为了体内流动的蒙蒂尼之魂，就算是现在，金百莉也愿意承担起贵族的责任。然而不了解她的人，对于这些行为，擅自就认为这是对过去生活安逸生活的留恋。单方面地对金百莉宣泄冷暴力，嘲讽和排挤几乎是她过去的日常；即便遭遇了不少痛苦的事情，金百莉也依然坚信着贵族的精神不会因此而改变，只是偶尔……偶尔会有些孤独。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "间谍调查结果为：蒙蒂尼家族曾和基金会有所来往，具体交易的内容暂且不明，但从记录上可以看出，蒙蒂尼家族于某年六月份和基金会断绝来往后，不到五个月，蒙蒂尼家族就宣告破产，随后被鲁比克财团收购；简单推测很有可能是基金会联合了鲁比克财团进行了商业打压，最终导致了蒙蒂尼家族的没落。考虑鲁比克财团对魂器学院的投入，暂且将此词条纳入绝密档案，仅供管理员参考。",
		level_6 = 0,
		record = "“对我来说，所谓贵族就是责任。”"
	},
