	[21104] = {
		soulid = 21104,
		valuation = "伊文捷琳的魂器适应性绝佳，但是几乎都集中在辅助方面的能力上了，她自身的战斗能力勉强能算是一般标准。",
		file_1 = "伊文捷琳母亲是隶属于教会的医护人员，如果让伊文捷琳说说自己对母亲的印象，那肯定是“天真”。 明明是成年人，但是毫不犹豫地将爱与希望挂在嘴边，受她影响，伊文捷琳也逐渐成长为温柔善良的少女。 伊文捷琳的母亲依靠先进的医疗技术救治了许多病人，在使用科技救治病人身体的同时，以信仰和温柔的言语治愈他们的心。 出于憧憬，伊文捷琳从小就立志成为母亲一般优秀的医护人员和信徒，为了达成这个目的，首要的目标是克服自身内向的性格，变成母亲那样开朗又招人喜欢的样子—— “小伊文现在这样不是挺好的嘛！”——来自当事人的母亲。",
		level_3 = 0,
		level_4 = 0,
		resume = "伊文捷琳，原籍耶梦加得。和大多数耶梦加得人一样拥有宗教信仰，跟随其作为医护人员的母亲学会了高超的医术，在“模拟智能网络”爆发时救治了诸多生命。 战后，学院对其发出了魂器适应性测试的邀请，伊文捷琳被测试出具有极其优秀的资质。对救治他人一事抱有使命感的伊文捷琳赞同学院的理念，故选择加入魂器学院医疗班，进行医疗方面的辅助工作。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "伊文捷琳的性格比较内向，平时与友人的交流更加倾向于倾听而不是对话。她几乎从不会与人辩论，但是如果有必要，她还是会平静地指出对方的问题。比起纠正现有的错误，伊文捷琳更加不想因为辩论制造出新的争端。对于是否要加入战斗，伊文捷琳也略显犹豫——不过只要看到有人受伤，她就会放下犹豫，全力投入到对他人的救治工作中去。 考虑到伊文捷琳这样的个性，院方将其安排到了医疗支援部队中，而且其产生的效果非常显著。在世界各地的救护行动中，伊文捷琳作为魂器学院派遣的医疗人员救治了无数的伤患，将学院的正面形象传播到了全世界。",
		file_3 = "“模拟智能网络”爆发后，耶梦加得同样陷入了人工智能反叛造成的混乱中，残酷的斗争迫使伊文捷琳拿起武器，加入到对抗人工智能的序列之中。 不过比起与敌人战斗，伊文捷琳更加擅长、也更加喜欢抚平他人的伤痛。 依靠过人的天赋与母亲悉心教导的医疗知识，伊文捷琳在战争期间救治了无数的伤患，甚至获得了教宗的嘉奖。 不过比起这些虚名，少女更加开心的是自己能够帮助到他人的事实，以及自己距离母亲更进一步的实感。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "实际上，一开始收到学院的入学邀请，伊文捷琳产生了犹豫。 获得了学院的支援，自己可能可以帮助到更多的人，这样的道理伊文捷琳也懂。但凭借自己的力量，仅仅是守护身边的人就已经是极限——伊文捷琳偶尔会冒出这样的想法。 “在这里妥协的话，放弃了那些在等待被你拯救的生命哦。”被母亲这样教育后，伊文捷琳终于下定了决心。 就算被说成自我满足也无所谓，自己能够帮助他人——这样的事实让伊文捷琳找到了自身的意义与使命。",
		level_6 = 0,
		record = "“虽然可能有点不切实际……但是我想要努力去拯救所有人！”"
	},
	[21120] = {
		soulid = 21120,
		valuation = "伊文捷琳的魂器适应性绝佳，但是几乎都集中在辅助方面的能力上了，她自身的战斗能力勉强能算是一般标准。",
		file_1 = "伊文捷琳母亲是隶属于教会的医护人员，如果让伊文捷琳说说自己对母亲的印象，那肯定是“天真”。 明明是成年人，但是毫不犹豫地将爱与希望挂在嘴边，受她影响，伊文捷琳也逐渐成长为温柔善良的少女。 伊文捷琳的母亲依靠先进的医疗技术救治了许多病人，在使用科技救治病人身体的同时，以信仰和温柔的言语治愈他们的心。 出于憧憬，伊文捷琳从小就立志成为母亲一般优秀的医护人员和信徒，为了达成这个目的，首要的目标是克服自身内向的性格，变成母亲那样开朗又招人喜欢的样子—— “小伊文现在这样不是挺好的嘛！”——来自当事人的母亲。",
		level_3 = 0,
		level_4 = 0,
		resume = "伊文捷琳，原籍耶梦加得。和大多数耶梦加得人一样拥有宗教信仰，跟随其作为医护人员的母亲学会了高超的医术，在“模拟智能网络”爆发时救治了诸多生命。 战后，学院对其发出了魂器适应性测试的邀请，伊文捷琳被测试出具有极其优秀的资质。对救治他人一事抱有使命感的伊文捷琳赞同学院的理念，故选择加入魂器学院医疗班，进行医疗方面的辅助工作。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "伊文捷琳的性格比较内向，平时与友人的交流更加倾向于倾听而不是对话。她几乎从不会与人辩论，但是如果有必要，她还是会平静地指出对方的问题。比起纠正现有的错误，伊文捷琳更加不想因为辩论制造出新的争端。对于是否要加入战斗，伊文捷琳也略显犹豫——不过只要看到有人受伤，她就会放下犹豫，全力投入到对他人的救治工作中去。 考虑到伊文捷琳这样的个性，院方将其安排到了医疗支援部队中，而且其产生的效果非常显著。在世界各地的救护行动中，伊文捷琳作为魂器学院派遣的医疗人员救治了无数的伤患，将学院的正面形象传播到了全世界。",
		file_3 = "“模拟智能网络”爆发后，耶梦加得同样陷入了人工智能反叛造成的混乱中，残酷的斗争迫使伊文捷琳拿起武器，加入到对抗人工智能的序列之中。 不过比起与敌人战斗，伊文捷琳更加擅长、也更加喜欢抚平他人的伤痛。 依靠过人的天赋与母亲悉心教导的医疗知识，伊文捷琳在战争期间救治了无数的伤患，甚至获得了教宗的嘉奖。 不过比起这些虚名，少女更加开心的是自己能够帮助到他人的事实，以及自己距离母亲更进一步的实感。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "实际上，一开始收到学院的入学邀请，伊文捷琳产生了犹豫。 获得了学院的支援，自己可能可以帮助到更多的人，这样的道理伊文捷琳也懂。但凭借自己的力量，仅仅是守护身边的人就已经是极限——伊文捷琳偶尔会冒出这样的想法。 “在这里妥协的话，放弃了那些在等待被你拯救的生命哦。”被母亲这样教育后，伊文捷琳终于下定了决心。 就算被说成自我满足也无所谓，自己能够帮助他人——这样的事实让伊文捷琳找到了自身的意义与使命。",
		level_6 = 0,
		record = "“虽然可能有点不切实际……但是我想要努力去拯救所有人！”"
	},
	[20802] = {
		soulid = 20802,
		valuation = "压倒性的气势与物理攻击能力，一定程度上完美发挥了【斩魂巨刃】的威力，战斗中头脑冷静，思路清晰，也都是远远超越同龄人的素质。",
		file_1 = "远坂家族，与其他同在洛加尔的古文化传承家族不同，远坂家族的文化传承涵盖面之广会让人觉得是以培养全才而存在的。\n实际上包含了茶道，插花，甚至于乐器等武学以外的各类知识，秋从被认定为下任家主开始就接受的是所谓的“精英式教育”，虽然是在外人看来非常繁冗复杂的课程，但了解到自己身上的责任之后，秋以非常认真地态度开始学习这些事物，当然，秋那种做什么事都认真过头的性格大概也是这时候开始的吧。总之，远坂家的各式传承都好好地印在了她的头脑中，可以说，在现在这样的特殊时期，秋就是远坂家族最后的火苗。",
		level_3 = 0,
		level_4 = 0,
		resume = "远坂秋，远坂家的下任家主，本应该拥有光明未来的她，或许也未曾想过一夜就失去了全部，\n连同远坂家族，都成为过去式的存在。然而，火种还未熄灭，作为自幼被当做下任家主培养的秋，优秀的掌握了几乎所有远坂家包括武道、历史在内的几乎全部的知识，随时可以重新燃起薪火。\n目前正在学院中修炼并不断提高自身，似乎因为自己的发小到来而变得更有动力起来。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【斩魂巨刃】是布克丝院长交付给秋的第一批搭载魂智能网络的武器其中之一，事实上的确拥有并不会辱没“巨刃”名号的外形。\n剑身异常的宽大，垂直立起的状态下甚至超过秋的身高，这方面连秋也非常苦恼，总觉得自己在“各个方面”还欠缺发育，因此喜欢上了牛奶。\n剑的周身并非平整的利刃，取而代之的是锯齿状的构造，去掉剑尖与来看或许还挺像电锯的，“就是以电锯为原型的”\n吐槽被布克丝博士严肃的语气所击败了，出乎意料的真的搭载了电锯的回转机能，当然，在重量方面进一步的提升了，有一段时间内秋都是以能挥动【斩魂巨刃】为目标在努力锻炼。",
		file_3 = "修行是从什么时候开始的呢？秋没有去记这种事情，遭遇袭击的那天，火光与废墟完全充斥着秋的视线，明明想战斗却怎样都无法动弹，\n直到被学院的队伍救下，浑浑噩噩地跟着院长来到学院。之后的很长一段时间，秋都没法完全的走出阴影。“以后，这里就是你的家”，\n以姐姐身份自居的院长收养了秋，难得的没怎么住在实验室里，整一个月的照看让秋再次体会到了属于家人的温馨，也明白不能一直消沉下去，\n决定开始去各处修行，这之后就一直奔波于各处战场，即为磨练技艺，也是数月之后复仇的开始，每日在战场与灭亡擦肩而过，秋的实力有了长足的进步，但秋很明白只有自己不断变强才能背负起整个家族，包括学院和院长，现在也是秋最看重的家和亲人。为此现在也在不断地修行中。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "薰的到来是秋意料之中的事，远坂家和柳生家本来是世交，虽然随着时间过去关系渐渐淡薄但也算还在互相联系，\n秋和薰同为从小被定为家族继承人的孩子，在一些方面上有着相似之处，也有共同语言，渐渐成为了朋友。\n只是灾难突如其来，两人再次相遇已经是数月之后，薰正处于自我满足的状态当中，然而秋知道这会让她在战场中送命，\n在报上魂器学院的名字之后，以绝对的实力击败了薰，对于这个发小，秋比任何人都要清楚她的争强好胜。显然，这次也不例外，看来，修行会稍微热闹一点了。",
		level_6 = 0,
		record = "修行！我需要更多的力量，才能保护我背负的一切。"
	},
	[20820] = {
