	[20202] = {
		soulid = 20202,
		valuation = "无法形容的狩猎技巧，无论是智械还是强化人，都是在没有察觉到的情况下被一击致命的，那样巨大的镰刀居然能做到如此精细的狩猎，作为学生来说早已破格太多了，可惜她太依赖命令了，在需要自由发挥的场合，可能会十分被动。 ",
		file_1 = "【绝对的七段分割】：只活跃在传说的狩猎术，因会将物体分割成七份质量相同的区块而得名。目前已确认，萱所掌握的狩猎术中便有【绝对的七段分割】的存在。具体是何人传授给萱的，暂且不明。     \n因布克丝院长表现出对该狩猎术的兴趣，故安排萱进行了相关的测试。      \n测试1 对象：代号303    结果：代号303被分割成七份，感压板的数据显示，这七份的质量仅存在0.25克的偏差。\n测试2 对象：优质派森和牛肉烧烤    结果：被分割成七份后马上就被吃掉了……感压板数据未能及时收录。\n测试3 对象：沙堆    结果：被萱本人用“你是白痴吗？”的天真眼神给伤害到了，测试人员提出了更换申请。\n测试4 对象：将近三十公斤的合金块    结果：被分割成七份，每块质量越为：4.3千克，多余的质量残留在刀刃上。\n结论：太不可思议了，无论是怎么样的技巧，都不可能做到如此精细的分割，如果学院内所有人都能掌握这项技巧的话，那么……不，还是算了，人才的多样性才是学院的最大优势。",
		level_3 = 0,
		level_4 = 0,
		resume = "萱，来自混乱的城市·克巴尔，曾经是那个臭名昭著的狩猎组织中的一员。精通大型武器的狩猎技巧，但不擅长谎言、色诱以及其他偏门的手段；在实战测试中展现出前所未有的战斗力，仅凭借一把冷兵器便将场上50名智械与强化人全部击垮，让原本是《躲避侦查》的考题，一下子变得混乱起来。\n性格上较为平淡，三无属性，对情感的表现较为僵硬，喜欢各种美食，一天当中见到她十次，有将近七次都在进食，是个相当可怕的吃货；另外和她同班的同学表示，这孩子似乎还有些天然呆。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "萱表现出对美食的高度热衷，不知道这是不是一件好事，但萱对于学院的依赖确实要比之前更高了。不过，根据厨师长反馈，这个月的肉类正以直线速度疯狂下降，处于对她的健康考虑，我们要采取措施，努力平衡她摄入的营养，养成更加良好的饮食习惯；虽然……目前看起来遥遥无期。\n其次是有关萱的天然呆部分，起初我们理解为：只是对话语的理解出现小部分误差，不会有太大的障碍；但是后来发现，萱的执行能力实在是太过强大了，在理解出现误差的后一秒马上就出发执行任务，这让我们很难对最初的指令进行修改……导致结果会和我们预料中的有所偏差。",
		file_3 = "暗影：克巴尔五区最可怕也是最臭名昭著的赏金猎人组织，内部有80%以上的成员都是女性，擅长各种各样的狩猎术，迄今为止已有不少关键人物都消失在了她们手中，其中包括人类和人工智能两方；是个只认钱，完全不挑对象的无底线狩猎组织。\n无论如何，萱能从这样的组织里脱身，从个人角度来说，是一件值得庆幸的事情，但同时，我们也需要对萱做更多更具体的评估才行。毕竟背后能托付的对象只有伙伴。 ",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【正在编辑的词条项，请具体确认持有的管理员权限等级后再执行此项操作，否则您将面临：监禁、剥夺职务、人事调动等风险。】     \n词条1【和平条约】：黑色圣诞节后，人工智能方和人类打算签订和平协议的当天，超高速监控机器人拍摄到了一组模糊的人影，经过系统的失真处理以及修复后，照片上呈现出的是三个身着【暗影】组织特有服装的狩猎者，其中一位被确认是萱，但根据当天的事故结果来看，被破坏的人工智能并没有呈现出七段分割后的相同质量，目前我们还需要更多现场的客观数据来重新模拟还原当天的事故。",
		level_6 = 0,
		record = "不知道失去了多少，才站在了这里的她，就连面对明天的笑脸都被遗忘，但只有那个人的孤单离去的身影依然深深地刻在脑海的深处。"
	},
	[20502] = {
		soulid = 20502,
		valuation = "诺诺妮娅的魂武威力非常巨大，但她的能力是一把双刃剑，因为没有指挥人员能与诺诺妮娅配合，唯有班长可以勉强一试。",
		file_1 = "简直是纵火犯啊！大家在见到诺诺妮娅之后的第一反应出奇的一致。为了防止学院在这个魂姬手上毁于一旦，学院紧急在全校做了防火措施，更换了新的防火材料，也在各地寻找防火相关的人才。因为恶劣的随时都有可能的纵火行为，让魂姬们对诺诺妮娅敬而远之，除了工作上的交流，日常生活上保持着微妙的距离。",
		level_3 = 0,
		level_4 = 0,
		resume = "诺诺妮娅与火焰为伴的病娇女郎。她的资料被档案室封存，好像是空降一般加入了魂器学院。\n有人猜测，她跟院长有着某种关系，也有人猜测，她是军方推荐来的。\n比起诺诺妮娅神秘的来历，诺诺妮娅如火焰般热烈张扬的作风更让大家印象十分深刻。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "诺诺妮娅丝毫不在意魂姬们微妙的态度，对她来说，来到魂器学院有着更重要的事情。那就是寻找到那个命中注定之人，然然永远的完完全全的在一起。敢阻挡她的人，全都要变成灰烬。新来的班长好像就是命定之人，诺诺妮娅对班长出乎寻常的热情，让班长时不时烦恼。不过部分魂姬对诺诺妮娅反常的热情持怀疑态度，总觉得神秘的诺诺妮娅背后可能隐藏着什么阴谋。",
		file_3 = "“烈焰之吻”作为魂智能武器，与常识里的火焰放射装置有着本质的不同。\n首先是它的温度，一般的单兵火焰兵器，放出的火焰温度都在一千度以内，这是由燃料与设备的特性决定的；就算是能够装载高温设备与压缩油料罐的重型火焰兵器，温度也就在两千五百度左右。而诺诺妮娅的“烈焰之吻”，它的温度在四千度到六千度。\n其次，是它的火力控制，一般来说，火焰的温度由燃料决定，火力由喷射设备决定，而“烈焰之吻”，它的温度与魂武本身无关，根据我们的试验，唯一能影响它的状态的，是诺诺妮娅的情绪。她越是激动、越是亢奋，“烈焰之吻”的输出就越高，就如同能回应诺诺妮娅的感情一般。这就是魂智能武器的神奇之处吧。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“3月1日，班长的裤子上有一个小破洞，执行任务的时候弄破的吧……啊啊，真是可爱，好想从那破洞里窥见更多的东西……”\n“3月2日，班长的头发长度比上周长了两毫米，不过这不影响班长依然是完美的，啊啊，好想亲手为班长理发，留下他身体的一部分……”\n“3月3日，班长的眼角有一道半公分的黑眼圈，是熬夜了吗……等等，难道说，是在晚上和某个学员……啊啊，一定要调查清楚！”\n“3月4日，潜入总务处的房间，查到了昨晚的宿舍录像，班长昨晚没有离开房间的迹象……那么，一个人在屋子里熬夜做什么呢？嘿嘿嘿，好想知道，好想知道……”\n——摘自被当做作业错交上来的诺诺妮娅的日记本。",
		level_6 = 0,
		record = "不要在诺诺妮娅的面前和班长距离过近，那样是把自己置于危险境地的行为。"
	},
	[20520] = {
		soulid = 20520,
		valuation = "诺诺妮娅的魂武威力非常巨大，但她的能力是一把双刃剑，因为没有指挥人员能与诺诺妮娅配合，唯有班长可以勉强一试。",
