		level_3 = 0,
		level_4 = 0,
		resume = "诺诺妮娅与火焰为伴的病娇女郎。她的资料被档案室封存，好像是空降一般加入了魂器学院。\n有人猜测，她跟院长有着某种关系，也有人猜测，她是军方推荐来的。\n比起诺诺妮娅神秘的来历，诺诺妮娅如火焰般热烈张扬的作风更让大家印象十分深刻。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "诺诺妮娅丝毫不在意魂姬们微妙的态度，对她来说，来到魂器学院有着更重要的事情。那就是寻找到那个命中注定之人，然然永远的完完全全的在一起。敢阻挡她的人，全都要变成灰烬。新来的班长好像就是命定之人，诺诺妮娅对班长出乎寻常的热情，让班长时不时烦恼。不过部分魂姬对诺诺妮娅反常的热情持怀疑态度，总觉得神秘的诺诺妮娅背后可能隐藏着什么阴谋。",
		file_3 = "“烈焰之吻”作为魂智能武器，与常识里的火焰放射装置有着本质的不同。\n首先是它的温度，一般的单兵火焰兵器，放出的火焰温度都在一千度以内，这是由燃料与设备的特性决定的；就算是能够装载高温设备与压缩油料罐的重型火焰兵器，温度也就在两千五百度左右。而诺诺妮娅的“烈焰之吻”，它的温度在四千度到六千度。\n其次，是它的火力控制，一般来说，火焰的温度由燃料决定，火力由喷射设备决定，而“烈焰之吻”，它的温度与魂武本身无关，根据我们的试验，唯一能影响它的状态的，是诺诺妮娅的情绪。她越是激动、越是亢奋，“烈焰之吻”的输出就越高，就如同能回应诺诺妮娅的感情一般。这就是魂智能武器的神奇之处吧。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“3月1日，班长的裤子上有一个小破洞，执行任务的时候弄破的吧……啊啊，真是可爱，好想从那破洞里窥见更多的东西……”\n“3月2日，班长的头发长度比上周长了两毫米，不过这不影响班长依然是完美的，啊啊，好想亲手为班长理发，留下他身体的一部分……”\n“3月3日，班长的眼角有一道半公分的黑眼圈，是熬夜了吗……等等，难道说，是在晚上和某个学员……啊啊，一定要调查清楚！”\n“3月4日，潜入总务处的房间，查到了昨晚的宿舍录像，班长昨晚没有离开房间的迹象……那么，一个人在屋子里熬夜做什么呢？嘿嘿嘿，好想知道，好想知道……”\n——摘自被当做作业错交上来的诺诺妮娅的日记本。",
		level_6 = 0,
		record = "不要在诺诺妮娅的面前和班长距离过近，那样是把自己置于危险境地的行为。"
	},
	[21005] = {
		soulid = 21005,
		valuation = "战斗技巧只能说是平均线以上，但是身体能力非常优秀，且玛姬与切割武器的相性堪称绝佳，她的战斗——用割草来说也不为过。弱小的敌人会在瞬间被击溃，而略微强大一点的敌人也会败在她的持续切割之下。",
		file_1 = "离开了孤儿院后，玛姬的破坏力与攻击性愈发日益强烈。\n并非是少女的心境发生了转变，而是外界严酷的生存环境逼迫她那样保护自己。\n不过因为孤僻的个性与让人难以接受的嗜好，玛姬一直没找到能够定居的地方。\n某一天，玛姬像是往常一般在教训欺凌弱小者的时候被外出度假的墨云发现，在了解了前因后果，并且亲手测试了玛姬的能力之后，墨云将玛姬带回了魂器学院。\n或许少女表现的性格不尽人意，但是无论是墨云还是院长都不会在意这些。",
		level_3 = 0,
		level_4 = 0,
		resume = "在奥杜因，像是玛姬这样的孤儿一抓一大把，比较幸运的是，玛姬被奥杜因的教会孤儿院所收养。\n奥杜因的社会风气不能说是健全，这一点连孤儿院都不能幸免，从某一时间开始，修女们不停地接到其他孤儿对玛姬的投诉。\n通过监控录像，她们看到玛姬用不会留下伤痕的手段折磨着这些孤儿。\n对此，监护者们一致认为玛姬被恶魔附身，但是无论是指责、洗礼甚至禁闭都无法让玛姬悔悟，孤儿院高层无奈作出了驱逐玛姬的决定。\n对此，少女并没有意见，在向照顾了自己许久的修女们道谢后，玛姬独自离开了孤儿院。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "墨云教官是玛姬的监管人——虽然这样说，基本也都是放养状态，墨云只会保证玛姬不闹出什么大事情，其他的琐碎事情她也没空去管理。\n魂器学院的环境让玛姬感觉自己有些格格不入。比起欺凌者，这里更多的是楚楚可怜的小动物一般的学员们，又或者开朗热心的小姐姐，就算性格比较孤僻的通常也不会没事找事，这原本是好事，但是积极的环境并没有让玛姬感受到代入感。\n于是玛姬变得更加孤僻，在课程以外的时间里，少女通常会独自待在无人的角落。\n这种状况在墨云教官的另一位监督对象——诺诺妮娅的到来后发生了改变。同样显露出破坏狂属性，却又有接近的本质的两人似乎一拍即合，演变成让学院上下都感觉头疼的破坏组合。",
		file_3 = "孤儿院孩子们之间的关系宛如奥杜因的缩影。\n原本的玛姬是一位内向的少女，这导致她在一开始才是受到欺凌的一方。\n分配的食物被抢夺，鞋子里被放入石子，心爱的兔子玩偶被撕破……\n无论怎么恳求，对方都不会放过她，这让玛姬意识到示弱只会助长欺凌者的气焰。\n在第一次击倒敌人，并且使其认知到自己错误后，不仅仅是自我防卫，就算是看见其他人被欺凌，玛姬也会毫不犹豫地介入。\n对欺凌弱者之人施加痛感，将他们造成的痛苦十倍奉还，这就是玛姬的想法——或许算是一种扭曲的正义感吧。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在进行“虐待”行为的时候，总是能够看到玛姬畅快地大笑，那样的表现就是不折不扣的虐待狂。\n但是偶尔独自一人的时候，少女却会露出落寞的神情。\n玛姬并不是单纯地在破坏中追求快感，那更像是要掩饰什么一般。\n证据就是，玛姬从来不屑于对弱小的无辜之人展露暴力，虽然语气不善，但玛姬为了“保护”某人而行动的次数更多一些。\n在非常罕见的情况下，还能够看到少女展现令人怀疑自己眼睛出问题的微小温柔。",
		level_6 = 0,
		record = "“施加在别人身上的痛苦，让你自己也好好感受一下吧！”"
	},
	[21020] = {
		soulid = 21020,
		valuation = "战斗技巧只能说是平均线以上，但是身体能力非常优秀，且玛姬与切割武器的相性堪称绝佳，她的战斗——用割草来说也不为过。弱小的敌人会在瞬间被击溃，而略微强大一点的敌人也会败在她的持续切割之下。",
