		file_3 = "孤儿院孩子们之间的关系宛如奥杜因的缩影。\n原本的玛姬是一位内向的少女，这导致她在一开始才是受到欺凌的一方。\n分配的食物被抢夺，鞋子里被放入石子，心爱的兔子玩偶被撕破……\n无论怎么恳求，对方都不会放过她，这让玛姬意识到示弱只会助长欺凌者的气焰。\n在第一次击倒敌人，并且使其认知到自己错误后，不仅仅是自我防卫，就算是看见其他人被欺凌，玛姬也会毫不犹豫地介入。\n对欺凌弱者之人施加痛感，将他们造成的痛苦十倍奉还，这就是玛姬的想法——或许算是一种扭曲的正义感吧。",
