	[20420] = {
		soulid = 20420,
		valuation = "和其他学员相比，艾丝翠德的体力实在是太低了，在一场半小时的物理测试中，足足有十五分钟都在休息，不过，她对战局的把控、方案的制定、战术的变化以及危机的处理都做到了极致，有培养的价值。 ",
		file_1 = "截止到黑色圣诞节时间爆发前，艾丝翠德所发布的游戏攻略便超过了五百篇，其中有不少内容涉及到利用简易游戏漏洞黑入电子脑（赛博人工智能），达到短时间的失明、体感时间加速等多种效果，由于这些效果危险性太高，所以大部分内容都被网站管理者封禁掉了。",
		level_3 = 0,
		level_4 = 0,
		resume = "艾丝翠德出生于耶梦加得，父母是普通的公务员，平时热爱游戏，曾制霸数款类型完全不相同的游戏，是游戏界有名的王者；因为她有着制霸某款游戏就会马上抛弃的习惯，所以对她的数据采集和追踪工作十分艰难，我们的工作人员曾用线上留言、寄出实体邀请函等多种方式，但全都失败了。黑色圣诞节爆发后，艾丝翠德主动联系了学院，据说本人回答加入学院的理由是：想要在乱世中依然能玩到游戏。这使得艾丝翠德的监考官在考试结束后的一段时间都十分郁闷。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【体感时间加速】：是一种通过仪器将大脑的运动指令绕开复杂的神经系统直接传达到肢体的技术之一，常见于义体和电子脑持有者，但由于信息本身的直接传达不会给予肌肉组织缓冲时间，所以会导致多项意外伤。是一项并不完善，且违反人体规律的技术。\n而艾丝翠德却能不依靠任何外接设备，做到毫无损伤的【体感时间加速】，这个能力使得她轻松就能做出各种不可思议的反应；用她的说法大概就是：在意识到攻击之前，身体就开始行动起来将其回避，自己所要需要考虑的只有反击。可惜的是，艾丝翠德的体力太差，这份能力并不能维持太长时间。",
		file_3 = "艾丝翠德在日常生活中经常会把游戏和现实弄混，这类人在体感游戏泛滥的年代里十分常见，所以一开始大家也并不在意。但后来，后勤人员发现，她的状态已经严重影响到生活……甚至是生存的程度了，经过院方的初步讨论，决定禁止艾丝翠德游玩有关虚拟现实类的所有游戏。\n就算如此，艾丝翠德还是能够靠着老旧的PC端游戏维持娱乐，并且每天依旧保持着八小时的游戏，从健康的角度上来说，十分让人担心。不过，目前为止并没有艾丝翠德因病倒下的记录，故申请剥夺艾丝翠德游戏权的请求暂时无法提出。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "以下为艾丝翠德部分异常的言行记录：  \n艾丝翠德：那片云……绝对是素材的重复利用吧？\n调查结果：那片三角状的云朵在未来一个月保持着从经度163°，维度70°平移到经度165°，维度98°的运动，该现象一直维持到下一场人工降雨后。\n艾丝翠德：为什么要和NPC打招呼？反正很快就会被其他人替换掉吧？\n调查结果：那位被称作NPC的员工在五天后和其他人员进行了简单的工作交接后便离职了。\n结论推断：艾丝翠德的特异性或许只是一种巧合，但这份巧合并不符合科学规律，超级计算机的计算结果表明：艾丝翠德的话语有某种引导性的力量，能够将73.51%的事物引导到自己渴望的结果上；但是……究竟是艾丝翠德将那份真实摆到了我们的面前；还是因为艾丝翠德的话语才导致了这样的结果，我们尚且无法得出结论。 不过好在科学得出结论之前，布克丝院长先用了一种比较通俗的说法让大家很快就理解了她的特异性。\n即：乌鸦嘴。",
		level_6 = 0,
		record = "已发现艾丝翠德企图通过隐藏实力来逃避任务分配，目前对于艾丝翠德的【思维处理能力】已重新评估。"
	},
	[20430] = {
		soulid = 20430,
		valuation = "和其他学员相比，艾丝翠德的体力实在是太低了，在一场半小时的物理测试中，足足有十五分钟都在休息，不过，她对战局的把控、方案的制定、战术的变化以及危机的处理都做到了极致，有培养的价值。 ",
		file_1 = "截止到黑色圣诞节时间爆发前，艾丝翠德所发布的游戏攻略便超过了五百篇，其中有不少内容涉及到利用简易游戏漏洞黑入电子脑（赛博人工智能），达到短时间的失明、体感时间加速等多种效果，由于这些效果危险性太高，所以大部分内容都被网站管理者封禁掉了。",
		level_3 = 0,
		level_4 = 0,
		resume = "艾丝翠德出生于耶梦加得，父母是普通的公务员，平时热爱游戏，曾制霸数款类型完全不相同的游戏，是游戏界有名的王者；因为她有着制霸某款游戏就会马上抛弃的习惯，所以对她的数据采集和追踪工作十分艰难，我们的工作人员曾用线上留言、寄出实体邀请函等多种方式，但全都失败了。黑色圣诞节爆发后，艾丝翠德主动联系了学院，据说本人回答加入学院的理由是：想要在乱世中依然能玩到游戏。这使得艾丝翠德的监考官在考试结束后的一段时间都十分郁闷。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【体感时间加速】：是一种通过仪器将大脑的运动指令绕开复杂的神经系统直接传达到肢体的技术之一，常见于义体和电子脑持有者，但由于信息本身的直接传达不会给予肌肉组织缓冲时间，所以会导致多项意外伤。是一项并不完善，且违反人体规律的技术。\n而艾丝翠德却能不依靠任何外接设备，做到毫无损伤的【体感时间加速】，这个能力使得她轻松就能做出各种不可思议的反应；用她的说法大概就是：在意识到攻击之前，身体就开始行动起来将其回避，自己所要需要考虑的只有反击。可惜的是，艾丝翠德的体力太差，这份能力并不能维持太长时间。",
		file_3 = "艾丝翠德在日常生活中经常会把游戏和现实弄混，这类人在体感游戏泛滥的年代里十分常见，所以一开始大家也并不在意。但后来，后勤人员发现，她的状态已经严重影响到生活……甚至是生存的程度了，经过院方的初步讨论，决定禁止艾丝翠德游玩有关虚拟现实类的所有游戏。\n就算如此，艾丝翠德还是能够靠着老旧的PC端游戏维持娱乐，并且每天依旧保持着八小时的游戏，从健康的角度上来说，十分让人担心。不过，目前为止并没有艾丝翠德因病倒下的记录，故申请剥夺艾丝翠德游戏权的请求暂时无法提出。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "以下为艾丝翠德部分异常的言行记录：  \n艾丝翠德：那片云……绝对是素材的重复利用吧？\n调查结果：那片三角状的云朵在未来一个月保持着从经度163°，维度70°平移到经度165°，维度98°的运动，该现象一直维持到下一场人工降雨后。\n艾丝翠德：为什么要和NPC打招呼？反正很快就会被其他人替换掉吧？\n调查结果：那位被称作NPC的员工在五天后和其他人员进行了简单的工作交接后便离职了。\n结论推断：艾丝翠德的特异性或许只是一种巧合，但这份巧合并不符合科学规律，超级计算机的计算结果表明：艾丝翠德的话语有某种引导性的力量，能够将73.51%的事物引导到自己渴望的结果上；但是……究竟是艾丝翠德将那份真实摆到了我们的面前；还是因为艾丝翠德的话语才导致了这样的结果，我们尚且无法得出结论。 不过好在科学得出结论之前，布克丝院长先用了一种比较通俗的说法让大家很快就理解了她的特异性。\n即：乌鸦嘴。",
		level_6 = 0,
		record = "已发现艾丝翠德企图通过隐藏实力来逃避任务分配，目前对于艾丝翠德的【思维处理能力】已重新评估。"
	},
	[21403] = {
		soulid = 21403,
		valuation = "学员奥德莉，除了高超的编程技术，还有着这个年龄不该具备的成熟稳重。她思维缜密，又冷静可靠。奥德莉在学院的战术学科展现出了非凡的才能，对于这样的人才，我们认为让她留在指挥中心，才是更合适的。",
		file_1 = "奥德莉正常的童年生活止于一场灾难。在一场小规模的边界冲突中，父母双双失踪。失去扶养人后的妹妹皮卡面临着被送入孤儿院托养的下场，而奥德莉自己由于年龄相对较大则将被送入寄宿学校。\n在通过一些渠道得知她们各自要去的地方并不是那么的“友善”后，奥德莉利用她初露锋芒的编程能力入侵了当地的民事档案中心，将自己的年龄篡改为18岁，并将妹妹的监护人改为自己。而这么做的代价就是姐妹两人再也无法收到联邦政府的救济金了。",
		level_3 = 0,
		level_4 = 0,
		resume = "奥德莉是家里的长女，她还有比她小2岁的一个妹妹——皮卡。父母均是研究所的工作人员，工作很忙。因此，奥德莉从小就开始学习做家务以及照顾妹妹。奥德莉有着一定程度上的洁癖，对家务和居住条件有很强的要求，不喜欢脏乱，空气不清新的地方。\n尽管与父母相处的时间很短，但奥德莉依旧从她的父母身上学到了很多。而编程是她所有学科中天赋最突出的。在她4岁那年，她就成功的设计了一个使房间的灯在房门打开时被同时点亮的简单程序。处于对女儿的奖励与对未来的考量，奥德莉在她5岁的时候就拥有了一款性能优异的个人电脑。\n从此，奥德莉就在编程的路上越走越远了。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "从小的耳熏目暗以及极高的天赋，奥德莉在编程方面是难得的天才。在父母失踪后，奥德莉开始用编程能力赚钱。公司的人力管理系统、无线网密码的破解程序、智能儿童玩具的逻辑代码……尽管奥德莉的业务范围广泛的惊人，但这些程序代工的工资仅仅只能在交完房租电费与妹妹的学费之后维持姐妹两的温饱。在奥德莉进入魂器学院的前一年，奥德莉曾负责设计过一个大型连锁超市的网络安全系统。在一次针对人类民用网络的网络电子战中，那家大型超市的系统成了整个地区唯一的幸存者。奥德莉对于这一类普通的委托并没有刻意的进行保密工作，于是这件事被迅速传播开来。奥德莉成了那里的大名人，并在黑客界名声鹊起，慢慢的引起了魂器学院的注意。截止到奥德莉收到学院的录取通知书的那一刻，她已经是一家巨头公司的网络安全顾问了。",
		file_3 = "许多人不知道的是，学院在奥德莉的加入后，程序编译系统也迎来了一次巨大的革新——那是由奥德莉独自一人研发的新版本，仅花费了一周，却将整个系统效率进行了提升。\n起初，是学院的系统维护老师发现，奥德莉对程序的处理速度比计算机还要快——虽然听起来相当离谱，但这这绝不是幻觉。老师们试验了好几次，将一段有问题的代码放在奥德莉面前，奥德莉总能一眼就找到 缺陷，并详细地说出 缺陷会导致的后果，这就是只能机械处理命令的计算机做不到的事。\n基于此，老师们决定将系统底层交给奥德莉，让她尝试优化。结局再次让所有人感到震惊——一周后完成的系统升级，让系统效率足足提升了三成。\n如果你有一日获得进入魂器学院系统底层的权限，就能在里面发现名为这个名为“奥黛丽”的系统。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "奥德莉与皮卡一直在追查父母的下落，虽然自从父母失踪以来已经过了五年，但如今去看、那场事件仍有许多的疑点。\n例如，作为研究员的父母会前往都市边界、被卷入冲突，是因为参与某个秘密研究项目，而该项目的所有情报，至今仍在封锁当中。\n再例如，父母就职的尼德霍格“巨伞科技公司”，原本经营状况良好，却在边界冲突事件后就被鲁比克财团收购，加入人工智能的研究当中。\n从这些线索展露出来的信息来看，不难判断，若是从边界冲突追查下去，恐怕会牵扯到越来越庞杂的事情，甚至会与“模拟智能网络”、改变了这场世界的黑色圣诞节有关。要揭开那层神秘的面纱，很可能引火上身。\n但即便如此，奥德莉与皮卡也不会停止自己的脚步。",
		level_6 = 0,
		record = "在喵酱的大力邀请下，参加了学院的考核，成为了一名魂姬。奥德莉的编程能力对学院的系统安全与电子战能力带来了极大的提高。据联邦情报部门的统计，奥德莉是极少数能够独自一人应对人工智能蜂群式网络攻击的顶尖黑客之一。"
	},
	[21430] = {
