		file_4 = "奥德莉与皮卡一直在追查父母的下落，虽然自从父母失踪以来已经过了五年，但如今去看、那场事件仍有许多的疑点。\n例如，作为研究员的父母会前往都市边界、被卷入冲突，是因为参与某个秘密研究项目，而该项目的所有情报，至今仍在封锁当中。\n再例如，父母就职的尼德霍格“巨伞科技公司”，原本经营状况良好，却在边界冲突事件后就被鲁比克财团收购，加入人工智能的研究当中。\n从这些线索展露出来的信息来看，不难判断，若是从边界冲突追查下去，恐怕会牵扯到越来越庞杂的事情，甚至会与“模拟智能网络”、改变了这场世界的黑色圣诞节有关。要揭开那层神秘的面纱，很可能引火上身。\n但即便如此，奥德莉与皮卡也不会停止自己的脚步。",
		level_6 = 0,
		record = "在喵酱的大力邀请下，参加了学院的考核，成为了一名魂姬。奥德莉的编程能力对学院的系统安全与电子战能力带来了极大的提高。据联邦情报部门的统计，奥德莉是极少数能够独自一人应对人工智能蜂群式网络攻击的顶尖黑客之一。"
	},
	[20602] = {
		soulid = 20602,
		valuation = "优秀的指挥与执行能力，在测试中仅用五名强化士兵便歼灭了敌方人工智能十五名，防御、进攻、包围、隐藏……多种战术无缝切换，且本人也有着一定的攻击手段，是一位没有明显缺点的优秀人才。 ",
		file_1 = "康茨坦丝·朱蒂提亚，强大到让人产生窒息感应该就是指这类人。刚担任学生会长才一个月就已经解决了学院内80%的繁琐事务，每天都保持着八小时的高强度工作，并且在这个基础上，每门课都能拿到优秀……要不是院长亲自保证，我甚至都怀疑她其实就是某个高级人工智能；虽然她各方面都很完美，但在我看来完美超人并不存在，时至今日，康茨坦丝开始逐渐露出自己的弊端了，她表现出了对自己实力的盲目自信，以及对权力与责任的沉迷，虽然目前来看还不是什么大问题，但长久下来，一定会发展成无法挽回的事情。",
		level_3 = 0,
		level_4 = 0,
		resume = "康茨坦丝来自玛尔斯，是军方高层的子女，曾获得过多项功勋与荣誉，并有着指挥军队成功反击人工智能方的记录，是一名真正意义上的实力派。 现阶段是魂器学院唯一以S级评价入学的学生，就连布克丝院长都对她作出了“如果有一天，我发生了意外，那么，康茨坦丝将接手我手头 上的一切权限。”这样的高度评价。 平时待人严厉，喜欢恩威并用，就连学院内的工作人员和部分教师都会下意识地对她使用敬语；本质是个有些害怕寂寞的人，不过因为其 过强的责任心，不太愿意将自己柔弱的一面展示给别人看，而且她总是单方面包揽过量的工作，令人有些担忧…… 担忧归担忧，她的能力确实是无人可及的；目前，康茨坦丝已经成为了学院的学生会长。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "康茨坦丝曾在学生时代负责耶梦加得·核心欧洲文化区的守卫工作，并在那个时候接触了大量的有关骑士以及十字军的文化。这些经历间接影响了她，使得她开始成为了一名果断、有担当的，富有骑士精神的人；据说当时的她在毕业不久之后就找到了相关教会的工作，但在黑色圣诞节爆发后，教会的不作为使得康茨坦丝理解了书本上描绘的十字军在这个时代并不存在。于是，她离开了教会并投身到了父亲所在的军方，凭借着自己强大的指挥能力，领导着军队长年活跃在战场的第一线…… 虽然有着多次反击成功的经历，但真正意义上成功战胜人工智能的战斗却一次都没有过；原因在于人工智能那过于强大的渗透性和压倒性的数量，康茨坦丝认为主动发起战斗存在过多的不确定因素，不如被动反击还能将损失降到最低。 然而布克丝和魂器的出现让康茨坦丝看到了一丝人类的希望，于是她拉拢了军方高层，在对布克丝进行多项资助后，自己也主动进入了学院，成为了一名魂姬。",
		file_3 = "【圣殿之盾】：其存在本身——就是拒绝；拒绝伤害、拒绝恶意、拒绝契约……只要是这个世界上存在的任何形式的攻击，都无法对圣殿之盾造成有效的伤害，同时，它也拒绝着契约所发出的能力波，是布克丝院长在早期制作的一件无限近乎失败的成功品。 本来，这件魂器的制作思路就是要对任何能量进行绝缘处理，但当时的布克丝院长没能考虑到契约本身也是能量共鸣这一点，使得这件魂器从根本上无法出现共鸣者。 康茨坦丝在得知这件魂器的情况下，主动提出了要和它进行共鸣，在经过数次共鸣实验失败后，她竟然依靠着魂器的中央控制台，从代码层面上和圣殿之盾达成了共鸣，整个过程简直是匪夷所思……",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【警告：无效档案】  重复授权…… 【警告：无效档案】  重复授权…… 【警告：无效档案】  重复授权…… 【新信息：现在来学生会议室一趟。】",
		level_6 = 0,
		record = "能力越大，责任就越大，被神眷顾的我必须要比别人更加努力……如果不这样的话，我就不再会被别人需要。 所以我要去做，不……是非做不可，如果无法连同那些无能之辈的份一起努力的话，迄今为止累积的一切就会全都垮掉…… 但是……果然一个人久了之后，还是会寂寞的呀……"
	},
	[20620] = {
