	[20720] = {
		soulid = 20720,
		valuation = "灵活的头脑与巨大的破坏力，让奈奈足以被称为一流的战士。更加可贵的是她那乐观的游戏精神，无论面对多么危机的状况，奈奈都能从容化解。",
		file_1 = "“电玩高手”是一件特殊的魂智能武器，它可以使用电流、引爆锤头内部的炸药以提升破坏力。诞生之初，“电玩高手”共设计了三种运行模式，分别是注重威力的“爆发模式”、用来应付长时间战斗的“续航模式”以及更注重灵活性的“轻量模式”，可以通过锤头附近的按键随时进行切换，以满足各种作战场景的需求。\n而如今，奈奈已对芯片进行重新编程，据她所说，现在的“电玩高手”共有七十二种模式可选，它们的名字有“魔王征服模式”、“圣剑出鞘模式”、“勇者冒险模式”以及“GAME OVER 模式”等。这些名字的意义整个学院可能只有奈奈一个人懂，但愿她没有要修理魂武的那一天吧。",
		level_3 = 0,
		level_4 = 0,
		resume = "奈奈，来自派森。父母均是狂热的棒球粉。在父母的影响下，奈奈对棒球运动十分热爱，从小就爱挥舞着棒球棒跑来跑去。稍大一点的时候，去电玩厅对打地鼠一见钟情，成了打地鼠游戏的脑残粉。随机参加了很多打地鼠相关的比赛，捧回了很多奖杯，成为了电玩届冉冉升起的一个新秀。喜爱奈奈的粉丝们给她取了各种外号“派森女战神”，“最强地鼠女王”等等……在众人的追捧中，奈奈的性格变得有些娇蛮，但是善良乐观开朗的天性让奈奈没有变成熊孩子。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在如今的 21 世纪 40 年代，奈奈腰间别着的那个可不是常见的玩意。在现代年轻人流行的“VR 眼镜”、“全息掌机”之间，那个装配古老液晶屏的掌机简直可以用“老古董”来形容。作为这个时代的电玩高手，奈奈最珍惜的却是那个过时的游戏机，让我们感到意外。\n后来，奈奈告诉我们，她放不下的是那个掌机里的电子宠物，那只她从小开始培育的，名为“波波”的球状虚拟生物。\n起初，是奈奈的爷爷从家里将掌机翻了出来，把“波波”交给奈奈“抚养”。到现在，“波波”已经陪伴了奈奈将近八年，那个古老的电子宠物程序也早已耗光了内容，当下的每一天，奈奈能做的就只有给“波波”喂水喂食，重复这些已经做过成千上万次的操作。但尽管如此，奈奈也不曾有一天懈怠，照顾“波波”，已成为奈奈日常生活中不可分割的一环。\n之后与奈奈的交流使我们明白了，“黑色圣诞节”之后的日子里，全世界的网络都波动了好一段时间。那阵子，这个世代的游戏几乎都无法运行，因为联网才是这个世界的常态。无聊的日子里，只有“波波”一成不变，陪伴着奈奈度过枯燥的时光，那也是奈奈非常珍惜的回忆。",
		file_3 = "打地鼠并不是那么轻松的游戏，它对人的集中力、反应力以及肌肉力量都有要求，通常人玩上几分钟就会气喘吁吁，而奈奈的最高纪录则是五个小时。\n这并不是只靠兴趣就可以坚持下来的，学院对奈奈进行了全方位的体检，发现她的肌肉强度并不像想象中那样突出，顶多算是普通人中坚持锻炼的那一类，真正让奈奈能产生爆发性力量的因素，是她的大脑。\n在实验中我们发现，在奈奈进入游戏状态后，她的大脑能产生强于普通人两到三倍的脑波，这说明她的大脑兴奋程度极高，除了能高效地协调身体外，也能通过神经命令让肌肉爆发出更强力量，换言之就是对“潜力”收放自如，这就是奈奈怪力的真相。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "奈奈的请假记录与游戏发售日的对比参考：\n3月3日，《赛赛传说都市之息》发售，奈奈请事假全天；\n3月26日，《人工智能 猎人》发售，奈奈感冒请假全天；\n4月14日，《GTB VI》发售，奈奈牙痛请假全天；\n11月10日，《黑客信条英灵殿》发售，奈奈头痛请假两天……\n以后似乎可以通过游戏发售日来预判奈奈请假的日子了，为了她的学业考虑，请假审批一定要放严格。",
		level_6 = 0,
		record = "如果整一天在学院里没看见奈奈与艾丝翠德，那一定是某个新游戏发售了。"
	},
	[20303] = {
		soulid = 20303,
		valuation = "学员皮卡，虽然性格还有些孩子气，但一旦投身到训练或是作战中，状态能够极快地转变。进入状态的皮卡，是十分严谨且主动的学员。“雷霆之握”原本是常规电磁系魂智能武器，但是在皮卡的应用下，几乎能够满足所有作战场景的需要。一方面能够输出极大的破坏功率，一方面能够用电磁波对敌人电子设备进行干扰，甚至还可以作为入侵网络的端口使用——这都是得益于皮卡的天赋与努力。",
		file_1 = "皮卡与姐姐奥德莉，原本生活在一个条件优渥的家庭当中，父母都是尼德霍格大型企业的研究员，工作很忙，奥德莉从那时起就承担起了照顾妹妹的责任。\n然而，美好的童年没有持续很久，在一场小规模的边界冲突中，皮卡与奥德莉的双亲失踪了。成为孤儿的姐妹俩，不得不靠着自己的双手生活。\n奥德莉利用自己的编程天赋，接了很多零碎的技术活——公司的人力管理系统、无线网密码的破解程序、智能儿童玩具的逻辑代码等等……如此广泛的业务量让她经常工作到深夜。虽然皮卡多次想要帮姐姐分担工作，但都被奥德莉以“你现在应该以学业为重”拒绝了。\n而让奥德莉记忆深刻的事情是，自己敲坏的一把键盘，第二天就被修好放在桌面上，桌子的另一头则趴着呼呼大睡的皮卡。",
		level_3 = 0,
		level_4 = 0,
		resume = "皮卡，来自尼德霍格的学员，从小与姐姐奥德莉相依为命。或许是基因的关系，皮卡与奥德莉相同，有着极强的学习天赋与动手能力。尤其是在电子机械领域，皮卡总是能迅速理解那些设备的结构，无论是修理、拆解甚至是改装都不在话下。\n然而在另一方面，皮卡的成长就只能用“灾难”来形容了——她几乎没有生活自理能力，不会收拾房间，不会洗衣服，更不会做饭。离开姐姐奥德莉，皮卡只需要一天就能把生活搞得一团糟。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在学院的体检报告里，皮卡的骨年龄只有十三岁，这比城市档案里的十六岁差了三岁之多，而她的姐姐奥德莉也存在这种状况——奥德莉的骨年龄只有十五岁，而尼德霍格移交过来的档案却显示奥德莉有十八岁。\n后来，根据我们的调查，发现尼德霍格的民事档案中心在几年前被入侵篡改过，那正是皮卡即将被转移到孤儿院的时刻。在我们的询问下，奥德莉交代了实情：原来，父母失踪后，尼德霍格的公益组织擅自将皮卡安排去了郊区的孤儿院。那里是数起霸凌事件的案发地，没有独立生活经验的皮卡、一定会成为被欺负的对象。于是，奥德莉不得不骇入民事档案中心，将自己和皮卡的年龄修改，让自己“成年”，这样便能够成为皮卡的监护人，让皮卡免于被送到危险孤儿院的命运。\n鉴于此举并未造成严重后果，学院决定不上报民政中心，保留奥德莉与皮卡的错误资料。",
		file_3 = "与人相处时，皮卡经常会表现得不够亲切、不够友善，但这并非是那种叫做“傲娇”的性格，而是皮卡自己在刻意地与人保持距离。\n曾经，小时候的皮卡，是很乐意与人交朋友的，但很快她就发现，自己与同龄人在兴趣方面存在着很大的差异。皮卡小时候就热衷于拆解电子机械，她会带着复杂的电子元件与小伙伴们分享，盯着电路板、专心致志地看上一天——然而这些对普通的孩子们来说，是无法理解的。\n那些日子，皮卡总在下午高高兴兴地出门，而到了傍晚，又是奥德莉从公园的角落、将孤零零的皮卡带回家——如此的次数多了以后，皮卡便不在出门了，对陌生人的态度也变得抗拒。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "皮卡与奥德莉一直在追查父母的下落，虽然自从父母失踪以来已经过了五年，但如今去看、那场事件仍有许多的疑点。\n例如，作为研究员的父母会前往都市边界、被卷入冲突，是因为参与某个秘密研究项目，而该项目的所有情报，至今仍在封锁当中。\n再例如，父母就职的尼德霍格“巨伞科技公司”，原本经营状况良好，却在边界冲突事件后就被鲁比克财团收购，加入人工智能的研究当中。\n从这些线索展露出来的信息来看，不难判断，若是从边界冲突追查下去，恐怕会牵扯到越来越庞杂的事情，甚至会与“模拟智能网络”、改变了这场世界的黑色圣诞节有关。要揭开那层神秘的面纱，很可能引火上身。\n但即便如此，皮卡与奥德莉也不会停止自己的脚步。",
		level_6 = 0,
		record = "优秀的家族遗传，皮卡拥有卓越的天赋，与姐姐搭档时状态更佳。"
	},
	[20330] = {
		soulid = 20330,
		valuation = "学员皮卡，虽然性格还有些孩子气，但一旦投身到训练或是作战中，状态能够极快地转变。进入状态的皮卡，是十分严谨且主动的学员。“雷霆之握”原本是常规电磁系魂智能武器，但是在皮卡的应用下，几乎能够满足所有作战场景的需要。一方面能够输出极大的破坏功率，一方面能够用电磁波对敌人电子设备进行干扰，甚至还可以作为入侵网络的端口使用——这都是得益于皮卡的天赋与努力。",
		file_1 = "皮卡与姐姐奥德莉，原本生活在一个条件优渥的家庭当中，父母都是尼德霍格大型企业的研究员，工作很忙，奥德莉从那时起就承担起了照顾妹妹的责任。\n然而，美好的童年没有持续很久，在一场小规模的边界冲突中，皮卡与奥德莉的双亲失踪了。成为孤儿的姐妹俩，不得不靠着自己的双手生活。\n奥德莉利用自己的编程天赋，接了很多零碎的技术活——公司的人力管理系统、无线网密码的破解程序、智能儿童玩具的逻辑代码等等……如此广泛的业务量让她经常工作到深夜。虽然皮卡多次想要帮姐姐分担工作，但都被奥德莉以“你现在应该以学业为重”拒绝了。\n而让奥德莉记忆深刻的事情是，自己敲坏的一把键盘，第二天就被修好放在桌面上，桌子的另一头则趴着呼呼大睡的皮卡。",
		level_3 = 0,
		level_4 = 0,
		resume = "皮卡，来自尼德霍格的学员，从小与姐姐奥德莉相依为命。或许是基因的关系，皮卡与奥德莉相同，有着极强的学习天赋与动手能力。尤其是在电子机械领域，皮卡总是能迅速理解那些设备的结构，无论是修理、拆解甚至是改装都不在话下。\n然而在另一方面，皮卡的成长就只能用“灾难”来形容了——她几乎没有生活自理能力，不会收拾房间，不会洗衣服，更不会做饭。离开姐姐奥德莉，皮卡只需要一天就能把生活搞得一团糟。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在学院的体检报告里，皮卡的骨年龄只有十三岁，这比城市档案里的十六岁差了三岁之多，而她的姐姐奥德莉也存在这种状况——奥德莉的骨年龄只有十五岁，而尼德霍格移交过来的档案却显示奥德莉有十八岁。\n后来，根据我们的调查，发现尼德霍格的民事档案中心在几年前被入侵篡改过，那正是皮卡即将被转移到孤儿院的时刻。在我们的询问下，奥德莉交代了实情：原来，父母失踪后，尼德霍格的公益组织擅自将皮卡安排去了郊区的孤儿院。那里是数起霸凌事件的案发地，没有独立生活经验的皮卡、一定会成为被欺负的对象。于是，奥德莉不得不骇入民事档案中心，将自己和皮卡的年龄修改，让自己“成年”，这样便能够成为皮卡的监护人，让皮卡免于被送到危险孤儿院的命运。\n鉴于此举并未造成严重后果，学院决定不上报民政中心，保留奥德莉与皮卡的错误资料。",
		file_3 = "与人相处时，皮卡经常会表现得不够亲切、不够友善，但这并非是那种叫做“傲娇”的性格，而是皮卡自己在刻意地与人保持距离。\n曾经，小时候的皮卡，是很乐意与人交朋友的，但很快她就发现，自己与同龄人在兴趣方面存在着很大的差异。皮卡小时候就热衷于拆解电子机械，她会带着复杂的电子元件与小伙伴们分享，盯着电路板、专心致志地看上一天——然而这些对普通的孩子们来说，是无法理解的。\n那些日子，皮卡总在下午高高兴兴地出门，而到了傍晚，又是奥德莉从公园的角落、将孤零零的皮卡带回家——如此的次数多了以后，皮卡便不在出门了，对陌生人的态度也变得抗拒。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "皮卡与奥德莉一直在追查父母的下落，虽然自从父母失踪以来已经过了五年，但如今去看、那场事件仍有许多的疑点。\n例如，作为研究员的父母会前往都市边界、被卷入冲突，是因为参与某个秘密研究项目，而该项目的所有情报，至今仍在封锁当中。\n再例如，父母就职的尼德霍格“巨伞科技公司”，原本经营状况良好，却在边界冲突事件后就被鲁比克财团收购，加入人工智能的研究当中。\n从这些线索展露出来的信息来看，不难判断，若是从边界冲突追查下去，恐怕会牵扯到越来越庞杂的事情，甚至会与“模拟智能网络”、改变了这场世界的黑色圣诞节有关。要揭开那层神秘的面纱，很可能引火上身。\n但即便如此，皮卡与奥德莉也不会停止自己的脚步。",
		level_6 = 0,
		record = "优秀的家族遗传，皮卡拥有卓越的天赋，与姐姐搭档时状态更佳。"
	},
	[20020] = {
		soulid = 20020,
		valuation = "为测验设备进行考核……感觉有些微妙。话归正传，零号的物理战斗性能堪称绝佳，或许是一直被当做模拟战斗对象的缘故，她的战斗技巧涵盖非常娴熟与广泛，魂智能化的回路提供的演算力使机体性能优化到极致，而院长临时加装的战斗部件也完全与零号契合，不过缺乏特殊作战能力终究是零号的硬伤。",
		file_1 = "零号的原型是“黑色圣诞”初期觉醒的模拟智能网络系列人工智能，原本是某座秘密设施的核心人工智能，拥有学习能力的人工智能，但是在被感染后离开了原本所在的区域。 因为研究需求，由布克丝院长当时手下的战斗人员与之交战，在夺取其部分元件后仿制出了现在的零号，但这之中出现了问题。 即使院长跳过天网的干涉屡次对零号进行初始化设定，但是一旦重新连入网络，模拟智能网络就会立即夺回机体的控制权。 进行多次实验后，院长发现零号的思维逻辑回路遭到了破坏，已经无法胜任“被感染的人工智能实验样本”这一职务。 无奈，布克丝院长在完成了初步的实验计划后就使其强制休眠，随后进行封存。 魂器学院建立后，因为对现有的对战模拟人工智能的不满，院长将零号从仓库深处拖了出来，进行简单的改造后当做训练机体使用。",
		level_3 = 0,
		level_4 = 0,
		resume = "布克丝院长用于研究模拟智能网络的素体，本应该处于强制休眠状态的机体于一次模拟实验中再度觉醒。重新检查之后，学院发现她的逻辑回路受到了魂智能网络的侵蚀，底层协议也已经失效。因为失去了底层协议，零失去了对人类的攻击性，同时会时不时地陷入迷茫状态，在没有与任何存在交互的时候会一直“发呆”。 对零号重新进行了威胁性评估后，院长决定将其留在学院中，布克丝院长期望从零号的变化中搜集数据，寻找解决现状的另一条路径。 观察到零号的行为模式：零号经常在学员中游荡，仔细观察着遇见的每一个人，努力让自己融入周遭的环境。 此外，零号似乎将班长当做了宿主机，试图通过班长来加深对这个世界的了解，这一点需要多加注意。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "魂智能化后，零号摆脱了模拟智能网络引导的对人类攻击倾向，但零号依旧保留着自“黑色圣诞”至今为止的记忆。 但也正是因为如此，零号迷失了“自我”。 自己到底是何等的存在？科研基地的统合型人工智能？危害人类的反叛人工智能？魂器学院的训练用机体？这些失去了“抑制力”的身份，又真正能够决定自己的归途吗？ 无法确认这一点，所以零号开始学习周围人类的行动，期望从“模仿”这一行为中找到自己存在的意义。 现在的零号经常游荡于学院之中，用仔细观察着从身边经过的每一个人，如果看到她做出什么奇怪的举动，那大概是因为又一次意味不明的模仿吧。",
		file_3 = "人工智能没有人类的大部分生物体征，使用魂器几乎是不可能的，现阶段布克丝院长也绝对不会对魂器的使用限制有任何下放。 但是，这一特性对于自身魂智能化的零号来说并无意义，她自身就同等于“魂器”的存在，除了持有控制权的布克丝院长，没有任何因素能够限制她对魂器的运用。 与通常的学员不同，零号持有的只是普通的科技武器，与她的机体也没有多大的匹配性，甚至连零号自己也回答不出来为什么会选择这样的武器。 “矛”与“盾”，或许这也是对零号现在的心里状态的体现。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "实际上，零号被封存在学院地下格纳库的期间并不是没有意识的，为了防止长时间关机导致硬件损坏，她的机体一直保持在最低限度的运行之中。 零号对那段时间的记忆也是存在的，虽然“醒着”，但是看不到任何东西；虽然“醒着”，但是无法与任何人交流。 那样的孤独，对于人工智能来说是应该无所谓的——真的是这样吗？ 时光流逝，零号在某一天被取了出来，稍加改造投入到了战斗测试中。 作为能够多次使用的消耗品，作为研究模拟智能网络的实验品，逐渐磨损，逐渐崩坏。 然后，那一天，封闭的世界中，有一束光照了进来。",
		level_6 = 0,
		record = "“还没有找到自己应该做的事情……但是在那之前，我想要先守护好自己眼前的东西。”"
	},
	[21505] = {
		soulid = 21505,
		valuation = "该说不愧是柳生家的家族继承人吗，剑术上的能力确实少有人能够匹敌，身体动作也能看出是经过磨炼的，高速反应下偶尔能做出超乎想象的动作。",
		file_1 = "薰使用的流派，是从柳生新阴流转变而来，糅合了薰对剑道的自我理解产生的另一种类的剑术。\n目前从薰的作战表现来看，是更偏向战斗，破坏的剑道，但却意外的充满技巧感。不论如何，是适合战场的剑道。\n当然，一开始薰修炼的也是正统的柳生新阴流，并非以伤害敌人锻炼剑技才是的神髓，但是见识了足够残酷的战场与非人的敌人后，\n薰的心性产生了变化，清楚知道敌人不再拥有“人性”这一概念后态度也变得犀利起来，固然还谨记着“无刀取”“活人剑”的战法，但更多的时候会选择主动进攻，然而从另一方面来说，战术上或许是略输一筹的。",
		level_3 = 0,
		level_4 = 0,
		resume = "柳生薰，柳生家预定的下任家族继承人，剑术方面的天才，可以说是各方面都被上天眷顾的孩子\n自幼展现出的潜力让当代家主直接定下了薰继承人的位置，虽然从习俗上来说，薰身为女孩子原本是无法作为家主的。\n不过薰的表现确实出众，没有辜负父亲的期望，认真潜修柳生流的剑道后，将其吸收改良，成就了薰的专属剑道流派。\n但是令人疑惑的是，在各大比赛中频频获胜的剑道天才少女，竟然为了探寻变强的秘密主动申请加入学院。\n到底是什么在吸引她呢。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【流风烈刃】是薰定制的专属魂智能武器，由一把收在鞘中的刀“紫苑“和两把背在身后组合在一起的刀型魂智能武器“烈”“风”组成。\n整体能源是由背后组合体中的源质发生器来提供，战斗过程中会产生持续性的能源供给，在只使用紫苑的情况下理论上能够让薰无限制的战斗。\n通常状态下薰只会使用”紫苑“来作战，机动力并不会受到限制，能够随心所欲的挥舞使出华丽的剑技。\n但这并不意味着薰对“烈”“风”的掌控力不够，正相反，武士的绝招在于不拔之刃，借助魂智能武器和自身身体素质，薰的突进攻击极为可怕，\n有时双刃有时合刃，毫不留情的撕碎前方的敌人。然而这并非薰的全力，似乎还藏有其他的招式，暂时不得所知。",
		file_3 = "对于在洛加尔这座城市隐藏起自己的獠牙的柳生家族，民间的的传闻也是众说纷纭，无法断定哪个才是真相：\n一说古剑术在现代社会已经没有存在的价值了，所以他们选择淡出大众的视线；一说家主重病垂危，整个家族分崩离析，处于存亡关头。\n不论哪一种都暂时无从考证了，但是可以确定的是，柳生家的剑道流传尚未断绝，黑色圣诞爆发前薰仍然活跃在各大剑道舞台上并频频胜出。\n这背后或许是当代家主对科技做出的妥协，亦是对下任家族继承人的试炼，不过单从学院方面截获的数据分析来看，柳生家的背后，似乎还有一个庞然大物在支持着他们，布克丝院长倒是没有过多的惊讶，“月和会？随他们去吧”\n目前暂时进入调查停滞的状态。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "随着对薰的观察记录增加，眼下或许能够判明一些她的入学原因了：争强好胜。实际上确实是能用四个字概括的单纯原因，\n具体描述一下的的话，是因为学院内的“某人”展现出的超越薰的实力，而薰追随她前来探寻变强的秘密，如此古老王道少年漫画的剧情展开。\n一直连战连胜的薰在某次的交手中被曾经的发小轻松击败，心中产生的巨大落差完全将她骨子里的好胜心完全激发了出来。\n虽然不知道这样的打击到底会不会让薰变成一心求胜的简单构造生物，但好歹是为我方增加了重要的战力，暂且继续观察吧。",
		level_6 = 0,
		record = "总有一天，我会胜过你！"
	},
	[21520] = {
		soulid = 21520,
		valuation = "该说不愧是柳生家的家族继承人吗，剑术上的能力确实少有人能够匹敌，身体动作也能看出是经过磨炼的，高速反应下偶尔能做出超乎想象的动作。",
		file_1 = "薰使用的流派，是从柳生新阴流转变而来，糅合了薰对剑道的自我理解产生的另一种类的剑术。\n目前从薰的作战表现来看，是更偏向伤害，破坏的剑道，但却意外的充满技巧感。不论如何，是适合战场的剑道。\n当然，一开始薰修炼的也是正统的柳生新阴流，并非以伤害敌人锻炼剑技才是的神髓，但是见识了足够残酷的战场与非人的敌人后，\n薰的心性产生了变化，清楚知道敌人不再拥有“人性”这一概念后态度也变得犀利起来，固然还谨记着“无刀取”“活人剑”的战法，但更多的时候会选择主动进攻，然而从另一方面来说，战术上或许是略输一筹的。",
		level_3 = 0,
		level_4 = 0,
		resume = "柳生薰，柳生家预定的下任家族继承人，剑术方面的天才，可以说是各方面都被上天眷顾的孩子\n自幼展现出的潜力让当代家主直接定下了薰继承人的位置，虽然从习俗上来说，薰身为女孩子原本是无法作为家主的。\n不过薰的表现确实出众，没有辜负父亲的期望，认真潜修柳生流的剑道后，将其吸收改良，成就了薰的专属剑道流派。\n但是令人疑惑的是，在各大比赛中频频获胜的剑道天才少女，竟然为了探寻变强的秘密主动申请加入学院。\n到底是什么在吸引她呢。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【流风烈刃】是薰定制的专属魂智能武器，由一把收在鞘中的刀“紫苑“和两把背在身后组合在一起的刀型魂智能武器“烈”“风”组成。\n整体能源是由背后组合体中的源质发生器来提供，战斗过程中会产生持续性的能源供给，在只使用紫苑的情况下理论上能够让薰无限制的战斗。\n通常状态下薰只会使用”紫苑“来作战，机动力并不会受到限制，能够随心所欲的挥舞使出华丽的剑技。\n但这并不意味着薰对“烈”“风”的掌控力不够，正相反，武士的绝招在于不拔之刃，借助魂智能武器和自身身体素质，薰的突进攻击极为可怕，\n有时双刃有时合刃，毫不留情的撕碎前方的敌人。然而这并非薰的全力，似乎还藏有其他的招式，暂时不得所知。",
		file_3 = "对于在洛加尔这座城市隐藏起自己的獠牙的柳生家族，民间的的传闻也是众说纷纭，无法断定哪个才是真相：\n一说古剑术在现代社会已经没有存在的价值了，所以他们选择淡出大众的视线；一说家主重病垂危，整个家族分崩离析，处于存亡关头。\n不论哪一种都暂时无从考证了，但是可以确定的是，柳生家的剑道流传尚未断绝，黑色圣诞爆发前薰仍然活跃在各大剑道舞台上并频频胜出。\n这背后或许是当代家主对科技做出的妥协，亦是对下任家族继承人的试炼，不过单从学院方面截获的数据分析来看，柳生家的背后，似乎还有一个庞然大物在支持着他们，布克丝院长倒是没有过多的惊讶，“月和会？随他们去吧”\n目前暂时进入调查停滞的状态。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "随着对薰的观察记录增加，眼下或许能够判明一些她的入学原因了：争强好胜。实际上确实是能用四个字概括的单纯原因，\n具体描述一下的的话，是因为学院内的“某人”展现出的超越薰的实力，而薰追随她前来探寻变强的秘密，如此古老王道少年漫画的剧情展开。\n一直连战连胜的薰在某次的交手中被曾经的发小轻松击败，心中产生的巨大落差完全将她骨子里的好胜心完全激发了出来。\n虽然不知道这样的打击到底会不会让薰变成一心求胜的简单构造生物，但好歹是为我方增加了重要的战力，暂且继续观察吧。",
		level_6 = 0,
		record = "总有一天，我会胜过你！"
	},
	[21820] = {
		soulid = 21820,
		valuation = "琉璃有着优秀的思维处理能力，在战斗中能够时刻监控着同伴的状态并作出对应措施，对于战况的把握也非常优秀，她的能力作为辅助人员来说无可挑剔。",
		file_1 = "幼年时期，琉璃就已经开始在音乐比赛的赛场上展露头角。少女展现出的歌唱技巧稚嫩但是令人耳目一新，而在对于观众“情感”与现场气氛的把控上却宛如老手。 拜此所赐，琉璃的历任音乐导师都对她寄予厚望，业界中看好琉璃前途的人也是比比皆是。在粉丝与相关业者的支持下，琉璃成为了派森地区的著名歌手，在中学毕业后就已经开始进行世界规模的巡回演唱。 这个时候，琉璃参加了魂器学院的适应性测试。在这样外界看来镀金一般的行为中，琉璃通过了与魂智能网络的链接测试并且取得了优秀的成绩。由此，琉璃开始了作为魂器适格者与偶像身份互相交替的生活。",
		level_3 = 0,
		level_4 = 0,
		resume = "琉璃出生一个音乐氛围浓厚的家庭，父母均毕业于音乐院校，但两人擅长的乐器却与各自的性格一般不搭调，自小，她就在架子鼓和小提琴无法融合的音乐中长大。 琉璃自小就展现出绝佳的音乐天赋，无论是摇滚、流行、古典等不同种类的音乐，她都可以驾驭，也顺理成章地就读某座音乐院校。 一切的改变源于人工智能“觉醒”的那天，琉璃所在的学院同样遭到了破坏，自己也不幸被埋入废墟中。在等待救援的漫长时间中，少女经历了深刻的绝望。 不过少女并没有因此崩溃，在获得拯救后，琉璃暗下决心。她想要成为能够为他人带去光明的人，用自己的音乐驱散绝望。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "自小到大，琉璃的父母始终保持着针锋相对的姿态，两人无论是乐器的选择、喜好的食物乃至常看的电视节目都有很大差异，因此产生口角是家常便饭。不过在琉璃严重，那差不多等于两人感情亲密的表现——即使争吵最激烈的时候，两人依旧会为彼此保留一份尊重，导致两人的争吵在琉璃眼中就像是秀恩爱一般。 琉璃对于自己父母的关系非常羡慕，她自身也对恋爱这种事物产生了小小的憧憬。",
		file_3 = "琉璃的歌声之所以拥有如此的吸引力，除了音乐方面的天赋与勤奋练习之外，还与琉璃自身拥有的一种资质有关。 共感（Empathy），深刻地感受他人的情感，并且以知性去理解的能力。配合琉璃自身的表达能力，令少女能够轻易地演奏出打动众人的音乐，在日常生活的交流中也很容易博得别人的好感。 依靠着这样的特质，琉璃不止一次地在两位不坦率的父母之间担任调停角色，即使如此不坦率的两人，在少女天使一般的笑容与温柔但是直指要点的话语下也被打磨掉脾气。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "琉璃希望通过包含爱意的歌声给世界带来守护的希望，因此才成为了偶像。 “哪怕是人工智能,也一定会被打动。”这样的信念一直支撑着她。 但是使用武力还是依靠爱来拯救这个世界，也是琉璃一直在思考的问题。 她没有办法不去承认学员们干脆利落的武力镇压，但她的内心深处仍旧迷茫。",
		level_6 = 0,
		record = "音乐是理解，音乐是祝福，音乐是爱，音乐是连接你我的桥梁。"
	},
	[21920] = {
		soulid = 21920,
		valuation = "沟通起来太累了……我开始心疼她的队友了，一码归一码，安娜的异能还是相当厉害的，如果不总是大喊招式名字，对敌人进行过长的说明的话，基本上还算是个不错的战士。",
		file_1 = "安娜自称弗拉德十七世，弗拉德这个名字来自古老时代的罗马尼亚传说，是夜族的代名词。幻想自己是夜族的安娜，做出了许多匪夷所思的事情。 1：明明黑色最能吸热，但却怕热的安娜依然选择了拿着黑色的阳伞外出。 2：用红葡萄水伪装成别的东西吞饮，却把伊卡洛维吓得不轻。 3：经常白天睡觉，夜晚醒来，但又会因为寂寞去睡回笼觉。 对于以上情况，我们对安娜提出了一些意见，嗯……仅仅只是意见罢了。",
		level_3 = 0,
		level_4 = 0,
		resume = "安娜，背景不明，身份不明，过往记录暂无，唯一得知的仅是她来自耶梦加得。平时喜欢以夜族自称，但并没有摄魂行为，睡眠时间日夜颠倒，为她安排对应的课程有些困难，目前针对安娜的课程安排都是由人工智能进行的。  性格上虽然会他人着想，但那也只是在自己的身份被对方认可的情况下，在来学院之前就和莱拉互相认识，两人存在一些因缘。  暂时无法理解安娜的模仿行为，因为这些行为并没有为她带来任何能力上的增幅，通过调查发现似乎在很久之前有过一种叫做“中二病”的心理疾病，这种病会带给他人过度的幻想和对现实的否定，为了安娜的健康，我们必须继续观察。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【幻想具现】：不知道是中二病影响了安娜，还是这份能力让安娜得了中二病，总之安娜确实使自己的妄想产物变成现实，大部分。\n其实安娜本身的具现能力比较弱，充其量只能具现出小型的火球，但能力的稀有程度确实是顶级的。\n通过适格者测试后，布克丝博士对安娜的精神波动进行过一段时间的观测，为安娜制造了魂器【幻想魔伞】，本质上是对精神增幅的装置。\n目前藉由魂器辅助，安娜的具现能力有了飞跃性的增长，能力范围与精准程度都有所提升。是自由度很高，十分便利的一项能力。",
		file_3 = "安娜对学院内的一些贵族活动产生了兴趣，经常沉迷于插花、茶会等活动。由于个人原因，无法准时地参加，本人对此也有些困扰，所以最近已经将起床时间改成了下午三点。当然……这个时间还是赶不上大部分的课程，不过算了，这也是相当大的进步了。\n另外本人对莱拉的称呼似乎是骑士，一开始认为两人只是中二病的同类，但后来发现里面似乎有些复杂的原由；在询问了莱拉之后得知，曾经安娜在自己最失落的时候用自己的方式安慰了自己。 另外在询问了更多人的意见后，我们发现安娜或许并不是单纯的中二病，那些行为很有可能只是出于关心他人的掩饰。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "关于安娜的部分记录在云端内被追踪到：日期：xxx 下午16:51分：海岸线附近发现大量鲸鱼搁浅，且无论用任何方式诱导都毫无作用。    日期：XXX 正午12:14分：小部分强化人突然失控，对周围的环境大肆破坏。 日期：XXX 下午15:19分：一位外形与安娜相似的小女孩于耶梦加得·七区回收站附近被发现。     能够找到的大致只有这三条，目前我们暂且无法得知在安娜身上究竟发生过什么，只能粗略地计算她能力觉醒的大致时间段。    如果有新的线索的话，我们将会持续上传到云端的。   ",
		level_6 = 0,
		record = "中二病是人对现实的逃避，是对幻想的渴望，安娜却并不是如此，她比谁都接受现实，也比谁都喜欢幻想。喜欢行走在没有阳光的夜晚，那也是因为她对太阳的不认可。她虽然在模仿夜族，可心里却比大多数人类要更了解自己，单方面的理解并不是真正的伙伴；而安娜需要的不是同好，也不是朋友，而是对她做出正确评价的能陪伴在她身边的人罢了。"
	},
	[22920] = {
		soulid = 22920,
		valuation = "相比于其他魂姬的表现，莱拉要更接近一般人，实力大致和强化人士兵相同，在战争的情况下很难成为扭转中战局的士兵，不过她的大部分标准都符合某件魂器……暂且挂名进入学院吧。",
		file_1 = "严格来说，莱拉是Abandoner（遗弃者）的受害者，在父母都是Abandoner的前提下，莱拉从出生便是他们一员，即便是渴望电子仪器，也没办法接触。童年仅有一本记载着游侠的古书陪伴，在同龄人在玩虚拟现实类戏的时候，莱拉却只能拿着木棍进行角色扮演。就算如此，莱拉还是度过了一个较为欢乐的童年。正义感是那本古书带给她的，也是我们这个信息碎片化时代里稀缺的名为感染力的东西。莱拉继承了书中所写的游侠精神渴望着用自己的方式去拯救世界，包括身边的那些遗弃者。",
		level_3 = 0,
		level_4 = 0,
		resume = "莱拉来自派森，是Abandoner（遗弃者）的一员，性格乐观善良，喜好骑士和游侠文化……为了找到游侠和骑的词条，工作人员翻阅了大量的历史文献，通过补充对历史的了解后，终于能客观地评价这点，简单地说就是位渴望着行侠仗义和潇洒行事的一位小姑娘。天真善良是好事，但这份善良在这个时代里什么用都没有，对敌人和伙伴都会伸出援手这一点真希望她可以改改，除此之外，由于过于追求潇洒反而有些本末倒置，做事再稍微认真一些的话会更好。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "莱拉和安娜曾于耶梦加得相遇，根据安娜的描述，那个时候的莱拉正处于情绪低落期，对自己的目标和正义感产生了疑问，甚至一度认为自己只是在自我救赎而已。 对于这样的莱拉，安娜表示实在看不过眼，于是告诉了她：没有办法救赎自己的人，也肯定没办法拯救他人如果需要理由你才会行动的话，那么就成为我的骑士吧。这句话使得莱拉的情绪安定下来，并对自己的目标有更深层次的了解。也是学院里总是以安娜的骑士自居的原因。",
		file_3 = "莱拉期待着潇洒的结尾，比如漂亮地完成了委托之后，拒绝他人的金钱，说着“那就请我喝一杯吧”，又或是在队友走投无路的时候，自己突然从天而降；然而在大部分时候，都会一些小瑕疵，导致莱拉无法做到潇洒；转身想要留下背影，却因为用力过猛原地旋转两圈什么的……作脱帽礼却飞出一只鸽子什么的……因为太过羞耻，那些事情大多数都成为了莱拉的黑历史。像这样不太可靠的她却承担起了学院风纪委员的工作，稍微有点令人担忧……另外，我们察觉到莱拉在帮助他人的时候，会爆发出极高的物理战斗力，但本人却对此毫无察觉，那之后重复测试，数据也和最初的幅度不大。我们推测，莱拉的体内隐藏着一份恐怖的力量，而这份力量仅能为他人使用。 【莱拉的物理作战能力已经重新评估。】",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【正义之刺】：主色调为红黑色的一把骑士剑，但并不能发挥出作为剑的所有特性，其剑内被赋予了骑士的项精神，只有在符合这些规则的情况下，正义之刺才会发挥出作为魂器的巨大威力。因为这件魂器只是院长心来潮的作品，所以在被制造出来的三个月内，完全没有人可以与这件魂器共鸣。这并不是说这件魂器的共鸣条件有多苛刻，只是在这个时代里，骑士本来就是一个罕见的词汇。【记录】：仅一次共鸣，莱拉就彻底掌握了件魂器，并且能轻松地发挥出它最大的威力，无法相信这是由那个最不像骑士的骑士做到的。我们猜测，有着力量却只能为他人所用的莱拉，威力巨大却只能由骑士使用的正义之刺，二者绝对有什么地方是相似的。",
		level_6 = 0,
		record = "生错时代的勇者哟，请怀揣着正义，大步向前吧。"
	},
	[21620] = {
		soulid = 21620,
		valuation = "用球棒把导弹打出去，还真敢想啊，不过那份胆识和毅力已经合格了。要是在战斗中再细心一点就好了，幸好她有一位专精辅助的搭档。",
		file_1 = "无论是什么都要全力以赴，音乐也是，棒球也是。 如果说夏洛特对于音乐的热爱完全来自兴趣的话，那么她对于棒球则是兴趣与天赋的组合。 瞄准投掷而来的白色圆球，聚集全身的力量，猛力但是平稳地将其击飞出场地——完成全垒打带来的成就感令她深深着迷。 夏洛特从未想过成为职业棒球手，但是她对棒球的喜爱并无虚假，只不过—— “比起棒球，我更喜欢架子鼓！所以很遗憾只能让棒球成为业余爱好了！” 不过如果有能够兼顾棒球与音乐的职业，夏洛特还是不介意去试一下的。",
		level_3 = 0,
		level_4 = 0,
		resume = "夏洛特出生在一户富裕的家庭，父母出于工作繁忙一直对夏洛特采取放养政策，家庭关系也算不上和睦。为了吸引父母的注意力，夏洛特性格开始变得叛逆——染发、逃课、泡吧，这些轻微不良行为少女几乎都尝试过，但是父母却依旧对她漠不关心。 在事态进一步升级前，夏洛特选择了放弃，然后将所有的热诚投入到对音乐与运动的爱之中。 在冷漠的家庭环境中用音乐艰难地维持着自己的心，这样的情况直到夏洛特步入中学才有所好转。在那座音乐院校中，她遇见了自己未来的搭档——琉璃。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "夏洛特钟情于架子鼓，原先选择这种乐器单纯是想要用巨响引起父母的注意，不过这种“捣乱”很快就变成了发泄。在将自己的不满与诉求通过架子鼓完美地表达出来之后，夏洛特发现了自己的音乐天赋。 她不在将音乐当做单纯发泄的途径，而是开始用心演奏自己的心声，用音乐抚平自己所受的创伤。 不过在生活中遇到郁闷的事情之后，夏洛特还是很喜欢用架子鼓大闹一场的。",
		file_3 = "夏洛特很容易沉浸在自己的世界中，每次开始演奏的时候几乎是旁若无人。 特别是少女选择了架子鼓这样破坏性强的乐器，在音乐院校的时候没少遭到他人的投诉。 急躁又有些孤僻的夏洛特也因此被他人所疏远，少女几乎从来都是孤身一人——直到她遇见了琉璃。 能够坦诚地对待所有人的琉璃用行动攻破了夏洛特的心房，两人成为亲密的好友，甚至更进一步组成了乐队。 琉璃的存在填补了夏洛特心中的某片缺口，在长久的相处后，夏洛特将琉璃当成了自己家人一般亲近的存在。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "与琉璃一同正式出道后，夏洛特凭借着或是狂野或是帅气的音乐表演取得了巨大的人气。 但即使女儿获得这种成就，父母之间的关系也依旧没有好转，也没有对夏洛特投入多一份的爱，或许那两人之间并不存在真正的爱吧。 对此，夏洛特也并无怨言，在这背后隐藏着怎么样的故事，她已经没有兴趣了。与自己一样，父母也有追求各自期望的生活的权力，用自己的存在去束缚他们等于是剥夺了两人的自由。 只要自己依旧爱着他们就足够了。 但是，果然还是希望有人爱着自己。",
		level_6 = 0,
		record = "“男朋友啊……嗯，首先一定是要围着我团团转的，其次最好喜欢我的音乐。再然后……一定要喜欢小孩子。”"
	},
	[22520] = {
		soulid = 22520,
		valuation = "在现实中看到武术还是第一次，作为未强化的普通人类，居然能空手做到击穿钢板，这着实让人感兴趣；或许我们可以以此为契机，在全学院推行武术这门新课程。",
		file_1 = "抛开麟表面上的爽朗和坚强，其实她本质就只是个处于青春期的惹人怜爱的少女。喜欢用“不可以让他人偷武术”为由，躲到没有人的地方看恋爱小说，然后又因为总是不小心将小说里的台词说出口而导致事情败露，自己却全然不知……虽然这些是麟作为女孩子可爱的一面，但请务必不要在本人面前提及这点，否则……经过千锤百炼的拳头打在上还是挺疼的。",
		level_3 = 0,
		level_4 = 0,
		resume = "麟的家庭背景是派森的一个武术世家，说实话，武术这种东西在今天早就成为传说一样的存在了，所以当我看到简历的时候，心里更多的是对她的怀疑；不过麟用实力证明了一切，她告诉了我们，人类即便只依靠自己，也能做到开山劈石。性格上，麟比较，嗯……豪爽？或许这个词语不是很合适，但麟确实带着一丝男孩子气，同时她也渴望着恋爱样酸涩的事情；只不过麟个人认为自己不适合那样的角色，所以一直以来都在隐藏着真正的自己。但是在学院生活，如果处处隐藏的话，会给自己带来巨大的压力，这一点希望她可以好好地思考一下。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【截拳道】：起源于古老时代的一门武术，在那个没有人工智能泛滥的时代里，人类依靠着名为武术的技艺锻炼着己的身体，做到强身健体、比赛竞技甚至还能投入战斗。而截拳道正是那个时代里最有名的武术，将其他武术的优点融会贯通，转而变自己的一部分，可以说，每一位截拳道的武者所使用的截拳道都是完全不同的。而麟的截拳道则是全面型的，攻击的时候防御，防御的时候进攻，让对手完全跟不上自己的战斗节奏，甚至能从各个盲角进行攻击。我们使用了人工智能对麟的招数做出了演算，其演算结果竟然高达三百多种，刷新了我们对普通人类的认知。",
		file_3 = "通过麟的对战记录，我们发现了武术中存在某种卸力的能力，这一点无论是在麟和斯卡兰斯战斗时，还是在对难以发力的沼泽地时，皆有体现。越是研究这些，就越能体会到武术的魅力，可惜的是麟本人并不愿意将武的奥秘公开出来，我们也只好尊重本人的意见，将这些数据暂时存入深层档案。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "过去的五年时间里，在库库尔坎、耶梦加得、尼格霍德、甚至是奥杜因都发现了麟和其父亲的移动记录；据人说明，麟的童年确实是跟着父亲到各个不同的地区进行武术的修炼，但那个时候的系统还是由【伊甸园】进行地区移动的相关审核，果没有在同一地区居住满三年，是无法移动到其他地区的……更不要说，移动到审核更为复杂的库库尔坎和尼格霍德地区。或许从五年前开始，模拟智能网络就已经开始深入各大系统了……",
		level_6 = 0,
		record = "弱者从外寻求力量，强者从内迸发力量，无论何时，我都会用这双拳头，守护好那些重要的人的。"
	},
	[22720] = {
		soulid = 22720,
		valuation = "斯卡兰斯在模拟战中展现出的强大的控场能力，仅仅靠自身一人就将成群的训练机体压制住。在不考虑留手的情况下也能轻而易举地将敌机破坏，不愧是在那个混乱之城担任过治安官的人。",
		file_1 = "斯卡兰斯出生于巴哈姆特本地的水手世家，自小就跟随家族船队出海捕捞。 幼年时在船队中的经历让斯卡兰斯掌握了绝佳的平衡力与高深的操船技巧。 而她本人的水性也是绝佳，只要提前做好准备，斯卡兰斯就算是鲨鱼也能徒手驯服。 此外，斯卡兰斯有一位妹妹同样加入了魂器学院，在这位妹妹面前，她总是想要努力表现出自己成熟温柔的一面，不过大部分时候都会因为紧张的原因闹出乌龙。",
		level_3 = 0,
		level_4 = 0,
		resume = "斯卡兰斯·格雷特，进入学院前于巴哈姆特担任治安官，身体素质优秀，性格正直。 在巴哈姆特的事件后，斯卡兰斯意识到只是维持治安并不能从本质上改变巴哈姆特的混乱，所以她加入了魂器学院，寄望于击败人工智能并且最终执行自己的“正义”。 斯卡兰斯的性格沉稳又不乏热情，这使得她拥有了独特的魅力。偶尔展现出的笨拙一面也能够让人心生怜爱之情。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在远离海洋的天空中，斯卡兰斯最大的爱好出海被限制住了，虽然在学院中的人工湖也能够驾驶快艇，不过终究缺少了一些风情。作为替代，斯卡兰斯开始学习手工艺品的制作。 其中，她最喜欢制作船的模型，虽然手法笨拙，零件的接合总是毛毛糙糙，成品总是惨不忍睹，但是少女从拼装模型这一爱好中找到了乐趣。 就算现在的作品难以入目，斯卡兰斯也不会放弃，只要一直努力下去的话，总有一天能够制作出让大家惊叹的作品……吧？",
		file_3 = "在充斥着暴力与混乱的巴哈姆特，治安官绝不是轻松的工作。 除了必要的镇压犯罪外，为治下的民众树立信心，调解城内势力的关系乃至策划一部分节日活动都是治安官的工作。 凭借着自己的手腕与气势还有与军方建立的关系，斯卡兰斯在巴哈姆特站稳了脚跟。 即使是巴哈姆特的黑帮们也不得不承认斯卡兰斯处事的平滑——不过这也绝对不代表她会对发生在眼前的恶意妥协。 在宽容地对待他人的同时，恪守着正义的底线，这就是斯卡兰斯，冷静而又热诚的巴哈姆特治安官小姐。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "以一个词来形容斯卡兰斯的话，用“豪杰”应该比较贴切。 自身拥有优秀的才能，无论是武力还是智谋都十分优秀，做事不拘小节，同时有着能够令他人佩服的气节。 这样的人，非常容易成为万众瞩目的焦点。 不过对于斯卡兰斯自己来说，又怎么样呢？ 驾驶着心爱的帆船在世界各地旅游，见识不同的风土人情，结交各种各样的人物，然后在感觉疲累的时候回到故乡的小庄园中休憩——这才是斯卡兰斯真正追求的生活。 但是，这样的梦想因为叛乱人工智能的存在而变地难以实现。 斯卡兰斯不可能放下自己熟悉的人们，自己重要的妹妹，独自一人享受自由的天地。 所以，她加入了魂器学院，期望在这里找到能够结束这场世界性灾害的方法。 然后，总有一天，独自一人——或者与自己喜欢的人，一同乘上心爱的帆船，扬帆远航。",
		level_6 = 0,
		record = "“如果每一样事情都要斤斤计较，那就忙不完了。多把注意力放在应该关心的地方吧。”"
	},
	[22320] = {
		soulid = 22320,
		valuation = "在与魂智能机兵的协作战斗中展现出了极高的天赋，值得培养。",
		file_1 = "认识到人工智能具备无限的发展可能之后，艾莉卡理解了父母是在为人类造福的伟大事业献身。于是立志成为一名受人尊敬的机械师，为了能帮上父母的忙，也为了将来设计出像喵球一样优秀的人工智能，陪伴跟自己一样孤独的人。所以经常可以看到，艾莉卡乖巧地待在父亲的家庭工作室里，一声不吭的自己鼓捣着做一些玩意儿。不仅活跃了思维还提高了创造力和想象力，看到自己亲手做出来的成品后内心也会充满了成就和自豪感，并发展成了爱好。",
		level_3 = 0,
		level_4 = 0,
		resume = "艾莉卡的父亲是一位小有成就的智能人工智能工程师，在地劫战争之后，与艾莉卡的母亲一起成立了一家科技公司，致力于研发独立于之前的人工智能网络，能为人类造福的新型高智能人工智能。因为工作繁忙，父母渐渐减少了对艾莉卡的陪伴。为了弥补对女儿的情感缺失，艾莉卡的父母专门设计制造了一款具备中级智能的人工智能—————喵球，让喵球代替自己陪伴艾莉卡。配备了情感感应系统的喵球能分析和同步艾莉卡的情绪，只接受来自艾莉卡的命令。在父母不在家的时间里，可爱而富有灵性的喵球成了艾莉卡的唯一玩伴。也是在与喵球的接触中，艾莉卡对人工智能产生了浓厚的兴趣，从而学习起了关于人工智能的知识。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "平静的日子没有过多久，一只人工智能军队攻入了城市，开始肆意破坏、袭击人类。暴走的人工智能闯入了艾莉卡家中，艾莉卡的父母为了保护她，被人工智能残忍的伤害了。人工智能本来想连同艾莉卡一并除去，但喵球挡在了幼小的艾莉卡面前，此时人工智能像是收到新的命令一般，放下了屠刀，突然扬长而去。艾莉卡茫然地看着双亲一动不动的样子，任凭如何呼喊也无法唤醒，原先开朗、活泼的性格已经随父母的逝去而消失不见。",
		file_3 = "经历过失去父母和失去喵球的痛苦，艾莉卡留下了难以抹去的心理阴影。变得有些孤僻，甚至害怕社交活动。在同情艾莉卡遭遇的同时，院长发现一款自律型魂器与艾莉卡产生了共鸣，但对喵球仍抱有感情的艾莉卡不愿接触新的机器人。最后院长突发奇想，想要将喵球残存的记忆芯片和情感模块移植到自律型魂器身上。艾莉卡得知后十分高兴，院长仿照喵球的原型，改造了魂器，在院长和艾莉卡的共同努力下，移植工程完成得十分成功，喵球最终在另一个身体中获得了重生。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "因心理创伤的问题，艾莉卡拒绝了学院安排照顾她的人，只接受喵球的照顾，导致过度依赖而失去自信甚至自我判断能力，遇见什么事都要与喵球眼神交流以后才能拿定主意。虽然时不时会哭一下鼻子，但艾莉卡的承受能力是很强的，面对他人语言甚至是身体上的攻击绝对不会反击。可一旦超过了她所能接受的范围，艾莉卡会陷入极度的自我封闭，以这种心理防御机制来回避环境以降低挫折感。",
		level_6 = 0,
		record = "请问有看到我的猫球吗？"
	},
	[22820] = {
		soulid = 22820,
		valuation = "爱丽丝的单兵作战能力极其薄弱，在面对两到三名普通士兵时就已经呈现出明显的劣势；不过在军事上，爱丽丝表现出了惊人的实力。  单靠指挥就让五名原型机体歼灭了二十架人工智能机兵，且在战斗中还在不断进化，学习能力高，值得期待。",
		file_1 = "鲁比克财团是世界知名的尖端科技开发集团，总部于尼格霍德，其势力范围包括：耶梦加得、莱希和库库尔坎，综合影响力排行第一，据说现在学院内的多项计划也有鲁比克财团的参与，目前学院已经有被渗透的可能性，故爱丽丝的部分档案转移到下一层。 爱丽丝的天才性是毋容置疑的，但这份天才却不是这个年纪应有的，她能看到比别人更多的东西，也更能受到外界的影响，不过好在交友环境的优良，让她变扭的个性在一点点被矫正，又或者……被刻意隐藏？ 优秀的成绩是她的证明，也是天才的附属品之一，目前推荐爱丽丝参与到院方某项计划的申请已提出。",
		level_3 = 0,
		level_4 = 0,
		resume = "注意：爱丽丝出身于鲁比克财团，因鲁比克财团对魂器学院的投资比例高达百分之三十，故部分资料转移至深层档案Ⅱ及以下，请权限不够的人员不要故作尝试， 否则将会面临：账号冻结、人事调动、撤销职务、短期监禁等风险。 爱丽丝是一位年龄尚小且可爱自立的小女孩，在无聊的时候喜欢玩魔方，对不可思议的事物表现出高度的好奇心。除此之外，不知是否和家庭环境有关，爱丽丝总是喜欢在言语中隐藏攻击和讽刺，在利用年龄和外表作为武器的前提下，也没有多少人会将爱丽丝的话放在心上；但是我个人认为这是个非常不好的习惯。 现阶段于战略指挥班学习，已和魂器共鸣契约。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "根据多项资料判断，爱丽丝是家族所特意培养出来的试管婴儿，基因当中的学习与智慧的钥匙被适当调整；从上次体检的结果来看，这种调整会给爱丽丝带来发育缓慢、失眠等多种影响，且这些影响可能会伴随其一生。 处于人道角度和多方因素，目前这件事并没有告之爱丽丝本人。",
		file_3 = "在早期，常常能看到爱丽丝在各种地方玩魔方，起初认为只是兴趣，但后来发现，爱丽丝的魔方上有着许多英文字母；根据人工智能的观察记录推断，爱丽丝喜欢问魔方问题，并随后用高超的魔方技巧拧出自己想要的回答，是一种极度寂寞的外在表现。 幸好随着爱丽丝朋友数量的增加，这个行为的次数在逐渐减少。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "鲁比克财团让爱丽丝入学的要求有以下三点：    1：确保爱丽丝的生命安全以及多项正常学生的权利，不可过多限制其发展和自由。 2: 必须参与二至三项学院方的核心计划当中，并承担计划中的重要角色。 3：在学院授业时间内至少要取得多项成绩，并且授业结束必须立即返回家族，不能以任何原因被滞留到学院中。 我们同意了第一条和第三条的要求，但对第二条依然有所存疑，经过多轮谈判，我们将参与到核心计划的数量减少到了一项。    让一名毕业就会脱离的学生参与核心项目原本是不可能的事情，但出于对爱丽丝的肯定，我们还是决定让她参与到部分计划当中。 ",
		level_6 = 0,
		record = "正如误入不可思议国度的那位爱丽丝一样。 这边的爱丽丝也渴望着不可思议的事情，那是她唯一还像个孩子的地方，也是对奇迹的某种期待。"
	},
	[22120] = {
		soulid = 22120,
		valuation = "伊卡洛维的实战能力很强，天生附带的异化让她可以在各种场合发挥实力，但本人的战斗意识太差，战斗风格粗暴，不适合团队作战和精密任务，想要让她成长必须要长期的思想培养。",
		file_1 = "在《弗洛伊德结构理论》中将心理拆分为本我、自我、超我三大部分。而在她这边，本我的部分要远超其他二者总和，简单来说就是想到什么就做什么，对自己没有什么较大约束，从侧面也可以看出伊卡洛维善良的本性。不过也因为这点，伊卡洛维在战斗的场合会陷入极度疯狂的状态，以至于敌我不分。 自我约束力弱的负面体现在她生活的方方面面，只要有喜欢的东西就会贴上去，讨厌的东西会马上动手解决掉。这样直率的个性不适合执行复杂的任务，建议从基础部分开始学习。",
		level_3 = 0,
		level_4 = 0,
		resume = "伊卡洛维·罗伊汀，库库尔坎出身，因过去母亲遭遇了辐射泄漏事故，导致腹中的伊卡洛维异化，具备了动物的野性与力量。但这并不属于变异的范畴，现今社会对辐射早已做到了清洁化、去污染化，所以可以断定那场事故并不是伊卡洛维异化的主要原因。 伊卡洛维十分天真乐观，身边的人对她都持有正面印象，不过因为她的精力过于旺盛，也会让人有些跟不上她。精神方面略微稚嫩，是那种在陌生环境就会不安，会主动寻找安全感的孩子。 现阶段十分依赖班长，经常跟着他出入各种场所，近期对班长的风评将会重新统计录入。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "伊卡洛维的依赖性可能是源自童年的被抛弃经历。当时，她的父母还不能接受这样的一个孩子，两人一致认为没有伊卡洛维对今后的生活会更好，所以就将她遗弃在了两公里外的一处废弃机械工厂内。 凭借着异化后的嗅觉，年幼的伊卡洛维依然找到了回家的路，因为愧疚，父母最后还是没能忍心将她再次抛弃，好好地将其抚养长大。 结果虽然是好的，但这个经历却导致了伊卡洛维心理上的孤独和恐惧。 目前，班长这一角色正好弥补了她对安全感的渴望。",
		file_3 = "从伊卡洛维身上发现了名为“野性”的东西，这就是导致她在战斗中会陷入狂暴状态的罪魁祸首。我们尝试用药物压制“野性”，但可惜因为做得太难吃了，导致她没能完整吞咽下去。 伊卡洛维的不配合，使得药物的数据采集十分艰难，希望下一次医疗部门能做出番茄味的药丸来……",
		level_7 = 0,
		level_2 = 0,
		file_4 = "对伊卡洛维的基因检查结果为：基因片段中有两组被精密的手术重新组合，导致部分身体特征出现返祖现象。 可能……伊卡洛维在无意间成为了某个组织的牺牲品，不过在调查伊卡洛维家庭背景和父母人际关系的时候，并没有找到可疑的对象；我们对此提出了两种假设：1、只是当年的某个妇科医生的一时兴起。2、某些隐藏在社会深层的势力还在筹备着属于自己的特殊军队。 无论哪种，都不是什么好事……",
		level_6 = 0,
		record = "因为什么都知道，所以才要装作什么都不知道，否则又会像小时候那样被抛弃掉吧？ 大家都在笑着，所以……哭泣的人只要有我一个人就好了。 这是什么都做不到的我，唯一能够做到的事情了……"
	},
	[22620] = {
		soulid = 22620,
		valuation = "芙蕾的战斗足够具有诗意，优雅纷飞的热能浮游炮宛若落樱飞舞，但在体术的方面很显然还不足以应付前线的作战。",
		file_1 = "芙蕾的家族，与其称之为家族，不如说与旧世的皇族更为接近，所以芙蕾偶尔也会被称为“皇女”。叛乱发生前，洛加尔地区一直由这个家族来统领。当然，他们的做派毫无瑕疵，行事磊落，不知不觉间就积攒了足够的名望和公信力。隐世于洛加尔的不少家族，都选择以结盟或归附的方式寻求庇护。叛乱发生后，联盟也曾以芙蕾的家族为首进行过抵抗，只不过在付出了惨痛的代价之后，也仅仅只让洛加尔地区稍晚一天才彻底沦陷。联盟支离破碎，皇室明面上的力量近乎全灭，但也算保全了一部分的传承，从此销声匿迹。",
		level_3 = 0,
		level_4 = 0,
		resume = "来自洛加尔地区拥有最高统治权家族的芙蕾，在洛加尔沦陷之后，\n本不想作为继任者继续权力的掌控，但为了确实的结束这种不应存在的战争，靠着过去的威信统合了洛加尔的大小家族，形成了一股聚合的家族势力，\n通称“月和会”，接受旧识的相约进入学院，并将月和会发展为拥有足够能力的情报组织。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【花前月下】是作为正在研制中的自律式魂武的第一代试作品，通过比较庞大的类外骨骼装置和使用者相连\n同时作为与之相匹的九枚浮游炮装的载体，作战时，通过内置于类骨骼装置的魂武核心辅助使用者控制最大九枚浮游炮\n浮游炮装可以通过能量存贮装置进行热能射线和浮游飞行等动作，但是一旦耗尽就必须通过载体骨骼上设置的能量罐进行补充\n所以从使用难度上来说，要求使用者必须有足够强大的脑处理能力，才能在辅助下实现一对多的控制。\n顺带一提即使是现任使用者芙蕾一次最多也只能控制6枚浮游炮装，不知是否有人能够展现它全部的实力呢？",
		file_3 = "月和会，无法明确指出具体成员，也无法了解它从何时开始活动的神秘组织。但不可否认的是洛加尔正有一股势力蠢蠢欲动。\n芙蕾学员入学后，学院方面才得以窥见月和会的全貌，藉由皇室统治留下的强大的威信力组织起来的地下反抗组织，就是它的本体。\n芙蕾虽然对于组织与权柄的管理没有表现出很大的兴趣，但为了停止这种无端而起，本不应该存于世上的战争。\n她选择再次联合了表面已经千疮百孔的各个家族，依靠军方给予的部分援助，在短时间内重新成长为一股新生的势力。\n目前的月和会不具备有很强的作战能力，但已经是情报体系完全成熟的情报组织，也有不少有魂武适格天赋的学员跟随芙蕾进入学院。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "虽然被称作“皇女”，但事实上芙蕾对于权柄之事毫不在意，军方接管洛加尔后也曾明确表示过自己不会以继承人的身份接下管理城市的职务\n对于芙蕾来说，极尽风雅之事才是人生乐趣所在，而如果像旧世那般勾心斗角，那么实在是可惜。当然，对于旧世的文献和诗词，芙蕾也算是小有研究。\n最喜欢的事莫过于闲暇之余，赏一树春樱，品一轮明月，也难怪有人把在樱树下遥望明月的芙蕾说成是天界的一枝神樱落下的一瓣。\n或许这样的说法才是对芙蕾最恰当的描述。",
		level_6 = 0,
		record = "那棵樱花树，今年也会盛放的吧。"
	},
	[22020] = {
		soulid = 22020,
		valuation = "风魔 胧的单兵作战能力非常强，擅长潜入，能够胜任远途的机密任务——在地形不复杂的情况下。",
		file_1 = "天赋异禀的胧对父亲教授的知识吸收的很快，不知不觉间已经具备了成为一个正式忍者的资格，胧的表现也一直没让父亲失望过。 “是时候考验一下胧的所学所得了。”父亲给胧夜安排了一场成为正式忍者的试炼——————让胧夜远离家门，只身前往自己同为忍者一族的前辈家中，挑战实力在自己之上的前辈。 在短暂的告别女儿后，父亲安然地等待着前辈那里的消息，“亲爱的你难道就一点都不担心自己的女儿吗？这可是她第一次出远门啊！”一旁的母亲非常担心自己的女儿。 “会有什么问题？不管能不能战胜自己的前辈，这对她来说都是一次成长，而胧是一定不会让自己失望的。”父亲对自己的教育充满了信心。 母亲白了父亲一眼，似乎早就知道会得到这样的回答，终究是放心不下胧，还是按照为人父母的规范，事先将忍者家族的名号和联系方式写了下来包好交给了胧夜。 常理说应该是不会出现什么问题，直到高傲的父亲接到了自己女儿从某个商场里打来的求助电话———————胧迷路了…… 在父亲眼中近乎完美的胧，在方向感这方面却意外的很差，很快就迷失在了这个独立于家门以外的世界，而糟糕的是自己居然连回去的路都不记得了。 加上由于城市化的发展，多年未出过家门的胧更加不认识这条已经被现代化科技改造的面目全非的大街，在这条大街上转了不知道多少圈后，还是没有找到回去的路，东张西望的样子甚至被路过的警官当成了可疑人员。 警官拦下了胧进行盘问，了解情况后，问她父母有没有在临走的时候交给她什么东西，胧便拿出了一个写有应急两字的锦囊。之后就是警官带着胧去商场打电话的故事了…… 无论忍术方面有多么高的造诣，胧还是个彻头彻尾的路痴，这一点连看着女儿长大的父亲也没注意到。",
		level_3 = 0,
		level_4 = 0,
		resume = "风魔 胧的家庭源自一个没落的忍者世家。为世人遗忘的忍者一族，虽早已退出历史舞台却仍然想在这充满战争和动乱的世界找回一席之地。 胧的父亲就是深受这种宿愿影响，认真而严肃地要求胧也成为和自己祖先那样优秀的忍者，将来扬名立万，为家族做贡献。 于是，在父亲严苛的教育和训练下，胧慢慢成长为一个见习忍者，一切似乎都在朝着令人满意的方向发展，胧夜父亲对自己的女儿充满了期待。 被寄予厚望的胧最终被迫切断了和同龄伙伴们之间的来往，终日沉浸在无休无止的封闭式训练和忍者意识培养中，渐渐养成了独来独往的性格。 “她会成为一个出色的忍者的！”除此之外，都不是父亲会关心的事物。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "打完电话后，警官嘱咐好胧夜待在原地不要走动后便离开了。过了一会儿，胧夜等待了父母许久，有些无聊，便张望起了四周。 衣食无忧、一切都在父亲管控之中的胧夜自然不会知道商场这种东西是做什么用的，只看到进去时两手空空的人们出来时却带着各种道具满载而归，看着人们幸福的表情，胧夜很好奇这个地方究竟有什么魔力。 于是，身为忍者的胧夜没能忍住对新鲜事物的好奇，跨入了通往“异世界”（商场）的大门，在琳琅满目的货架间和如迷宫般魔幻的走廊里，觉醒了某个不得了的属性。 等到父母赶来，公用电话前早已没了胧夜的身影，最后在工作人员的指引下，她们在商场的角落里找到了正抱着一堆刚从货架上拿下来的，精心包装好的商品不肯放手的胧。",
		file_3 = "胧的父亲也试过了很多方法，比如带着女儿四处走走，熟悉熟悉街道和环境；买了手机，安装了最新的定位导航系统；拜访了最权威的医生…… 但依然没有效果，熟悉完街道后，过几天胧再走一遍，又忘了个精光；使用导航系统虽能一时派上用场，但毕竟不是长久之计，危急关头总不能停下来慢慢盯着手机引路吧；就连医生也是摇摇头，说是此病无药可医…… 独自战斗的确没什么影响，但撤退、追击、寻敌等等都是问题……看到胧这个状态，父亲无奈的明白，这样的胧或许是个优秀的忍者，但可惜的是依然不能独立作战，还是需要团队的支援。 然而家族这边都是独来独往的作风，一旦行动起来根本无暇顾及胧。随着胧的成长，父亲能教的已经不多了，自己对胧的教育似乎陷入了瓶颈，可是又找不到合适的前辈接替自己教育。 可是该上那里去找一个实力过硬，对女儿的成长有益的团体呢？胧的父亲烦恼着，直到看到了魂器学院的招生广告……",
		level_7 = 0,
		level_2 = 0,
		file_4 = "入学后的胧虽有和同学们打好关系的意向，但不愿刻意表现自己的性格且不知如何表达感情的胧夜一直是班上比较文静的学生，相对于班上那些经常闹得击飞狗跳的同学，胧夜的存在感一度低的可怜。 加上独来独往的习惯使她经常缺席一些团体活动，以及忍者特有的气质，胧成为了一个幽灵学员的存在。",
		level_6 = 0,
		record = "嘘，暗夜的使者降临了。"
	},
	[23120] = {
		soulid = 23120,
		valuation = "真是出色啊，很久没有看到过这样的学生了，虽然身体的各项数值较为平均，但是那同时操作数十台机甲的身影真是让人记忆犹新。沉着冷静的性格和进退皆可的计划，比那群小混蛋都要可靠得多，暂时想不到什么意见，可以让她考虑一下当教官吗？ ",
		file_1 = "索菲亚能够制作出机器人、强化部件、武装外骨骼等各式各样的军用、民用设备。在鲁比克财团担任顾问期间，索菲亚用最少的经费开发出了世上最强的脉冲武器之一，被高层一致认为是无论如何必须要保留下来的人才。但目前，索菲亚似乎已经脱离了鲁比克财团，促使这件事发生的原因，以及脱离的手段至今尚未得知。不过通过索菲亚的个性很容易就能得出，两方在合作的期间发生了某件不愉快的事情，导致了商业关系的破裂。",
		level_3 = 0,
		level_4 = 0,
		resume = "来自奥杜因的天才少女，鲁比克财团的前技术顾问，掌握着高超的制作技巧，虽然是宅女不过性格并不内向。重视效率所以不喜欢讨论“无意义”的复杂话题。但是如果话题的内容与机械相关，那就不得了了，索菲亚对于机械的执着堪称狂热。不过如果在此时将话题转向诸如青春啊，恋爱啊之类的酸涩话题，索菲亚会马上宕机，变成只会迎合对方的机器人。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "索菲亚的行动模式十分微妙，看上去像是在为他人着想，但实际上围绕着的核心部分都是自己；举个例子：在班长入学的时候，索菲亚自告奋勇地承担了带领班长熟悉学院的工作，但是带去的地方都是自己感兴趣的……比起“导游”更像是在进行普通的社交。\n在战斗中的时候，索菲亚习惯以自己为中心操控机器人进行战斗，即使与其他学院组队，也会建立以自己为核心的战术。\n索菲亚随身携带的机器人——分别叫做麦克斯韦、伽利略与爱因斯坦，全部都是小型机体。小体型的机器人便于维护，也不会对自己的科研预算造成负担，在日常生活方面也可以提供更大的帮助，所以索菲亚几乎不会去制造大体型的机体。",
		file_3 = "以这种年纪担任鲁比克财团的技术顾问，并且在各个科研领域展露头角，索菲亚可谓是万众瞩目，如果她选择留在鲁比克财团，迟早有一天能够进入财团的核心阶层。\n然而，鲁比克财团的行为一次次地让她失望。将机器人用在地下拳击赛，结果伤及人命；把装备着强大兵器的佣兵投入到争夺地盘的乱斗中，造成大量伤亡。\n索菲亚不介意自己制造的机械被用作军事用途，她自身也非常喜欢兵器开发，但是——\n不是将她制造出的机械用作与人工智能的战争，用在保护无辜之人上，反而借此以肮脏的手段掠取财富，索菲亚对此是无论如何都不能容忍的。\n由此，索菲亚单方面解除两方的合作条约，与鲁比克财团分道扬镳。而在她的友人——鲁比克财团的大小姐爱丽丝坚持下，财团也没有对其进行追究。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "以能够自由学习魂智能网络的技术为条件，索菲亚与魂器学院定下了时长几乎是“终生”的雇佣契约。\n随后，很长一段时间里，索菲亚几乎断绝了与外界的联系，一心一意投入到科研与“工作义务”之中。\n用自由为代价，少女想要追寻的究竟是何物？\n答案是——为了找回逝去的所爱之人们。\n索菲亚的父母，亲友，老师全部在那名为“黑色圣诞”的灾难中失去了生命。\n少女想要完成能够扭转时间，或者让亡者复活的机械，将自己所爱的人们带回身边。\n哪怕那只是妄想也无所谓，如果不找到能够坚持的，能够支撑自身的事物，名为“索菲亚”的存在迟早会崩溃。",
		level_6 = 0,
		record = "“我不希望任何人从我眼前消失……不，就算是消失了也没关系，我一定把你们都找回来的！”"
	},
	[21320] = {
		soulid = 21320,
		valuation = "这么冒失的女孩是怎么来到考试现场的？而且在实战测试的时候摔倒了三次，真是让人担心，不过她的枪械天赋真是和性格完全成反比，测试射击一共二十轮，期间替换枪械六种，从手枪到狙击枪，每轮都是满分，值得培养。 ",
		file_1 = "【定点移动】：将物体从固定坐标直线送到另一个固定坐标的能力，详细解释为：将接触到的物体通过各种方式发射出去，与视野范围内确定的预设点进行百分百重合的能力。是一项绝对能让能力者百发百中的作弊能力，历史上出现过该项能力的人记录在册的仅有三名，因为时间久远，许多数据都已经严重损失，故我们需要对千竹进行相应的能力测试。\n测试1 道具：年代久远的柯尔特响尾蛇左轮 内容：击中五百米外，放置在玻璃罐上的樱桃。 测试结果：命中 详细：樱桃正中央被击穿，玻璃罐完好无损。\n测试2 道具：鲁比克动力型脉冲枪 内容：遮挡住一只眼睛，在不瞄准的情况下要求击中一千米外的羽毛 测试结果：命中 详细：羽毛被烧焦，羽毛靠着的墙壁也被击穿。\n测试3 道具：一号3000型自动狙击枪 内容：关闭自动狙击模式，在遮盖双眼的前提下，击中五百米内的机器人 测试结果：未命中 详细：子弹击穿了练习场的天花板。\n根据以上的测试看来，初步可以认为，触发这项能力的条件是被视线锁定，只要搭配简单的侦查设备，千竹就是最强的狩猎者。",
		level_3 = 0,
		level_4 = 0,
		resume = "千竹，户籍派森，天真可爱，日常生活中十分冒失的九岁小女孩；喜欢帮助他人，但总会因为自己的冒失，导致自己非但没能帮上对方的忙，甚至还越帮越忙……   因为担心打击到千竹的积极性，所以一般大家都不会指明这一点，这反而使得她更加无法意识到自己的问题所在，所经之处都是一片狼藉。很容易就被原谅，也就意味着，很难得到夸奖……但愿有一天千竹可以获得他人的肯定吧。   除此之外，千竹热爱动物，虽然在这个时代有不少虚拟演算的动物，但千竹却更喜欢现实中存在的动物。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "千竹的熊猫名叫团子，从她的简述来看，团子是在一次拍卖会中，被自己解救下来的，那个时候的团子腿上还受了很严重的伤，为了让它痊愈，笨拙的千竹想了各种各样的办法，都没能成功，最后是千竹的父亲将团子的伤口治好，也许是被真诚打动，从那以后，团子便开始跟着千竹行动，千竹一直照顾着团子，一人一熊就这样一起生活到了今天。\n不过从学院内的观察来看似乎和千竹说的有所出入，团子在和千竹的行动中，十二次中有八次都是团子将她从危险的地方拉回来，另外四次则是团子抢先将危险因素排除；这个熊猫跟着千竹的理由绝对是因为放心不下吧……我们不禁这样认为。",
		file_3 = "千竹的父母都是普通人，父亲是一名兽医，母亲是普通的上班族，可以理解千竹对动物的喜欢，但【定点移动】这个能力的由来，我们却无法理解。因为千竹的家族中，并没有出现过特殊能力者的特例，整体基因趋势偏向缓和，要突变出某种能力的话，至少还要遗传八代以上才有一丝可能性。另外，派森整体并不在战争范围，辐射、空气和水质监测都是正常值，千竹一家也从未从派森往其他城市移动过。因环境造成的间接变异几乎是不可能的。\n结合【定点移动】这份能力的稀有性，我们开始怀疑，这项能力是可以继承，且有人故意把它赋予了千竹。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "结合多方影像资料和数据比对，我们得出了一个谁都无法接受的事实——千竹的能力是被团子赋予的。确实，特殊能力并不会只出现在人类身上，只不过由于动物的数量在当今社会上十分的稀少，所以有关特殊能力的动物就更加罕见了，不过正因为罕见，我们才能确定团子就是原先【定点移动】的持有者。\n根据影像资料显示，在派森的原自然公园保护区，曾出现过一只扔竹子百发百中的熊猫，后来因为盗猎者的出现，这只熊猫的消息暂时消失，大约过了一两个月，枪械天才少女的传闻才逐渐传开。\n另外用影像上熊猫身上的伤口，和团子进行比对的结果为：93.7%。\n已经基本可以确定千竹的能力和团子有着必然的关系。",
		level_6 = 0,
		record = "美少女与小可爱！"
	},
	[23220] = {
		soulid = 23220,
		valuation = "从未见过的战斗方式，撕咬、拉扯、碰撞……宛如一只野兽那样；被她击倒的人工智能全部都呈严重损毁状态，根本无法依靠修复来重新投入使用……这一点让人有点烦心。",
		file_1 = "野性，除了凯茜以外，伊莉莎应该是最符合这个词语的人吧？\n但和稍微有点野蛮的凯茜不同，伊莉莎从头到尾都散发着庞大的野性；走路完全不会发出任何声音，热衷于捕鱼和吃鱼，整个人完全就是一只野猫，同时她的战斗方式也是以偷袭为主，可一旦得手，就会将对手四分五裂，要找到符合她特征的魂器是一件相当艰难的事情。\n不过比这个，更优先的是要找到伊莉莎的身份记录。",
		level_3 = 0,
		level_4 = 0,
		resume = "无法查询到任何关于伊莉莎的资料，连伊莉莎提供的部分关键词也很难在网络上搜索到。在这个信息全部被网络连接的时代，除非她的信息被赋予了极高的权限又或者是本身就不属于这个时代，否则是无法做到这一点的。\n在行为上，伊莉莎的表现十分的野性，虽然有着最低限度的餐桌礼仪，但整体的表现却如同野兽，例如：为了吃到更多的食物尽可能地简化咀嚼步骤，休息的时候也会警惕周围细微的变动。\n虽说学院主张每个人都要有自己的风格，但伊莉莎的风格某种程度上来说太过了……我们需要她在可能的范围内尽量收敛一些。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "发现伊莉莎身上存在着实验残留的痕迹，从粗糙的创伤处理和绝对精准的缝合来看，对她进行实验的应该是人工智能一方，但对于实验的项目、内容、结果，我们都一无所知。\n而想要从人工智能那边得到伊莉莎的实验情报……几乎是无法做到的事情。\n对此，我们将会派出顶尖的黑客·奥德莉进行资料的窃取工作，但愿一切都能顺利。",
		file_3 = "和伊莉莎进行了多次约谈，我们得出了以下信息：\n信息1：伊莉莎在这个世界上没有任何亲人，她自己也无法理解近几年来 发生在自己身边的事情。\n信息2：伊莉莎的认知与当今现代常识有着相当的差异，有些对她来说是“常识”的事情对我们来说几乎是异想天开。\n信息3：伊莉莎曾经被人工智能抓走并进行了多种实验，但是实验结束后人工智能并没有将她像其他实验体一样进行废弃处理。\n根据结论3来判断，伊莉莎应该是生活在这个时代的人，但结论2却完全驳回了这一点，或许这和人工智能们在她身上所做的实验有关，我们需要适当催促奥德莉的工作了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "通过奥德莉三天三夜不吃不睡的黑客攻击，我们终于得到了有关伊莉莎的实验档案。\n项目：【多元宇宙测试实验】\n描述：使用人类个体进行亚空间传送，获取平行时空内有利的情报。\n实验开始：\n记录1：投入三名人类男性个体进行传输实验。 结果：失败，人类个体无法压缩到能够传输的质量层级，三名人类男性当场灭亡。\n记录2：使用人工智能个体进行传输实验。 结果：失败，人工智能数据压缩到了1bt，虽然完成传输，但1bt内难以存贮大量信息。\n记录3：投入一名人类女性个体进行记忆传输。 结果：成功，人类女性成功完成了和相近时空的记忆交换。\n对于参与实验的个体进行观察记录：\n观察记录1：询问该个体【■■■■】计划在平行时空执行后的成败。 回答：该个体对计划表现出困惑状态。\n观察记录2：询问该个体【魂器学院】在平行时空的活动路线。 回答：该个体对魂器学院表现出困惑状态。\n观察记录3：询问该个体生活的时代背景。 回答：该个体表述时代吻合千年前的时代。\n实验结论：在执行【多元宇宙测试实验】的同时，其他相近平行空间执行同一计划的可能性为89.567%，该个体作为实验品投入的可能性为67.561%；该个体的记忆有极大的可能性被转移到了偏差值极高的平行宇宙。因多个平行宇宙都执行了类似的实验，导致作为多个宇宙内的不同个体的伊莉莎，其记忆被互相传送，使得该宇宙和偏差值极高的宇宙进行了信息交互。因平行宇宙也有可能重复实验，实验结果将会被严重干扰，故重启计划无意义，该项目废弃——转存系统档案721。\n\n执行人工智能：赫莫\n反复阅读以上内容，我们得知伊莉莎的身体虽然是这个时代的，但精神却是来自平行世界，但这也无法解释，为何我们无法查找到有关伊莉莎的出身档案；或许伊莉莎原本就是被人工智能特地培养出来的实验体。",
		level_6 = 0,
		record = "“人类、人工智能，究竟那一边是好，那一边是坏……脑袋不灵光的我肯定想不出来。”\n“不过，一直以来温柔对待我的你，绝对不会是坏家伙。”\n“好的，就这样决定吧，只要是欺负你的人，我会用这双爪子统统撕碎。”"
	},
	[23720] = {
		soulid = 23720,
		valuation = "单论破坏力还是相当可观的，可是伦茨完全不明白瞄准目标的意义，总是闭上眼睛就一头撞上去了……如果将目标替换成移动的敌人，例如：121自律型卫兵的话，成绩可能要比现在还要差吧。 ",
		file_1 = "发现了伦茨携带的小型机器人为未确认型号，本来打算好好研究一番的，考虑到其对伦茨的重要性，不得不暂时放弃这个想法。但在一次偶然的机会，我们发现了索菲亚所持有的某个小型机器人·编号11的外形与伦茨的机器人大致相似，所以特别邀请了索菲亚进行确认。 确认的结果为：该机器人确实是索菲亚早期研发的私人型号·编号库洛01，主要应用在心理疾病方面，由于索菲亚本人的私心，库洛01内部也配置了不少武装设备，其中包括：生火设备、脉冲以及自爆程序。 让这样一个危险的机器陪伴在一个患有自闭症的孩子身边……到底是要怎么样啊…… 目前对索菲亚的风评将会在近期进行调整。",
		level_3 = 0,
		level_4 = 0,
		resume = "伦茨·黑尔姆特，嗯……说实话，我们很难猜测她在想什么，一天到晚都站在随机的地点一动不动，最高时长记录居然有四个小时三十六分钟……她头顶的那个玩意在太阳底下很快就会变热，要是那样一直站在太阳底下，很快就会中暑，为了防止那样的情况发生，我们打开了所有的户外加湿器…… 我不清楚应该在她的履历里要写些什么，如果说有什么和她类似的东西的话，大概就是那种设定好时间的机器人吧，天哪……我可不是为了做保姆才来到这种地方的，如果情况在未来一个月还没有任何改变的话，我就要辞职了……",
		level_1 = 0,
		level_5 = 0,
		file_2 = "对伦茨的心理评测的结果为：中等程度的抑郁症，神经敏感，容易被小事刺激。 明明只有九岁，却有着这么严重的心理疾病，一定是遇到了十分难过的事情吧。为了让伦茨的状态往更好的方向发展，我们准备了许多心理辅导课程，可是她似乎并不感兴趣，只愿意和库洛01进行沟通和交流。虽然这个机器人在一定程度上缓解了她的心理疾病，但如果继续这样保持下去，可能会发展成其他的沟通障碍。 好在班长入学之后，伦茨的现状开始有所改变，虽然大致还是和以往差不多，但已经开始愿意和身边的人进行简单的交流了，不过……在伦茨见到班长的时候，总是会兴奋得一头撞上去…… 在回忆起伦茨实战的画面，我们开始为班长的生命安全表示担忧。",
		file_3 = "伦茨的父母消逝于黑色圣诞节，人工智能叛变爆发的第一夜，据说当时救援队找到伦茨的时候，她父母的遗体就在十米范围内，这是大概就是她心理疾病的根本原因，在那之后，为了让伦茨得到更好的康复环境，救援队将其安置到了尼格霍德五区的一家病院，身体虽然逐渐康复，但精神却并非如此，伦茨依然被过去束缚着……当时刚刚脱离鲁比克财团，回到奥杜因的索菲亚听说了这件事后将自己制作的小型机器人·编号库洛01送给了她…… 以上就是这个孩子的过往，而随着和班长的交流愈发频繁，我们逐渐开始了解这个小女孩，害怕陌生的人和环境、害怕别人大声说话、害怕打雷……几乎是什么都害怕的状态，和他人交流需要靠得特别近，不然很难听到她的声音；另外她似乎喜欢捉迷藏，并且总是将自己扮成机器人，然后融入到环境里，虽然从我们的视角来看，那种行为只是单纯地站在那里…… 另外对于亲密的人，就会一股劲地冲到对方的怀里，是的……一股劲。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "记录上显示，黑色圣诞节当晚，虽然耶梦加得大部分地区陷入了战争状态，但伦茨所在的区域却是安全的。救援队也表示，当时周围确实出现了部分伤亡，但只有伦茨家呈现出了遭受到恶意爆破后的样子……具体的情况我们还需要更多的资料，不过根据伦茨父母的部分记录，基本上可以推断，这绝对不是什么意外事件。",
		level_6 = 0,
		record = "“大家的吉祥物，看上去软绵绵的好可爱。”"
	},
	[23820] = {
		soulid = 23820,
		valuation = "虽然成功击败了训练用的人工智能，不过战斗本身并没有可取之处。就旁观者看来只不过是利用了电击的特性达到了机械特性的敌人，只是取巧而已。至于物理攻击力……非常符合年龄与外表。",
		file_1 = "芭荼荼在学院任职预备风纪委员，但从她的执勤记录来看，芭荼荼所做的早已超过了这个职务应承担的工作强度，甚至要比一般的风纪委员还要更加尽职尽责。\n高强度的工作实际上很难获得他人的认可，目前已经有部分学生对她有所微词，觉得她的做法是严重的越级行为。\n我们所采取的做法是：将她的部分工作转移到其他的风纪委员身上，但芭荼荼很快就陷入了情绪低落的状态，我们得为这孩子想想办法……\n记录：班长入学一周后\n我们委托了芭荼荼帮助班长熟悉学院的环境，看样子她对十分喜欢这份新工作，现在已经完全黏在了班长身边，心情也改善了不少；……虽然这一切都是建立在牺牲班长的前提下。",
		level_3 = 0,
		level_4 = 0,
		resume = "芭荼荼·伊万·伊万诺夫，来自尼德霍格未被战火波及的区域，目前仍有大量的人居住在那个区域，通过严密的审查，可以初步确认芭荼荼没有间谍、特工的可能性。\n性格上，芭荼荼偏向严厉，喜欢遵守规则，并且也会要求别人也遵守规则，是那种喜欢用自己的标准去要求别人的类型，但这同时也表示，芭荼荼绝对不会勉强别人去做自己做不到的事。整体而言是个对自己定位清晰的孩子，但或许是太过清晰了，芭荼荼总是将自己未来的规划提前放置到自己身上，这也就导致了，她对自己过于严厉，总是不满意。长期下去，会逐渐引发各种心理上的问题，建议为她寻找一个可倾诉的对象。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "对芭荼荼上午的观察记录：\n六点四十分：起床 七点二十分：洗漱和早餐 七点四十分：在寝室门口等待班长 八点三十分：打断了班长和伦茨的独处 九点二十五：体育课依然观察着班长 十点三十四：假装和班长同一时间下课 十一点十分：游泳课记录缺失 至此上午结束，下午集体转移至实战设施。\n结论：嗯……是不是有点像是跟踪狂？不如说几乎把所有的活动时间都放在盯着某个人身上了，如果不是两人之间的交流太过正常的话，或许我会申请风纪仲裁吧。\n附录：来自布克丝的音频记录：管理员10492，如果下次还看到你调用学院内的监控设备做这种无聊事情的话，你就自觉地注销管理员身份吧。",
		file_3 = "【记录】管理员10492：无论怎么看，芭荼荼·伊万·伊万诺夫都只是一位普通的十二岁小女孩，她在实战中所表现出来的能力要达到及格线也有些困难。更别提就这样堂而皇之地成为学院的一员了；虽然布克丝院长叮嘱过我，绝对不可以再进行有关芭荼荼相关事件的调查，但那也只是针对她的过去，在学院内的数据还是能调用的吧？\n【记录】管理员10492：没有充能记录……芭荼荼手中的电击棒并没有任何充能的记录！这也就意味着，她本身能够提供对应的能量，等一下！究竟是将部分能量转换成电流，还是她本身就能产生电流？那支电击棒能释放的电压可是有一百万伏特的啊！就算异能者再怎么强大，那也只是体表的程度，体内的细胞又怎么可能承受那么强大电压？必须要和布克丝院长提出相关的测试申请才行！\n附录：来自布克丝的音频记录：不用申请了，你被开除了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【院长亲自编辑的词条】\n芭荼荼为基金会所属的成员，是我和基金会达成某种协议的附带品，虽然那个协议里大部分都是对我不利的地方，但……能够将这个孩子带到学院的话，一切都算是值得的。管理员10492差点就接触到了真相，我必须在这之前将他开除，否则将会对今后的计划产生不确定因素。\n没错，芭荼荼·伊万·伊万诺夫……啧，这名字真是拗口，总之这个孩子确实能够产生人体所不能承受的超级电压，并存储到细胞当中，而那支电击棒里所释放出的仅仅只是体内电流接近饱和后，所溢出的少量电流罢了。这份能力，如果反过来运用的话，甚至能够做到吸收掉外界的高压电流，然后将其重复释放；只要能做到这一点……夺回那个大部分被人工智能攻陷的发电之都·奥杜因就不是难事了。\n夺回奥杜因的话，那么今后的一系列计划都不需要走弯路了。",
		level_6 = 0,
		record = "那副天真，究竟是本性还是伪装，也许……就连本人也无法解释吧，只有一点可以确定，那就是她对班长的那份心情，远比闪电还要耀眼。"
	},
	[24020] = {
		soulid = 24020,
		valuation = "这个人真的是人类吗？不对……难道说她才是正常的人类吗？抱歉，让我冷静一下，成绩的统计就交给其他人来做吧。",
		file_1 = "魂器名：【动力回旋】\n记录：该魂器的特点为强大的曲线打击能力和返航能力，流线型的造型能够更好地符合空气动力学，外设的四个推进装置可以在抛出去的同时，迅速地控制攻击方向，但美中不足的是，片翼灾星操作的复杂性以及严格的共鸣条件；目前片翼灾星的面试者以及超过了二十名，但却连一名基础适格者都没有出现，其最基本的原因就是身体素质上的问题；片翼灾星需要适格者有着强大的身体素质，否则在使用阶段就会导致使用者发生严重的肌肉拉伤。\n我们一度认为片翼灾星将会逐渐被转移到仓库尘封起来，但凯茜的出现却改变了这一切，在经过复杂的测试和共鸣后，她竟然轻松地掌握了这件魂器，就好像最初就是为了她而诞生的那样……",
		level_3 = 0,
		level_4 = 0,
		resume = "凯茜·弗里曼是现代社会结构中少见的守旧派，虽然目前也有Abandoner（遗弃者）这一完全厌恶网络的存在，但凯茜却和他们截然不同；她的行事作风更偏向于旧时代人类的感觉。面对高科技和相关课程的时候，她表现出了部分的棘手、跟不上讲师思路的状态。但在实战使用的时候，却能够马上上手，在半小时内熟练地运用C-TRL至D系列的任何远程近攻武器，完完全全是个实战派天才。\n性格沉稳，有着大人的成熟感，充满英气，擅长各种各样的运动，有着完美适应任何体育项目的运动细胞。就目前而言，还没有人在身体素质方面超过凯茜。\n另外，学院内有不少女生表现出对凯茜的好感……",
		level_1 = 0,
		level_5 = 0,
		file_2 = "根据档案上记载，凯茜的原居住地为奥杜因·五区的轻工业区，但那块地方现在早已被人工智能彻底占领，虽然也有通过各种途径逃离封闭区域的方式，但我们并不认为只有实战才能的凯茜能通过战斗的方式开出一条通往学院的生路。\n另外，轻工业区的居民都通过了C级的《防污染项目条例》考核，而凯茜却连这个考核的标题都无法回忆起来。由于奥杜因·五区被彻底攻占，相关的文件档案无法通过连接超级计算机来读取。\n我们需要一段时间来调查这名身具怪力的少女。",
		file_3 = "在某日测试中，凯茜拒绝了使用片翼灾星攻击虚拟猛犸象的测试，即便我们事先已经告之这只猛犸象是由人工智能操作数据模拟出来的，她仍然表示自己无法伤害动物，并尝试亲近那只虚拟猛犸象。\n为了避免多余的事故，我们中止了这场测试，以这件事为契机，测试人员开始询问凯茜一些问题，其中包括：为何不想伤害动物以及加入学院的具体原因。而凯茜的回答是，自己喜欢动物，曾经也和许多动物互相生活，所以没办法伤害它们；至于加入学院的理由是，自己曾在某个组织内部工作过一段时间，但最后发现组织利用了自己和动物的亲密性，不断地猎伤动物，并将尸体贩卖到地下黑市。没办法忍受这点的凯茜偷偷逃离了那个组织，经过一些波折之后，最终加入了魂器学院。n我们询问那个组织的具体名称时，凯茜却表示没办法回忆起来，在通过精密的仪器检测之后发现，凯茜有被人实施记忆操作的痕迹，而关于无法回忆起某些记忆的情况也很有可能是洗脑的副作用。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "我们用侧写的办法，利用了记忆的连续性将凯茜脑内被清除的记忆再次还原。\n还原的结果很完美，凯茜顺利地回忆起了一切，并表示那个组织的名字叫做■■■■，是由具备异能的遗弃者们组成的一支民间组织，平时隐藏到各种被人工智能攻占的废区进行活动，是个擅长游击战术的阴险组织。\n目前学院方已经通缉了该组织，但愿一切都能顺利。",
		level_6 = 0,
		record = "醒来吧！少女，为了正义、为了伙伴、为了这个世界，哪怕有一天，这些都将一点点离你而去，也请不要放弃与命运的斗争。"
	},
	[24120] = {
		soulid = 24120,
		valuation = "优秀的抗性，特别是针对火焰的时候，居然能做到82%免疫，实战和笔试方面的分数也不低，没有明显缺点，是个综合性很高的人才。不过……没有缺点这件事也就意味着没有优点，再多留意一下自己的方向吧。 ",
		file_1 = "卡米拉性格上较为乐观，做事谨慎，一丝不苟，我想这应该归功于她那长达七年的消防工作。平时喜欢检查生活场所的各种设施，将所有火灾的可能性全都悉数排除。虽然本质上是好事，但这对我们来说却有些困扰。 例如在一些课程中，我们需要模拟火灾的环境，然后让学员在这样艰难的情况下进行人员的救助以及资料的转移；但每当系统模拟出一丝火苗的时候，卡米拉总是第一个挡在所有人面前，然后单枪匹马地去执行任务，虽然最后也成功地完成了……但这个过程却没能让大部分的成员都参与进来，从教育意义上来说是失败的。 目前我们请求卡米拉尽量对火焰持有一丝丝宽容，但被直率地拒绝了。",
		level_3 = 0,
		level_4 = 0,
		resume = "卡米拉·S·纳尔泰，来自库库尔坎·三区·住宅区，迄今为止已蝉联了五届最佳消防员、六届灭火之星。是位相当能干、被众人深深依赖着的孩子。 曾出过个人传记《与火焰斗争之人》，被当地媒体采访过不下二十次，工作期间成功扑灭火灾高达一百多场，救火成功率100%…… 然而这些都不是我们需要了解的，学院内有设置专业的防火系统，而且火灾这种事情也只是在住宅居民区这类人口密集的区域，我们很难说学院是需要卡米拉的。好在卡米拉本人似乎知道这些，她没有表现出太大的沮丧，她对生活依旧充满信心。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【火焰绝缘能力】：一项在单一环境下较为强势，具有针对性的特殊能力。历史上暂无其他人持有该项能力的记录，但却有着类似：低温、雷电、酸性等各种单一条件绝对免疫的能力记录。这项能力的本质实际上是通过释放固有立场，达到隔绝火焰的效果，如果长期使用的话会导致能力持有者本人对高温的严重迟钝。目前卡米拉已经表现出了在30℃以下的环境无法正常感知热度的状态，我们担心这样下去会影响她的汗腺无法正常工作，从而引发多项并发症。\n目前正在想办法为她安排相关的手术矫正和身体检查。",
		file_3 = "身体检查的结果出现了，令人吃惊的是，卡米拉的汗腺并没有受到任何影响，对环境温度的迟钝现象仅仅只是她适应了高温环境的结果，并且通过检查我们还发现了她持有的另一项特殊能力：一种能够让她轻松地嗅出五百米范围内任意物体的能力。\n这项能力本身是相当常见的，令我们吃惊的是她的身体居然能够承受两种不同异能。因为从科学的角度来说，异能的诞生往往和基因有所关联，而一旦形成某种异能，那么基因就会为了保持这项异能的运作而固定下来。\n初步推断，卡米拉体内的基因应该是处于不完全固定或者介于二者之间的状态，如果是后者的话，那么卡米拉将会是学院内罕见的双重能力者；但如果是前者的话……卡米拉将会随着时间的推移诞生更多的异能。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "基因检查结果：卡米拉的基因总体呈现出介于两种状态间的不稳定状态，简单来说，在不远的未来，卡米拉将会在持有当前两项异能的情况下获得第三种特殊能力……\n背景调查结果：超级嗅觉为卡米拉两岁时觉醒的异能已被其父母确认，另外在她九岁那年曾遭遇过一场火灾，但事后却毫发无伤，基本可以断定卡米拉的火焰绝缘能力是在那个时间段诞生的；如果以七年作为一个觉醒周期的话，排除环境和事件要素，或许卡米拉会在近期就觉醒出第三种异能。",
		level_6 = 0,
		record = "哪里有火焰，哪里就有我！但如果全世界都被战火吞没……那么，我又该何去何从呢？"
	},
	[25120] = {
		soulid = 25120,
		valuation = "在战斗中最需要的并不是压倒性的力量，而是智慧与危机应对的能力，阿加莎的战斗有着其他人都没有的稳重和时机把握能力，故评价为A级。 ",
		file_1 = "战斗狂人，阿加莎对待敌人十分残忍，曾经转眼间平定了被认为无论如何也至少需要一年才能击溃的帮排，并将十分之九的人给清理掉。 击溃敌人肉体的同时也将对方的心智摧残掉，经常为了尽情享受战斗而故意放对手一马。 而自己对待部下却十分宽厚，总是将获得的战利品分给部下。",
		level_3 = 0,
		level_4 = 0,
		resume = "“曼珠沙华”的首领，墨格尔最年轻且拥有最强实力的头目。出生于墨格尔边境地区，从小就被自己的黑帮父亲灌输“只有强者才能在这个无法地带生存下去”的思想。 从小弱肉强食的思想根深蒂固，在一次单独游玩发现一个帮派被另一个帮派所灭，从此更加认定若要生存只有成为强者。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "外冷内热，外表上看起来孤傲冷艳，实际上相当关怀家人和部下。智勇双全，沉着冷静，有着极强的突发事件处理能力和极高的战斗智商。 不喜欢别人插手自己的战斗。凭借着能够看到预见未来的能够，能将敌人招数完美拷贝或者扼灭在摇篮， 但面对强敌非常尊重，会想要公平的与对方分出高下。",
		file_3 = "超喜欢鸣门卷，鸣门卷是一种以鱼浆为原料而制成的食品，所使用的鱼是白身鱼，即鱼肉为白色的鱼种，有别于鱼肉为红色的赤身鱼。 阿加莎也喜爱爱吃甜食，偶尔会带着一包上面写着“阿加莎的点心”的零食袋并一个人默默地吃着甜点，如果有陌生人靠近就会用呆呆的样子说“我不会把这个分给你的”。 只有当阿加莎在吃喜欢的食物时，才会表现得平易近人。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【警告：无效档案】  权限不足……",
		level_6 = 0,
		record = "一个首领，有时候是不能逃避战斗的，尤其是当同伴的梦想，被人嘲笑的时候。 记住不逃避，一个首领一定要足够努力，你不能自己都瞧不起自己，要有担当，才能无所畏惧的勇往直前，兄弟是不能让人欺负的。"
	},
	[25320] = {
		soulid = 25320,
		valuation = "喂……喂……这家伙是不是开挂了。这个人真的是人类吗？",
		file_1 = "【呼吸法】 贝蒂掌握的特殊能力之一。其能够通过不同的呼吸方式以不同的方式运使身体，进而使出各式各样的独特剑技，例如将意识集中到脚上，将力量灌注于此，积累而后爆发即能实现雷鸣般的高速，或以柔软变化的刀势防御并偏转攻击，诸如此类。此外，呼吸法使用者亦对自己的身体有着超乎寻常的感知和控制能力，可通过集中精神止痛，或长时间保持全力以赴的状态以与没有疲劳或负伤概念进行作战。呼吸法的基本是“全集中呼吸”，即通过特有的呼吸方式加速体液流速及心跳速度，令气管扩张，氧气量增大，进而实现如“恶魔般”的强大。",
		level_3 = 0,
		level_4 = 0,
		resume = "谜一般的人物，阿加莎·克利斯蒂的姐姐（非亲缘关系，阿加莎父亲所收养的孤儿，但两人都互视为亲姐妹），曾作为海外佣兵部队“复仇女神”的所属军人生活，有着非常高的战斗力，能够独自挑战百名士兵，战斗力实属恐怖。极度妹控，对阿加莎百依百顺。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【回响】 贝蒂掌握的特殊能力之一，一种高速移动技，将力量灌输在脚部并产生爆发性的反作用力来做高速移动，从敌人眼前看来简直就像消失一般。 【无心】贝蒂掌握的特殊能力之一，卸下全身力量，通过对手动作所产生的气流变化，犹如风一般轻松自如的控制身体，对朝向自身的攻击，都能千钧一发的躲开。 【荆棘之路】贝蒂掌握的特殊能力之一，跳跃时在空中踢击，在下落前改变移动轨迹。有了这种空中移动的体术，可以不留盲区的从空中发动攻击。 【岚切】贝蒂掌握的特殊能力之一，并非通过踢蹴敌人给予伤害，而是通过超高速且具有威力的踢腿卷起真空产生斩击攻击对手，可轻易将目标劈成两半。",
		file_3 = "超级妹控，宿舍里全部是关于妹妹的玩偶或抱枕。平常给人感觉是一位冷酷少女，但和自己妹妹在一起。 却表现格外乖顺，那种温柔的笑颜真的很罕见，这也许是贝蒂只有在阿加莎面前才有着小女人的一面。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "不要随意她的底线，尤其是她的妹妹，否则后果不堪设想。",
		level_6 = 0,
		record = "弱小...真是弱小啊....不去直视问题并尝试跨越...只会惨兮兮地拼命逃避...那种弱小的行为...简直令人绝望！"
	},
	[25420] = {
		soulid = 25420,
		valuation = "不用什么紧密的仪器，只是用双眼就能确认那个躯体的“异常”。玛琉的运动能力比起通常人类实在是超出太多了，不过想必为了得到这样的力量，玛琉也付出了无比惨痛的代价。",
		file_1 = "作为力量代价，玛琉在没有集中注意力的时候非常容易失控——只是身体上的。她周遭的小物件很容易在恍惚之间被破坏，钢笔、桌椅、卫生间的水管……\n超人的力量对于她的日常生活也造成了不小的麻烦，不过在面对人类的时候玛琉会发挥百分之百的注意力，所以不要担心正常的交流。\n对了，上次玛琉在训练中受了伤，伤口刹那间就痊愈了。我们还发现她还能够使药品、试剂等无法在其体内产生超过数秒的作用。\n据说变式能够增强的人类体内体液和细胞的活性，让人体潜能激发出来，同时强化人类的新陈代谢机能。不过，只是加快新陈代谢是无法达到这种自愈水准。但在没有取得确切的数据前，我们不应该妄加猜测。",
		level_3 = 0,
		level_4 = 0,
		resume = "琉·蕾·拉米亚斯作为“杰格”计划第一个也是唯一一个成功的案例，玛琉依靠该计划最终拥有了人类可能拥有的最完美躯体，身体各方面机能都达到了人类所能承受的极限。\n不过这个家伙真的是一位很可怕的学员，她的入学体能测试打破了魂器学院的纪录。自魂器学院创立以来，没人能在体能测试上超过她……而且所有仪器都被她摧毁至“体无完肤”。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "对玛琉的心理评测的结果为：为人十分认真，率直同时也是颇为冲动的人。\n活着面对自己的错误并尽量去弥补是人生最大的勇气和责任感，对于这种事那些人大概永远也不明白。\n一个成熟的成年人应该是在有着善良的内心的情况下，能独立思考并对自己的选择负责，而不是将选择和拒绝的权利一并交给别人来决定。\n她一直在坚守自己的信念——不仅是作为一个战士，还是能够贯彻自己正义的人。",
		file_3 = "【隐藏词条，仅能使用固定的密码才能搜索到。】\n【记录】管理员1069：10月6日，玛琉去地面上的城区执行派遣任务，回来时发现她被枪械所伤，但是其异于常人的体格会把对普通人来说致命的子弹并不会造成致命伤，虽然会伤口溃烂，但对玛琉的行动影响并不大，就像我们摔倒擦破皮一样，玛琉拥有超乎常人的自愈能力，即使受到致命伤也会短时间内完全并且不会感到疲惫。\n【记录】管理员1069：11月7日，定期体能测试。今天测试项目为卧推（无任何辅助）与耐力测试。在耐力测试中，玛琉在不到一分钟的时间内跑完1.6千米（每秒26.6米）等，最高时速可高达48公里。这也许是试剂强化了她的新陈代谢机能、能够将肌肉中的乳酸等有造成疲劳的物质完全代谢掉，这给予了她正常人完全无法想像的耐久力。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“变式试剂”可增强使用者代谢功能和所有身体机能，并且将脑部的使用率开发到恐怖的高度，即使是将之称为“进化”也不为过。\n超级战士试剂是玛尔斯的科学家“亚·帕金森”最初开发的一种试剂。该试剂的制造目标是为了增强人体和精神，为军方创造出世界上最强的战士。\n玛琉是使用该试剂转变为超级战士中第一个也是唯一一个成功的案例，在她之后使用的都是“变式-Ⅱ”或“变式-Ⅲ”，在能力与潜力上都无法与原型所抗衡。\n精神方面，玛琉丰富的战斗经验将她训练成了一个高明的战术家，以及优秀的战场指挥官，队友们在战斗中往往都会乐于听从她的指挥。\n玛琉的反射神经与感觉器官都十分的敏锐，这使得他能够毫无阻碍的学会各种武艺，并靠着她超人的运动能力在实战中视战术需要随意组合成为一种高度洗练的战斗风格，也可使她的灵活度足以闪躲子弹。\n长年的训练令她能够人盾合一，无论是狙击、反弹敌人攻击、近身战斗、以少对多都完全不是问题。",
		level_6 = 0,
		record = "玛琉非常在意与他人的缘分，无论是友情还是亲情她都会好好珍惜。"
	},
	[25520] = {
		soulid = 25520,
		valuation = "综合实力相当之强，能够使用世界上所有类型的格斗技巧，体能测试结果非常接近玛琉的数值，她也打破了魂器学院曾经的纪录，在各方面表现也相当优异。",
		file_1 = "表面上塞雅表现的非常冷漠，但是内心还是一个极度温柔的少女。她会常常帮助那些需要帮助的魂姬，但塞雅却很少与魂姬们交流，除了玛琉。 也许是因为曾今的一些事情才导致塞雅如今性格吧。她不想过于亲近她人，也许是不想再见到友人在自己面前倒下吧。 对了，塞雅好像与玛琉的能力非常接近，但又不完全一样。塞雅各项能力指数相对于玛琉的能力指数要相对弱一些。 虽然同为“强化人”，但塞雅还是明显弱于玛琉，这是为什么呢？",
		level_3 = 0,
		level_4 = 0,
		resume = "塞雅·瑟尼欧里斯自卑而温柔的少女，心思单纯，容易轻易信服别人，自小在孤儿院长大，因为自己的能力而被孤儿院驱逐，后加入卡莱克尔防卫部。害怕给别人添麻烦，认为自己给周围的人带来了不幸，因为卡莱克尔防卫部收留了自己而对防卫部的人尤其是部长感激有加。 早期一直在孤儿院生活，孤儿院的生活很痛苦，塞雅甚至不能哭泣，后来因为觉醒了能力，破坏了孤儿院的设施而被赶出（塞雅本人并不知道自己的能力），之后一直在卡莱克尔城区里流浪，直到遇到了卡莱克尔防卫部部长。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【变式-Ⅱ】试剂与原型【变式】能够赋予人类的能力近乎相同，唯一区别是它弱化了与人类细胞相结合的突变速度。 变式能够通过重新组合生物遗传因子的特性，来使得人类获得新的潜力，但它所造成的二次突变却导致了人类在转为“强化人”过程中的突然变异。 就人类而言，有承受试剂力量体质的人，数千万人之中最多只有1个。 但是为了量产“强化人”，卡莱克尔的科学家优化了试剂对人类细胞的突变速度，能够更安全的转变为“强化人”。 不过能够承受新型试剂力量体质的人，数百万人之中最多只有1个。",
		file_3 = "以下为塞雅在学院内三个月以来的实战记录：       \n【记录一】 塞雅对战布兰琪   场地：虚拟城区   结果：压倒性的优势击倒了布兰琪（胜利）\n【记录二】 塞雅对战斯卡兰斯   场地：虚拟沙漠   结果：塞雅与斯卡兰斯一开始战斗时表现五五开，在长时间的高温环境下，斯卡兰斯无法适应酷暑而倒下。（胜利）\n【记录三】 塞雅对战玛琉   场地：虚拟城区（雨天）  结果：在玛琉面前，塞雅的表现并不是很出彩，所有招式都被玛琉所看穿（战败）        \n根据以上记录，我们发现了塞雅拥有常人远所不及的力量、敏捷、敏锐度、体格。而且加上她以前是一名出色的战士，这使她在模拟训练中表现的极为出色。   \n但是在与玛琉对战中表现得相对弱势，虽然两人同为“强化人”，塞雅的能力明显弱于玛琉，而且在战斗技巧上也稍逊于玛琉。       ",
		level_7 = 0,
		level_2 = 0,
		file_4 = "塞雅最痛苦记忆莫过于“6.13”行动，这次行动主要是剿灭准备袭击卡莱克尔得武装团伙，但是似乎这次行动情报被武装团伙所窃取。 塞雅的队伍到指定地点，就受到了来自武装团伙的攻击，除塞雅外其他人员都在这次行动中失去性命。 而塞雅被不法分子（其他城区）用榴弹炸伤，后被赶来来的玛琉小队带回医院，在生命垂危的时候，“变式-Ⅱ”拯救了她的性命。 不仅如此试剂还使得塞雅极强的再生能力、力量以及速度。当塞雅在病床上醒来的时候，询问护士其他小队成员还安好吗？ 护士只是让她冷静，好好休息，塞雅似乎是明白了什么，她只是静静的躺在床上开始默默的哭泣。",
		level_6 = 0,
		record = "如今明明拥有了一切，却对此无知无觉，而是愚蠢地沉浸在过去的伤痛里。"
	},
	[26020] = {
		soulid = 26020,
		valuation = "珍妮特本身并没有什么作战能力，她的作战能力全部来自于魂器（空中机动装备）——林德沃姆。并且以光子集束枪的自动引导模块进行辅助射击。",
		file_1 = "对于珍妮特来说，在成为一名合格的空机兵是非常艰难的。需要进行各种对于高空、失重、低压、缺氧等特训练。\n对于一个年仅11岁的少女，这无疑会对她的身体造成很大的负担。但珍妮特并没有气馁，她每天都在坚持训练。\n无论是白天或是黑夜，无论雨天或是炎热。珍妮特都会坚持训练，只为成为一名真正的空导机兵。",
		level_3 = 0,
		level_4 = 0,
		resume = "正义感很强，希望能够长高，变成母亲那样受欢迎的女性，对自己和别人都很严格。尽管个人能力并没达到普通魂姬的水平，但依靠着适配的魂器——空中机动装备·林德沃姆，珍妮特获得了强大的作战能力。\n珍妮特从小就梦想成为空机兵，虽然在实际作战的经验上有些欠缺，但是仍十分努力。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【空导机兵】卡莱克尔计划研制一个新型的兵种，这个计划就是——撒计划。而珍妮特的母亲则是该计划的负责人员兼武器试验员。\n能够载人进行空中飞行，时速600km，可以承载一吨以下的重量，核心为量子融合炉，能够提供对于单兵来说几乎无穷的动力。\n旧版空中机动装备配备有微型空对地导弹十二发，微型机关枪及弹药五千发，还有照明设备与喷火设备等。\n魂器学院的魂器【林德沃姆】是在撒计划的装备为基础创造出来的，可谓是与珍妮特梦想同源的装备。",
		file_3 = "虽然使用着空中机动装置，不过珍妮特在近战能力却毫无天分，远战的射击能力也不足以称为优秀，但幸运的是，少女拥有极高的飞行天赋，同时有着与之匹配的上进心。\n为了克制自身短板，珍妮特便向原卡莱克尔防卫部队的队长玛琉请教，希望玛琉教她如何使用武器。在尝试了上百种不同类型的武器后，珍妮特终于找到了能够最适合自己的武器——光子集束枪。这种配备了高精度辅助瞄准设备，同时没有多少后坐力的武器与珍妮特非常之高。由此，珍妮特离自己的梦想更近了一步。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "少女年幼时的记忆被深爱自己的母亲所填满。\n握住自己的柔软手，拥抱自己的温暖的怀抱，安慰自己的轻声细语。\n还有，在天空中飞翔的时候，比任何人都要闪耀的她——在珍妮特的心中留下了名为“憧憬”的种子。\n如果努力下去，少女迟早也能够变成那样的，她所期望中的优雅而华丽的姿态吧。",
		level_6 = 0,
		record = "“妈妈……我离梦想更近了吗？”"
	},
	[23420] = {
		soulid = 23420,
		valuation = "雯的体力、攻击都十分出色，特别是她投掷标枪的时候，那份对抛物线、风向和各种因素的计算，简直是做到了完美中的完美，但不知为何，像这样出色的人，一场战斗下来居然发呆了五到十次。",
		file_1 = "慵懒，这个词语简直就是为了雯量身打造的，无论在什么情况下都会逃避任务和职责，无论在任何场合里都会下意识地打起哈欠；简直就是由慵懒组成的人类，嗯……这样说她可能有点过，毕竟在遇到一些麻烦事的时候，她都会迅速地采取方案，完美地将其解决，前提是她没有发呆的情况下。\n另外作为独生子女出生的雯，一直渴望有一个弟弟妹妹，但因为自己的存在感过低，这个简单的愿望一直都得不到实现；如果有机会的话，悄悄地在她耳边叫一声姐姐，然后观察她的反应，一定会非常有趣。",
		level_3 = 0,
		level_4 = 0,
		resume = "雯来自较为和平的派森地区，父母为企业的高层管理，是标准的中产阶级家庭，雯从记事起便展现出了超人的智力，三岁便能背诵课文，像这样的她从小便被父母赋予了厚望。和其他孩子不同，雯的童年被各种各样的课程给挤满了，就连休息也必须一边闭眼，一边背书；如果这样的生活继续下去的话，她一定会是一名出色的企业家又或者是政客吧？\n但出人意料的是，雯在九岁的时候生了一场大病，因为这场大病，雯失去了一切九岁以前的记忆，甚至连那份天才性也随之消失。父母深感失望，不再为其安排那些繁重的课程。\n雯也因此从那样单一的生活中得以解脱，成为了自己梦想的标枪运动员，只不过偶尔，她会用发呆的方式来缅怀过去。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "发现了雯有着近乎100%的标枪命中率，我们怀疑她是和千竹同样的命中技能持有者；在这样的前提下，我们展开了一系列的测试。\n项目：普通靶子 距离：一千米 结果：命中，正中红心。\n项目：来回摆动的钟表 距离：两千米 结果：命中，镜面被粉碎。\n项目：被抛出的标枪 距离：一千米 结果：命中，两支标枪同时落地。\n项目：射出的5毫米子弹 距离：一千五百米 结果：未命中，标枪贯穿墙壁。\n结论：基本可以推断，雯的高命中率来源于自身的锻炼和高超的演算，但在物体速度快到一定水平的时候，就无法捕捉。另外，这份演算能力也是她没有失去天才性的证明；不过擅自下结论有点太片面，我们需要更多的数据。",
		file_3 = "关于雯的发呆情况，做出了部分的统计：雯在白色空间内发呆的次数要远远高于其他颜色的空间；自身除外在人数超过两名的情况下雯发呆的次数会突然增加；另外，在环境变得复杂以及空间信息量提升的时候，也会突然发呆。\n可以确定，雯的发呆是刻意的，是想要隐藏些什么以及封闭自身信息的做法；并且，大量的数据证明了，她在发呆之后的做事效率反而要远远超出平时水准。\n我们可以这样认为：雯为了掌握环境和其他因素，将大脑的大部分演算能力都分配了出去，而这个过程看上去就好像是在发呆一样。\n被人无视和他人不客观的评价都是她所期待的情况，为了能够让她继续安心学习，我们还是不揭穿这些吧。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "雯的脑波活动呈现异常状态，或许有什么东西盘踞在她的大脑，可无论怎么检查，我们都找不出异样。\n在她九岁那年，到底发生了什么呢？",
		level_6 = 0,
		record = "闭上眼，就好像呼吸要停滞那样，紧握标枪将它高举过头顶，耳边是风的声音、人的欢呼以及……自己的心跳……\n可以了，现在的话，就算投中也没问题了，虽然被人瞩目多少还是有点不习惯呢。"
	},
	[23320] = {
		soulid = 23320,
		valuation = "根本搞不清她到底在做什么，整场测试下来，她都是在挨打，只是本人看起来十分享受……不过医疗测试上，她倒是展现出了不错的水平，虽然看上去有点毛骨悚然，但战场上可不能挑剔。",
		file_1 = "发现拉普拉斯的自虐倾向和自身的兴奋程度挂钩，疼痛感会促使其脑内的多巴胺直线上升。简单来说：是个彻头彻尾的受虐狂，一开始，我们取走了对方的针管之类的道具，但即便是没有针管，拉普拉斯也会通过撕咬、拉扯的方式给予自己痛感。不得已，我们只能给其换上了拘束服，但她却依旧能通过撞击墙壁的方式获得疼痛感…… 为了让拉普拉斯对自己的伤害降到最低，我们还是将针管还给了她；经过以上的事件，我们决定将对定期为拉普拉斯进行身体检查，时刻维护对方的身体健康，避免伤口感染、扩大。 可是……对方的医疗技术早就超出了保健室的老师，\n每次检查都未能查出任何外伤。",
		level_3 = 0,
		level_4 = 0,
		resume = "拉普拉斯·德普，根据记录表明，她从小到大都是生活在巴哈姆特·四区·贫民区的一位普通小女孩，乐观积极是周围人给她的常见评价；但……不知道在她身上到底发生了什么，我们见到\n的拉普拉斯完全和记录上的不同。 整个人陷入疯狂，行为作风毫无逻辑可言，理念、信仰、梦想全都空荡荡的，着实令人心疼……并且，她展现出了一定的自虐倾向，经常用针管扎自己，我们很担心她会发展成更严重的自虐行为，所以目前将会安排十到十二名工作人员对拉普拉斯进行轮流监督，确保对方不会伤害自己。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "拉普拉斯在学院的行为显得有些微妙，其具体表现为：对水和强光的恐惧，对尖锐声音的敏感以及对于人际交流的困惑。前面两点可以暂且认为是长期的监禁生活导致的创后反应，但对最后一点却存在部分的疑惑。 调查记录表明，拉普拉斯曾在贫民区有着一定良好的风评，而她在学院表现出的，却好像是从来不曾与人交谈的那种僵硬感，就算互相交流顺畅，也多变会变成她单方面的说话……丝毫没有记录上的性格特点。",
		file_3 = "虹膜检查·一致，瞳孔检查一致，基因嵌合度·99.7% 结论：基本确认和记录上的拉普拉斯是同一个人，不过我们在检查的过程中发现了其尾椎骨部位有一组序列编号，在记录下编号后通过推算和云端信息整合，我们发现了一个地下组织。 与此同时，于巴哈姆特四区的贫民区似乎发现了真正的拉普拉斯……这背后隐藏的信息值得玩味。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【项目编号：79771】        \n基因来源：拉普拉斯·德普        \n内容：拉普拉斯·德普具备短时间内的创伤再生能力，基于项目所带来的巨大痛苦，我们将会生产她的大量克隆体，并逐渐运用到今后的项目试验当中。                 \n记录一：失败，克隆的五百名克隆体没有继承母体的创伤再生能力。      结果：废弃处理\n记录二：失败，克隆的两千名克隆体仅有三名呈现出微乎其微的再生能力。      结果：对表现出能力的三名进行观察，其余全部废弃处理\n记录三：失败，剩下的三名克隆体有两名亡于项目的测试中。       结果：对剩下的一名定期给予强烈的痛感，刺激再生能力的进化。\n记录四：失败，仅剩的这名克隆体也进入了休克状态。        结果：因该项目已被高层遗弃，今后实验室将被封闭，不再开放。         \n学院内的拉普拉斯已确定为由以上实验诞生的克隆体，并且具备一定的自愈能力；目前考虑到她已经和魂器共鸣的前提下，我们将会这项词条进行封锁。         并在近期安排作为克隆体来源的拉普拉斯母体进行相同的魂器测试……我们很期待，能够出现两个不同个体操作同一件魂器的情况。   ",
		level_6 = 0,
		record = "“我眼中的世界像是摔碎的玻璃一样，七零八落的……嘻嘻，怎么样，要试试把它拼起来吗？”"
	},
	[21630] = {
		soulid = 21630,
		valuation = "用球棒把导弹打出去，还真敢想啊，不过那份胆识和毅力已经合格了。要是在战斗中再细心一点就好了，幸好她有一位专精辅助的搭档。",
		file_1 = "无论是什么都要全力以赴，音乐也是，棒球也是。 如果说夏洛特对于音乐的热爱完全来自兴趣的话，那么她对于棒球则是兴趣与天赋的组合。 瞄准投掷而来的白色圆球，聚集全身的力量，猛力但是平稳地将其击飞出场地——完成全垒打带来的成就感令她深深着迷。 夏洛特从未想过成为职业棒球手，但是她对棒球的喜爱并无虚假，只不过—— “比起棒球，我更喜欢架子鼓！所以很遗憾只能让棒球成为业余爱好了！” 不过如果有能够兼顾棒球与音乐的职业，夏洛特还是不介意去试一下的。",
		level_3 = 0,
		level_4 = 0,
		resume = "夏洛特出生在一户富裕的家庭，父母出于工作繁忙一直对夏洛特采取放养政策，家庭关系也算不上和睦。为了吸引父母的注意力，夏洛特性格开始变得叛逆——染发、逃课、泡吧，这些轻微不良行为少女几乎都尝试过，但是父母却依旧对她漠不关心。 在事态进一步升级前，夏洛特选择了放弃，然后将所有的热诚投入到对音乐与运动的爱之中。 在冷漠的家庭环境中用音乐艰难地维持着自己的心，这样的情况直到夏洛特步入中学才有所好转。在那座音乐院校中，她遇见了自己未来的搭档——琉璃。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "夏洛特钟情于架子鼓，原先选择这种乐器单纯是想要用巨响引起父母的注意，不过这种“捣乱”很快就变成了发泄。在将自己的不满与诉求通过架子鼓完美地表达出来之后，夏洛特发现了自己的音乐天赋。 她不在将音乐当做单纯发泄的途径，而是开始用心演奏自己的心声，用音乐抚平自己所受的创伤。 不过在生活中遇到郁闷的事情之后，夏洛特还是很喜欢用架子鼓大闹一场的。",
		file_3 = "夏洛特很容易沉浸在自己的世界中，每次开始演奏的时候几乎是旁若无人。 特别是少女选择了架子鼓这样破坏性强的乐器，在音乐院校的时候没少遭到他人的投诉。 急躁又有些孤僻的夏洛特也因此被他人所疏远，少女几乎从来都是孤身一人——直到她遇见了琉璃。 能够坦诚地对待所有人的琉璃用行动攻破了夏洛特的心房，两人成为亲密的好友，甚至更进一步组成了乐队。 琉璃的存在填补了夏洛特心中的某片缺口，在长久的相处后，夏洛特将琉璃当成了自己家人一般亲近的存在。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "与琉璃一同正式出道后，夏洛特凭借着或是狂野或是帅气的音乐表演取得了巨大的人气。 但即使女儿获得这种成就，父母之间的关系也依旧没有好转，也没有对夏洛特投入多一份的爱，或许那两人之间并不存在真正的爱吧。 对此，夏洛特也并无怨言，在这背后隐藏着怎么样的故事，她已经没有兴趣了。与自己一样，父母也有追求各自期望的生活的权力，用自己的存在去束缚他们等于是剥夺了两人的自由。 只要自己依旧爱着他们就足够了。 但是，果然还是希望有人爱着自己。",
		level_6 = 0,
		record = "“男朋友啊……嗯，首先一定是要围着我团团转的，其次最好喜欢我的音乐。再然后……一定要喜欢小孩子。”"
	},
	[21830] = {
		soulid = 21830,
		valuation = "琉璃有着优秀的思维处理能力，在战斗中能够时刻监控着同伴的状态并作出对应措施，对于战况的把握也非常优秀，她的能力作为辅助人员来说无可挑剔。",
		file_1 = "幼年时期，琉璃就已经开始在音乐比赛的赛场上展露头角。少女展现出的歌唱技巧稚嫩但是令人耳目一新，而在对于观众“情感”与现场气氛的把控上却宛如老手。 拜此所赐，琉璃的历任音乐导师都对她寄予厚望，业界中看好琉璃前途的人也是比比皆是。在粉丝与相关业者的支持下，琉璃成为了派森地区的著名歌手，在中学毕业后就已经开始进行世界规模的巡回演唱。 这个时候，琉璃参加了魂器学院的适应性测试。在这样外界看来镀金一般的行为中，琉璃通过了与魂智能网络的链接测试并且取得了优秀的成绩。由此，琉璃开始了作为魂器适格者与偶像身份互相交替的生活。",
		level_3 = 0,
		level_4 = 0,
		resume = "琉璃出生一个音乐氛围浓厚的家庭，父母均毕业于音乐院校，但两人擅长的乐器却与各自的性格一般不搭调，自小，她就在架子鼓和小提琴无法融合的音乐中长大。 琉璃自小就展现出绝佳的音乐天赋，无论是摇滚、流行、古典等不同种类的音乐，她都可以驾驭，也顺理成章地就读某座音乐院校。 一切的改变源于人工智能“觉醒”的那天，琉璃所在的学院同样遭到了破坏，自己也不幸被埋入废墟中。在等待救援的漫长时间中，少女经历了深刻的绝望。 不过少女并没有因此崩溃，在获得拯救后，琉璃暗下决心。她想要成为能够为他人带去光明的人，用自己的音乐驱散绝望。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "自小到大，琉璃的父母始终保持着针锋相对的姿态，两人无论是乐器的选择、喜好的食物乃至常看的电视节目都有很大差异，因此产生口角是家常便饭。不过在琉璃严重，那差不多等于两人感情亲密的表现——即使争吵最激烈的时候，两人依旧会为彼此保留一份尊重，导致两人的争吵在琉璃眼中就像是秀恩爱一般。 琉璃对于自己父母的关系非常羡慕，她自身也对恋爱这种事物产生了小小的憧憬。",
		file_3 = "琉璃的歌声之所以拥有如此的吸引力，除了音乐方面的天赋与勤奋练习之外，还与琉璃自身拥有的一种资质有关。 共感（Empathy），深刻地感受他人的情感，并且以知性去理解的能力。配合琉璃自身的表达能力，令少女能够轻易地演奏出打动众人的音乐，在日常生活的交流中也很容易博得别人的好感。 依靠着这样的特质，琉璃不止一次地在两位不坦率的父母之间担任调停角色，即使如此不坦率的两人，在少女天使一般的笑容与温柔但是直指要点的话语下也被打磨掉脾气。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "琉璃希望通过包含爱意的歌声给世界带来守护的希望，因此才成为了偶像。 “哪怕是人工智能,也一定会被打动。”这样的信念一直支撑着她。 但是使用武力还是依靠爱来拯救这个世界，也是琉璃一直在思考的问题。 她没有办法不去承认学员们干脆利落的武力镇压，但她的内心深处仍旧迷茫。",
		level_6 = 0,
		record = "音乐是理解，音乐是祝福，音乐是爱，音乐是连接你我的桥梁。"
	},
	[20220] = {
		soulid = 20220,
		valuation = "无法形容的狩猎技巧，无论是智械还是强化人，都是在没有察觉到的情况下被一击致命的，那样巨大的镰刀居然能做到如此精细的狩猎，作为学生来说早已破格太多了，可惜她太依赖命令了，在需要自由发挥的场合，可能会十分被动。 ",
		file_1 = "【绝对的七段分割】：只活跃在传说的狩猎术，因会将物体分割成七份质量相同的区块而得名。目前已确认，萱所掌握的狩猎术中便有【绝对的七段分割】的存在。具体是何人传授给萱的，暂且不明。     \n因布克丝院长表现出对该狩猎术的兴趣，故安排萱进行了相关的测试。      \n测试1 对象：CT-303    结果：CT-303被分割成七份，感压板的数据显示，这七份的质量仅存在0.25克的偏差。\n测试2 对象：优质派森和牛肉烧烤    结果：被分割成七份后马上就被吃掉了……感压板数据未能及时收录。\n测试3 对象：沙堆    结果：被萱本人用“你是白痴吗？”的天真眼神给伤害到了，测试人员提出了更换申请。\n测试4 对象：将近三十公斤的合金块    结果：被分割成七份，每块质量越为：4.3千克，多余的质量残留在刀刃上。\n结论：太不可思议了，无论是怎么样的技巧，都不可能做到如此精细的分割，如果学院内所有人都能掌握这项技巧的话，那么……不，还是算了，人才的多样性才是学院的最大优势。",
		level_3 = 0,
		level_4 = 0,
		resume = "萱，来自混乱的城市·克巴尔，曾经是那个臭名昭著的狩猎组织中的一员。精通大型武器的狩猎技巧，但不擅长谎言、色诱以及其他偏门的手段；在实战测试中展现出前所未有的战斗力，仅凭借一把冷兵器便将场上50名智械与强化人全部击垮，让原本是《躲避侦查》的考题，一下子变得混乱起来。\n性格上较为平淡，三无属性，对情感的表现较为僵硬，喜欢各种美食，一天当中见到她十次，有将近七次都在进食，是个相当可怕的吃货；另外和她同班的同学表示，这孩子似乎还有些天然呆。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "萱表现出对美食的高度热衷，不知道这是不是一件好事，但萱对于学院的依赖确实要比之前更高了。不过，根据厨师长反馈，这个月的肉类正以直线速度疯狂下降，处于对她的健康考虑，我们要采取措施，努力平衡她摄入的营养，养成更加良好的饮食习惯；虽然……目前看起来遥遥无期。\n其次是有关萱的天然呆部分，起初我们理解为：只是对话语的理解出现小部分误差，不会有太大的障碍；但是后来发现，萱的执行能力实在是太过强大了，在理解出现误差的后一秒马上就出发执行任务，这让我们很难对最初的指令进行修改……导致结果会和我们预料中的有所偏差。",
		file_3 = "暗影：克巴尔五区最可怕也是最臭名昭著的赏金猎人组织，内部有80%以上的成员都是女性，擅长各种各样的狩猎术，迄今为止已有不少关键人物都消失在了她们手中，其中包括人类和人工智能两方；是个只认钱，完全不挑对象的无底线猎人组织。\n无论如何，萱能从这样的组织里脱身，从个人角度来说，是一件值得庆幸的事情，但同时，我们也需要对萱做更多更具体的评估才行。毕竟背后能托付的对象只有伙伴。 ",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【正在编辑的词条项，请具体确认持有的管理员权限等级后再执行此项操作，否则您将面临：监禁、剥夺职务、人事调动等风险。】     \n词条1【和平条约】：黑色圣诞节后，人工智能方和人类打算签订和平协议的当天，超高速监控机器人拍摄到了一组模糊的人影，经过系统的失真处理以及修复后，照片上呈现出的是三个身着【暗影】组织特有服装的狩猎者，其中一位被确认是萱，但根据当天的事故结果来看，被破坏的人工智能并没有呈现出七段分割后的相同质量，目前我们还需要更多现场的客观数据来重新模拟还原当天的事故。",
		level_6 = 0,
		record = "不知道失去了多少，才站在了这里的她，就连面对明天的笑脸都被遗忘，但只有那个人的孤单离去的身影依然深深地刻在脑海的深处。"
	},
	[27000] = {
		soulid = 27000,
		valuation = "水晶球“森罗万象”的存在以及依芙极高的幻象天赋，幻象系的异能在极大程度上发挥出了强效的控制和辅助能力， 不论是人类还是人工智能其视觉系统都会受到影响，但另一方面，终究只是是幻象，可以预见单人作战时则完全没有进攻能力。",
		file_1 = "【森罗万象】原本并非魂器，单纯是巫术世家传下的不可思议的水晶球。虽然不连接网络就可以使用，但本人还是执意要求改造。 确认依芙为适格者后，学院将【森罗万象】改造为依芙的专属魂智能武器，不过并未对水晶球本体进行大的改动，只是镶嵌在了杖型精神力的辅助增强装备上 毕竟这份能力尚还不能用科学解明，哪怕是布克丝博士也不敢轻易动手，只能在一定程度上进行简单的装置补正，水晶球的本体随时可以取下。 目前可以知道的是，【森罗万象】的能力完全可以做到武器和服装的投影变形，没有特殊精神系异能的人绝大部分会受到影响。",
		level_3 = 0,
		level_4 = 0,
		resume = "依芙的想象力非常出彩，配合“森罗万象”展现出的幻象创造能力令人叹为观止。 另一方面，疑似预知未来的占卜给予依芙的是优秀的危机察觉能力，让她可以提前做出应对，哪怕单独作战时也有一定的自保能力。 事实上，在洛加尔地下活动的这段时间，对于如何骗过偶尔闯入的暴乱的人工智能，依芙已经累积了充分的实战经验，可谓视觉欺骗的艺术。 不得不提恶作剧的手段十分高明，配合幻象的能力简直就是完美的恶作剧发生器，一定要注意观察不能让依芙和其他几个点子多的家伙长时间接触。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "其实对于依芙所掌握的幻象能力，学院方面曾未公开的做过一次实验，得出的结论非常惊人。 在【森罗万象】的辅助下，呈现出的最大有效范围是半径50M的球形空间，依芙可以在这个基础上自由向下调整需要的空间形状。 但如果要完全动用这份能力，需要非常大的依芙本人的精神力支持，依芙动用越多的精神力构筑，幻象世界就越真实稳定。 这是个隐患，布克丝博士在实验后指出，如果依芙在使用广域幻象巫术时由于高压让精神力崩溃的话，可能会出现极端情况。 所以现在依芙暂时被禁止使用广域的高精度幻象放出，并在接受特别的精神力辅导课程。",
		file_3 = "依芙所在的家族，据本人描述是庞大的巫师家族。但先不论巫师的职业是否还有留存，对于如此大的家族却不在各方势力的视线之中这件事本身就有诸多疑点。 但依芙的能力确实是货真价实的存在着的，也因此引起了学院方面的重视，开始着手进行调查。目前推进不算顺利，但还是能够收集到一些蛛丝马迹。 巫师活动的目击报告不难获得，虽然大部分都是无关紧要的视觉误差，但隐藏在其中的一小部分还算有点帮助。 或许真正的巫师数量并没有想象的那么多，所谓家族也只有少数人拥有使役精神力的能力，大部分的人都与常人无异，家族也一直低调行事，并不想引来麻烦的事。 但爆发了黑色圣诞节之后，有很多被谜团包围的势力开始慢慢与外界接触，尚不知道是特殊时期的做法还是蠢蠢欲动的野心。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "总是跟在依芙身边的小黑球“库洛”，是依芙在洛加尔地下据点边碰到的，黑不拉几的小流浪猫。 一开始的接近非常困难，库洛对于依芙的投喂抱有戒心，常常是依芙放好食物后就发现库洛逃得不见踪影。 不过依芙并不在意，至少第二天回收的食盆都是干干净净的....一人一猫就这样达成了神奇的默契。 库洛的直觉，或者说，猫的第六感特别敏锐，总是能提前发现异常的地方，依芙在这方面受库洛关照不少。",
		level_6 = 0,
		record = "关于依芙的占卜术，稳定性和真实性还有待考证，魂姬之间口碑不一，最好还是亲自去试试。"
	},
	[26620] = {
		soulid = 26620,
		valuation = "妮妮珐对于作战的策略仿佛没有什么概念，她真正感兴趣的还是研究灵魂和制造人造机器战斗对她来说只是获得灵魂的一种途径而已，但通常她不会主动出手获取。",
		file_1 = "【红粉甜心】与其说是魂器，不如说是妮妮珐定制的灵魂处理的一体式仪器，当然还是具备一定程度上的作战能力的，能够配合妮妮珐的异能转化出带有恢复治疗能力的“灵魂”，在开发阶段就被称为是移动的灵魂工作站，能够做到高纯度的能量转换。 因为考虑到仪器的精密性和功能性，这件魂器很难得的基本全程由医疗部进行开发跟进，算是为数不多的并非为了战斗开发的魂器。 根据目前已知的情报来看，这台仪器除了采集，储存和释放等基础功能外，后面的箱子还可以进行灵魂的解析和灵魂的制作妮妮珐本人对这件魂器爱不释手，但是考虑到安全问题，目前妮妮珐也只有得到许可后才能开启使用。",
		level_3 = 0,
		level_4 = 0,
		resume = "出生于混乱之城巴哈姆特的妮妮珐，所属组织不明，或许也可能没有组织，这正是这个小姑娘让人感到费解之处根据学院的档案来看，年仅11岁的妮妮珐却是巴哈姆特附近大小“战场”的常客，并非直接参与的人，准确的说，妮妮珐大部分的战场行为都是在进行采魂作业或者对伤员进行“救治”。 说是救治也只是把随身携带的“灵魂”强行输入伤者体内，好在并不是什么致命的东西，大部分伤员被发现后，都由正规的医护人员救了回来。现在正在考虑有必要对妮妮珐进行正规的医学知识教学，防止她在灵魂问题上乱来，希望她都能认真学习。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "巴哈姆特这座城市异常混乱，每天都有帮派的大小斗争生产灭亡，对于一般人来说会产生剧烈不适感的场景，对妮妮珐而言不过是家常便饭，很难想象妮妮珐是怎样在如此混乱的地区生存下来的，但可以确定妮妮珐的性格也逐渐开始受到强烈的影响，一旦话题涉及到了伤员和灵魂，妮妮珐的言语举止就会变得极其“糟糕”，达到必须要有人出面制止的程度，但除了完全不符合年龄的表现出对“灵魂”的强烈兴趣外，妮妮珐在各个方面都是正常的11岁心智，偶尔也会做些小孩子的举止，让人完全搞不清楚她的行动准则。现在拟定班长作为监督人员，希望阻止并尽可能纠正妮妮珐的扭曲性格。",
		file_3 = "虽然妮妮珐本人拥有很不错的异能攻击资质，但鉴于妮妮珐对伤员表现出的积极治疗欲望，以及她危险的救治手段，院方暂时决定将妮妮珐安排在医护班系统性的学习相关的医疗知识，有必要时跟随指示行动，并不允许单独进行医疗活动，由伊文捷琳担任妮妮珐的医务知识教师。目前看来，虽然妮妮珐表现出对课程学习的不满，但是灵魂相关知识的掌握有了非常大的提升，至少已经明白了不能随意输液这件事。同时对“灵魂”的制作方法产生极大的兴趣，在本人的强烈....病态的要求下，姑且在一定范围内给予了一间实验室部分设备的使用权，但经常有学生目击妮妮珐抱着什么东西进了实验室之后，一个人空着双手出来了，正在讨论有无必要进行干涉。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "深度调查后，我们得到了一些妮妮珐幼年时期的信息，她由哥哥带着一起在某个组织的庇护下生活，在某一次的小规模的械斗中，哥哥受伤过多却没能得到足够的输液治疗，作为医护人员的哥哥最后只是希望要有足够的生命力。 妮妮珐在后来将这句话作为行动准则开始以自己的方式大量甚至偏执地收集灵魂，身边若是没有足够的灵魂就会陷入慌乱的境地一旦身边的人出现受伤的情况，妮妮珐会不顾一切的为其输送“灵魂”，虽然输的液体大部分情况下只是类似抗生素的东西。 大概，是不想在失去身边的人了吧。但还是必须严肃地指出，危险的救助行为是禁止的！",
		level_6 = 0,
		record = "啊~你消亡了呢~鲜红的灵魂流淌而出~多么绚丽，但是不行！请接受我的治疗！我会很温柔的~"
	},
	[28420] = {
		soulid = 28420,
		valuation = "希艾姆在作战中表现出来的战斗力和格斗术，是仅从她的表现是看不出来的。她的作战风格和她的性格一样，不拘小节，豪放。在看似莽撞的攻击中，希艾姆也没有丢失自身的灵活性。",
		file_1 = "【苍蓝咆哮】是进行远距离进攻的电磁机械弩炮型魂智能武器。其主要的攻击方式是电磁炮。\n作为远距离魂智能武器，【苍蓝咆哮】的设计灵感来源于希艾姆对某种海洋生物的喜爱。\n在适格之后，使用魂智能武器进行了数次模拟训练之后，希艾姆向学院提出了改造升级【苍蓝咆哮】的构想。\n改装后的【苍蓝咆哮】在面对敌人近身攻击时，也能靠展开的功能侧翼放出麻痹电流。就算电流产生的伤害比较小，希艾姆还可以利用侧翼进行近身攻击。\n据参与改装设计的人员透露，【苍蓝咆哮】在远距离攻击上加入了电磁镭射攻击。在特殊情况之下，希艾姆可以将【苍蓝咆哮】反向插入地面，形成小范围电磁场。",
		level_3 = 0,
		level_4 = 0,
		resume = "希艾姆来到魂器学院完全是因为在父亲下落不明后，代为掌管事务的母亲所授意的。\n平时对这种安排都会奋力反对的希艾姆，这次乖乖听从了母亲的安排。这也引起了海盗团成员的疑惑。\n进入学院的希艾姆并没有表现出对新环境的不适应，反倒是像破网而出的鲤鱼。甚至和布兰琪在学院里掀起一股恼人的撩妹旋风。\n希艾姆在获得魂智能武器的适格之后，改变了以往的作战方式，并且将远距离作战方式玩出了花来。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "希艾姆遗传了母亲的高度近视，在年龄适合的时候，借助激光技术矫正了近视。但是偶尔会习惯性眯眼。\n在恢复正常视力之后，希艾姆对于远距离攻击武器产生了极大的兴趣，并尝试和练习远距离进攻方式。\n但是由于海贼团以往的训练模式，希艾姆仍旧以近身搏斗和作战技巧为主来训练。在进入学院之后，希艾姆适格远距离魂器之后，开始新的作战方式。\n意外的是，在进行远距离作战训练之后，希艾姆竟然在远距离魂器作战方式上玩出了新花样，和她性格一样，远距离进攻和以往单纯的对点进攻有了不同。\n据说，克妮雅曾经向希艾姆推荐过新型眼镜，希艾姆貌似接受并且和她进行了秘密交易。",
		file_3 = "伊莎贝拉海盗团，是在耶梦加得地区由希艾姆家族世袭的海盗团体。在进入新时代之后，该团体更像是一种爱好者组织。\n在耶梦加得地区并没有什么惊人的事迹广为人知。但是，在耶梦加得的港口区域，海盗团名下有着好几十艘飞空艇和航海艇。\n甚至，在耶梦加得的航海航空科研机构，也有海盗团身份的成员。海盗团成员更像是一种身份，而不是职业。\n希艾姆的家，便是伊莎贝拉海盗团的基地和集会场所。可想而知，希艾姆所谓的“家”有多大了。\n海盗团的行动在一定程度上并没有受到耶梦加得军方的限制。所以，据传言，海盗团和军方有着密不可分的关系。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "海盗团的行动在一定程度上并没有受到耶梦加得军方的限制。所以，据传言，海盗团和军方有着密不可分的关系。\n而在人工智能事件后下落不明的父亲，拥有从军的经历。在军方开展和执行强化人计划之后，希艾姆的父亲辞去了军籍，离开了军方。\n有传言，希艾姆的父亲是被军方保守派委托了其他的秘密任务。\n深究伊莎贝拉海盗团崛起的历史，可以明显地发现，此团在一夜之内崛起，并拥有一定的规模。组织目的尚不明确。",
		level_6 = 0,
		record = "据说，希艾姆曾经将附近超市的柠檬绿茶抢购一空，造成小几天的断货。甚至，还怂恿其他学员一起购买。"
	},
	[26820] = {
		soulid = 26820,
		valuation = "虽然艾玛同学与魂器的同步率只是堪堪合格，不过她对于枪炮武器的精通不愧于“猎兵”之名。原本是追求破坏力的低精度武器在她的手中却能够用来进行狙击，对自身体力与能量的掌控使他可以用最少的资源造成最大的压制效果，在混乱的战场中也能保持完全的冷静，简直是战士的典范。",
		file_1 = "所谓猎兵，与“佣兵”意思相近，指拥有专业军事技能，接受雇佣的的战斗人员，不过与雇佣兵不同，他们只会接受与人工智能相关的委托。 猎兵的敌人只有人工智能，他们之中大部分是对人工智能抱有仇恨的人，故乡被毁的难民，亲人被害的复仇者，在接受非官方组织的训练和援助之后组成了狩猎人工智能的部队。 通常猎兵部队都会选择入驻边缘地区的城市执行防卫任务，或是接受大财团的雇佣进行运输护卫任务。当然也有一部分人会直接与人工智能产生冲突，通过狩猎高性能机体获取其部件，转而高价售卖给需求者，艾玛就是后者。 在人工智能占区的边缘，任何活动都是非常危险的，几乎随时都可能与忽然涌现的人工智能军团交战，能够在这样的区域生活下去并以此为生，艾玛个人的能力是毋庸置疑的。",
		level_3 = 0,
		level_4 = 0,
		resume = "艾玛·洛阿芙尔，原籍耶梦加得，职业：猎兵。 性格飒爽，不拘小节，虽然言行看上去放荡不羁，不过意外是个对他人的感情细致入微的人。 她的右眼是来自基金会实验室的生化眼，功能与结构接近于真正的眼睛，但是性能却远超其上。 艾玛的察言观色力几乎可以用天赋来形容，她很容易就会感觉到周遭人们的情绪，他人的悲伤，他人的痛苦都会带给她不适感，而艾玛也并不是会将亲近之人弃之不顾的类型。她会努力地排解对方的忧虑，像是知心姐姐一般地与对方促膝长谈，用飒爽的笑容冲淡对方的不安。 艾玛无论是外表还是言行都能够让人充满好感，那是不分性别、不分年龄的，对于亲近之人的好意与期待。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "艾玛的故乡位于耶梦加得的外围区域，于地劫战争爆发时毁于人工智能之手，与故乡一同失去的还有艾玛的右眼。为了活下去和复仇，艾玛在收容所中接受了基金会的契约，被训练成与人工智能作战的猎兵。 虽然业务不同，不过猎兵中同样不乏放纵乃至无法无天之辈，而艾玛同样喜欢这个职业带来的自由感，但是她同样会小心斟酌着，坚守着自己的底线。 “唉，有些时候，我希望自己是个纯粹的恶人就好了，无论什么事情都放得下，无论什么事情都以自己为优先，那样的话应该可以轻松一点吧。” 但是，亲眼见证过那些放弃道德，无视一切，纯粹为自己而活的人们的下场，艾玛在感到可悲的同时也引以为戒。",
		file_3 = "与基金会的契约结束后，艾玛成为了一名自由猎兵，像是孤狼一般独自游荡在危险区域，狩猎着人工智能。 工作的危险性同时伴随着丰厚的报酬，艾玛早就已经衣食无忧，唯一支持者她战斗的动力只有寻回自己容身之所。 但是故乡的人们已经消失在战火中，就算将那个地方重建，自己也无法再见到相识的人们。 于是她将自己的一部分报酬捐献给了曾经收容过自己的收容所，作为报答的同时，也希望更多像自己一样失去故乡的人能够在那里找到未来的出路。 然后，在某次于战场上与魂器学院的执行部队合作狩猎某台首领级人工智能之后，对这个势力产生兴趣的艾玛接受学院抛来的橄榄枝，加入了魂器学院。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在某个时间点，艾玛曾经受到过某个享乐主义组织的招揽，不过最后因为获得“愉悦”的方式产生分歧而分道扬镳。 就算稍微累一些也好，就算真正放下了现实给予自己的束缚，也只是投入到另一种欲望的束缚之中而已，性格慵懒的艾玛，不愿意为了这种失去而去改变自己。 在加入了魂器学院后，艾玛很容易就融入了群体。开朗的她仿佛没有染上任何战争带来的精神病症，毫无保留地发挥着自己的魅力，与部分学员成为了亲密的友人。 在大部分学员眼中，艾玛是一个大胆的、潇洒的、勇于尝试新事物的女性，而且能够一直保持他人对自己的新鲜感。 但是，经历了无数残酷的战斗，在那样的泥潭中拔身而出的人，真的会不沾染上污点吗？",
		level_6 = 0,
		record = "“如果变成人工智能的话，是不是会稍微好受一些呢……说笑的，我可舍不得你们哦。”"
	},
	[27220] = {
		soulid = 27220,
		valuation = "缇法对于各类枪械的运用程度极度娴熟，也再次让人惊叹于她的武器改造能力。 随机应变的能力也极其出色，临场制作武器和小型爆破物的速度很快，就是对各种网络系统尚在摸索阶段。",
		file_1 = "【绝斥双星】是由缇法亲自设计开发的魂武，外观上来说和通贩的近未来枪械没什么不一致，相较于异型的武器，缇法还是更加中意顺手程度。 不过内部构造足够复杂，缇法从一开始就是冲着制作究极魂武进行的设计，理论上来说拥有现阶段最高的能量准换效率，以及隐藏其中的微缩斥力场的应用。 是连布克丝博士都赞不绝口的设计，也有传闻说这两人经常可以就魂武的开发问题畅聊到深夜。 然而虽然作为现役的魂武，缇法似乎对其仍有不满意的地方，经常抱着【绝斥双星】往返于宿舍与实验室，一副行色匆匆的样子。 世上不存在究极完美的武器，这件事情其实缇法比任何人都要明白，但仍然在追随这个目标并为之努力。 用她本人的话来说：已经没有任何事能让她停下脚步了。",
		level_3 = 0,
		level_4 = 0,
		resume = "很难想象这是个18岁的女孩子，我是指身高，以及讲话的口吻，极度不会说话。甚至很难让人体会到这个年纪女孩子应该有的温柔，或许这是我个人的偏见，但是缇法的个人经历确实影响着她的性格，辗转各处汲取武器尖端知识的期间，通过贩售奇怪的各式小装置赚取生活费用柔弱女生温柔的态度，大抵是在这个世界里是生存下去最不需要的东西。缇法对于武器的理解非常深刻，可以说拥有这方面的绝对领域。 成为适格者，进入学院的第一件事，就是向院长申请独立开发自己的魂器，并要求资源上的帮助。 战斗或许已经是家常便饭的事情，但缇法永远只有一个努力的目标，就是制作究极完美的武器，单纯就难度上来说与突破物理法则的难度无异。 另外，缇法对于网络的理解，说实话糟糕的不行，后续要好好让她进行学习。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "关于缇法出生的组织，已经查明是驻扎地在巴哈姆特的小团体，并非多有影响力的组织，甚至在最初的一段时间组织成员的生存都成为问题。 后来缇法制作的改造品在黑市上逐渐变得受到欢迎，组织在这段时间才发展起来并拥有稳定的生活来源，对于天才少女缇法带来的收益，组织的人由一开始的感恩，到渐渐富裕后变得贪得无厌，或许就是穷怕了，但这依然让缇法感到人性的可悲与黑暗。 于是一方面为了追求究极的武器制作，一方面也是为了逃离组织，缇法开始了独自一人的旅程，并在过程中逐渐变得不会说话起来，大概也是本人保护自己的一种方式。 据说曾有被组织追捕的过程，推测身体停止发育也和逃亡过程中没有足够营养摄入有关.....大概..... （#修正不严谨的档案内容，缇法本人的停止发育与放射性物质的接触有关，抑制了生长激素的放出）",
		file_3 = "缇法的武器改装技术，完全是自己摸索出来的基础，加上后续各处吸收的知识和大量的实验数据积累，缇法在圣诞节事件后发现人工智能的自我进化和高速演算使得武装能力得到了提升，于是设计了一场掠夺，精准执行了自己拟定的诱导作战，一次性获得了大量的机体部件。 改造的困难比想象的要多，可惜的是提法虽然在物理拆解上非常精通，破解人工智能的晶片电子锁是绝对的苦手，也就是传统意义上的电脑白痴。 导致大部分的武器并不能正常投入使用，即使没有限制，在实战过程中还是会被X-MAX的主系统检测到并锁定，缇法随即放弃了这个想法。 有了这段经历，后续的制作缇法或多或少的开始有意识地针对人工智能进行不可逆破坏的武器开发，不知道算是研究狂的报复还是......",
		level_7 = 0,
		level_2 = 0,
		file_4 = "对于网络，缇法的掌握程度是毁天灭地性质的差，可以说完全没有基础，甚至和“遗弃者”的网络使用水平相差无几。 可以理解在巴哈姆特的贫民窟没法接触网络，但缇法在脱离组织之后也并没有对网络的操作上心，慢慢成长为彻头彻尾的电脑“白痴”。 发现自己无法破解电子锁的窘迫境地后，缇法在军方的实验室稍微进行了一番研究，但是脱离网络的时间实在是太长了，缇法发现自己很难适应之后暂时搁置了学习计划，来到魂器学院后，得知使用魂智能网络是自由开发武器的前提后,再次开始一段困难的学习历程。",
		level_6 = 0,
		record = "安静一点，白痴，别打扰我的研究工作！"
	},
	[26720] = {
		soulid = 26720,
		valuation = "“灰烬扳机”是与其粗犷的外表相同有着巨大破坏力的武器，所幸她的持有者懂得进行细致的操作，学院已经养了太多只会乱轰一气的破坏狂了。洛卡娜自身的数据也处于中上游的水平，不过战斗经验有所欠缺，推荐从基础的战斗科目学起。",
		file_1 = "不知为何掌握着很多只有老一辈人才知道的生活小技巧，像是如何整理衣服的折皱、绳子牢固的绑法、酱油料理之外的妙用等等让人感觉到年代感的小贴士。听洛卡娜说，那是她留在墨格尔的祖母教她的。洛卡娜将其铭记于心，并且积极地运用到自己的日常生活中去。如果偶尔看到洛卡娜做出一些奇怪的举动，不要意外，或许那只是不合时代的小常识而已。",
		level_3 = 0,
		level_4 = 0,
		resume = "洛卡娜的行事较为成熟，或许是因为家教的关系，洛卡娜即使与其他学员发生冲突也不会过多纠缠，比起证明自己的正确，少女更希望能够早点息事宁人。不过这并不代表洛卡娜的思维模式迟钝，相反，她的想法非常富有创造力，擅长利用固有的资源制造出让人意想不到的效果，即使在战斗之外的地方也展现出了天赋。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "虽然洛卡娜有着远超于常人的聪敏，不过终究是十四岁的少女。刚刚来到魂器学院的洛卡娜对于环境的突变显得有些难以适应，课程之外的时间几乎都是躲在寝室中闭门不出，那样的日子一直持续到开学半个月后——伊卡洛维用蛮力轰开洛卡娜的房门，想要将她带出来游玩为止。因为这种入侵领地的举动，两人大打一场，幸好在艾莉卡弱气但是坚定的调停下达成和解。在那之后三人就成了保持着微妙平衡的友情。",
		file_3 = "在被脱线人员占领的学院之中，洛卡娜是少数的“常识人”（自称）之一。实际上，努力地想要让自己显得成熟，用新奇（过时）的小贴士来吸引他人的注意力，本身就是洛卡娜怕寂寞的体现，这点上，她与艾莉卡、伊卡洛维一样都是需要关爱的人。不过想要贸然接近洛卡娜或许有些困难，她就像一只小兔子一样，只要有风吹草动就会缩回自己的巢中，班长大人真是任重道远啊。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“为了洛卡娜的家人，必须要更努力才行。”",
		level_6 = 0,
		record = "洛卡娜的父母是来自墨格尔的移民，而库库尔坎的本地居民对于外来移民抱有天然的优越感，再加上父母的工作都是外人眼中的不入流职业，这让洛卡娜在同龄人之间也受到了不少冷落。父母为了提升这个家庭的社会地位而不辞辛劳地工作着，这一切也映入了洛卡的眼中，小小的少女一直都梦想着出人头地来回报自己的父母，而魂器学院的让她看见了希望。"
	},
	[29520] = {
		soulid = 29520,
		valuation = "黎波娜对“机器人”，有着与常人不一样的理解。她能够将机器人当做“战友”看待，她开发的机器人也拥有作为她“战友”的性能。他们已经经过了漫长时间的磨合，因此，黎波娜一名学员，就有着一支小队的战斗力。",
		file_1 = "拉弥亚黑街的“达达尼昂”，是在当地有一定名气的神秘机械师。据说，他从不以真面目示人，向来用机械面罩遮住半张脸，留着白色的中长发，嗓音经过面罩的变声装置加工，甚至让人无法判判断他的性别。虽然真实信息是一团迷，但慕名前来寻找“达达尼昂”的人依然数不胜数。想要找这名机械师定做设备，档期通常在一年以上。“达达尼昂”作品的特别之处在于，它们不需要网络的支持，就可以运转得相当智能。正如电脑时代的人无法理解机械时代、无需凭借芯片就能运行的自动人偶一样，网络时代的如今，人们也无法想象没有网络的机器人是如何运作的。在 人工智能 控制网络的当下，达达尼昂的技术就显得更加可贵。",
		level_3 = 0,
		level_4 = 0,
		resume = "黎波娜是来自库库尔坎的一名机械师，她从小跟在父亲身后，除了学得了精湛的机械技术，也培养出了别具一格的审美。在黎波娜眼中，粗犷的、能够凸显功能性的设计，比光滑的漆面与花哨的图案要更加符合机械美学。所以，她制作的机器人就是这般，尽管“貌不惊人”，但功能极其强大。据档案显示，在 模拟智能网络 叛变的“黑色圣诞节”当日，是黎波娜的三名机器人“阿多斯”，“波尔多斯”和“阿拉密斯”从 人工智能 手中救下了黎波娜一家人，让人难以置信。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "比起与人类组队，黎波娜更喜欢与自己的机器人合作。用她的话说就是“机器人会无条件服从、无条件地执行命令，既可靠，又有效率。”理性上讲，的确所有人都想要自己的小队拥有机器人一般的执行力。但感性上来说，我们还是希望黎波娜能够适应与人合作。这不仅关系到一个青春期女孩的心理健康发育，也便于让她理解真正的“团队合作”——人类的意义就在于，不只是“执行”。",
		file_3 = "黎波娜来到魂器学院，起初是想借助学院的技术，修复自己在“黑色圣诞节”被 人工智能 损坏的两台机器人。因为两台机器人的芯片受损，里面包含有它们与黎波娜一同积累了十年的数据，仅凭黎波娜自己、也许要花费一年以上的时间才能修复。但布克丝院长看中了黎波娜的才能，对她提出条件——只有黎波娜加入魂器学院，才能对她的机器人进行修理。这个要求并非不合理，因为这项工作需要调用魂智能网络，是魂器学院的最高机密，没有理由为学院外的人使用。有趣的是，本以为黎波娜会对这个要求花时间仔细考虑一番，没想到自院长提出条件到黎波娜接受，中间只过了两秒钟的时间。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在研究室拆解黎波娜的机器人之后，我们发现机器人的毁损并非唯有魂器学院能够修复，而黎波娜选择来到魂器学院，是因为别的理由——黎波娜在自己的机器人中，安放了国际严格管制的钚元素。它是核裂变的催化剂，因为太过危险，国际上绝对禁止民间使用，而若是黎波娜机器人的秘密被发现，她也必定遭受牢狱之灾。在布克丝院长的授意下，我们将会为黎波娜保守这个秘密。",
		level_6 = 0,
		record = "“达达尼昂”的面罩下，是怎样的一张脸——这是拉弥亚最热门的话题之一。"
	},
	[27520] = {
		soulid = 27520,
		valuation = "快速战斗，但并不莽撞，而是事先分析好了对手的能力，善于抓住敌人的弱点，并且长期战斗锻炼出极快的反应力，关键时刻可以给敌人致命一击，并且因为家族原因知识丰富，简直就是一个天才。",
		file_1 = "尼格霍德海因里希人工智能公司，负责研究人工智能的公司，与鲁比克存在合作关系，但据报道其与人工智能有联系，具体不为人知，随后在尼格一年前被海因里希被尼格霍德手下的人工智能袭击，高层人员几乎全部被捕，菲娅的父母不知所踪，妹妹缇娜变为人工智能：具体情况不得而知。",
		level_3 = 0,
		level_4 = 0,
		resume = "虽然脾气暴躁，待人冷淡，但是对比自己小的人展现出格外的关爱。喜欢打架，但并不会无端生事，并且会尽量避免被年龄小的人看见，喜欢老生常谈，不喜欢吹牛，但确实是一个好人，经常给小朋友讲大道理。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "人体计划，海因里希公司执行的将人类变为人工智能的实验，为了让人类获得能与人工智能对抗的能力而实行的人体实验，在不断创新之后投入实施，起先是公司的安保人员，后来公司的高层也投入了实验，其中包括菲娅的妹妹：缇娜.海因里希。但这一切被流放的菲娅并不得知，由于实验的弊端，人造的人工智能最终还是没办法战胜被感染的人工智能。",
		file_3 = "菲娅无意间偷听到海因里希高层人员的会议中，父亲表示将让自己继承家族产业而准备将缇娜“废除”。恼羞成怒的菲娅随后在公司的地下室里倒放汽油之后点燃，烧毁了大半个实验室。被抓住后质问父亲为什么要这么做，最后被公司罢免，流放致巴哈姆特的墨格尔无法地带。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "加入学院的要求：1.学院要帮助自己找到妹妹，并且将她从尼格霍德手里多回来。2.安葬“巴莱理”组织中去世的人，并且给活着的人提供帮助。3.自己隶属于学院，但听调不听宣，没有任务时不接受任何浪费体力活动。",
		level_6 = 0,
		record = "暴躁与仁爱，就像一颗咖啡糖，在那苦涩之后，是一种长久的回味，并且时间越长，就清甜。"
	},
	[24820] = {
		soulid = 24820,
		valuation = "多莉丝学院个体机动性非常优秀，她对于滑板的运用令人耳目一新，这种单人控制且不会占用双手的载具或许会在未来的巷战中占有一席之地。多莉丝学员本人有一定的领导力，虽然没有经过系统性的锻炼，但她对于如何使唤他人已经驾轻就熟。",
		file_1 = "在多莉丝的父母眼中，她像是觉醒一般，在某天毫无征兆地进入了叛逆期。那是因为双亲多年以来的高压政策将少女逼到了绝境，被安排地满满当当的学习课程，毫不留情地被剥夺的自由时间，爱好全部被否定，像是牢狱一般的生活中，多莉丝逐渐累积的压力在某一天爆发。从那之后，多莉丝开始纠集与自身同样境遇的少年少女们，组成集会，开始了与“命运”反抗的里程。",
		level_3 = 0,
		level_4 = 0,
		resume = "库库尔坎地区有名的不良少女，曾经担任不良组织的首领。与夏洛特是同城旧识，两人曾经一同作为不良活动过，不过与喜爱音乐的夏洛特不同，多莉丝完全是音痴。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "作为夏洛特学员曾经的同伴，两人成为不良的理由完全相反，夏洛特因为父母的无视而展现出叛逆，多莉丝纯粹是因为讨厌被安排的人生而选择走上成为不良的道路。在两人的领导下，多莉丝与她的“小弟小妹”们时而聚集在一起竞速，时而在无人的建筑废墟中开展演唱会，乃至组成棒球队参加城市大会甚至拿下冠军。比起不良少年，多莉丝她们更像是脱离的父母管束的兴趣社团。",
		file_3 = "多莉丝与夏洛特的性格不算多么契合，不如说两人是待在一起久了就会互相看对方不顺眼的类型，也就是所谓的冤家。两人偶尔相互争吵，偶尔一致向外，喧闹中又带着一丝和谐。像是这样的日子，一直持续到了夏洛特“不良毕业”的那天。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“模拟智能网络”爆发后，库库尔坎的秩序一度崩坏，四处游荡的失控人工智能，趁乱为恶的不法组织，包夹在他们之中的普通居民几乎毫无防护。面对这场混乱，多莉丝展现出了令人惊异的领导力。少女从自己的“小弟小妹”们开始，一点点将学校内的其他学生、家长乃至教师组织起来，集中在一起对抗这场混乱。不得不说这一行为在初期非常有成效，虎视眈眈的不法组织因为集体的威慑而退避，游荡的人工智能也在多莉丝设立的巡逻体系下失去了威胁，完成了这样事迹的多莉丝一时被奉为传奇。直到“库库尔坎”出现为止。叛乱的核心人工智能“库库尔坎”轻而易举驱散了多莉丝组织起来的自卫团体，让叛逆的少女产生了巨大无力感。多莉丝加入魂器学院的目的之一，就是取得与自己适应的力量，向人工智能，向那个打碎了她高傲的“模拟智能网络”复仇。",
		level_6 = 0,
		record = "每个人都有属于自己的骄傲，那并不是能够让步的东西。"
	},
	[26520] = {
		soulid = 26520,
		valuation = "克妮雅展现出传统将军对战场掌控、领兵作战的才能。相对于进攻来说，防守反击战争她更得心应手。\n不仅是副武器带来的高额防御，近距离进攻的戟形魂器造成的伤害也十分可观。",
		file_1 = "【凯旋冲锋】作为戟形魂器，它的近距离穿刺有着不俗的伤害。\n相对传统长武器的戟来说，【凯旋冲锋】舍弃了远距离的突刺攻击，保留了戟头的锋利和大范围进攻。\n【凯旋冲锋】的体格也相对传统戟来说大很多，两片双刃刀头组成锋利的戟头，周身还伴有其他的尖锐刃器。\n正向和反向的钩状刃器，不仅能造成撕裂伤害还能暂时控制对手。这也使魂器挥击时候，容易对敌人造成群体伤害。\n配对的副武器，也让克妮雅在进攻的时候也增强了防守的机动性。也可以借助近身盾击来击晕对手，制造反击机会。",
		level_3 = 0,
		level_4 = 0,
		resume = "克妮雅在进入学院之前，都一直在接受精英化的教育，在家的时间也接受了家庭教师的指导。\n所以养成了精英阶级的自尊和骄傲。出于阶级礼仪，对别人都是温和带笑，但是，内心已经将人分三六九等。\n人工智能事件之后，克妮雅暂时失去了长期的精英化教育，但是，父母很快将克妮雅送入学院，继续精英式的学习。\n克妮雅对人工智能的态度有点模棱两可，一方面觉得是人工智能破坏了她精英学习的计划；另一方面认为人工智能在某些方面比一般民众来得好。\n但是，无论是人工智能还是普通人，他们在被征服的时候，克妮雅内心升腾的满足感都是一样的。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "克妮雅对眼镜的喜爱已经到了执着的地步，在宿舍里她的衣物很少，但是大部分空间都用来收藏和陈列不同款式的眼镜。\n甚至，克妮雅还制作了假人的头部模型来展示隐形眼镜和美瞳的款式。她丝毫不害怕起夜的时候，吓到自己。\n关于眼镜的发明历史，眼镜款式的变革，眼镜制作工艺以及眼镜公司的发家史，克妮雅都如数家珍。甚至，她还会自己生产眼镜片。\n听说，克妮雅每天戴的眼镜都是精心挑选的，她会根据当天的天气、室温来选择眼镜的佩戴。\n在她鼻梁上架的眼镜似乎也是经过她自己改造的，据说有着特殊的作战功能。",
		file_3 = "克妮雅表面上对人都保持着精英阶级待人接物的温和礼仪，但是她在内心中已经将不合礼数的人分为三六九等。\n而她和爱丽丝一起，成为了学院里其他魂姬“闻风丧胆”的淘气恶魔组合。\n克妮雅将每一天都变成了可以恶作剧的节日，有时候，她自己并不出手，而是将一些点子告诉给爱丽丝。爱丽丝就足够让其他魂姬无可奈何了。\n在看着别人无可奈何束手无策的样子，克妮雅内心对征服的满足感就会油然而生，她十分享受征服带来的快感。\n有传言，某天夜里，魂姬宿舍大停电事件和淋浴间停水事件就是克妮雅一手策划的恶·作·剧。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "克妮雅在小时候十分在意自己的身高，精英意识觉得身高阻碍了自己的进步。\n直到克妮雅在典籍上了解到了皇帝拿破仑，她像恋爱一样立马坠入了爱河，不仅是因为拿破仑的外表，也对他的英雄事迹深深着迷。\n她觉得拿破仑是精英时代完美的贵族，身高问题被谋略、才智一扫而空。她更加努力学习精英知识，就是为了离拿破仑更近一些。\n甚至，她想通过军事作战学习，体格锻炼，以及科学技术的掌握，发现可以穿越时空的方法或者DNA技术复活拿破仑，与他并肩作战。",
		level_6 = 0,
		record = "虽然克妮雅喜欢收集各种样式的眼镜，但是大家从来都没有看过克妮雅带墨镜。"
	},
	[28120] = {
		soulid = 28120,
		valuation = "很久没有出现这样乖巧的孩子了，我真的很想给她的评价打到最高！抱歉……我稍微激动了一点，但是红叶确实是有着达到A评价的素质。而且她的天赋也展现出了绝佳的成长性，找个机会试试她对枪械的亲和力吧。",
		file_1 = "红叶的一族一直都流传着鸟神“拉克”以及拉克的影子邪神“莫罗斯”的传说。在传说的最后，拉克为了阻止莫罗斯毁灭世界，自身化作一把长弓封印了莫罗斯。这便是红叶的将自己的魂智能武器改名为双神双生的由来。红叶的信仰非常虔诚，但是并没有到狂热的地步。根据学院的心理学家兼宗教学者的分析，红叶将自己的特质导致的孤独感寄托在对神明的信仰上，这样的人很坚强，但是心理防线也非常薄弱，如果遇见真正愿意亲近她的人，大概很快就会沦陷吧——不过也正是因为那种特质，少女至今也没有找到能够与自己亲近的同龄人。",
		level_3 = 0,
		level_4 = 0,
		resume = "学员们对于红叶的印象非常少，因为大部分人必须要在与彼此产生关联（比如听到名字）的时候才能意识到她的存在。倒也并不是特意无视或者欺负红叶，相反的大家都愿意和这位可爱的少女接触。只是，大家单纯无法注意到她的存在罢了，这点在人数越多的时候越严重。天生的存在感稀薄，这便是红叶的特性——也是令她自卑的地方之一。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "作为鸟神的崇拜者，红叶的一族是鸟类偷猎者的天敌，为了驱逐偷猎者，必须要有高超的射击以及潜伏和丛林生存的技巧，只有这样，才能压制狡猾的偷猎者。即使进是进入现代，威斯特一族依旧没有放弃传承下来的古老锻炼方式，让即将成年的族人进入原始森林中，与鸟兽一同生活，驱逐狩猎鸟类的人与走兽。红叶的狙击技巧，一半归功于她自身的天赋，另一半就是因为父母对她的严格锻炼。",
		file_3 = "对于红叶而言，存在感的薄弱一直都是她的心病。渴望被认知到，渴望获得别人的目光，渴望被称赞。所以从天赋“觉醒”之后，红叶就十分注重打扮。为了引起注意而穿着暴露或者夸张的行为也曾有过，即便如此，效果还是不如意，反而还受到了来自父母的斥责。在那之后，红叶就开始研究如何让自己穿地端庄而又能够引人注目——虽然没什么效果就是了。因为夸张的言行会为他人带来困扰，所以她也不会主动找人搭话。或许有一天，随着能力的加强，自己的存在会被所有人遗忘，到那个时候，红叶·威斯克，还真的算是存在于世界上吗？",
		level_7 = 0,
		level_2 = 0,
		file_4 = "自从“觉醒”了天赋之后，即使是家人，偶尔也会无视掉红叶的存在，被不小心关在库房中，分发点心的时候永远没有自己的那份，在捉迷藏的时候被彻底遗忘直到天色变黑——这样的经历原本应该塑造出极度孤僻的性格，但是少女将一切伤感和不安压抑在心中，用华丽的衣装与滔滔不绝的言语将自己伪装起来，不过那终究是有极限的。在入学当天，被所有人无视的少女一个人躲进花园之中抽泣。这个时候，她与班长相遇了，想她伸出的那只手，还有从掌心传递来的小小温度，给予了少女无上的祝福。故此，红叶将班长称为“拉克”，在那一刻，眼前之人毋庸置疑是她的神明。",
		level_6 = 0,
		record = "“被人忽视的感觉非常让人难受，明明就在你的身边，但是你却意识不到我的存在，那种感觉就像是被世界遗弃了一样。拜托，就算只有你，就算只有现在，请记得我。”"
	},
	[22220] = {
		soulid = 22220,
		valuation = "不愧是运动员出身，维卡学员对于身体的掌控力已经达到了相当的高度，只要稍加训练就能转变成合格的狙击手。此外，该学员似乎对人工智能抱有深刻的执念，推荐在入学后进行心理辅导。",
		file_1 = "维卡自小在奥杜因北部的雪原上长大，自小就展露出射击天赋的她被作为猎人的父辈们视作传承手艺的对象，他们不遗余力地将狩猎、射箭的技巧传授给维卡，乃至于将她带到雪原上直面严酷的自然。年幼的维卡却对于这样的生活展现出了强大的适应性，她的射箭技术也与日俱增。或许是因为童年大部分时间都在跟随父辈的关系，维卡的言行都非常男孩子气，但是那些叔叔舅舅们却对于维卡现在的状态非常满意。",
		level_3 = 0,
		level_4 = 0,
		resume = "正射必中！来自奥杜因的优秀射箭运动员，热情开朗，有些男孩子气的北国少女。在距离世界冠军一步之遥的时候受到了人工智能的阻碍，为了复仇摩拳擦掌的银发美少女维卡，无论是固定靶还是移动靶都放马过来吧！",
		level_1 = 0,
		level_5 = 0,
		file_2 = "时间流逝，为了维护日益衰弱的生态圈，奥杜因地区颁布了禁猎法令，维卡的父辈们瞬间就失了业。担心家族手艺失传的男人们整天聚在一起浑噩度日，直到某天看不下去的维塔冲进屋子用扫帚一个个敲醒他们。年幼的维卡向着不成器地瘫倒在地上的父亲和叔叔们宣言——她会将他们教授的技艺带上世界，在运动会中夺下冠军，绝对不会任其埋没。",
		file_3 = "艰苦的训练对于维卡来说算不上折磨，就喜欢弓箭的少女来说，每一次射击都令她身心愉悦，拉紧弓弦时产生的悸动，射击时产生的放松感——令她欲罢不能。比起这些，如何去瞄准、调整自己的姿态就变得次要了，那是轻而易举就能够完成的事情。依靠着这份才能，维卡开始在赛场上展露头角，轻而易举地斩获地区各大赛事的冠军，拿到参加世界大赛的门票。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "将维卡将对手一个接一个击败，在世界瞩目的赛场上进入决赛的，“模拟智能网络”发动了叛乱。维卡所在的赛场受到了攻击，连带筹备委员会的要员们身受重伤，世界大赛因此停摆。在离梦想一步之遥被迫停下，少女的不甘心也是理所当然的。 “我要把可恶的叛乱人工智能全部干掉，然后再一次站在那个赛场上。”发下这样的誓言，维卡以绝佳的战斗素质通过了魂器学院的筛选。在她的面前将会是通往危险的未知道路，但是少女并不会恐惧。",
		level_6 = 0,
		record = "为了梦想的话，代价就算稍微大一点也是值得的！"
	},
	[28020] = {
		soulid = 28020,
		valuation = "出色的攻击性，强大的环境调查能力，一对一拥有令敌人恐惧的攻击力。当务之急是增加更多种类的攻击手段和近身格斗能力。",
		file_1 = "【风隐青岚】庞大的本体让它和伊尔莱丝看起来十分不协调，但是两者的相性十分出色。",
		level_3 = 0,
		level_4 = 0,
		resume = "常年狩猎的经历，让伊尔莱丝有些脱离正常人生活很久，导致她的交流能力十分低下，不过她本人一直在试图解决这个问题。虽然身体已经被治疗好，但是由于受到伤害时年龄太小，导致不得不戴着面罩生活。本人对于人工智能暴乱导致她身体有恙并没有什么实感，所以对于人工智能并没有很大的仇恨。进入学院后对于课程并没有什么兴趣，但是为了能够和大家有更多交流的机会，所以伊尔莱丝上课十分认真，成为了班上的尖子生。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "比起一击得手完成任务，伊尔莱丝更看重的是一击必灭那一瞬间目标身体被撕裂的过程。她认为这是世界上最美丽的画面之一。当伊尔莱丝完成目标后不会立即离去，而是再次潜入，欣赏自己的完美的作品，也会观察一下目标身边人的表情，这算是伊尔莱丝为数不多的小爱好。由于这个奇怪的爱好，伊尔莱丝在暗影组织中也被人孤立，这也让伊尔莱丝的语言交流障碍更加严重。",
		file_3 = "在派森伊尔莱丝领略到了有别于其他几座城市的风景，浓郁的东方风情与较少的现代科技相结合给她带来的强烈的冲击。由此伊尔莱丝多了一个新的兴趣，站在派森的参天大树顶端俯瞰这个郁郁葱葱的城市。这样会给她带来难得的心灵上的安宁。来到魂器学院后，伊尔莱丝发觉这里的环境比派森更加吸引人，巨大的绿化面积给她带来了无限的活动空间。除去平时上课和训练的时间，伊尔莱丝就活跃在魂器学院的各个无人踏足的领域。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "伊尔莱丝对于自己出生地奥杜因并没有很清晰的记忆，在她的记忆中那里如同一团迷雾，吸引着她但是同时让她感到恐惧。进入魂器学院以后遇到了许多愿意和她交流的学员，这让伊尔莱丝变得开始拥有人情味，她心中也逐渐喜欢上了这个地方。",
		level_6 = 0,
		record = "据不愿透露姓名的目击者称，有在平时看见伊尔莱丝在学院里偷偷爬树。"
	},
	[28720] = {
		soulid = 28720,
		resume = "来自基金会，内向乖巧的大小姐。时常携带着叫做“巴特莱尔”的兔子玩偶，这个兔子形状的魂智能机兵时不时地就会在主人与他人交谈的时候插上几句嘴，将话题导向有利于主人的一面。作为接受了精英教育，被另一位基金会大小姐爱丽丝视作宿敌的天才，妮妙熟悉大多数基金会的尖端科技，能够熟练掌控大部分运用在魂智能机械中的基底技术。",
		file_1 = "妮妙的父亲是玩具制造商，母亲是VR系统工程师，两人皆是工作繁忙。为了不冷落乖巧的女儿，在那个虚拟现实盛行的时代，两人共同为妮妙在“Avalon”上创造了童话一般的王国，“巴特莱尔”则是为了管控妮妙的教育与网络生活而创造出的人工智能管家。虽然与现实世界的接触减少，但完美的人工智能教学与生活规划并不会令妮妙产生与现实世界的隔阂，在VR网络上是享受着高端教育、劳逸结合的精英子女，在现实中是落落大方、惹人喜爱的大小姐，妮妙的人生轨迹一帆风顺——本来应该是这样的。",
		level_5 = 0,
		level_4 = 0,
		level_3 = 0,
		level_1 = 0,
		file_3 = "如果说“模拟智能网络”对现实中的城市造成了巨大的混乱与破坏，那对于“Avalon”造成的就是毁灭性的灾难。虽然与完全将精神投射到“Starlight-System”义体人不同，自然人的躯体不会直接遭受来自“模拟智能网络”的攻击，但来自精神上的冲击依旧足够使人发狂。被封闭在虚拟的城市中，无法依靠自己的意志离开，一次又一次地遭受着现实中同样正在发生的苦难。当现实中的救援队以强制手段将妮妙的意识唤回时，妮妙已经患上了失语症，性格也变得与过去大相庭径。虽然妮妙的精神状态在之后的细心治疗中有所好转，但是原本天真活泼的少女已经变地孤僻，再难与人相处。但是，事情在某一时点迎来了转机。在疗养院接受着治疗的妮妙，忽然有一天收到了幼时玩伴的邀请而久违地踏出了房间，少女的目的正是爱丽丝所在的地方——魂器学院。",
		file_2 = "虚拟城市“阿瓦隆”，是在“星光系统”上建立的VR交互环境。设立之初，基金会将“把人们的日常生活以全新的方式展现在虚拟城市中”、“即使分处两地依旧能够零距离接触”作为口号进行宣传活动。实际上，“阿瓦隆”的存在的确为人们带来了极大的便利，近乎真实的工作、生活体验和多样化的娱乐系统使其轻易地获得了大量的用户。患有先天疾病、身体残疾乃至身体机械化的义体人，同样可以在这里享受到完整的生命。对于人类来说，在“阿瓦隆”中享受天堂一般生活同时，也能够不冷落现实的人际关系，这也是妮妙的父母放心地将少女“寄宿”在这里的原因之一。",
		level_6 = 0,
		level_7 = 0,
		level_2 = 0,
		file_4 = "实际上，妮妙怀中的布偶并没有内置人工智能系统，陪伴着她一同长大的人工智能程序“巴特莱尔”早在“Avalon”被叛乱人工智能控制的时候就已经为了保护妮妙而被破坏。现在的“巴特莱尔”仅仅是学员为妮妙量身定制的魂智能机兵，所有看似“兔子”的发言都是由妮妙假装成“巴特莱尔”发出的，无论是谁只要与她相处久了都能发现这一点。这里面既包含了妮妙对于陪伴自己长大的“兔子管家先生”的不舍，又有因为自信被摧毁产生的社交障碍的因素。",
		valuation = "妮妙学员自身的作战能力完全依靠那个兔子玩偶形状的魂智能机兵，虽然在远程控制与操作能力上显露出了天赋，但本身并不是适合战斗的类型。反之，作为辅助人员或许是不错的选择。"
	},
	[28920] = {
		level_6 = 0,
		level_5 = 0,
		soulid = 28920,
		level_4 = 0,
		level_3 = 0,
		level_1 = 0,
		level_7 = 0,
		level_2 = 0,
		valuation = "修菈"
	},
	[24620] = {
		soulid = 24620,
		valuation = "对于伊迪斯能否独自在残酷的战场上顺利存活下来我们还持怀疑态度。 在单体爆发的战斗中，伊迪斯往往能凭借【破碎巨刃】的特性形成必胜碾压，面对持续性作战对手，伊迪斯战斗就成了难题。",
		file_1 = "【破碎巨刃】原先是一把巨大的魂智能武器，在应对进攻和防守层面都十分优秀。 但是，它的操作依靠的不是学员的力量，而是凭借学员手腕上的磁电磁感应手环，进行实际操作。“破碎”之名也是因此得来。 它不依靠力气的使用，更加决定了需要使用者细致的操作。在使用者细致的操作下，也能迅捷地使出斩击、防守等技巧。 伊迪斯对于细致操作的天赋，也能用它使用出类似回旋镖般的作战技巧，造成中远程伤害。 如果，学员的力量提升，或许可以进一步激活和最大化【破碎巨刃】的战斗伤害。",
		level_3 = 0,
		level_4 = 0,
		resume = "伊迪斯的性格和力量并不适合战斗，但是她来到学院并通过适格测试，获得了魂智能武器【破碎巨刃】，这有些令人意外。 但是伊迪斯凭借自己对于细致工作的天赋，以及对【破碎巨刃】细致的使用，让她达到了进入战场的资格。 虽然，伊迪斯看上去比较顺从，但是在来到学院并通过适格测试之后，她的内心已经慢慢开始有了变化。 伊迪斯尝试着扯开嗓子和别人说话，保证对方能够听清楚自己的说话声。虽然，到大声说话还有许多努力要做，但是，伊迪斯也开始慢慢尝试了。 她性格的改变，不仅在说话上，和不同性格的学员接触之后，伊迪斯也慢慢开始有自己的决策想法了。这是个良好的转变。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "伊迪斯对掰手腕的热衷，远超乎常人想象。在获得了【破碎巨刃】的适格之后的一段时间，伊迪斯对自己的力量充满了自信。 她开始寻找学院内的学员们进行掰手腕的比试，以伊迪斯的小力气，根本赢不了多数的学员。 但是学员们觉得一个小小声喊着你的名字，拽拽你衣角的小姑娘十分惹人爱，总是会故意让着伊迪斯。 于是，伊迪斯在掰手腕上建立起了自信，这对于她决定要自己开始做决策的决心有十分大的影响。 至今还没有看到伊迪斯在掰手腕上真正赢过其他学员，看上去能赢过的学员，伊迪斯都没有找过她们比试比试，而都是寻找和自己年龄相仿或大的。",
		file_3 = "伊迪斯，除了掰手腕之外，常常一个人坐在花园边的长凳上发呆，不知道她在想什么吗。有时候询问她，她总是笑着小声地说，只是走神了。 虽然，她不像学院里其他学员展现出姐姐型的温柔，但是，伊迪斯的温柔呵护就像在有空调的房间里，门外吹进来的一股凉风，轻轻地，不动声色的。 伊迪斯是在慢慢成长的学员，也许进步不大，但是总是默默地在进步着，当初她的父母决定送她来学员的想法没有错。 直到有一天，伊迪斯能够凭借她自己的力量为想要保护的人挥舞起【破碎巨刃】，也许那一天，才称得上【巨刃】。 她的微笑也会感染更多和温暖更多的人，也许有时候伊迪斯自己并不明白微笑的深层含义。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在伊迪斯童年的时候，和正常的少女一样，有着同龄人的力气和说话声音。开朗淘气的她和现在完全判若两人。 六岁的时候，伊迪斯罹患急性髓细胞白化病，在毫无预兆的情况下突然病发，在紧急送往医院的途中触发可并发症。 虽然伊迪斯及时送医并挽救了生命，但是，她就像重新出身的婴儿一样，变成了一张白纸。对病发之前的事一无所知。 当时，伊迪斯接受了什么样的治疗仍旧是个迷。但是，她就像从头到尾换了一个人一样，唯一的后遗症就是声带和肌肉力量受限。 伊迪斯的体质，表现出和变式试剂很高的适配性。",
		level_6 = 0,
		record = "据说，彩虹糖是伊迪斯康复之后最喜欢的甜食，希望纯白的她能够有一个彩虹色的明天。"
	},
	[27420] = {
		soulid = 27420,
		valuation = "雅娜黛茜亚进行测试的时候，展现出来的作战能力，让在场的测试员都觉得，自己像是被测试的人。 而她对测试员展现出来的实力，是她现阶段想要透露给大家的，可以看出来，其实她还留有余地。",
		file_1 = "【绯影摄心】不仅是雅娜黛茜亚身佩的魂智能武器的名字，也表现出她作战时候的风格。\n“射人先射马，擒贼先擒王。”雅娜黛茜亚的作战完美地诠释了这句话，只身深入敌后，取其性命，快速迅捷。只在敌人眼中留下绯红的倩影。\n雅娜黛茜亚的魂智能武器在获得之后，在她的要求之下，院长对其需求又进行了进一步的改造，使其使用的灵活性增加。\n【绯影摄心】在日常状态下，收纳在雅娜黛茜亚的腰间。雅娜黛茜亚对敌方展现出来的压制力，并不依靠大型的魂智能武器。\n而是来自于，自身的威慑力。选择轻便、易于收纳的魂智能武器，是出于快速击敌的选择。\n在快速靠近敌人的时候，利刃割开对方的护甲，改造后的剑柄部分暗藏扳机能够精准进攻对方“软肋”。",
		level_3 = 0,
		level_4 = 0,
		resume = "雅娜黛茜亚来到魂器学院是在组织的授意下到来的，成熟稳重的她来到学院，让大家都以为是新入职的教职人员。\n不过她在一定程度上的确承担起了“教育”学员的责任。作为曾经是教职人员的她，传道受业解惑的能力也是数一数二的。\n这也引起了另外一位“好为人师”学员——摩洛娜的关注，她们相见的时候，就像是几百只鸭子一同讲话一般，互不相让。\n真不知道，她们到底是对头还是关系真的非常好。但是能够看明白的是，很早之前，她们就认识。\n对于，作战策略和战斗机巧来说，雅娜黛茜亚的理解远远超过学院里的教职人员和大部分学员。\n那她为什么来到学院，来到学院是为了学习或者进修什么，至今仍旧是个未知的谜。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "耶梦加得修道院以培养了雅娜黛茜亚为荣，但是，也以培养了雅娜黛茜亚而缄默。修道院称她为“狂信徒”，称摩洛娜为“传教狂热”。\n摩洛娜和雅娜黛茜亚在耶梦加得的时候，就相识了。因为对宗教信仰不同的阐释，她们经常因此而争执，争执着常常演变成互相温柔发难。\n也是因为此，雅娜黛茜亚对于自己的身高被抓着发难耿耿于怀，所以喜欢穿有底，有高底的鞋子。这样不仅能够拉伸一下视觉高度。\n同样，也能让雅娜黛茜亚感到如履薄冰的感觉，这样的危机意识，让她安心。\n其实，摩洛娜的聪明，看穿了雅娜黛茜亚表面笑脸后面的佯装，想要用一种特殊的方式来给她一些支持。\n也许，尊重彼此的选择，心领神会对方的意图，这样也是一种奇特的友谊。",
		file_3 = "雅娜黛茜亚是托拉武装部门——执剑会的成员之一，ESP先遣小队也是雅娜黛茜亚手下管理的小队之一。\n作为执剑会的成员，雅娜黛茜亚也是托拉组织对新人训练的剑术、体术教官。因为训练严格，铁面无私，也被称为“绯色恶魔”。\n在人工智能暴乱之后，雅娜黛茜亚立马组织了部分成员，统筹了“电子统筹计划”来保护一般民众和人类历史智慧结晶。\n身为执剑会的管理层，雅娜黛茜亚对局势的预判和应对都非常敏锐。所以，能够迅速应对突如其来的变故。\n托拉给予她非常大的信任，同样，和雅娜黛茜亚一同参与任务的成员，也对她表现出极大的信任。其中，也包括摩洛娜。\n有传言说，雅娜黛茜亚不仅执掌着执剑会的明面部门，其实一些不见光的东西，也是由她管理着。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“当你凝视深渊的时候，深渊也在凝视着你。”雅娜黛茜亚把它当作坚定信仰之后，最为坚信的东西。\n雅娜黛茜亚在进入修道院的时候，不仅受到了信仰的洗礼，也看到了信仰无法触及或净化的地方。\n信仰总是站在人性的光辉制高点上去拯救、感化世人，但是，仍旧无法驱散黑暗。因为他们根本不了解黑暗，只是告诉世人黑暗的存在。\n为了驱散黑暗，必须先要深刻地感受到黑暗是什么，为什么会有“黑暗”。所以，雅娜黛茜亚身先士卒地拥入黑暗的怀抱。\n她那双坚定的眼睛，告诉着所有人，她深知黑暗是什么，所以她不会变，所以她要用她的方式给世界光亮。",
		level_6 = 0,
		record = "“小动物光靠自己可是无法想象出猛兽的叫声哦。”"
	},
	[28520] = {
		soulid = 28520,
		valuation = "卡翠欧娜是个安静的小姑娘，但是可别因为这样就小瞧她。面对复杂的操作系导弹精准打击，她表现出卓越的才能。冷静和细致的分析，在她这个年纪是非常难得的作战素质。正是得益于此，卡翠欧娜有着主导战局的能力。",
		file_1 = "【深海狂鲨】是卡翠欧娜的操作型魂智能武器，主要以远距离进攻为主。虽然是远距离，但是打击异常精准。\n以海洋生物来命名她的魂智能武器，不仅是卡翠欧娜自己本身对海的喜爱，也是一种对其战斗方式的描述。\n在面对如疾风怒涛般袭来的炮击，就像无意间落入水中，挣扎和躲避的无力感。\n无力感面前，等待着的还是深海里最具战斗的凶兽之一，令人无法喘息。\n原本重武器的炮击威胁和灵敏没有那么大，但是在卡翠欧娜的操作下，有着强有力的威胁。",
		level_3 = 0,
		level_4 = 0,
		resume = "卡翠欧娜，耶梦加得现任海军准尉。在海军编制的历史里，这么年轻就达到准尉的军衔的人屈指可数。\n虽然也有人怀疑是因为卡翠欧娜是得到了家族名声的荣荫，但是在见到卡翠欧娜指挥和日常训练的时候，他们都心服口服地闭上了嘴。\n卡翠欧娜虽然年纪轻轻，但是在耶梦加得海军行动和人工智能叛乱行动中，都有出色的表现。\n尤其是，在人工智能叛乱期间的反击指挥，在忍着眼疾问题指挥队员突破人工智能防线，拯救区指挥核心。在新兵口中被越传越神。\n也许这些听起来很遥远，但是你和卡翠欧娜接触、慢慢熟识之后，你会开始相信这些。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在卡翠欧娜出生的时候，由于母亲的身体原因，她天生就体质孱弱。\n由于体质孱弱，黄斑病变，导致锥细胞排列不规则，所以卡翠欧娜的右眼天然就带有器质性弱视。\n视力问题一直都是入伍的问题。作为耶梦加得海军世家，卡翠欧娜的爷爷自然希望后代子女都能够传承家族衣钵。\n所以，为了解决弱视问题，在卡翠欧娜8岁那年，爷爷决定接受基金会朋友的建议，用人工智能纳米医疗技术来解决眼疾问题。\n人工智能技术的确解决了眼疾问题，甚至没有任何排异反应和后遗症，直到人工智能叛乱当天……卡翠欧娜彻底失去了她的右眼，甚至差点丢了性命……",
		file_3 = "斯库拉斯家族是耶梦加得地区的海军世家，从祖辈到父辈再到子代，他们全部都是海军领域的佼佼者。\n外人总是好奇，他们家族为什么都对海军事业情有独钟，都纷纷投身到这个职业中去。难道就没有人对此感到厌倦吗？\n更深的原因，我们也不得而知。但是，的的确确他们对于海洋的喜爱，以及海军职业的喜爱已经有些迫近病态了。\n卡翠欧娜的爷爷，安泰·斯库拉斯是耶梦加得海军将官级的元勋人物，即使是现在在享受退休生活，在海军也有举足轻重的威信。\n自小在家里长大的卡翠欧娜，对于海洋和沙盘游戏，产生了不一样的喜爱。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "海军和空匪海贼，永远都是一副官匪有别、“猫鼠”不容的样子。但是在耶梦加得，海军和海盗的关系似乎不是表面上那么简单。\n进一步说，耶梦加得海军和伊莎贝拉海贼团，其实并不是表面上看上去的简单对立。\n其实，伊莎贝拉海贼团是前耶梦加得海军的民间分支，其首领在海军上层授意下，以“贼盗”的名义方便行官方不便行动之事。\n在海军高层加密档案上记载，安泰·斯库拉斯和希格纳是耶梦加得海军双雄。\n卡翠欧娜来到学院，一部分是为了治眼睛，还有就是完成和希格纳孙女接触的机密任务。",
		level_6 = 0,
		record = "“眼罩之下，说不定是一个开得很深的脑洞！”总有学员这样吓唬刚入学的新学员。"
	},
	[25920] = {
		soulid = 25920,
		valuation = "操作能力和战斗能力优秀，气场十足。在审时度势的能力上非常优秀。在如何选取正确的进攻方式上，也表现的优异。",
		resume = "辛西娅，拉弥亚黑街的女王，无人能撼动的存在。在鱼龙混杂的拉弥亚黑街，能够在一众人中脱颖而出，自然有她的手段。无论是严厉还是严苛，在黑街待过的人都领教过辛西娅的厉害。她手中听说把握着黑街的情报网络相关的秘密，所以被瓦利斯忌惮。也许来到学院，也有出于暂避风头的原因。",
		level_5 = 0,
		level_4 = 0,
		level_3 = 0,
		level_1 = 0,
		level_6 = 0,
		level_7 = 0,
		level_2 = 0,
		record = "冰雪永不凋零，容颜永不衰退。"
	},
	[201220] = {
		soulid = 201220,
		valuation = "战斗并不是火羽率先考虑的。相对与真正投入战斗，思考和应对，反而是她喜欢的。但是，一旦火羽认真起来，配合上魂智能武器的力量，她能挥打出漂亮的一击。",
		file_1 = "【烈火熔砾】是热能蓄放式魂智能武器。主要的热能储存，在于火羽背后的压缩气缸内。在战斗的时候，通过火羽的计算和操作，在锤头尾部释放高温火焰。\n得益于多年来的地质勘探经验，火羽的耐力是其他学员中数一数二的。在地质勘测中，多次接触火山地质，也让火羽知道怎样和高温环境相处。\n所以，对于火羽来说，忍受【烈火熔砾】在作战中散发出来的高温并不是什么煎熬的事。\n加之，在勘探期间获得的身体锻炼，也让火羽能有足够的力气去挥动锤型魂智能武器，并展现出惊人的压迫作战技巧。\n锤型武器在打击力度上原本就足够有冲击力。再通过热能冲击扩大挥击速度，对于敌人的贯穿伤害显著提升。",
		level_3 = 0,
		level_4 = 0,
		resume = "火羽会加入学院，仿佛是一场意外。在拉弥亚附近的矿山聚落进行地质勘探的火羽，正巧遇到了“托拉”的ESP小队成员。\n在摩洛娜的邀请之下，火羽计划在学院落脚一段时间，以此完成巴文克森金属矿的地层演变研究。在表示自己有兴趣的意愿之后，协会和托拉就立马办理了推荐手续。\n当火羽入学的时候，许多教职人员和学员都认为她应该是以“教职”身份来到学院，而不是单纯的学员。\n在众人表示疑惑的时候，火羽仍旧坚持以学员的身份在进入学员。她表示，自己还有很多东西是要学习的，并不能成为教导别人的老师。\n墨云老师在得知此事以后，表示了遗憾，觉得没有人能为她一天要上多门课而分忧了；也觉得，火羽的专业知识，应该被更多人所看见。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "火羽的父母，在她十八岁说要独自进行地质勘探的时候，并没有表示惊讶和制止。他们让女儿亲自去看看和体验这个世界，注意自身安全就行。\n就在火羽准备把地质知识转化为实践的时候，她遇到了“指南针”协会的地质勘探员乌波娜教授。\n乌波娜教授看重火羽对于地质学极大的热情，带领火羽一起进行了三年的实地勘探研究。在这三年里，火羽的专业技能有了大跨度的提升。\n在教授的引介下，火羽加入了“指南针”协会，成为了其中的一名成员。协会信息填报的时候，火羽并没有使用樱岛火羽的原名。\n而是填写了火羽鸦的名讳。由于鸦认为自己和家族理念存在一定的冲突，不愿使用樱岛之名，但却用了家族族徽火羽鸦作为自己的代称。\n在结束和导师c的一同研究之后，火羽开始了独立勘探研究。这次，火羽打算以巴文克森金属作为研究对象，探究这个影响世界格局的矿物有什么地质学层面的奥秘。",
		file_3 = "樱岛家族，是旧时代洛加尔知名的望族之一，也是沿袭了旧时神道信仰的家族之一。樱岛家族以尊崇自然“火灵”为尊，以“火山”为具体尊崇之物。\n在家族中，成员从小时候就要受到“炭火”的洗礼——高温禅房修行等等。经过长时间的沿袭，樱岛家族后续的基因产生了演化，身体对于耐高温比常人更为明显。\n但是，在新世代的洛加尔，科技的冲击，神道信仰日渐衰微。以及供奉的“火山”在地壳变动中，由休眠火山转变为寂灭火山，樱岛家族影响也逐渐衰退。\n失去信仰支撑的洛加尔地区，虔诚的樱岛家族心灰意冷地离开了。举家迁往仍旧有复杂信仰的拉弥亚地区。\n拉弥亚地区不仅有复杂包容的信仰环境，也有着丰富的地质矿藏。在一定程度上，受到“火山”信仰的火羽，也因此衍生出了对地质的喜爱。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“指南针”协会事是以自然科学为中心的世界性组织。他们涵盖了上至天体，下达地核的科学研究。\n协会成员没有固定的组织形式，或是明确的上下级关系。协会更多的是为各地的专业研究员，提供了不同地区科考的便利，以及研究场所。\n但，协会在每年固定的时间（11月16日）会举行全协会成员的科学成果、科研过程交流会。虽然，并没有强制到场要求，但是，每年几乎是全员到会。\n协会与组织托拉之间保持着密切的联系，并非是划边站队的亲近关系。而是，在托拉的协助下，为协会提供了许多成果保存和信息交流的便利。\n布克丝、波拉克、叶菲姆、扬等人也曾是协会中知名的成员之一。",
		level_6 = 0,
		record = "如果，火羽认真起来的话，在辩论上，可以和摩洛娜不相上下呢。"
	},
	[28820] = {
		soulid = 28820,
		valuation = "梅洛迪学员的战斗……完全就是演唱会，不过与含蓄的琉璃学员不同，梅洛迪学员丝毫不掩饰自己的热情。缺少作为辅助人员的自觉，偶尔会将自己置于危险的境地。所幸梅洛迪学员的身体素质足够优秀，能够应付大部分的突发状况，不过最好还是注意一下自己在战场上的定位。",
		file_1 = "梅洛迪的出生并不光彩，她是作为大家族继承人的父亲与门不当户不对、不被家族接受的母亲所生的孩子。懦弱的母亲在祈求梅洛迪能够幸福成长的同时也无比惧怕失去心爱的女儿，因此少女的童年几乎都是在耶梦加得郊区的别墅中度过的。在母亲为梅洛迪挑选的爱好中，梅洛迪唯独喜欢上了唱歌。她的歌声带有一种天然的感染力，像是将“意志”嵌入歌词中，以此牵动他人的感情一般。少女就这样与歌声相伴，作为母亲的笼中夜莺一点点成长着，直到那一天为止。",
		level_3 = 0,
		level_4 = 0,
		resume = "于音乐与科技交缠的时代，追逐星空的偶像——梅洛迪·克里斯托，以将歌声传递全宇宙为目标！\n在很久以前，梅洛迪就得到了当时还是独立学者的院长定制的魂器，从而摆脱身体上的缺陷，踏上了同时作为偶像与研究者的道路。人工智能叛乱爆发后，梅洛迪所在的空间项目研究所陷入停摆，而少女则作为贵重的战力被学院召回。\n梅洛迪的猫耳、话筒与扩音器属于外设魂器的一部分，控制端则是在少女的背部背部——依附着颈椎的“电子神经续接系统”。\n梅洛迪学员拥有与琉璃学员相同的共感能力，通过魂器的增幅能够产生意想不到的效果，这也是少女参与战斗的方式。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "梅洛迪童年时，曾经失足从二楼的阳台跌落。\n脊椎被草地上凸起的石块击中，几近断裂，肢体也失去了知觉。不幸的是，留守在家中的佣人们并没有听到年幼少女的哭声。梅洛迪就那样躺在草地上，直到眼泪流干，双眼倒影出夏日的星空。温柔的星光照耀着她的身体，群星的闪烁像是在演奏一曲无声的乐章，被那样的深邃与温柔吸引，少女的心中泛起了小小的感动。\n不久后，梅洛迪总算被外出巡视的佣人发现，经过诊断，梅洛迪脊椎部负责控制身体的传动神经受到重创，为了免于下身瘫痪的命运，委托当时依旧是独立学者的布克丝教授在梅洛迪的背后装设了“电子神经续接系统”——金属脊椎一般，集合了早期魂智能技术与耶梦加得尖端医疗技巧的次时代辅助设备。通过人造元件传输生物电流，让濒临瘫痪的少女能够再次站立。",
		file_3 = "因为那场意外，梅洛迪的母亲被命令不要再对女儿的生活加以干涉，梅洛迪就这样从母亲的宅邸中走了出来，开始作为歌手崭露头角。\n周围的人原本都认为身体上遭受的创伤会让梅洛迪变地孤僻，但少女却一天变地比一天开朗。同时，梅洛迪的歌声变地更具有感染力，自那天以后爱上了星空的少女，用自体内迸发出的热情，努力地想要将自己感受到的，来自星空的温柔传递给他人。想要前往给予了自己无限的灵感，令自己着迷的星空之上。\n加装在护脊末端的“辅助尾”是“电子神经续接系统”的延伸，黑色的尾巴实际上是有传导性的电子肌肉构成，通过一定程度的自律来控制梅洛迪的身体平衡。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "然后在某一天，梅洛迪遇见了名为琉璃的偶像少女。\n‘像是太阳一样温柔乐观的样子，真是让人羡慕。’‘像是星空一样深邃神秘的样子，真是让人好奇！’\n踏上同一舞台的瞬间，拥有优秀共感能力的两人就依靠歌声达成了互相理解。\n被悠远的星空牵着着，仿佛随时要冲上宇宙梅洛迪，第一次感受到了来自地球的吸引力。\n如果说梅洛迪的歌声是自深远宇宙而来的回响，琉璃的歌声就是自内心油然而生的温柔灯光，两人互相尊敬着对方，又互相将对方视作劲敌，结下了属于两人，属于歌声的缘分。",
		level_6 = 0,
		record = "“这种程度的事情对梅洛迪小姐来说只是小菜一碟，全部放马过来吧！”"
	},
	[201020] = {
		soulid = 201020,
		valuation = "因果的能力十分平均，几乎每项测试成绩都卡在及格边缘，某种程度上来说，这也非常厉害了。",
		file_1 = "赌场是库库尔坎最常见的场所之一，在穷奢极侈的销金窟里，没有人相信那个闯入的少女是为了寻找钱包的失主。 但事实就是如此。\n 因果捡到了钱包，一路追着失主来到赌场，又阴差阳错上了赌局，对规则一窍不通的她被诓骗着压上全部身家。赌徒们幸灾乐祸地围观着这场好戏，他们喜欢圈套中的猎物一无所有时流露出的挣扎和崩溃。\n 一切出乎意料。少女奇迹般地赢下了赌局，同时获得了令人眼红的财富，人们不甘心地称呼她为“幸运儿”，以此安慰自己的嫉妒心。然而“幸运”并不意味着安全，穷凶极恶的赌徒们盯上了因果，城市阴暗的巷道中上演着追逐。\n 高空摔下的花盆离她一步之遥，飞速行驶的车辆和她擦身而过，连穷途末路之际都意外出现了转机，少女似乎总是和幸运随行——正在库库尔坎执行任务的风魔胧顺手救下了因果，两人一起回到魂器学院。",
		level_3 = 0,
		level_4 = 0,
		resume = "客观来说，在一众优秀学生之中，因果的个人能力并不突出。\n很多人认为因果身上有着神秘的幸运力，但我们不能以这类无实际根据的因素来对她进行评判。不过，有一点是可以确定的——无论“幸运”是真是假，这种说法的存在为团队中的部分成员带去了信心和激励，从而在某些时刻激发出她们更多的潜力。除此以外，因果天真善良的性格让她拥有不错的人气，这无形中增强了同伴之间的凝聚力。\n或许她本人没有察觉，当身处团队中，她将发挥出无与伦比的价值。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "自从因果加入学院，学员中不知不觉流行起了“考前幸运传递仪式“，具体的流程如下：\n 一、沐浴更衣，净手焚香。\n 二、寻找因果，以手触碰她身体的任意部位。（注意征得本人同意，不可引发同学矛盾。）\n三、诚心感谢，虔诚祈祷考试顺利。\n根据大家的反馈，因果同学的幸运传递非常灵验，但我们更希望魂姬们通过平时扎实的训练和积累来取得优异的测试成绩。",
		file_3 = "总是好心办坏事的千竹向因果取经，究竟怎么样才能真正帮助到别人？于是因果担起了千竹的半个“师父”，两人经常一起完成日行一善的目标。\n某次，千竹在帮助老人搬运一株月季花的过程中不小心把花盆摔碎了，再次将事情搞砸的千竹十分沮丧，为了让她打起精神，因果偷偷找到那位老人，恳请他撒一个善意的谎言。\n ——花盆是去世的妻子留下的，她还在其中藏了一封家信。如果千竹没有失手将花盆打破，老人永远无法解开和妻子的心结。\n单纯的千竹相信了老人的话，并重新振作起来，更加积极地帮助他人。事情却没有就此结束，老人受到因果的启发，真的在妻子的遗物中找到了什么，那不是书信，而是最后留给老人的真情告白的特别录音。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "因果的日记本里记载了日行一善的内容，但其中还有一个秘密——从日记本的最后一页翻起，上面记录的是因果做的恶事。\n 我们摘取了部分文字：\n 2月20日，我饿得晕倒在库库尔坎的小巷里，浑身黑色的流浪猫叼着一条香喷喷的烤鱼放在我面前。抱歉，我忘记说“我开动了”就把烤鱼吃得一干二净。\n3月7日，我拿到打工的报酬啦！我给小黑买了两条烤鱼，趁着它吃鱼的时候偷偷摸了耳朵。抱歉！毛茸茸的手感实在太好了，忍不住多揉了几下，小黑瞪了我好久。\n…………\n……",
		level_6 = 0,
		record = "根据因果的叙述，目前为止，她经历过最幸运的事是……在红苹果抽奖环节抽中了唯一的一箱青苹果。"
	},
	[26120] = {
		soulid = 26120,
		valuation = "黑木幸的单独作战能力是无可挑剔的，精准快捷地结束战斗是她的特色。和热能匹配的相性也给她的作战助力许多。但是，在面对多敌人的情况之下，就可能暴露出控制能力不足问题。",
		file_1 = "【赤影】若是存在以前的时期，定会被称之为妖刀，通体乌黑，闪烁着赤红色的妖异光芒。 但是，这把传闻的妖刀，在幸的手里就像温顺的小兽。体格娇小的幸，却能用【赤影】施展出多样的刀术。 虽然幸能够用它使出不同的刀术甚至剑术的变体技，但是幸仍旧偏爱以必灭的一击结束战斗。 快速，精准，不拖泥带水是幸的战斗信条，也是幸对传统剑道的传承。 当【赤影】出刀的时候，就像夜幕中红色的下弦月初现，眨眼间幸就出现在敌人背后，完成从背到前的致命一击“宿业两断”。",
		level_3 = 0,
		level_4 = 0,
		resume = "黑木幸的家庭环境和之前受到的训练，形成了她高冷话少的性格。她像忍者，也像军人一样，对命令完美执行。 不该问的不问，不该说的不说，除非必要，交流多以肢体语言代替。要开口说话的场合，也是简洁有力的对答，很少有过多的语气词。 幸虽然喜欢和式点心大福，喜欢振袖，但觉得传统的和服过于笨重，又不喜欢忍者服装的拘谨，所以偏爱宽袖的便服。 进入学院之后，幸对于洛加尔地区的学员和喜好武技的学员表现出了很大的好奇，经常和她们进行联合修行，来提升自身技力。 幸的战斗风格干净利落，以迅速完美完成任务为首要目标。用敌人无法反抗的必灭一击完成宿业两断。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "幸在击倒敌人后，从来不回头看敌人是否还能行动。她对于自己的一击致命有着十分的自信。 诚然，到现在为止，暂时还未记录到受到幸致命一击的对手还能继续存活的样本。 至于，模拟战中对战的学员和一同修行的学员为什么没有受到致命一击，大概是因为幸还未完全爆发出她的凶意。 传闻当幸在对敌人爆发出完全的凶意的同时，魂器【赤影】的性能也会有一定的改变，幸的必灭斩击会带有撕裂和吸魂的效果。 即使，仍旧一息尚存的敌人也会因为持续伤害而毙命。",
		file_3 = "目前尚不明确幸在战斗机动性上的作战技巧来源于潜行还是日式忍道，但是她和胧的行动能力能达到不相上下的地步。 幸的战斗学习天赋是难以估计的，在和秋、薰之间的模拟训练的时候，通过观察能很快地学会对方使用出相对简单的技术。 通过研究观察，幸的眼睛是她学习快速，精准定位对方的强有力武器之一。 借助双眼的观察，在和麟的切磋之中，幸的魂器【赤影】在应对敌人近距离贴身攻击的时候，幸也可以借助刀柄的力量击退对手。 同时，幸自身的战斗力量也不可小觑，在脱离魂器白刃战中，尚未观测到幸所使用的格斗技巧流派。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "黑木家族长久以来，都是洛加尔地区背后的影武者。担任保护权要，执行狩猎计划，秘密任务等，权利背后的活动。 到现在，黑木家对于家族成员的训练已经告别传统日式忍道以及剑道的专门培养，在重视传统技术的培养之外，还注重对多种战斗技术和作战知识的培养。 他们对新技术、新科技知识的接纳也与传统守旧有很大的差别。而且在家族成员出生之时，家主就注重成员观察双眼的训练和培养。 双眼观察术对于黑木家来说，是除了战斗技艺之外的核心机密。\n同样，黑木家族也是以统一世界语言为目的的世界语组织——“托拉”的支持者。 自1887年柴门霍夫创造世界语，以期统一世界语言的时候，组织托拉就在背后运营而生。组织主要是在柴门霍夫博士背后保证世界语计划的推进。 各国许多宗教团体都确认世界语作为官方语言来使用，并用世界语翻译了许多典籍。 当人工智能事件发生之后，组织托拉察觉到其背后暗流涌动的复杂势力，其中除了“军方”“基金会”“暗影”等已知的势力之外，潜藏在阴影里的组织“巴别塔”也露出了尾巴。 对于学院和魂器以及人工智能的高度关注，组织托拉也派遣了他们的先遣队进入学院，完成秘密的任务。",
		level_6 = 0,
		record = "据统计，幸在开心的时候，最常用的回应就是，点头和“好的”。据班长描述，当幸将嘴巴用衣服高领遮住的时候，是害羞了。大概。"
	},
	[26220] = {
		soulid = 26220,
		valuation = "芸的狩猎技巧和灵活性是出类拔萃的，对于体格较大的敌人也能轻松取下对方的首级。但是闪电一击的战斗方式反而会让她的体力加速消耗，长时间的消耗战芸并不擅长。",
		file_1 = "【凰羽】是六把闪电匕首的魂器总称。六把闪电匕首都是锋利无比的快刀。 平时，【凰羽】都安静地躺在鞘内休眠。在激活之后，【凰羽】会释放出黄色的电光，并依靠磁力悬浮在身侧。 当芸展开【凰羽】的时候，就像猎鹰起飞展翅一般，若是很近的距离内，可以很明显地听到匕首出鞘的雷声轰鸣。 在狩猎敌人的时候，芸使用单把的匕首一般不超过四把就足以将对手击败。芸毫不害怕敌人反抗，因为闪电匕首击中时，附带了短暂的麻痹效果。 若是有幸逃脱，【凰羽】也会在芸的手中变成把把飞刀，准确地追击移动中的敌人。",
		level_3 = 0,
		level_4 = 0,
		resume = "作为职业的狩猎者，芸与人讲话简短干练，看起来很冷酷的样子，其实很喜欢跟自己养的麻雀嘟嘟交流各种事。 知道自己是家里的养女之后，对日后的生活并没有什么影响。只是，对于洛加尔地区的好奇占据大多数思考。 对于人工智能暴乱，芸并没有什么特别的感觉，只是面对组织交付的任务，芸将人工智能定位为敌对势力，是需要扫除的障碍。 许多时间里，芸都逃掉了学院安排的课程，要么躲在图书馆看鸟类图鉴，要么在风景好的地方和鸟类交流。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "芸的狩猎技巧，真的能算得上狩猎吗。这个问题需要思考。在没有魂器【凰羽】的情况下，芸像忍者一样巧取敌首。 但，在使用魂器作战的情况下，其声如雷霆，行动如电。虽然能够顺利击倒对手，但是对方是被突如其来的雷声吓破胆了，还是利器取命，有待考证。 芸的作战技巧，明显受到了仿生学的启发。 在准确锁定目标上，芸就像猎鹰在制高点盘旋一样，等待最佳的时机。夜间和复杂地形环境下，能够像猫头鹰一样灵活和精准。 面对负伤逃亡的敌人，芸也能够像兀鹫一样不放过任何一个目标。 或许芸真的像传闻一样，能够和鸟类进行沟通交流。 也许，芸的歌声也会像夜莺一样动听。",
		file_3 = "芸除了喜欢和鸟类说话之外，还喜欢用食物训练自己的狩猎技巧，当然训练用的食物也不会浪费，导致芸的料理技艺意外的很不错。 她喜欢切牛肉、羊肉、猪肉等，在分解大块肉的时候，体悟肌肉的肌理，并感受用匕首伤敌手感。 魂姬们都觉得芸是个奇怪的魂姬，也都不怎么和她过多的交流。但是，对经常停在她头上肥嘟嘟的麻雀充满了兴趣。觉得那不是麻雀，而是一只肥胖的烧鸡。 而麻雀嘟嘟则是芸和家族交流的信使，芸教会了嘟嘟用鸟喙简单地敲击出世界语的莫斯电码，以此来向家里传递交流代号。 至于，对于它身材产生怀疑的人，其实都中了障眼法。 不过，如此的肉质，也许做烤乳鸽级别的美食~……",
		level_7 = 0,
		level_2 = 0,
		file_4 = "芸的养父母是世界组织“托拉”在耶梦加得地区的背后拥护者之一。 作为家族的养女，芸为什么没有随家族的姓，是因为养父母在遵从芸亲生父母的嘱咐，根据她原本姓名的世界语发音所命名的。 家族长久以来，都是忠勇之士的后继家族。所以，他们尊重芸自己的意愿，并教授她家传的武术技巧，而这狩猎技巧正是来源于对世间生物习性的道法。 效法不同的生物，所悟出的本领都是自己所独有的，只有其源统一。对于鸟类的喜爱，让芸学会了灵敏的作战技巧。 武术的高天赋，也让芸很早就进入组织，成为组织的成员，并和黑木幸、摩洛娜组成电子稳定先遣小队，展开组织秘密任务。",
		level_6 = 0,
		record = "有人透露，芸和麻雀嘟嘟联系的暗号是：“呼噜噜。”但是，其他学员尝试并没有什么反应。难道，芸真的会鸟语？"
	},
	[26320] = {
		soulid = 26320,
		valuation = "令人意外的是，摩洛娜在白刃战中表现出来的格斗技巧，作为一名文化保护者来说，在没有魂器的情况下还能持续作战，实属难得。 在防御和辅助二者之间，有着很好的协调，局势判断和预估也十分难得。作战时的传教，对于敌人来说也是一种精神折磨。",
		file_1 = "【巴兰之诫】相对于【圣堂十字】和【圣殿之盾】来说，更像是两件魂器性能的综合。 提供了摩洛娜不俗的治愈能力，也赋予了她一定的防御能力。综合摩洛娜本身对于战场的把握，能够给队友提供强有力的援助。 【巴兰之诫】在同步率达到100%的时候，不仅可以抵御对手全部的攻击，治疗的效果也得到极大提升，附加的“传教”也让学员们终极技能能量的积累也加快了许多。",
		level_3 = 0,
		level_4 = 0,
		resume = "摩洛娜·菲西斯自小在耶梦加得五区生活，接受的是宗教知识的教育。 除此之外，摩洛娜进入托拉前，还作为教会的守护进行过格斗术的培养，之后在教官雅纳黛茜亚的指导下进一步提升了实力。 在科技发达的现在，摩洛娜认为人工智能会侵蚀人类的精神，毁坏人类的独特性。因此，她会饱含爱意的教育所有人远离人工智能。 而对于人工智能，摩洛娜则是毫不留情，她会清除一切失控的人工智能，这也是组织的目的之一。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "摩洛娜的毅力是全学院算得上顶级的。 在每次进行完精疲力尽的模拟战训练之后，都还有很大的余力和学员们进行灵魂式的理念传教。 终于，在摩洛娜多次传教之下，魂姬麟终于忍不住地问摩洛娜：“你认识唐三藏吗？”此刻，摩洛娜的眼里发出了欣慰的闪光。 摩洛娜表示她很钦佩唐师傅的执着，对信仰的坚定，没想到麟竟然对此很感兴趣。于是，摩洛娜更加卖力地向麟传授教义。",
		file_3 = "学院里几乎没有摩洛娜不认识的学员，或者说，全学院的学员没有不认识摩洛娜的。 就算大家以渎神的口吻说她是“恶魔的传教士”“邪魔的低语者”，她也毫不生气，还打算教大家区别地狱恶魔的种类以及被她指代成相关恶魔的人工智能。 当然学员们对她说的都是开玩笑。而在平常她们需要帮助的时候，摩洛娜都会热心地帮忙。 虽然因为年龄和外表的原因，摩洛娜看起来和学员们有点差距，但是她的无微不至夹带“私货”的关心，总能温暖到每一位学员。 也正是因为如此，在电子稳定小队中，摩洛娜深受幸和芸的信赖。出众的口才让她成为了情报和小队决策人。 任务的执行和展开，主要是靠摩洛娜的信息收集，在幸和芸身上组织则被交付了武力相关的任务。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "菲西斯加入组织的时候是典型的模范生，默默关心小队的成员，雅纳黛茜亚教官说东绝不往西，不过是那位的话，大概很多人都不敢反抗吧哈哈哈。 她们那一个小队是出了名的沉默寡言。那位教官为了她们更好的进行任务，逼着三个人讲话。 她们手上时常拿着《400句顺口溜》、《人生道理大全》、《如何和人沟通》等等书籍，最后大成功的只有菲西斯一个人，也不知道她怎么开悟的，之后，她的嘴就没有闭上过。 听说，她开悟的那瞬间，当着雅纳黛茜亚教官的面提出了很多课程的不合理之处，没想到雅纳黛茜亚教官没有报复，反而把她任命为小队队长。看到的人告诉我，那是个百年难得一见的场景，诶，太可惜了。\n——某位饱受摧残的组织成员",
		level_6 = 0,
		record = "如果不是学院禁止开设礼拜场所，摩洛娜一定会在学院最好的地方建立祷告所，邀请学员们每天诵读托拉的教义。"
	},
	[29220] = {
		soulid = 29220,
		valuation = "露缇拥有强劲的战斗实力，多项能力的评级近乎顶峰，但与此同时， 另外几项能力评级接近谷底，可谓是某种程度上的超乎常人了。",
		file_1 = "露缇钟爱粉色，她的世界闪耀着“粉嫩~粉嫩~”。露缇的衣柜里一大半的服饰和粉色相关，房间布置更是无时无刻不散发着粉嫩嫩的少女心思。据说她曾经想把自己的魂智能武器涂上粉色颜料，但“歌德的意志”对此存在异议，她只好无奈作罢。\n关于露缇对粉色的喜欢可以追溯到教堂时期。当年被安置在西维特教堂的露缇非常内向，年长的修女玛利制作了一盒精致的桃花酥送给小女孩，或许是甜蜜的糕点融化了心防，从那以后，露缇正式开始了教堂生活，而粉色的桃花酥至今是她的最爱。",
		level_3 = 0,
		level_4 = 0,
		resume = "露缇有着自己的行事逻辑，旁人很难理解她的想法。她的世界里，歌德是存在于浩瀚宇宙中的造物之主，歌德的意志即是万物的意志，歌德的指引乃命运的指引，因此她虔诚地成为了歌德的“傀儡”。\n电波是露缇和歌德的中间桥梁，她坚信任何事物都有独特的电波，而电波契合的彼此终会相逢。至于她所说的电波的密码、颜色……实在不得而知。\n作为“怪人”，露缇入学之初几乎没有交到朋友，而后在班长的影响下才逐渐融入学院。她崇敬的歌德则以“意志”的形式暂存于魂智能武器中，为她的每次战斗保驾护航。不得不说，露缇的战斗能力十分优秀，但社交方面还需要多多引导。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "由于歌德的意志暂存于魂智能武器中，所以露缇干脆给武器取名——“造物之主·歌德”。\n每当人们以为歌德就是武器时，露缇总会不厌其烦地解释着两者的差别，但那些话听起来就像奇怪的绕口令，往往让人一头雾水。\n武器“歌德”的日常维护一般由露缇本人完成，令机械师都感到惊讶的是，露缇能在第一时间感知“歌德”的状态，哪怕是武器内部精密零件的细微损坏。用露缇的话来说，这就是“电波感应”。\n露缇主要通过手中的操控版来操纵“歌德”，与机械手臂相连的傀儡丝是运用蜘蛛丝仿生技术研发的特殊丝质材料制成的，具有弹性好，强度高等诸多优点。无聊的时候，露缇会用傀儡丝翻花绳……",
		file_3 = "七年前，军方在耶梦加得破获了一起大型人口贩卖案件，五岁的露缇被成功解救，随后被安置于当地的西维特教堂。\n神父和修女们对这些可怜的孩子很友善，不仅给予衣食和住宿，还教导他们学习，同时进行传教。\n当周围的孩子们都有了虔诚的信仰，露缇却始终“不开窍”，她不明白信仰究竟是什么。\n直到那天，她因为没有参加礼拜而被几个年长的孩子殴打，教堂彩窗透过了五彩琉璃般的光线，她似乎在那一瞬间听到了来自遥远世界的声音。\n——那是独属于她的造物之主，是她心中的“歌德”。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "当年的大型人口贩卖案件轰动一时，二十几位受害者得以解救，军方的声望再次水涨船高。\n受害者的年龄均低于十岁，他们一部分和父母团聚，那些身世不明的则分别被安置在教堂、孤儿院等地，同时军方也收留了部分资质优秀的儿童。\n露缇不记得自己的父母，她和其他五位孩子被安排进了西维特教堂。两年内，三位同伴被好心的家庭收养，露缇却不想离开，她留在了修女玛利身边，直到学院一行人出现。\n临别之时，玛利将珍藏的十字架送给了露缇，并告诉她——\n“信仰本身没有形状，因此才可以是任何形状，那么耶稣、歌德……种种称呼又有什么不同呢？走出你的内心吧，露缇，一切都是相连的。”",
		level_6 = 0,
		record = "“我会和真正的歌德相遇，在未来的某个2月30日。”"
	},
	[201320] = {
		soulid = 201320,
		valuation = "佩特里夏对魂智能武器的使用有些不太稳定，有时状态绝佳，有时极不协调，她需要学会更好地掌控武器。",
		file_1 = "佩特里夏擅长打扫、插花、烘焙……这些都是跟母亲学的。此外，她的飞镖玩得很好，甚至蒙上眼睛也能准确投中靶心。为此，学院试图挖掘她的射击能力，例如使用弓箭、枪支等。但遗憾的是，除了飞镖，佩特里夏玩转不了其他武器。\n至于佩特里夏的魂智能武器——碎裂回旋，她似乎是将它当做特殊的回旋镖来使用的。",
		level_3 = 0,
		level_4 = 0,
		resume = "佩特里夏拥有超群的记忆力，与此同时，她对方向有着天生的敏锐度。即使是陌生的场所，佩特里夏也能迅速熟悉，并摸清转角、出口等关键地点，这在战场上非常有利。\n佩特里夏的耐心和毅力都很优秀，这大概是从她喜爱的拼图游戏中锻炼出来的，但她的耐心会在遇到人工智能时化为乌有——我们注意到，佩特里夏将人工智能视为“绝对错误”，她憎恶那些家伙，并一定要将其纠正。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "佩特里夏很少主动与人交流，但她对外出执行任务非常狂热，每个月的外出任务统计次数中，她总是高居前三。一旦回到校内，佩特里夏就窝在宿舍，不太乐意出门了。\n我们在例行查寝的过程中发现，她的房间摆满了各式拼图，连地毯的形状都是一块一块拼凑而成的飞镖靶子。但有一处不同寻常：整洁的墙面上挂着一张巨大的残缺拼图，分辨不清原貌，或许是她还没有完成的作品吧……",
		file_3 = "加入魂器学院后，佩特里夏新学了一门技术——机械组装。佩特里夏可以将拆卸掉的枪支、机甲等迅速组装还原，在她看来，这和拼图的过程十分相似。据相关人员反映，佩特里夏在机械组装上非常有天赋，甚至能够改装出性能更加优异的器械，目前，她对作战时使用的新型防护罩进行了改良，提升其承受物理攻击的上限，效果理想。\n有传言称，佩特里夏一直想拆卸一次小机器人阿基米德，不过总是在伦茨哭天喊地的叫声中败下阵来。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "佩特里夏出生在一个普通家庭，尽管生活不是那么富裕，但她拥有非常幸福的童年。\n父亲回家的日子是佩特里夏最期待的时光。每个月的这一天，母亲会早早打扫干净屋子，为窗前老旧的花瓶插上新鲜花束，然后烘焙好香喷喷的奶油面包，准备好甘甜的百花蜜，陪着佩特里夏一起等待傍晚来临。父亲总是踩着夕阳回到家中，他会给佩特里夏带大大小小的礼物，尤其是拼图玩具。佩特里夏没什么玩伴，但她并不感觉孤单，拼图变幻莫测，她喜欢将散乱的一切恢复成规则的感觉。\n佩特里夏遇到了挑战，那是一份有着万张单片的拼图，也是父亲送给她的生日礼物。佩特里夏花了近一个月的时间才拼凑出完整图案，她看到了海洋、森林、山脉、城市……世界的风景如画卷般展现在少女的眼前，她激动地想向父亲炫耀成果，但那个傍晚，父亲没有回来。整座城市陷入了前所未有的恐慌，人工智能肆无忌惮地残害人类，母亲的肢体浸透了那份破碎的拼图。\n世界成了碎片。\n每个人，每个人工智能，每个物体都是一块单片，如果将所有错误的单片纠正回正确的位置，一定能拼凑出那个和父母共同生活着的安宁和平的世界吧？",
		level_6 = 0,
		record = "在加入魂器学院前，佩特里夏去过的地方很少，对她而言，世界曾经是新奇而未知的。"
	},
	[203020] = {
		soulid = 203020,
		valuation = "看似笨重的双掌实际非常灵巧，配合上惊人的撕扯力和爆发力，承受艾的一击必定会付出惨痛的代价。更为重要的是，我们相信，艾拥有着突破自我的无限可能。",
		file_1 = "普通情况下，艾的手掌大小是正常人的四倍左右，放松时掌心非常柔软；启动魂智能武器之后，手掌可以增大二至三倍，力量和硬度也大幅增强，与此同时，手掌对疼痛的敏感度相对降低。\n除了战斗，艾的手掌还有许多妙用，比如冬天取暖，做熊爪饼干的模具……闲暇的时候，艾经常和伊卡洛维互相捏手掌肉球， 这让许多人感到羡慕。",
		level_3 = 0,
		level_4 = 0,
		resume = "异化人的身体机能融合了相关动物的特质，这一点在艾身上具体表现为：力量。\n绝对的力量面前，技巧形同虚设。艾的战斗给人一种畅快感，没有多余的动作，以最干净利落的姿态，最直接纯粹的力量击碎眼前的一切障碍。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "艾喜欢棒球，她借此训练自己的控制力。每次挥舞球棒，艾需要掌握好力道，尽量让球的落点符合预期，而不是因为击打的力气过大而消失得无影无踪。此外，她的棒球手套都是定制的，常规手套对她来说太迷你了。\n拳击是艾的强项，自从她加入魂器学院后，一直蝉联校园拳击比赛的冠军，至于万年老二是谁……不如猜猜看吧。",
		file_3 = "艾加入魂器学院后的第一战非常轰动。作为新生，她在战场上秒了敌方的人工智能首领，并且初步展示出了战斗指挥才能。那一战振奋人心，军方也对她表示赞赏。面对媒体铺天盖地的报道，艾没有详谈战斗细节，她感谢了队友的支持和帮助，然后开始“跑题”。身为异化人，她证明了自己的力量，并且公开呼吁人们给予这个群体公平公正的对待。\n据说艾的发言在洛加尔的城市巨屏上直播到一半就被掐断了，即使如此，艾和异化人还是成为了当时的热点话题。一夜之间，艾有了许多的欣赏者、仰慕者和支持者，当然，更多的是反对者。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "尽管世界宪章中规定了异化人平等地享有权利，但实际上，社会对异化人的包容度极低，歧视现象普遍存在。与此同时，由于异化人身上的谜团还有不少，针对他们的研究从未停止。\n艾是在实验室出生的，或者说，她本身就是一个实验品。\n十岁之前，艾没有见过外面的世界。拥有尾巴的同伴被一次次切割断尾，记录再生时间；有着长长耳朵的同伴被灌输各种声音，测试听觉敏锐度；至于艾本人，她的手掌不知道在击打、撕扯中断裂过多少回了。\n随着非法实验室被取缔，艾终于开始了正常生活。融入社会的过程非常困难，但她满怀信心，然而她很快意识到，一切都没有改变。明显的动物特征被视为低劣的象征，各种场合中，异化人都得不到平等对待，甚至在地下黑市，还存在着针对异化人的贩卖与交易。\n“去推动一场变革吧！”，艾心底的声音呼喊着，“为了有尊严地活着。”",
		level_6 = 0,
		record = "艾的名字是自己取的，在实验室里，她仅仅拥有一个代号。"
	},
	[26920] = {
		soulid = 26920,
		valuation = "李的各项测试成绩较为均衡，整体实力不俗。高超的剑法极具伤害力，同时兼顾灵巧飘逸，她的战斗身姿令人赏心悦目。",
		file_1 = "李一入校就吸引了布兰琪的注意——那个巨大的瓶实在惹眼。这本来应该是结交朋友的好契机，结果却出乎意料。\n爱喝的两个人莫名展开了一场争论，布兰琪喜欢喝尽兴，因此总是醉醺醺的；李坚持饮三分，严格控制在微醺而不醉的状态。正当两人相持不下时，看热闹的学员们提议以饮料定胜负。结果，李还没喝到微醺，布兰琪就醉得高高兴兴睡大觉了。\n虽然这场史无前例的争论不了了之，但故事却在学院里广为流传。很长一段时间内，餐厅甚至将她们的海报贴在门前，以此吸引客人。从那之后，布兰琪和李成了全校皆知的一对冤家。",
		level_3 = 0,
		level_4 = 0,
		resume = "李的剑法自成一派，有着非常强烈的个人风格，据说是她的父亲传授的。学院一致认为，李的剑术水准精湛，可以与之匹敌的人寥寥无几，但她本人却表示还没能发挥出这套剑法的全部实力。\n值得说明的是，李对使用芯片来增强身体机能的行为比较抵触，在院长的说服下，她才勉强接受普通无害的芯片，一旦下了战场，她会第一时间摘除芯片装置。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "李和阿加莎有过多次秘密交谈，贝蒂还因此大发脾气，认为这个新人占据了妹妹的时间。\n关于交谈的内容，阿加莎直言不讳。李想争取曼珠沙华的支持，让荆棘鸟的首领迪丽莎卸任。\n“曼珠沙华”事件过后，迪丽莎率领的荆棘鸟受到重创，被尼德霍格欺骗的成员们对迪丽莎的领导产生了质疑，对增强型的玛伽也产生了不信任感。组织中的几位老人前往派森找到了李，希望她返回墨格尔，接替迪丽莎的首领之位。关于母亲的记忆在这些人的叙述中变得逐渐清晰起来，李不想当什么首领，但她希望完成母亲未完的心愿——将致幻芯片玛伽彻底从荆棘鸟中剥离，依靠清醒的头脑和真正的力量推动女性保护。\n由于担心迪丽莎先一步对李出手，李听从组织中几位老人的提议加入了魂器学院，一来这里绝对安全，二来可以和曼珠沙华的首领阿加莎接触。\n阿加莎明确表示暂时保持中立态度，曼珠沙华不愿意干预荆棘鸟的内斗，但是，如果她们的内部争斗影响了整个墨格尔地区的安稳，曼珠沙华不会坐视不理。",
		file_3 = "李的剑术传承自父亲，据说这套剑法是他游历各地后独创的，称为侠客行。\n尽管李在剑术上的造诣早已超过同龄人，但她还远远没有达到父亲的境界。为了修行剑法所需的“身形灵动，飘逸自然”，李一直负重练习，她的身法几乎没有破绽，然而，李始终没有领悟到内心的“洒脱随性，剑随意动”。李的父亲生性自由桀骜，他的剑法一招一式无不潇洒地表达自我，可是李的性格更像母亲，沉稳内敛，坚定执着，还有着强烈的责任感，这让她很难体会父亲剑法中的感情，剑术也迟迟不再精进。当李向父亲诉说困惑时，他哈哈大笑。\n“不要总是追随别人的脚步，哪怕这个人是你的父亲。你应该去打破！去开拓！去创造属于你的独一无二！”\n因此，当那些来自母亲故乡的不速之客登门时，李明明知道这是一趟浑水，却还是打算去经历。为了母亲，为了剑术，她需要独自成长。意料之中，父亲支持她的一切决定，并在临行前将她心心念念的巨大瓶赠送给了她，瓶里还装满了陈年的女儿红。\n“喝完这一大坛，就回来看看吧。”",
		level_7 = 0,
		level_2 = 0,
		file_4 = "二十年前，墨格尔还不是如今这座战后城市，而是一座不依靠科技的小村落。一位外乡人游历至此，和当地女性保护组织“刺鸟”的核心成员之一米兰达相恋，而后两人育有一女。女孩儿的父亲为她取了一个传统的东方名字，人们不习惯外乡的取名方式，干脆称呼她“李”。\n飞速发展的科技最终打破了墨格尔的宁静。李三岁那年，一种名为“玛伽”的致幻芯片悄然流行，“刺鸟”组织中的不少成员以此来增强自己，并认为这是推动女性保护的捷径。人们陷入了疯狂的芯片热潮，部分成员甚至想将“玛伽”植入年幼的李体内，以此获得超乎常人的体魄和力量。米兰达面对昔日的伙伴们感到十分痛苦，无奈之下，她决定让李离开墨格尔，前往那座东方城市——派森。米兰达独自留了下来，她想将歧途上的“刺鸟”拉回正轨，但最终失败身亡。\n之后，“刺鸟”内部制度变革，选举出了第一任首领，并正式将组织更名为“荆棘鸟”。现在，墨格尔不再是曾经的小村落，而荆棘鸟也成为了和芬里尔、曼珠沙华齐名的三大黑帮之一。荆棘鸟的成员不仅依赖于致幻芯片玛伽，甚至增强了它的效果，唯一不变的是，她们始终只接受女性成员。",
		level_6 = 0,
		record = "李微醺的时候，话比平时多一些。不过，不要试图在这期间从她嘴里套话，她很可能直接拔剑。"
	},
	[202220] = {
		soulid = 202220,
		valuation = "作战能力非常优秀，这也是经历过军方训练的魂姬的共性，她们在年纪轻轻之时就已经掌握了丰富的战斗技巧。霞的优势之处还不止于此，她的体能也异于常人，但与同样军方出身的玛琉又有些不同……保密的资料太多，似乎有不想让人知道的过去。",
		file_1 = "“炽骨守御”是非常特别的魂智能武器，它包含有战斧、单手盾还有拟态尾三个部分。意外的是，虽然外形庞大、结构坚固，但武器本身的质量并不高，所以敏捷性很优秀。主要的破坏力则来自于斧刃、盾面以及尾针的高温。经测，战斗中斧刃的温度能够维持在一千摄氏度到三千摄氏度之间，由霞自己的意志操控。有这样的性能，便足以切开大部分敌人的装甲。盾面的高温则可以将飞来的弹头熔化，减少动能以降低损害。而拟态尾就更加令人惊奇了，它似乎有着自我意识，能自动帮助霞应对复杂的战局。既能防御，又能主动出击，最快加速度高达 10 G，几乎与青蛙舌头的速度相当……关于“炽骨守御”，看来还有很多谜团需要揭开。",
		level_3 = 0,
		level_4 = 0,
		resume = "军方秘密移交过来的孩子，往往有着悲惨的同年——霞也不例外。第一次观察她时，她拒绝与任何人沟通，甚至拒绝与任何人产生联系，所有的问题都得不到她的回应，所有的玩具也无法勾起她的兴趣。\n但幸运的是，经过魂器学院两年的特别心理课程，霞康复得很不错，如今已经和一名普通的十四岁女孩无异，甚至霞要更加理性、更加懂得体贴，这是非常令人欣喜的成果。值得一提的是，来自派森的“乳品公主”牌雪糕在治疗中起到很大的作用，如今也是霞最爱的零食。\n然而在战斗时，可能是条件反射或是别的原因，曾经冷漠的表情会重新回到霞身上，虽然还未发现不利影响，但也请在以后的任务中注意。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "我们针对“炽骨守御”的拟态尾进行了一系列实验，发现拟态尾的自主防御，无论是否处于战斗场景、霞的注意力在何处，都保持着运行状态，能够防御所有来自视野盲区的攻击。而自主攻击，仅在战斗情景中能够保持，非战斗情景则需要霞本人意志的控制。\n虽然深层逻辑与运行原理仍未研究清楚，但这个实验起码证明了——“炽骨守御”的拟态尾很安全，无论是对霞、还是对她的队友。\n拟态尾只会攻击被霞敌视的人，而自动防御则从不间断，这样的系统只能用“完美”二字才能形容。",
		file_3 = "对霞的身体观测，从她刚进魂器学院时就开始了。最早得到的数据有：体温明显异于常人，通常维持在三十九度，战斗时会突破四十度，对全身脏器造成很大负担；皮肤、肌肉、骨骼的强度也与正常人不同，能抵御高压，还有更强的爆发力。很明显，这是经过军方试验调整的结果。\n之后经过对霞体液以及干细胞样本的分析，我们发现了惊人的事实——霞的基因组中不止含有二十三对染色体，这是非常明显的“染色体病”表现，这让在场所有的研究人员都不禁打起了冷颤。\n利用化学与物理手段更改基因组，试验体存活率应该不足万分之一，霞能成长到十四岁无疑是个奇迹。\n然而奇迹的背后，还有多少被隐藏在黑暗之中的秘密……",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“基因组嫁接计划”，是早年遭到军方冻结的试验项目之一，其领头人是西奥多博士。试验核心是通过在人类基因组中嫁接动物基因，永久改变人体蛋白质特性，以获得更高的肉体强度——与“杰格 计划”相同，是军方强化人计划之一。\n西奥多博士起初使用克隆体进行试验，但试验发生事故，导致所有克隆体都亡于免疫反应。之后，理论上应该被终止试验权限的西奥多博士、收到军方高层的秘密指令，在暗中利用人类婴儿继续进行基因组嫁接试验。基因组调整对肉体的改进起到了明显作用，但这批婴儿在发育过程中均出现了智力问题，平均寿命也只有八岁。于是，没有收获理想结果的军方彻底冻结了“基因组嫁接计划”。\n然而，那位疯狂的科学家西奥多博士却全身而退，离开了军方，在未知的地方继续进行着他的非人道试验。",
		level_6 = 0,
		record = "摘录自魂器学院接收霞时的记录：\n实验体12541，暂名“日露 霞”，人格缺失，精神状态不稳定，需要长期使用药物与心理疏导治疗。\n在调整阶段，可尝试让“日露 霞”与玛琉、塞雅进行接触，作为同样经历过军方试验的学员，玛琉与塞雅或许可以打开“日露 霞”的心扉。"
	},
	[202520] = {
		soulid = 202520,
		valuation = "妮可尔是一位很有志向的魂姬，尽管学院第一的目标离她还有一段距离，但是她始终坚信自己能够登顶。我们不妨多给她一点鼓励。",
		file_1 = "妮可尔对周围的事物抱有强烈的好奇心，不过她常常掩饰这份情绪。比如她分明很想了解班长的过往，却假装毫不在意，事后又试图偷偷翻阅班长的个人资料，被逮到时还谎称只是凑巧。\n因此我们总结出了一条和妮可尔相处的小技巧：交谈时直视她的眼睛，如果她遮遮掩掩地避开了目光，那意味着她没有表达出内心真正的想法。\n至于如何让她直白地说出心里话……这还有待实践。",
		level_3 = 0,
		level_4 = 0,
		resume = "妮可尔给自己的武器取名“绝情冷光”，冷光球的数量并不固定，这取决于主人的能力和状态。至今为止，妮可尔最多一次性成功召唤出十个冷光球。试想一下，如果更多数量的冷光球一齐发射光线，那可以编制成天罗地网，让敌人无落脚之处。从这一点上来说，妮可尔的战斗潜力是巨大的。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "除了校方的成绩排名，学员之间还评选出了五花八门的排行榜。\n最不像运动系的运动系魂姬——这是妮可尔入学后夺得的首个第一名。“她像是宅系那一类呢！娇小可爱……居然是运动系的啊？”大部分人对妮可尔的第一印象是如此，出乎他们的意料，妮可尔非常喜欢运动，跑步、游泳、球类、体操……她乐于尝试各类运动项目，而且能够达到不错的成绩。尽管妮可尔对人们的刻板印象感到不满，但是她接受了这个“最不像运动系的运动系魂姬”的头衔——好歹也是第一嘛！",
		file_3 = "妮可尔经常提起自己的家乡，虽然她总是表现出满不在乎的样子，但是我们能够看出她对故乡的热爱。洛加尔并不是处处繁华，至少妮可尔口中的那部分是灰色的，可是她依然养成了开朗的性格——如果忽略掉别扭的那部分。\n妮可尔刚入校的时候表现得像个初次离家的孩子，她在想念父母，周围的人都察觉到了这一点，不过没有人因此嘲笑她。而现在，妮可尔已经像个独当一面的小大人了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "小时候的妮可尔经历过意外烧伤，左手臂至手背部位高度受损，而后接受植皮手术。\n手术非常成功，然而在恢复期间，妮可尔的玩伴们嘲笑她成了丑八怪，这让年幼的妮可尔一度陷入自卑之中。数个月后，手术的痕迹完全消失了，她的身体恢复了原貌。被压抑的自卑感在“失而复得”后转变成了极度自信，她的性格也变得别扭起来。\n巧合的是，妮可尔的魂智能武器所发射的光线能造成类似烧伤的损害，或许……这是魂智能网络希望她直面内心的恐惧吧。",
		level_6 = 0,
		record = "妮可尔非常喜欢小孩子，却讨厌被别人当成小孩子。"
	},
	[20130] = {
		soulid = 20130,
		valuation = "出色的战斗风格，步伐、气息以及节奏都做到了完美，体力的分配也十分合理，如果不是年龄问题的话，我都怀疑这个孩子已经上过战场了。 ",
		file_1 = "布兰琪的父亲是地下拳王，因为单亲家庭的结构使得布兰琪从小就跟着父亲学习拳击，性格上也逐渐往男孩的方向上发展；曾经有过将一个餐厅里的人全部揍趴的光辉历史。喜欢勾搭漂亮的女孩子，八岁到二十四岁都是她的好球带，因其频繁搭讪行为，导致学院内的大部分女孩子都苦不堪言，不过这一点在金百莉入学后改善了许多。",
		level_3 = 0,
		level_4 = 0,
		resume = "和许多人一样，来自耶梦加得；擅长拳击，性格乐观开朗、喜欢交友，行为作风有些大大咧咧，是位有些男子气的小姑娘。原本……是这样认为的，但是随着时间推移，对布兰琪的认知也开始不断刷新。百合属性、喜欢说一些粗鄙的言语的部分也开始浮出性格表面，最开始对布兰琪赞不绝口的那名监考官，现在也显地有些后悔。不过本质还是个好孩子，嗯……大概吧。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "布兰琪十分崇拜自己的父亲，同时也想要超越父亲，从布兰琪的战斗风格上就能看出这点。因为父亲打的大部分都是限时擂台格斗，所以是以快节奏的刺拳让对手在短时间内被击垮；但布兰琪却在继承父亲战术的基础上，开发出了专门应对持久的全新拳法。在实在是无法短时间制胜的情况下，就将对手拉到自己的节奏中去，渐渐累垮敌人。因为还有不少弊端，布琪并不打算用这套不完整的拳法去挑战父亲。",
		file_3 = "因一次拳击事故，布兰琪的父亲左半身完全瘫痪，一生都无法再次从事拳击事业。而布兰琪在那之后，因不甘心周围的人对父亲的冷言冷语，是自愿接过了父亲的头衔，站到了擂台上。满怀着怒气的布兰琪不但将对手全部击倒，在遇到机械人的情况下，还会将对方彻底拆毁，以此宣泄自己的不满。渐渐的，拳击女王的称号逐渐在地下世界传开，布兰琪也发现再这样下去是没办法找到引发事故的真凶的，于是她直接从擂台上隐退，转而加入了目前人才济济的魂器学院……",
		level_7 = 0,
		level_2 = 0,
		file_4 = "记录来自特工艾伦对基金会的调查：    记录1：拳击事故当天，布兰琪的父亲对手，自律型人形机械·夏娃有被人恶意调整过的记录；而夏娃目前是鲁比克财团生产投入最多的型号之一，这场拳赛事故和鲁比克财团可能存在某种关联性。  记录2：发现夏娃型号为索菲亚设计开发的早期机型之一，因索菲亚本人也在学院，所以我们特地向其询问了那场事故的前因后果，结果让人震惊；鲁比克财团为了扩展资本，故意委托基金会特工将EVE的输出率调整到了500%，通过打败地下拳王的方式增加产品的曝光率，这件事也是索菲亚脱离财团的主要原因。   结论：考虑到鲁比克财团的继承人爱丽丝也在学院内学习的关系，我们恳请索菲亚对这件事的具体事项进行保密，该档案也会被归纳到废弃资源文档，并在未来一周内进行消除。 ",
		level_6 = 0,
		record = "如果是金百莉是郁金香的话，那么布兰琪就是幽谷深处的百合花，美丽并带着危险，如果没有准备的话，一不留神就会跌落山谷。"
	},
	[202420] = {
		soulid = 202420,
		valuation = "作为没什么战斗经验的新人，艾瑞儿的表现不仅仅是合格而已，而称得上亮眼。不过呢……各方面都还需要进行系统化的学习。",
		file_1 = "我们调查过的学员都有各自的往事，受黑色圣诞节的广泛影响，那些往事大多染上了悲剧色彩。艾瑞儿无疑是幸运的一个，她的过去几乎没有任何悲伤的记忆，她被保护得很好，生活富足，家庭和乐。原本艾瑞儿会继续过着衣食无忧的生活，但人类和人工智能的冲突日益严峻，她的父母担心将来无法庇护自己的孩子，希望她能具备自我保护的能力。\n艾瑞儿刚加入魂器学院的时候，生活自理能力几乎为零。经过一段时间的学习和适应，她才逐渐掌握了一些常识，起码不会再将衣服穿反了。",
		level_3 = 0,
		level_4 = 0,
		resume = "艾瑞儿是被父母送来参加适格测试的，他们希望女儿掌握一定的自保能力，同时结交新的伙伴。这意味着艾瑞儿本人参加战斗的意愿并不是特别强烈，但也没有抵触情绪。\n经过观察和测试，让所有人感到意外的是，毫无战斗经验的艾瑞儿竟然有着超乎常人的战斗天赋。她是一位天赋型的魂姬，具备令人羡慕的才能，如何将天赋发挥到极致，这是需要我们挖掘的地方。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "可以这么说，艾瑞儿是在蜜罐里长大的，但她并没有养成骄纵傲慢的大小姐脾气，反而很好相处。当然，好相处的脾气不意味着交流顺畅，事实上大多数人和艾瑞儿的交流存在着微妙的偏差，这个“偏差”主要体现在人情世故和常识方面。\n举个真实的例子，在宿舍补习了一天理论知识的薇薇恩跑到艾瑞儿房间串门，饿得晕乎乎的薇薇恩正好瞧见了柜子里放着的一大袋肚脐饼零食，可是她有些不好意思开口，只能委婉地表达“一整天都没有吃东西了，肚子空空的呢。”，艾瑞儿明白不了薇薇恩的意思，非常认真地回答了“好厉害呀！”。",
		file_3 = "艾瑞儿的好奇心不容小觑，她最常说的话是“为什么？”“怎么会这样？”“这是什么原因呢？”，一般性的问题能够被解答，但类似于“为什么猫咪是喵喵叫，而不是汪汪叫呢？”这样的提问，实在让人难以解释。\n如果无法回答艾瑞儿，千万不要敷衍地告诉她下次再说，否则她很可能每隔几分钟就重复问一遍为什么，不得到答案绝不罢休。正确的做法是，让她有机会回家的时候问问父母吧。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "加入学院前的艾瑞儿对世界的残酷一无所知，她在极短的时间内被迫接收了这个世界阴暗的一面，甚至没有任何缓冲的余地。我们以为艾瑞儿会拒绝战斗，毕竟这离她曾经的美好生活太遥远了，但事实并不是这样。艾瑞儿勇敢地执行着学校的任务，她的目的十分单纯——父母让她做个乖学生。\n仅仅如此吗？\n艾瑞儿绝不只是听从父母的嘱咐，走出了从小到大的庇护伞，她也想成长为可以庇护别人的人。",
		level_6 = 0,
		record = "网络信号差的时候，试试靠近艾瑞儿身边吧。"
	},
	[29920] = {
		soulid = 29920,
		valuation = "令人可畏的战斗力，几乎没有短板，无论是战术意识还是复合作战能力都堪称绝佳，恐怕只有把一切都投入到战斗中的人才能拥有这种程度的战斗知识与战斗力。",
		file_1 = "虽然是新入学员，不过黑闪翼从很久以前就已经开始为布克丝院长工作了。 在学院建立之初，黑闪翼就已经为院长处理了无数台面下的危机——处理冥顽不灵的妨碍者，威胁不安分的企业家，消灭图谋不轨的破坏分子。像是冷酷无情的机械一般，命令者的底线就是她的底线。 接下了这般职责的黑闪翼，自然也无法生活在阳光下，原本认为自己会永远生活在暗面的她，在某天接到了新的命令……",
		level_3 = 0,
		level_4 = 0,
		resume = "正如其代号“黑闪翼”一般，于战场上翩然起舞，安静地收割着敌人生命的狩猎者。如今的她被指派到班长的手下，毫无抗拒地接受一切命令，作为一名学员活跃在对抗人工智能的战场上。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "黑闪翼掌握着能够隐匿气息的技巧，像是班长的影子一般，安静地潜伏在护卫目标的周身。即使现身也很少与他人发生互动，只是一心一意地执行自己的任务。对于周围事物的观察非常细致，但是又似乎对一切漠不关心。 虽然沉默寡言，但是从为数不多的交谈中能够看出黑闪翼非常有教养——应该说彬彬有礼呢，还是有着微妙的贵族气质。 从这点看，黑闪翼曾经是尼德霍格某个势力继承人的传言似乎并非单纯的传言。",
		file_3 = "【未影尖兵】 黑闪翼的魂智能武器是院长特制的，无论是物理还是能量攻击都可以胜任的武装，配合本人强大的资质，灵活的攻击让敌人防不胜防。 虽然战斗方式较为内敛，但是实质的破坏力依旧可观。被长枪命中的物体会被暗物质瞬间消解，黑闪翼能够以此切开大门、墙壁乃至屏障，在台面下的世界中，黑闪翼以此葬送了无数的敌人。 一般的小型据点仅靠黑闪翼一人就能完全突破。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "黑闪翼真名是“希尔芙”。 她曾经所在的家族是基金会的一份子，但是却在基金会的内部斗争中被抹去，希尔芙是唯一的幸存者。学院建立之初在很多方面都受制于基金会，为了达成制衡，需要有一个熟悉基金的人在暗处搜集情报与进行破坏工作，为此，她被当时的布克丝院长收养，并且作为狩猎者接受训练。 因为家族毁灭而受到打击的少女封闭了自己的内心，在院长的请求，少女舍弃了自己的名字，化身于暗夜中的舞者，为学院的道路清除台面下的障碍。 然后，时至今日，希尔芙——“黑闪翼”被院长派到了班长的身边，负责后者的人身安全，虽然很疑惑为什么让她来执行这样台面上的任务，不过狩猎者并没有提出异议。 “虽说是为了学院，但是我的确利用她做了很多不好的事情，现在所做的一切都是为了补偿她……虽说如此，也根本补偿不了的吧，所以拜托你咯，要对那个孩子好一点哦。”——来自院长对班长的私人邮件。",
		level_6 = 0,
		record = "“今天的阳光还是一如既往的刺眼，不过我并不讨厌。”"
	},
	[27620] = {
		soulid = 27620,
		valuation = "室内战、室外战、移动战、追击战、特种作战…噬身之蛇是我见过的唯一一个能够进行如此多种类作战的单兵系统，更重要的是，它并不仅仅是适配于这些作战，而是能够近乎完美的去执行这些作战。",
		file_1 = "动物性拟态外骨骼系统初号试验机型，代号【噬身之蛇】，虽然借用了魂智能网络勉强可以划入魂武之列，但实际上基因组的嫁接才是整部外置骨骼的核心技术。作为动物性拟态外骨骼系统的原型机，是西奥多博士一生之中的最高杰作。【噬身之蛇】的内核由两部分组成，一部分是放入动物基因组的中枢部分，另一部分则是将中枢部分包裹的隔离环。中枢部分在运作之时会使内核产生能量，隔离环的职能是将这个能量转换成使用者需求的性质，然后分流进入外骨骼的攻击系统内进行循环待机。理论上来说，这种的转换可以让噬身之蛇根据使用者的需求使用所有种类的能量攻击。噬身之蛇这种能量转换的特性除了在进行能量攻击的时候被应用以外，还被应用到了外部的机身之上。外部装甲可以利用热能改变颜色、硬度、韧性以及伸缩性。也可以在机体内部装填暗物质使得蛇身质量增大，提升物理战的破坏力。",
		level_3 = 0,
		level_4 = 0,
		resume = "蝰影是那种会用凶狠的态度去对待第一次见面的人的类型，实际上只是因为害怕与人接触而进行的自我保护，内心深处还是渴望能够与他人相处。这也是她这么快就能融入学院的原因。从这点而言，她就是个非常普通的十六岁少女。但是，她的基础常识和自我生活能力非常的糟糕。把衣服扔进去设定好就行的洗衣操作，课程转换时服装的替换，自身饮食的点单以及是否为可通行道路的判断……如果再放任埃希诺对蝰影进行无限制的溺爱，蝰影必然成为一名废人。不，应该说现在已经是废人了。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "蝰影出生在耶梦加得的一个小家庭里面，父母都是金色头发。但蝰影出生却有着粉红色的头发。这让她的父亲对她的亲缘产生怀疑。虽然亲子鉴定的结果毫无异常，但是已经破裂过一次的家庭无法再修复。作为使得家庭破裂的恶魔之子，蝰影自小就缺失了家庭之爱。然后更加不幸的是，蝰影拥有着招引和使唤蛇类的特殊天赋。在耶梦加得，蛇在教义里一直就是地狱与恶魔的象征。也因此蝰影被人视作魔女。排挤、非难，在他人的恶意浸染下成长的蝰影为了保护自己，不得不形成了强势的性格，但又渴望理解自己的人出现。作为话负面话题的中心人物，耶梦加得的地下组织有不少都注意到了这位绝色的美少女，想做人口贩卖的只多不少。毫无留恋的，11岁的蝰影逃离了那里。在躲避黑帮追捕的时候偶遇了西奥多博士，从此开启了新的人生。“我是一名普通的研究者，我的工作就是使得世界产生改变，我不能保证其他人会不会受到这改变的影响。但是，我能保证至少你的世界会有改变，怎么样？要跟我一起来吗？”",
		file_3 = "黑暗狩猎者（三角），过去西奥多博士创立的组织，或许这样说并不太合适，实际上这只是为三台搭载动物性拟态外骨骼系统的试验机型取的统称代号西奥多博士去世后，才由蝰影正式创立并接管的组织，正如三角形是最为稳定的架构一般，黑暗狩猎者这个组织只有三人，也只会有三人。不过在这之前，为了掌握动物性拟态外骨骼系统的真正性能，军方也曾向西奥多博士下发任务，多是一些军方无法在明面上处理的棘手事件或恶性集团所以各处也有数量不等的目击事件，不过在黑色圣诞节之后就销声匿迹了。现在的黑暗狩猎者遵循着“将社会秩序拨回正轨”的理念，在蝰影的领导下，活跃在未来夺还的战场上。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "激活形态，动物性拟态外骨骼系统特有的增强功能。当使用者进入激活形态之后，使用者神经和武器内核的神经系统的对接率会被强行激化。动物性拟态外骨骼系统会进入超负荷行动的状态，战斗力会得到2~3倍的飞跃式提升。但是可惜的是，西奥多博士并没有将这个系统制作到能够量产使用的稳定程度。现在存在的三台装载了动物性拟态外骨骼系统的武器并不统一。黑翼报丧没有内置激活形态，审判巨刺的激活形态会在螯蝎的情绪有大幅度变动之时自动开放。最为奇怪的是，噬身之蛇的激活形态是被禁止使用的。院长曾经想要打开噬身之蛇的限制，当时埃希诺竭力反对的姿态让人完全无法想象她是那位冷静到可怕的“黑暗狩猎者”军师。由此判断，噬身之蛇的激活形态会对使用者造成无法估计的损伤。",
		level_6 = 0,
		record = "从其他学员的口中，我们得知了这样一个故事。有一个少女，她从出生开始就被人视作恶魔之子，从小就失去了父母的关心。空荡荡的家以及回来之后就走进自己房间将房门锁上的父母。圣诞节前两个月搬到隔壁的老奶奶，在每年圣诞节的时候都会做苹果派。老奶奶的记性很差，每次都将苹果烤过头。不过幸好的是，老奶奶的厨艺还不错，能够利用烤过头的苹果来制作反转苹果派。做好之后，老奶奶就会将苹果派分发给邻居。少女也是从那时开始，第一次吃到热腾腾的手工料理。说实话，老奶奶做的反转苹果派并不好吃，时间过久导致大部分的苹果都烤焦了，眼神不好会弄错糖的分量，力气太小最后糖聚在一块不是过甜就是没味道。即便如此，少女还是满心期待着每年的圣诞节，反转苹果派的美味，少女一生都不会忘记。"
	},
	[27720] = {
		soulid = 27720,
		valuation = "螯蝎的审判巨刺比想象中的还要强大，除了直接刺中敌人释放有害物的绝招以外，还能够作为特殊移动的工具和防御的盾牌。外部像甲壳一样的装甲能够进行分离，利用内置的微型电磁弹射装置和耐高热伸缩材料可以在1.25秒内攻击到20米以外的敌人。这个攻击范围和有害物使得她成为近战型的绝对克星。在小规模的冲突中极具威胁性。",
		file_1 = "动物性拟态外骨骼系统试验机型二号，代号【审判巨刺】，优秀的蝎尾外骨骼形态的战争兵器，西奥多博士继【噬身之蛇】之后以埃及柱尾蝎的基因组嫁接开发的第二台动物性拟态外骨骼系统，使用者是螯蝎。于机身架构处采用与“征服者”动力机甲同种的合金，具有高强度和足够的延展性，完全能够做到攻防一体的效果。附带的电磁发生武装与关节处的仿生学运用，则让使用者可以轻松利用蝎尾做出广域的攻击。同时，【审判巨刺】也搭载一个模仿埃及柱尾蝎腺体结构的机械腺体，不需要进行多余的外部填装动作，在神经连接的状态，这个机械腺体能根据需要制造出对生物使用的强效神经有害物和能融化合金的溶解有害物，足以应付多种类的敌人。",
		level_3 = 0,
		level_4 = 0,
		resume = "螯蝎，出生于尼德霍格，在加入西奥多博士的研究队伍之前是军方的高级军官，但是脾气古怪，总是自称“美之极致的追求者”对于之前西奥多博士的人体改造计划多有耳闻，因为那种实在无法称得上是美的行为，拒绝了西奥多博士至少10次以上的邀请。但在见到蝰影之后，无法言明的感觉让她觉得可能遇上了自己一直在追求的东西，为了守护这份美而自愿成为动物性拟态外骨骼系统的实验者。军方似乎还抱有从她这里取得情报的想法，不过就结果而言，大部分的时候都是螯蝎在利用军方而已。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "螯蝎给人的第一印象，相较于女性的身份，男性的各种礼节和口吻更容易给人留下深刻的印象。给人一种不可以轻易向她搭话的氛围，但所有的行动又是那么恰到好处。据她本人自述，对于英伦绅士的文化非常着迷，无论是着装还是饮食，都有这足以成为学者的研究量。在螯蝎看来，绅士的优雅之美正是她所追求的，美之极致的其中一种。所以平时的各项行动准则都会努力尝试着向绅士的标准来，再加上她出色的外形，不止在军营里，即使来到学院，被认错性别也是常有的事。不过有一点需要特别注意，螯蝎非常乐意给他人建立行事准则，并严格要求他们执行相应的礼数，建议不要在螯蝎进行她的美学理论讲座的时候靠近她周遭30米。",
		file_3 = "对于黑暗狩猎者的现任领导者——蝰影，呈现出完全被折服的额态度，从螯蝎形影不离的表现来看，已经是蝰影忠诚的捍卫者了。蝰影接管“黑暗狩猎者”一事，螯蝎没有表露出任何不满的情绪，反而负责出面摆平了军方那边反对的声音，与主管内部事务的游枭正好相反螯蝎的强势对外一定程度上彻底将“黑暗狩猎者”的发展基底稳定了下来，至少对于这支拥有特别力量的组织，明面上暂时还没有人想要动不该有的念头。曾自述视蝰影为美之极致的体现，兼具天使与恶魔之人，是需要自己穷尽一生去守护的目标。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "螯蝎对于有害物的研究可以说完全是偶然，虽然是出于“五彩斑斓的有害物也是美的一种”这样奇怪的理由，但她在这方面的成果却不容小视，数百甚至数千的化学试剂配方可以信手拈来，只要手边有相应的材料就能制作有害性不等的炫彩液体。对于使用剂量与相应症状烂熟于心，这样的知识与实验储备让她在作战中能够完全发挥【审判巨刺】内置的机械腺体的作用。同时也掌握了奇怪的不易受伤的体制，目前推测是动物性拟态外骨骼系统带来的一部分有害物的抗性技能，对于蝰影的奇怪料理能够完全免疫食物过敏的现象，是非常稀有的能力，值得进一步研究。",
		level_6 = 0,
		record = "根据索菲亚和奥瑞特对审判巨刺的分析报告，我们大概完成了动物性拟态外骨骼系统在机械制作工艺上的解析。西奥多博士使用的合金和“征服者”动力机甲使用的是同一种合金，没有任何特殊的地方。动物性拟态外骨骼系统能够匹敌魂智能武器的根本理由，还是因为承载了动物基因的内核以及遍布审判巨刺内部的神经网络。在基因对接的状态，审判巨刺的神经网络会与使用者的神经网络统一化，成为使用者的一部分，使得使用者可以如自己的身体一样使用审判巨刺。这种方式，比起牢记操作手册的训练方式更加效率和节约成本，也会更加地灵活。不得不说，西奥多博士真的是个天才。"
	},
	[27820] = {
		soulid = 27820,
		valuation = "作战技巧和战斗能力异常低下，如果不是因为动物基因提升了游枭的身体素质，我甚至怀疑任意一名成年男性都能轻易将她击倒。但是游枭对于战局的整体把握超出预期，合理有效的资源分配以及冷酷果决的判断力。她的决策，往往能够影响到整个战局。",
		file_1 = "动物性拟态外骨骼系统试验机型三号，【黑翼报丧】正如其名，是翼状的外骨骼装置，西奥多博士在开发时采用了名为“枭”的猛禽的基因组嫁接至中枢系统，能够赋予使用者近乎完美的飞行能力，与现有的机械构造样式的背装飞行翼不同，【黑翼报丧】的飞行能力不需要任何的能源供给，仅凭借气流就可以实现地面上不利用高低差的腾空起飞与长时间的滞空盘旋。同时，羽翼末端装设有微型的传感器，可以自动收集判断空中湿度与风向的变化，能够提前预知气象的变化。黑翼的尖端也有相当的坚硬程度，可以作为近身战的一种攻击方式，其余的能力尚且不明，但作为西奥多博士的助手，游枭或许在【黑翼报丧】上隐藏了什么也说不定。",
		level_3 = 0,
		level_4 = 0,
		resume = "处事精明，待人随和。无法成为游枭想要接触的人的话，对她的评价永远是超乎想象的正面。而且你去询问那些认为自己和游枭相处很好的人游枭的事情他们也只会在沉默之后恍然大悟，得出自己对她完全不了解的结论。由此可以判断出，游枭心理学的造诣高深莫测。对于她的观察结果不排除被引导的可能性。但是有一点可以确认的是，游枭在蝰影和螯蝎面前会表现出强烈的情绪波动。而她本人也没有掩饰这点的打算。就这一点而言，她还是一个正常的人类也是让我能够继续观察下去的动力。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "根据动物性拟态外骨骼系统分析后得到的数据来看，动物性拟态外骨骼系统的使用者在连接状态时会大幅度受到动物基因的影响，这种影响除了身体素质和动物般的能力以外，更明显的表现方式为对使用者人格的影响。蝰影会变得冷静，螯蝎在战斗时会暂时变成另一种人格。但是游枭和他们明显不一样，即使是处于连接状态，她的性格看起来也没有改变。由于样本数据不足，这点只能作为单纯的推论列出，但我认为这是需要引起重视的注意点。建议加大对游枭连接后状态的精神分析。另外，或许受生理学角度的影响，游枭有严重的夜行性活动习惯，有必要进行一定的纠正。不然她在白天打瞌睡的样子真的很容易让其他人也一起犯困。",
		file_3 = "游枭对蝰影的溺爱达到了让人难以理解的程度，只要可能，她就不会让蝰影离开她的视野。而且在进入学院之后，她也还是会去叫蝰影起床，帮蝰影穿衣服、洗漱。给蝰影做饭，在蝰影无法食用她所提供的食物的场合，也会做出类似试药一样的行为，就像是在侍奉君主一般。不过仔细观察她的行为，可以发现她很享受和蝰影的肌肤接触，而且会收集蝰影使用过的物品，对于靠近蝰影的人会进行过度的警戒。这只是一个推测，或许……游枭对于蝰影有着混杂着母性与奴性的恋爱情感。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "游枭从“GG“计划时期开始就已经开始担任西奥多博士的助手，可以说她是对博士最了解的一位，对于她来说，博士的实验与理想是令人敬佩的。即使当时有很多反对的声音出现在他们周围，但她从没有受到丝毫的影响，一如既往地支持着博士的工作，博士也很乐意和游枭分享自己在学术方面新的见解托博士的福，游枭对于基因学的研究也到达了更深的层次。动物性拟态外骨骼三部试验机型全部都有游枭参与调整，因此对于动物性拟态外骨骼的真实能力，游枭非常的清楚。“黑暗狩猎者”成立以后，游枭完全发挥了自己在博士身边学习的各种知识，成为了军师一般的灵魂人物，处理大小事务早就如同家常便饭，连院长都曾对这样的处理能力表示出羡慕之情。",
		level_6 = 0,
		record = "以下记录摘自前任调查员的个人日记片段：\n第一片段：\n没有想到，游枭竟然是军方那位大人物的女儿，这种人物，留在学院真的好吗？这对于学院来说，应该是不合理的才对吧？我必须让院长改变决定。\n第二片段：\n竟然是这样的吗……也就是说……学院是这样成立的啊……\n第三片段：\n今天院长找我谈话了。看来，我必须忘记这些，也必须离开学院了。"
	},
	[203620] = {
		soulid = 203620,
		valuation = "月和会中专门负责重要人物安保的部分出身的成员，在进行战斗测试的时候，出于学院双方的协议内容，测试情况有些保留。常规的作战技巧都近乎满分，在特殊情况的处理下，部分测试内容并未开展。根据往常数据预估，深入测试雾夜能展现的实力也不凡。",
		file_1 = "【灵枪紫罗】是根据突击步枪为原型制作的魂智能武器，在最大程度保留突击步枪的射速和射程的同时，简化和优化了换弹流程。而且在面对复杂多敌人的环境下，【灵枪紫罗】还配备了简单的智能自动换弹流程。在一定程度上，缓解复杂战局的应对情况。区别于大型枪炮类热兵器，【灵枪紫罗】的便携和机动性就显示出优势。但，在子弹的护甲穿透性上还是稍稍逊色不少。毕竟，没有人会用匕首和坦克肉搏。有研究员提出加强【灵枪紫罗】子弹的穿透能力，来应对大型人工智能的战局。而雾夜本人提出了拒绝，她表示，现在的单独作战、潜行作战更适合她。而【灵枪紫罗】的命名，也是雾夜自己的兴趣。这种偏向洛加尔式的命名，和她的兴趣相悖。雾夜解释说，是因为曾经芙蕾大人吟诵过的诗句给她的灵感。",
		level_3 = 0,
		level_4 = 0,
		resume = "洛加尔之乱后，月和会对游学在外的现领袖——芙蕾殿下充满了担忧。害怕有不法分子利用芙蕾大人的“吊儿郎当”来动摇洛加尔现有的社会结构。加之，学院所属为中立区，有各地的生源和教职，不免鱼龙混杂。所以，月和会内部派遣了水原雾夜在内的数名成员入学，暗中保护芙蕾的安全。雾夜刚入学的时候，校内学员都觉得她是来自耶梦加得的贵族小姐。每天上课和出行都打扮得非常精致，像电影里的翩翩佳人。很快，大家发现雾夜无论衣着怎么精致，她都会在发饰上佩戴“般若”面具。久而久之，大家才慢慢知道，原来雾夜是洛加尔地区的生源。彬彬有礼是学员们对雾夜的一致认可，如果她们在参加了模拟训练之后，还是如此评价雾夜的话，那说明她们心理承受能力不错。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "雾夜使用【灵枪紫罗】压制敌人，甚至让部分学员在模拟战中不愿遇到的原因，并不是因为她的枪术。而是她在枪术中柔和的武技。枪斗术，除了依赖中小型枪械的熟知和射击理解之外，还更依赖本身的身体素质和临场判断能力。雾夜对于枪斗术的理解，并不是根据弹道预计而施展出的华丽技巧。由于身份原因，雾夜对于枪斗术中的藏枪术、格斗与身法展现得更为淋漓。你总是无法预判被雾夜近身之后，迎接你的先是拳头、枪托，还是热情的子弹。即使是，战斗都还坚持穿礼服的雾夜，你都不知道她会从哪里“变出”她的【灵枪紫罗】。得益于【灵枪紫罗】以突击步枪作为原型，突击步枪的口径和火力都和枪斗术有非常好的契合性。所以，在雾夜的战斗中，你仿佛在欣赏一个穿礼服的性感女郎为主角的黑色电影。",
		file_3 = "水原家，洛加尔当地的名门望族。在旧时代里，人尽皆知的水原商会在经历了现代科技冲击之后，慢慢弱化了原先的产业，更多是依附人脉资源上进行运转。历代从商的家族商道影响下，水原家逐渐形成了开放自由的门风。对于新事物的接受和引入都走在常人之前，这也是能够培养出雾夜这样洋小姐的原因。早在月和会早期，水原家就已经开始负责月和会的外联事务。而且在对外的同时，水原家也撑起了月和会的内部信息交流和传达的中转系统之一。别看水原家和洛加尔外的世界接触得比较多，就会容易动摇对洛加尔传统的忠心。作为旁支的水原，也是月和会早期的成立者之一，长时间保持着绝对的效忠。传闻水原、三轮、风魔、橘、荒井、古畑等家族与古洛加尔皇族有着千丝万缕的联系，甚至他们一同许下结义之盟，共同捍卫某样东西。具体是什么尚且不明朗。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "水原雾夜，在月和会里的职责，和主家在月和会中的职能完全不同。她隶属于专门负责芙蕾殿下安全的战斗部门——寂。寂是月和会内精挑细选出来保护重要人物的组织，到现在，寂已经成为专门保护月和会首领的组织。成员由月和会精挑细选，而后完全听命于首领。但现在，芙蕾虽然是月和会的首领，因为性格的原因对月和会是一种放任自由的状态。芙蕾自己也是随性到漫游世界。所以寂现在由首席统领管理，其他月和会部门协作管理。因为是专门负责战斗和保护的，按照承袭和惯例，成员最多不会超过十二人。在月和会内部，寂的成员都会佩戴般若、能面等面具配饰作为象征。寂的成员一般不会三四名成员一同出现，只有重要的行动才会以复数成员组队出现。她们彼此独立，但是都对唯一的信念而奋斗，甚至愿意献出生命。",
		level_6 = 0,
		record = "异色瞳很奇怪吗？那你就把它当做戴了美瞳好了……什么？有人谣传我戴美瞳装异色瞳？"
	},
	[203220] = {
		soulid = 203220,
		valuation = "铃兰是罕见的、战斗天赋极高的学员，很难想象有人能在她这样的年纪就积攒了深厚的战场经验，想必是接受了异常残酷的训练。在潜入、奇袭方面，铃兰的技术更是无人出其右，如今有着“翠影忍姬”这样灵活魂器的辅佐，足够让她应付所有复杂的战斗状况。与和她具有相似特质的学员“风魔胧”相比，铃兰的技法要更加冷酷、更加果决，宛如机械一般，有着超高的执行力。",
		file_1 = "在刃隐家经历的漫长修行，如今已让铃兰形成习惯，其中有些我们不得不正视的问题。\n例如铃兰每餐只会吃少许不经过调味的蔬菜或豆制品，最多辅以一枚青梅做增味剂。据调查，这是久远时期的忍者为维持体形而保留的饮食习惯，因为脂肪、碳水一类能促进身体发育的营养素，会导致身高、体重的增加，从而不利于忍者们进行潜行等本职工作。\n铃兰的身体也是如此，若是将这种习惯保持下去，她的身体将停止发育，维持一百四十六公分身高与三十四千克体重、以便于她执行家族的任务——但我们认为这是落后且不人道的举措，铃兰正处于青春期，这种饮食习惯是以摧毁发育为代价、达到培养任务机器的目的。从今以后学院会着手改进铃兰的饮食，在不违抗本人意愿的前提下、提供满足她身体正常发育需要的营养。",
		level_3 = 0,
		level_4 = 0,
		resume = "出生于忍者世家——“刃隐”一族的少女。她的家族与风魔家不同，一直活跃在世界暗处，并积极接纳新兴技术以强化自身实力，是举世闻名的狩猎组织。\n作为刃隐家的后代，铃兰的天赋极为出色，在很小的时候就展现出与同龄孩子不一样的冷静与沉着。她很快参与训练，在六岁时便能与职业忍者交手，七岁开始执行任务。时至今日，铃兰已独立完成任务近五百次，是刃隐一族里最优秀的忍者之一。\n见识到风魔胧的成长之后，家主，也就是铃兰的父亲，决定让铃兰也加入魂器学院，为的是带回能让刃隐一族更进一步的技术。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "铃兰对任何事物、任何人都不会表现出特别的兴趣，似乎这也是修行的成果，唯有一样东西除外——那就是猫。\n据她本人所说，自己对猫有着“师傅一样的感情”。原来，从小时候开始，铃兰就与猫一起生活。\n族人要求她学习猫的一举一动，将猫的轻盈、猫的柔韧、猫的安静全部作为知识吸纳，这是刃隐家族修炼的开始。以猫的姿态为启蒙，化为忍者行动的基础。\n久而久之，除了身形体态越来越有猫的影子，铃兰还学会了一套与猫相处的办法，例如安静地接近、抚摸、甚至呼吸，铃兰都能做到让猫感到亲近，于是学院里的猫都对铃兰有十足的好感，经常能看到猫咪们围绕着铃兰的景象，这一点让很多学员都羡慕不已。",
		file_3 = "铃兰的魂智能武器“翠影忍姬”，包含有数个单元，它们在电磁的操控下，聚合为利刃，或散开成长鞭，形态根据铃兰的指令可自由切换，非常灵活。更加特别的是，在鞭的形态下，单元并非只依靠铃兰的挥舞而动，而是能够凭借电磁力自如位移，宛如一条具有自我意识的青龙，在极具战斗力的同时，也可以环绕在铃兰的身周，达到防御的效果。必要时，还可以将鞭的单元以高速射出，造成远程打击。\n作为一个近战魂武，“翠影忍姬”的灵活让敌人难以捉摸，就如忍者一般昼伏夜出，与铃兰是绝配的搭档。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "作为观察与记录员，我现在正考虑更改铃兰的资料，有关前些日子提到的“所有事物中只对猫感兴趣”这一点，如今需要变更。进入学院后，铃兰很快迷上了一样对她来说新鲜的事物——电视。\n忍者的修行非常注重对“心流”的锻炼，意思是忍者需要时刻保持足够的专注，这在执行任务时是至关重要的能力。因此，尽管铃兰在科技发达的洛加尔长大，但从未接触过杂志、电视这些会分散注意力的东西。那些试图掌控人注意力、挑动人情绪的媒体，本就与忍者追求的“心流”是背道而驰的。\n离开了族人的管控，电视的“魔力”便完全展现在铃兰面前。那些有趣、精彩、富有冲击力的节目，一下就把铃兰吸引住了，然而铃兰本人是一名“电器盲”，完全不懂得如何使用电视。于是她经常在课程结束后进入风魔胧的房间，在电视前一直坐到睡着。\n据风魔胧所说，铃兰最喜欢看的是古装片以及言情剧。",
		level_6 = 0,
		record = "单兵突入的王者，黑夜里的战斗机器，绿色的闪电伴随着疾风般的脚步，“翠影忍姬”不只是魂武，亦是对刃隐 铃兰的最佳评价。"
	},
	[203120] = {
		soulid = 203120,
		valuation = "尽管从前没有与 人工智能 作战的经验，但拉比特有着超乎常人的热情，接受新事物的能力也极快，这让她迅速掌握了魂武的使用方法，并且很快适应了战斗。",
		file_1 = "智能都市耶梦加得，一直是热情与奔放的象征。在这里，可以看到各种激情的极限运动，还有有趣的街头文化——涂鸦便是其中的一种。\n在这个时代，显示屏犹如拼图一般塞满了建筑物的墙壁，这让用油漆喷涂出画作的涂鸦显得格外另类与叛逆。甚至有部分涂鸦者专找显示屏下手，并以能在更高、更大的显示屏上涂鸦为荣，因此涂鸦运动饱受争议。\n在“黑色圣诞节”事件发生后，情况发生了转变。越来越多的人加入涂鸦者的行列，在城市各处涂鸦以表达对 模拟智能网络 的不满与抵抗。而他们的领袖，便是耶梦加得最优秀的涂鸦艺术家——拉比特与碧萝丝。",
		level_3 = 0,
		level_4 = 0,
		resume = "拉比特，来自耶梦加得的涂鸦艺术家，与同样在福利院出身的碧萝丝组成的创作团体“热带水果派”，在当地拥有数量众多的粉丝。\n二人关系非常亲密，以姐妹相称，但并无亲缘关系，是同样被遗弃在福利院的孤儿。她们一起长大，拥有着顶级的默契。\n拉比特因先天患有腿疾，在小时候进行了义肢手术，然而这丝毫没有影响她形成活泼的性格，甚至其淘气程度要远超其他同龄人，在福利院留下过不少轶事。这些也时常成为“热带水果派”的涂鸦素材，命运坎坷却保持乐观的个性，这样的拉比特让耶梦加得的许多人都受到感染。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "反抗的涂鸦终究还是受到了 模拟智能网络 的关注。\n在躲避 模拟智能网络 搜捕的过程中，拉比特与碧萝丝受过许多涂鸦者的帮助。涂鸦者为她们提供庇护所，还修改了二人的身份资料，然而最后 模拟智能网络 还是从蛛丝马迹中获得了二人与福利院有关的信息。\n它们迅速行动，劫持了福利院所有人作为人质，逼迫拉比特与碧萝丝接受 人工智能 的处分。为了“家人”，拉比特与碧萝丝不得不投降，答应 模拟智能网络 进入它们的监狱。危急之时，是组织“托拉”的“ESP先遣小队”救下了二人，这也是二人加入托拉的契机。",
		file_3 = "对乐于欣赏绚丽色彩的涂鸦者拉比特来说，“赤耀加农”是件令她十分满意的魂武。\n超频完成的当天，拉比特就用她的特长、对“赤耀加农”做了精心的涂装。主体喷漆采用她最爱的橙红色，使得整个炮身看起来像一只巨大的胡萝卜，还在前端签上了自己的名字。\n战斗时的“焰火加农”，则更具有拉比特的个人风格。在她的操控下，“赤耀加农”就犹如一只巨大的油漆枪，虹光肆意喷射而出，每一次战斗，都宛若一场绚烂的涂鸦秀。\n得益于此，这名永远在追寻“刺激”涂鸦者，如今在魂器学院找到了新的归宿。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "迄今为止，魂器学院招收了各种各样性格迥异的学员，她们的魂武也因此显得五花八门。然而，像“赤耀加农”这样特别的魂智能武器，我们还是头一次见。\n它由一柄巨大的主炮、以及近十个支援组件构成。其中，支援组件又分别拥有不同功能，自动火力、热成像、侦查影像、声呐……简直就是一只小型部队的配置。\n“天马行空”，这是我们对“赤耀加农”以及它的魂姬的共同评价。",
		level_6 = 0,
		record = "拉比特入学的第二天，学院工作人员在图书馆、训练室、宿舍外墙、院长办公室等地发现了共计三十一处涂鸦，图案无一例外都是红色的卡通兔子。接着，拉比特被安排包办了接下来整整两个月的卫生值日。"
	},
	[203520] = {
		soulid = 203520,
		valuation = "碧萝丝与魂武“炫彩波澜”的相性非常不错，也许是经常使用油漆喷枪的缘故，她用起“炫彩波澜”的喷射双枪也异常顺手。经过测试，碧萝丝与“炫彩波澜”这对组合的精准度、威力以及灵活性都在平均水准之上。",
		file_1 = "碧萝丝与拉比特都是性格超级活泼的学员，无论在学院的哪个角落，只要有她们二人出现，气氛都会立即变得躁动起来。\n但两人的个性还是有着少许的差别——拉比特是对所有事物都充满热情，而碧萝丝则是对“能刺激他人”的东西更感兴趣。\n乐意看到旁人大吃一惊、手足无措或是恼羞成怒的模样，这是从前在福利院、与拉比特一起恶作剧时觉醒的特殊癖好。\n我们采访了耶梦加得福利院的几名看护，了解到曾经发生过数次“藏起看护老师的手帕”、“在同龄孩子的背后贴乌龟”、“在福利院院长的茶杯里撒盐”这样的事件。但意外的是，无论是看护老师、还是福利院里的孩子们，没有人对碧萝丝与拉比特的恶作剧感到厌恶，这些让人啼笑皆非的往事，反而成为了福利院清贫生活中的调剂，给大家留下了美好的回忆。",
		level_3 = 0,
		level_4 = 0,
		resume = "碧萝丝与拉比特一样，是来自耶梦加得的涂鸦艺术家，二人组成的创作团体“热带水果派”，在耶梦加得当地有数量众多的粉丝。\n虽然没有亲缘关系，但碧萝丝视拉比特就犹如亲姐姐一般。年幼的碧萝丝在福利院时，由于腿部残疾曾陷入深深的自卑，无法融入同龄人的集体。是拉比特将碧萝丝从心灵的孤岛解救出来，让她变成如今活泼的模样，因此碧萝丝对拉比特充满了憧憬，平时会使用“姐姐大人”来称呼她。\n由于 人工智能 劫持福利院的事件，碧萝丝与拉比特加入托拉，决心在保持绘制反 人工智能 主题的涂鸦同时，寻求与 模拟智能网络 抗衡的力量。于是，她们来到了魂器学院。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "魂武“炫彩波澜”的核心，是由碧萝丝背在身后的那台“颜料混合机”。\n在连接魂智能网络的情况下，颜料混合机会源源不断地生产颜料，通过软管，最后用两只配枪加高压射出，射程最远能达到三十米。\n作为魂武“炫彩波澜”的弹药，那些颜料并不是普通的染料，而是含有特殊粒子的“解离液”。它拥有很强的附着性与腐蚀性，很容易就能沾上敌人的外壳，并迅速瓦解护甲。\n而生产颜料的素材，则可以通过电子元件来补充。颜料混合机会自动解构投入的素材，提取当中的元素作为颜料的材料——这意味着在作战中只要打败 人工智能、取得部件，就能补充颜料，达到持久作战的效果，非常实用。\n至于颜料的颜色，则是碧萝丝的个人兴趣。",
		file_3 = "整理碧萝丝的资料时，我们发现在最早的几份档案里，都能看到福利院的看护老师、对碧萝丝表示担忧的评价，比如——\n“碧萝丝是一名安静的孩子，但那不是令人放心的状态。她拒绝沟通，似乎对所有人封闭了内心。”“在短暂的沟通中，我了解到碧萝丝十分在意自己的义肢，古怪的双腿让她觉得自己是一名‘异类’，无法对同龄人敞开心扉“……\n这些记录让所有人都感到意外，因为“安静”是与现在的碧萝丝最不搭调的一个词了。\n档案里我们还发现，幼时的碧萝丝最喜欢一个人默默地观察兔子，兔子的沉默、温顺，能让她感受到安全感——联系起拉比特的特征，两人成为“姐妹”时的景象，就让人不得不好奇了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "加入了魂器学院后，碧萝丝那满脑子坏主意的个性没有一点收敛，反而因为亲密接触的人增加而显得变本加厉，用现代流行的一个词来总结就是——“小恶魔”。\n她非常记仇，嫉妒与“姐姐大人”拉比特关系亲近的所有人。根据收集到的学员证词，我们发现凡是和拉比特单独相处过的学员，都受到了碧萝丝的恶作剧。其中班长倒霉的次数最多，至今已遭遇了十次“黑板擦攻击”、五次“汽水开盖冲击”、三次“背后贴条”还有一次“洗洁精地板摔”。\n碧萝丝的恶作剧，就连拉比特也不能幸免。神经大条的拉比特曾忘记碧萝丝的生日，当晚就在被子里发现了窜来窜去的电动老鼠。\n可是现在，碧萝丝遇见了一些麻烦。\n她想要看看布克丝的另一面，那个整天摆着平静扑克脸的学院院长，遭受意想不到的恶作剧时，会是怎样有趣的表情呢？\n——然而针对布克丝的恶作剧一次也没有成功，她总能避开挂着黑板擦的门、换掉摇动过的汽水瓶、出门前轻描淡写地取掉背后的字条……“那家伙如同背后长了一只眼！”，每次恶作剧失败的碧萝丝都咬牙切齿地如此说道。\n于是，“让布克丝吓出眼泪”，成为了碧萝丝最新的目标。",
		level_6 = 0,
		record = "小恶魔碧萝丝虽然十分喜欢捉弄学员，总是不间断出演一个又一个恶作剧，但是实际上，她很珍惜学院里每一分每一秒的生活。"
	},
	[202320] = {
		soulid = 202320,
		valuation = "多线操作能力非常亮眼，一边狙击一边还能够对机械犬作出指挥，原本就高命中率的狙击在机械的辅助下更加致命，想必能够成为优秀的后卫人员。",
		file_1 = "虽然从事猎兵这种危险的行业，不过萨姬塔本身并不是喜欢引发争端的类型，平静恬淡就是她最好的生活方式。\n另外，如果说的话太长，萨姬塔可能会因为压力增加导致发言变地断断续续，甚至直接中断交流。\n造成这种现状的原因来自她的养父——一位活跃在过去的战争中的猎兵。将所有的技艺与知识教授给了养女的那位沉默寡言的老人，唯独没有教会她与正常人相处的方法——当然这可能也是某种程度上的天赋不足吧。\n顺便一提，萨姬塔慌张起来的话偶尔会打喷嚏，这个时候一定要小心哦。",
		level_3 = 0,
		level_4 = 0,
		resume = "萨姬塔来自混乱的巴哈姆特地区，由一位老猎兵抚养长大，性格冷静平淡。萨姬塔的美人外表与潇洒特质非常引人注目，但实质上少女并不擅长与他人交流。\n战斗方面，萨姬塔精通各种属于猎兵的作战技巧，与其匹配的魂智能武器也拥有强大的远程支援能力。明明应该是善于单独行动的猎兵，但却意外懂得团队协战，似乎是过去与已经加入学院的艾玛学员有过交集。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "与萨姬塔形影不离的机械犬名为“凯撒”——集侦查、护卫、追踪为一体的电子机兵。虽然并不具备高智能，但本身附带一定的学习能力。\n它的工作之一就是代替萨姬塔打扫战场，从AI的残骸中挖掘有价值的材料。\n在战斗中，凯撒能依靠加装在头部的高性能监视器监控战场，充当射击辅助系统，在关键时刻也能够作为备用能源用为萨姬塔的武器充能。\n偶尔，萨姬塔也会命令凯撒做一些旁人难以理解的动作，权当娱乐。",
		file_3 = "实际上，在加入学院之后，萨姬塔学员反而很快交到了朋友。\n无论是类似琉璃、艾玛这样善于观察揣摩他人心意的学员，还是萱这样同样寡言少语的学员，似乎都能与她进行完整的交流……\n虽然萨姬塔与她们的之间交流大部分只需要一个短句甚至单字就能完成，不过似乎并没有理解错误的场合，果然怪人就应该在怪人堆里找朋友吗？此外，萨姬塔学员与艾玛学员的关系……明明平时还能气氛很好地交流，但是一旦发生冲突就会毫不犹豫地大打出手，无法确定她们实际上的关系如何。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【逆星极光】是为萨姬塔学员定制的魂智能武装，按照她所希望的“大功率”、“高精度”、“外表帅气”的要求所创造的。\n战斗的原理是用斥力场将等离子约束在发射口，再以磁场推送出去，无论是精确的狙击还是大范围的轰炸都能胜任。\n相对一般的魂智能武器在操作上有些许的繁琐与危险性，不过萨姬塔学员能够完美胜任操作的任务。\n不过在攻击方式上与同行的艾玛小姐有些异曲同工，难道这也是对抗心？",
		level_6 = 0,
		record = "“这样就够了……应，应该吧。”"
	},
	[203420] = {
		soulid = 203420,
		valuation = "让人惊叹的综合素质！无论是对外输出还是协调队友控制战局都有着十分耀眼的表现！军方出身的刻罗战斗经验丰富，面对危机时临危不乱，天生的战斗天才！",
		file_1 = "关于学院。\n刻罗加入学院时距离她加入联邦军方已经过去了三年，在这三年里的刻罗从一开始对一切都充满期待到对这军事化的训练方式感到十分厌烦。\n让她感到有趣的事物也已经依次被她玩了个遍。她在这三年里举办过极限跳水比赛，十次的体育运动八次是在速降、 攀岩 、雪板、空中冲浪 、 极限越野 、极限滑水。越是危险的运动，她就越是觉得有趣，欲罢不能。\n曾经在军队出行的饯别宴会上大出风采，甚至与把那群古板无趣的军官调戏了个遍，也许这身为海军军官的事业对她来说已经到了倦怠期。\n正当她百无聊赖之时，她的至交老友索菲亚向她抛来了橄榄枝，魂器学院在对海洋作战部分十分薄弱，希望联邦军方能够派遣一位海军军官担任海战指导，这正中刻罗的下怀！\n尤其是当她知道那个让她唯一一次尝到失败滋味的无面之神——斯卡兰斯也在学院时，这位联邦的军官已经迫不及待来征服魂器学院这片全新的海洋。",
		level_3 = 0,
		level_4 = 0,
		resume = "潘欧森·刻罗·冯·威斯敏斯特，出身鲁比克背后财阀世家的联邦军方海军军官，因为厌烦了军方日复一日的训练从而向上级申请转以海军指导的身份空降魂器学院。\n出身贵族的她从小便享受了大量的教育资源，天资出众的她从未让父母失望，无论是文化课程还是艺术创作都有着极高的成就，在投身军方后亦表现出卓越的战斗能力，是实打实的“人中龙凤”。\n一路顺风顺水成长的刻罗性格十分放荡不羁，举止轻浮神经质，热爱调戏下属与队友并欣赏他们窘迫害羞的样子，十足的恶趣味。在军方玛尔斯就任海军上将时被称为“海上的妖精””偷心的猎手“。一方面是因为其在海上优秀的战斗能力，一方面是因为刻罗出众的外表和魅力曾迷倒一众士兵。\n但让人意外地是，刻罗在作战时会收敛所有不正经的性子变身为严谨可靠的上将，深得下属的爱戴。关于这一点，在她的挚友索菲亚口中称之为“贵族的教养”。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "关于家世。\n刻罗的不凡的家世背景从她名字而言便可窥见一斑。潘欧森·刻罗·冯·威斯敏斯特，威斯敏斯特家族身为尼德霍格区域的老牌贵族资本家，其贵族底蕴可追溯到数百年前，这一古老的家族与鲁比克财团大小姐爱丽丝背后的家族互相制衡。\n与爱丽丝家族的创新与冒进不同，威斯敏斯特家族更加古板保守，因此刻罗的出生躲去了身为试管婴儿出生的命运，但这并不妨碍刻罗成长后的优秀。在索菲亚还在布鲁克财团时，她与索菲亚和爱丽丝互为挚友，因她们在财团势力中举重若轻的影响力，并称为布鲁克三巨头。\n比起爱丽丝家族在科学技术领域的经济投资而言，威斯敏斯特家族因祖上为海军世家，曾在海上称霸一方（海上之王英译，潘欧森因此而来），倾向于把更多的资金投入了军队建设。这也是为什么刻罗与联邦军方联系密切并选择加入海军的原因。",
		file_3 = "关于义肢。\n那夸张的义肢是刻罗浪漫主义天性的最好体现。对多数选择安装义肢的人而言，比如拉比特和碧萝丝，大部分是因为她们身体自然的缺陷而迫使她们对身体做出改造，而刻罗选择摘除原先健康的身体部分换成如今的义肢只是因为义肢——看上去很酷！\n这委实有些疯狂了一些，但是对于解放天性的刻罗而言是十足的新鲜且刺激的事！比起人类弱小的肉体，刻罗认为拥有钢铁铸造的肉体才能体现科技的浪漫和拥有更加强大的力量，这也正巧让她以后能够灵活地使用【碧波万顷】。\n索菲亚在得知她大胆的决定后也只是摇头叹息，随后亲自为她设计了这一款性能优秀并使用最新微分子金属材料的军用义肢，她这位拥有上帝之手的挚友，在制作时还不忘为这义肢做出时下最时尚的造型。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "关于从军。\n这是刻罗人生中干的第一件“出格”又“计划外”的事。曾经的刻罗每日的日程都在父母严格的监视之下，一举一动都要保持贵族应有的优雅与风范，密集的教育课程和训练排满了她的童年，让她小小年纪便变得古板无趣。\n她心中的叛逆与渴望被深深掩埋在教条之下，在鲁比克财团总部工作时枯燥的生活平静如一潭深水，直至人工智能战争爆发造成的短暂动荡为她深水一般的人生打开一道缺口。她透过这道缺口看见了人类喜怒哀乐的众生相，那些生命的挣扎与延续是如此的鲜活多彩。\n她心中的叛逆与渴望被深深掩埋在教条之下，在鲁比克财团总部工作时枯燥的生活平静如一潭深水，直至人工智能战争爆发造成的短暂动荡为她深水一般的人生打开一道缺口。她透过这道缺口看见了人类喜怒哀乐的众生相，那些生命的挣扎与延续是如此的鲜活多彩。\n那时恰逢私交好友索菲亚与布鲁克财团决裂，这件事成为刻罗决心要改变这无趣生活的契机。她一边暗中相助索菲亚脱离财团，一边为自己的“出逃”做好万全准备。正当父母因索菲亚的终止合作而焦头烂额无暇顾及自己之时，刻罗毅然选择趁机离开家族，去拥抱自己全新的人生。\n刻罗在初次加入海军面对未知的未来也曾经有过片刻的恐惧与迷茫，但是这些情绪在见到无边无际的大海时全部化为泡影，海洋让她完全解放天性，释放了她的魅力，让她在战斗时无时无刻保持着激情。\n同为海军的斯卡兰斯曾与她在海上有一面之缘，在刻罗兴致勃勃地打算好好会一会这位无面之神之时，却被对方的面瘫脸搅碎了兴致，堪称这位“海上妖精”在她魅惑众生的生涯中唯一一次败北。",
		level_6 = 0,
		record = "“我已经受够联邦军方的古板无趣，该去找点新乐子了。”选择来到魂器学院之前，刻罗抚摸着【碧波万顷】淡淡说道。"
	},
	[200920] = {
		soulid = 200920,
		valuation = "薇薇恩的近战能力比远程战斗能力更出色，虚无双刃的多种形态可以让她的近身战灵活多变。",
		file_1 = "薇薇恩的爱好与众不同，她喜欢做白日梦，她的愿望是每天都能留出时间来做白日梦——这一点被因果吐槽了很多次。\n据说薇薇恩梦到过各种稀奇古怪的事，山洞中的恶龙，飞天的独角兽，会说话的蘑菇……当意识比较清醒的时候，她甚至能操控梦境，比如爬上恶龙的翅膀，摸摸独角兽的角，以及吃掉会说话的蘑菇。当然，薇薇恩也有做噩梦的时候，不过她往往记不住噩梦的内容。\n薇薇恩在课堂上睡觉的时间比夜晚睡觉的时间多得多，因此，她经常被任课老师命令站着听讲。",
		level_3 = 0,
		level_4 = 0,
		resume = "别看薇薇恩平时活泼可爱，一旦战斗起来会变得非常“莽”，一股脑地往敌人阵营里冲，总之勇敢地前进就对了！这让同伴们头疼得要命。好在薇薇恩听得进意见，被呵斥之后又迅速返回。\n薇薇恩的魂智能武器“虚无双刃”除了常规的刃口，还可以伸展出一段近乎透明的刀刃，有利于发动出其不意的袭击。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "薇薇恩很困惑，当别人因为年纪变大、晚睡等等原因而导致记忆力下降甚至失忆时，她却多出了一些不属于自己的记忆。\n那是一片无边无际的紫罗兰花田，不是温室中培育出来的，也不是全息投影，而是大自然孕育的产物。为什么这么肯定呢？在阳光遮蔽，土地稀缺的今天，哪里还会有一大片野生花田呢？薇薇恩说不出所以然来，但直觉是这样告诉她的。\n可能是梦境吧！薇薇恩不止一次地想，可是这个梦境出现得太频繁了，就像是真实的记忆。如果能找到那片紫罗兰花田，也许就能揭开一切谜题。",
		file_3 = "最近薇薇恩的梦境有了变化，一望无际的紫罗兰花田中出现了一个人影。\n那是个模糊的影子，只能看出不清晰的轮廓，它躺在迎风摆动的花田上，似乎沉睡了许久。薇薇恩十分惊喜，她朝着人影一路奔跑，却始终无法接近。这个梦境重复了很多次，每一次，模糊的人影都安静地睡着。\n“怎么会有人比自己还能睡呢？”，薇薇恩疑惑着，“或许它也是一个喜欢做白日梦的人吧。”",
		level_7 = 0,
		level_2 = 0,
		file_4 = "薇薇恩的魂智能武器事件非常特殊，我们对此展开了调查。\n两年前，薇薇恩卷入了当地的一起械斗案件，凑巧路过的她被枪弹击中了脑部，随后送医治疗。由于脑内损伤严重，并且没有时间寻找匹配器官，医生只能尝试使用义体技术修复了脑组织内三分之一的神经网络。手术结果不容乐观，薇薇恩在病床上昏睡了近三个月。也许是强大的求生意志战胜了一切，薇薇恩的身体终于逐渐好转，但她的性格明显和以前不太一样了。\n根据学院的复诊显示，薇薇恩脑内的义体和原先的器官融合得不错，大部分记忆没有缺失，除了性格变化，一切正常。但是，为什么薇薇恩能生成两套不同的“妖精之匙”呢？我们推测，薇薇恩脑内的生物神经网络保留了之前的性格，由于残缺而被压缩成了其中一个人格，同时义体修复的部分产生了另一个人格，也就是我们见到的“薇薇恩”。这两种不同的精神状态让魂智能网络生成了两套“妖精之匙”。\n当然，这只是我们的推测，目前还没有明确的证据来支撑我们的观点。",
		level_6 = 0,
		record = "薇薇恩的父母给了我们一本童话书，书中描写了一片无边无际的紫罗兰花田，那是她以前最喜欢的故事。原来不管是以前，还是现在，盛开的紫罗兰花田真的只是遥远的梦境罢了。"
	},
	[203920] = {
		soulid = 203920,
		valuation = "对魂武的掌握可以说是在实战的演练中达到了炉火纯青的地步，与双人配合作战的完美形成对比的是，单兵作战能力实在是差强人意。也许是这对姐妹之间的羁绊，当她们并肩作战时，她们无所不能。",
		file_1 = "阿黛拉姐妹第一次遇见爱伦伊斯贝尔家族的使者的时候，是在库库尔坎的福利院中，那时正值凛冬时节，天空中飘荡着细小的雪点，寒风如刀割。\n使者们温柔的手抚摸孩子们稚嫩的脸庞，随后留下纯净水，白色的羊毛衫，羽绒服以及食物。当她们的视线触及阿黛拉姐妹时，惊艳的神情一闪而逝。\n当使者们将要离开，孩子们依依不舍之际，福利院院长却告诉她们优秀的孩子将会被鲁比克财团下的爱伦伊斯贝尔家族收养。\n鲁比克财团！这个掌握世界经济命脉的财团，孩子们无不流露出憧憬的目光。\n就这样，阿黛拉姐妹与其他几个女孩在其他孩子的羡慕目光中跟随使者们离开，那时的梅洛尔在车内欢呼出声，满心都是被收养的喜悦和对未来美好生活的憧憬。但薇丝缇儿却心事重重，对于此番机遇她心中总觉得事情并不简单。",
		level_3 = 0,
		level_4 = 0,
		resume = "丧失家人的孤儿，1000号“姐妹”，流浪的赏金猎人，“暗影”的元老创始人，爱伦伊斯贝尔家族的使者。在短短的人生路上阿黛拉姐妹拥有众多的身份。\n出身平凡的姐妹花，人工智能战争的爆发打破了她们平静的生活。孤儿院潭水一般的生活让她们在面临爱伦伊斯贝尔家族派来挑选孩子的使者时，看着她们伸出的双手好像看见了耶稣降临，但是事实真的如此吗？\n阿黛拉姐妹成为了家族收养的“姐妹”中的一员，没人知道阿黛拉姐妹究竟在爱伦伊斯贝尔家族发生了什么，只知道她们轰轰烈烈地从家族中逃出，再如泥沙入海一般陷入沉寂。\n赏金猎人的流浪生活是这对姐妹为数不多快乐，她们在旅途中结识了另外两位伙伴无心插柳创立了“暗影”，并收养了一位女孩——萱。但是很快“姐妹”再次找到了她们，家族的指令无可违抗，当她们再次出现在人前时，已经成为爱伦伊斯贝尔新一轮的使者，魂器学院正是她们此次的目标。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "自她们踏入爱伦伊斯贝尔家族大门的那一刻起，“姐妹”一词将永远与她们相伴而行。\n在这里她们遇见了许多和她们一样被使者选中的女孩们，她们或局促不安或假装镇定，但幼小的孩子们都对向她们伸出援助之手的爱伦伊斯贝尔充满感激与向往。\n她们被带进一间又一间四周环绕玻璃墙的空旷洁白的房间，随后在这里渡过了一段平静又美好的生活。每天都有温柔的使者带领她们出去玩耍，食物和生活用品永远充足，她们还在那里的电视上看到了鲁比克财团的大小姐爱丽丝，以及那个大科学家索菲亚。孩子们再也不用担心寒冷与饥饿——除了每个月都有一个孩子被带走。\n但是粗心的梅洛尔浑然未觉，凭借着话痨的特性很快和其他“姐妹”打成一片，总觉得薇丝缇儿每天担心这个担心那个实在是杞人忧天，她一直保持着这种想法直到有一天薇丝缇儿被使者带走再也没回来。\n梅洛尔不知道妹妹遭遇了什么，但是她仅凭自己的遭遇就让她恨不得掐倒过去的自己。再相遇时，她们相对而视，默契地抚上一侧不正常的眼睛。看着变得身体病弱的妹妹，梅洛尔深知她们必须离开。",
		file_3 = "逃离爱伦伊斯贝尔后，阿黛拉姐妹过上了四处流浪的赏金猎人的生活，但是她们从未动过回去的念头。她们在夜晚流浪，与暗夜中的蝙蝠作伴，如同幽灵一般昼伏夜出，无知无觉中取走目标的性命。从库库尔坎到耶梦加得，从耶梦加得到洛加尔，直到一个奇奇怪怪拿着巨大剪刀的疯女人挡住她们的脚步。\n同为赏金猎人，阿黛拉姐妹因和理发师争抢同一桩生意而彼此剑拔弩张，双方不过短暂交手，理发师便觉得自己遇到了完美的对手，她们本该酣畅淋漓地打上一场，却迷迷糊糊地被一位笑眯眯的女孩拉住，又迷迷糊糊地与她们一起结伴而行，并最终创立了暗影。\n拥有【伙伴】的日子十分温暖，梅洛尔这个直来直去的姐姐会为了更好领导暗影前去月和会请教芙蕾管理之道，冷漠的妹妹薇丝缇儿会为了照顾组织内的孤儿送出自己珍藏已久的玩偶。她们还会为了争取“暗影”的资源去与当时的大黑帮“曼珠沙华”商讨合作。\n阿黛拉姐妹在“暗影”的最后一年冬天，她们遇见了一个被埋在雪地里的女孩，当那个女孩纯净的眼神望过来时，她们好像看见过去的自己，让她们冷硬的心肠浮现一丝柔软。最终这位少女成为了她们的养女——萱。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "阿黛拉姐妹成为爱伦伊斯贝尔的使者来到魂器学院时，萱的反应异常激烈，但最后也只是在姐妹二人冷淡的目光下逐渐安静下来。在二人离去后，鲜少有感情波动的萱望着她们的身影默默低泣。\n阿加莎贝蒂姐妹和芙蕾更是吃惊于她们目前的状态，在院长告知她们目前的身份后，也只是沉默不语并不探究往事。\n就在院长以为只要小心防范她们学院就不会发生什么大事的时候，一个变故打得院长措手不及——阿黛拉姐妹袭击了爱丽丝和索菲亚，虽然最后二人并未受伤，但是这件事也让两姐妹在魂器学院内的信誉降低为0。事后院长在询问她们这么做的理由时，她们沉默许久才断断续续说出一句话。\n鲁比克，讨厌。",
		level_6 = 0,
		record = "在这个混乱的世界，仅仅是活下去已经很艰难了，自由只是……奢侈的祈愿。"
	},
	[27120] = {
		soulid = 27120,
		valuation = "反应非常快速！感知能力和预判能力都远超常人。除灵敏的动作和迅猛的身手之外，仍保有不错的输出频率，非常适合远程偷袭！",
		file_1 = "米优的父母是在人工智能统治下将【平凡】贯彻一生的市井小民，日复一日的矿区工作，吃饭，休息；成长，成年，结婚生子。在米优的眼里，父母的一生是勤劳而短暂的，渺小又狭隘的，他们被名为奥杜因的牢笼笼罩着一生，这牢笼不仅体现在城区的边界线，更存在于他们的内心。\n即使父母是不停歇地劳作，米优的家庭依然十分贫穷，物质的极度缺乏让她在年幼时期就对金钱生出无限渴望。然而她却未曾因此走上歧路，秉性正直的父母从小身体力行地教育她：我们可以卑微如尘土，不可扭曲如蛆虫。\n这样正直善良的夫妇最终早早丧命于奥杜因的矿区污染，他们没有倒在人工智能仿生人的手中，而是人类上层阶级无休止的剥削与压迫中。",
		level_3 = 0,
		level_4 = 0,
		resume = "米优出身在平凡的矿工家庭，幼年时的记忆大多是奥杜因黑色的天空与父母一日复一日的辛劳，从她睁开眼睛的第一刻，黑猫美杜莎就陪伴在她的身边。父母去世后，米优决心不再停留在一个地方耗尽一生，她拿起父亲生前常用的16号工箱，想要走出奥杜因黑色的天空。\n加入暗影只是米优孤身一人在这混乱的世界行走时给自己添加的保障，尽管自幼的贫穷让她对于金钱十分渴望，但父母的言传身教让她始终坚持“君子爱财，取之有道”。\n成为“旅者”是她仔细思考后选择的能够满足四处行走却又能赚钱的第一份工作，让她自己都没想到的是，这份工作至今都未曾改变，她与美杜莎一人一猫也仍旧乐在其中。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "“走出奥杜因”是米优在父母离去的那一刻突然闪现在脑海中的念头。但那时尚且处于懵懂时期的她并不明白这念头代表着什么，直至她与一位活力四射的女孩相遇。\n与伊沫的相遇源于一场矿区塌陷的意外，由于矿区塌陷矿场中心的电力设施损毁严重，身为电力工程师的伊沫在接收到消息的那一刻就马不停蹄地赶到现场。那时对矿区工作无限麻木的米优被伊沫工作中眼中散发出的光深深吸引，她并不能理解为什么会有人面对工作还能兴致勃勃，对此，伊沫理所当然地告诉她：“那当然是因为这是我所热爱的事业啊！”\n那一刻的米优终于明白那个念头代表着什么，那是她对自己人生未来的追寻，是不甘于步父母后尘的反抗。",
		file_3 = "经常有米优的顾客看着她年复一年地重复行走各个地区而问她：这样长久没有变化，真的不想换换生活吗？\n对此，米优的回答永远是不想。对于米优来说，能够一边游历世界又能一边在游历过程中见证人间的各种酸甜苦辣，再也没有比这更加快活的事业了！但是身为赏金旅者的日子并非是一帆风顺的。匹夫无罪，怀璧其罪。米优经常要面对想要抢夺她手中货物的雇佣兵或是成群的流浪汉，好在她在一次被洗劫一空后遇到了身为猎兵重伤的萨姬塔。在她救下萨姬塔并治好她后，对方便以教授格斗术和战斗技巧作为报答，米优自然是求而不得，这么说来萨姬塔大概算米优的半个师父？\n经此一难，二人就此相识，萨姬塔时常需要米优提供一些生活物品，米优有时需要萨姬塔帮助她解决一些棘手的麻烦。就这样，年复一年月复一月，二人逐渐成为了相识相知的老伙计。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "米优是一个闲不下来的人，从小养成的持家习惯总让她不自觉去处理工作。她不认为这样不好，在米优心中，勤勤勉勉才能获得更多钱财和物资，工作赚钱是人生中第一重要的事，家里还有一只猫主子要养呢！\n米优做事时一旦打定主意就不撞南墙不回头，因此她常常钻牛角尖。因为这个伊沫不止一次被她气到跺脚。她很不喜欢变化，因为变化往往意味风险和未知，这不利于她做好万全的计划。更何况她在作为旅者的数年里认识了不少老顾客，肩负着他们的委托的米优更不愿意去冒险。\n与魂器学院的合作要多亏伊沫的规劝和萨姬塔的牵线搭桥，对于魂器学院来说，时常会有外派的学员需要魂器学院输送的物资，而米优行走各地经验丰富，与她合作在合适不过。但对米优来说，与魂器学院合作意味着改变，而最终能让她这个万年不变旅行道路的人改变，这一切都是因为魂器学院给的太多了。",
		level_6 = 0,
		record = "美杜莎其实是一只基因合成的长寿猫咪，也许，它的寿命比米优还长也说不定。"
	},
	[26420] = {
		soulid = 26420,
		valuation = "奥瑞特在战场上表现出的沉着冷静是十分难得的品质。由于出色的运动能力和机械理解，巨龙之拥在她的开发和使用下表现出多样的作战手段。【巨龙之拥】的中近距离作战能力和辅助的副武器暂时致盲效果，让奥瑞特对战场有着优秀的掌控力。",
		file_1 = "奥瑞特的父母暂时还没脱离灾害后带来的生命危险，仍旧处在看护阶段。奥瑞特在空闲的时候，会经常到医院去看望父母，并和她们分享学院生活的细节，和生活的苦恼。\n在多次交流中，我们发现奥瑞特和父母谈起班长次数也变得多起来，看来她十分认可班长出色的表现，并认为是值得信赖的伙伴。\n在医院里，奥瑞特并没有被忧愁困住，也时常把笑容挂在脸上。她经常到医院会做一些机械小玩具给住院的孩子们，逗他们开心。她也经常帮助机工修理和维护医用器械。\n唯一令人医院人员无可奈何的是，“请奥瑞特小姐下次回去的时候，不要从楼顶走，医院周边禁止跑酷啦~”",
		level_3 = 0,
		level_4 = 0,
		resume = "奥瑞特·宁芙，在学院中无疑是优秀沉稳的学员之一。她在机械技术上体现出来的理解，得到了院长布克丝的赏识，也得到了同样擅长机械改装的魂姬索菲亚的认可。\n人工智能事件之后虽然失去了左手，但是和魂器【巨龙之拥】的同步率达到了100%，并进入魂器学院进一步学习。奥瑞特对于人工智能事件的态度和大多数魂姬对其的仇恨、敌视不同，她想要弄明白这背后的原因，所以更加努力投入机械知识学习和身体锻炼上。\n为了方便运动和机械工作，奥瑞特喜欢轻便的装束。同时，她还时常自己对魂器进行维护、升级。敌人永远也想不到被“巨龙”钳制住之后，等待他们的是“巨龙的火焰”还是“女神的闪光”。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【学院秘闻】\n性格沉稳，开朗的奥瑞特在学院中有着“老好人”的美誉。但是，淘气的魂姬们出于好奇，想要看看“老好人”生气的样子，想了很多稀奇古怪的方式想要去惹恼奥瑞特。奥瑞特毫无动摇，不动如山。直到有一天，某位淘气的魂姬做了一件事，真的惹奥瑞特暴走了，而这件事竟然学院里的魂姬都三缄其口，刻意回避到底做了什么。\n传闻，奥瑞特暴走时候的怒吼，就像巨龙的咆哮，甚至，学院里的机械设备一度当机。只有，魂姬们献上鸡胸肉祭品之后，“恶龙”才停息怒火。",
		file_3 = "奥瑞特有过将自己全身都进行改造的念头，但是，在人类意志和电子化生命的抉择中，她选择了前者。\n她认为，只有这样才能考自己的双手开创出新的未来，查明人工智能背后的真相。直到，真相水落石出的那一天，才能带着在意的人和父母一起攀登皮里翁山，征服世界的山峰，享受自然的拥抱，以及家人的笑脸。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "奥瑞特最喜欢的鸡胸肉做法并不是白灼，而是奥尔良烟熏。当然，她对鸡胸肉的喜爱远远超过了正常人，甚至开发了独特的做法。",
		level_6 = 0,
		record = "【巨龙之拥】原本是和【上帝之手】性能相似的魂器，久不经启用。在和奥瑞特同步率达到100%之后，【巨龙之拥】的适用范围和作战形式也发生了变化。在奥瑞特的机械理解下，【巨龙之拥】的近距离攻击方式有：束缚，麻痹电击，摔打，抓取对手时的散射光束和无抓取时的极热爆破攻击。\n中距离的攻击方式：抓取，投掷，进攻干扰，中距爆破攻击。对于远距离的奥瑞特的副武器在造成伤害的同时，还可以致盲对手。在非战斗期间，【巨龙之拥】还可以帮助奥瑞特在机械工作中，进行重物抓取，热能焊接等复杂而细致的操作。奥瑞特本身跑酷、攀岩的运动能力，在很大程度上弥补了【巨龙之拥】在作战机动性不足的问题。"
	},
	[204120] = {
		soulid = 204120,
		valuation = "灵巧有余而力量不足，优点和缺点都十分明显，在作战中更加偏向于辅助，虽然作战方式常常剑走偏锋了点，好在结果都达到了预期目标。不过希望以后在真正的战场上，还是要能够好好听从指挥才是。",
		file_1 = "蒙蒂尼家族破产前夕奈儿正在进修临床医学，这个年少的姑娘在医学上拥有着惊人的天赋。当蒙蒂尼家族覆灭的丧钟在她眼前敲响时，一向活泼好动的奈儿意外的平静。\n对于她来说，家族的覆灭是十分符合历史规律的事情，没有哪个家族可以一直昌盛下去，兴衰变化，三十年河东三十年河西，这不是自然的吗？\n顺应天命及时行乐是奈儿的人生信条，她从未想过要跟着姐姐金百莉一起重振衰亡的蒙蒂尼家族，既然属于蒙蒂尼的故事已经落幕，那么现在就应该是属于奈儿个人的，而非蒙蒂尼家二小姐的——金牌战地守护者的故事。",
		level_3 = 0,
		level_4 = 0,
		resume = "奈儿·蒙蒂尼是蒙蒂尼家族中金百莉的胞妹，目前在长姐的介绍下凭借一流的医疗技术担任魂器学院医疗班的金牌战地守护者。\n奈儿口癖颇多，元气可爱古灵精怪是她的代名词，但当她顶着这张娇憨可爱的脸行事荒唐时，这就不是那么美妙了。金百莉身为她的长姐，在学校里不知道给她收拾了多少烂摊子。\n相比于金百莉对家族复兴的执着，奈儿就无所谓的多，对她来说什么家族兴衰都已经成为过去，人生在世就应该适时放下及时行乐才对，就像她一样——\n奈儿的脑回路常常与他人不同，这一点充分体现在她的医疗事业动机上。虽然客观上她活泼热情地性格为许多人带来了阳光，但她治病救人才不是因为什么“希望大家都幸福”，只是因为她享受掌控别人命运的感觉，享受拯救他人带来的心理满足罢了。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "奈儿最初来到魂器学院后并非一帆风顺，就比如与伊文捷琳的不合是学院内人尽皆知的事情。但是她们之间的不合并非那种剑拔弩张的仇视，而是因为医疗观念不同而产生的的不合，尽管她们时常因为如何制定手术策略而大吵一架，但彼此都因为对方丰富的医学知识而惺惺相惜。如果要用比喻的话，大概就像是同为风流才子的两人彼此欣赏却因策论观点不同而时常斗嘴吧？\n对伊文捷琳来说，奈儿的救治手段十分极端，她时常采用剑走偏锋的急救方式让喜欢中庸稳妥的伊文捷琳十分不赞同；而对于奈儿来说，伊文捷琳的救治方式实在是太——传——统——啦！等到救治见效，黄花菜都凉了。\n因为两人观念的不和，魂器学院医疗班分为了两个小队，以奈儿为首的激进派和以伊文捷琳为首的温和派分庭抗礼。",
		file_3 = "来到魂器学院后的日子常常伴随着与伊文捷琳的争论，时常气到奈儿觉得这学院不来也罢！但是这个念头很快就因为遇见了那个让她兴奋地浑身颤抖的疯女孩——玛姬而打消。在奈儿的眼中，玛姬就像是身在深渊的疯狗，颓废，自暴自弃，癫狂，犹如潮湿的淤泥，等待阳光的照耀。\n拥抱她！拯救她！让她重获新生！这个念头在奈儿的脑海中如野火般燃烧一起来，啊，这个可怜的红色的小女孩，她多么需要你的拯救，多么需要你的怀抱啊！快去温暖她！救赎她！让她对你感激涕零！让她视你为她的神明，让她没有你就活不下去！\n然后她就被玛姬一拳撂倒了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "随着奈儿在多次前线行动中的卓越表现，学员们对奈儿的观感也渐渐由“混世魔王”转变为“金牌战地守护者”。学院中每每有学员看到她欢呼着骑着喷射型魂武【热情援护】冲向战场时，都会感叹奈儿对战地守护者这一工作的热爱和无私奉献的精神。\n实际上是真的如此吗？在幼时玩家家酒的时候，奈儿就迷恋上了扮演拯救者向苦难中的人伸出援助之手的感觉，这种感觉让她感到自己可以摆弄他人的命运，感受到那些可怜人对自己迫切地需要，让那些人的喜怒哀乐皆被她所掌控。\n奈儿从这种感觉中获得了来自灵魂的愉悦，所以在她尝试了战地守护者这个职业之后，其他的工作选项都被她抛到九霄云外。在战场上的每一次救助都是在与老天爷抢人，每一次的援救都是她对一条生命的救赎，当她紧紧握着伤员求生的双手之时，从灵魂中传递而来的愉悦让她的大脑都颤栗起来。",
		level_6 = 0,
		record = "人生在世，吃喝二字！人生在世——开心完事！"
	},
	[202720] = {
		soulid = 202720,
		valuation = "不愧是制服过逃走的恶人的监察者出身，无论面对什么类型的人工智能都有应对之法，手脚利落狠辣，作战时处变不惊。但是遗憾的是，可能因为是体重不足的原因，凯拉的体力在战斗时并不够持久。",
		file_1 = "凯拉自出生时身边就只有母亲一人，据她那日日垂泪柔弱不能自理的母亲说，她的父亲凭借一张美貌的脸迷得她神魂颠倒，与她许下海誓山盟。待母亲与自己的贵族家人决裂与他私奔，她那狠心的父亲却卷了钱跑路了！\n年幼时的凯拉面对的永远是母亲的怨恨，因为母亲看见她那张漂亮的脸蛋就会想起她的混账父亲。她聪明懂事，小小年纪就懂得赚钱回家，但无论她多么努力都得不到母亲的笑脸。但年幼的凯拉相信只要自己更优秀一些，母亲总会抱抱她的吧？\n她坚信如此，一直等到母亲抛下她回到贵族家族，她也没有得到过一个拥抱。\n长大后的凯拉曾机缘巧合之下见过母亲一面，那时她记忆中总是怨恨她的母亲满面慈爱的微笑，拥抱着一个可爱的女孩，身边站着一位彬彬有礼的绅士。凯拉那时明白，她再也等不到母亲抱她了。",
		level_3 = 0,
		level_4 = 0,
		resume = "凯拉是军方驻扎在拉弥亚城的重型恶人关押地里的王牌监察者，据说在她看管下的罪犯无论多么凶恶最终都会服服帖帖地服从管教。她是拉弥亚本地人，出身于单亲家庭，被母亲抛弃后饥一顿饱一顿磕磕绊绊的长大。年少时因为姿容甚美，时常让她遭到觊觎，这让她不得不加入军方寻求庇护。\n凯拉性格狂放，行为处事放浪形骸，常常对月高歌，与人交流时嬉笑怒骂不成体统。仪表不修边幅，衣服就没有好好穿过，但是这并没有使她的美貌明珠蒙尘。她想法偏执，别人很难改变她的既成想法，堪称不见棺材不掉泪的典范。同时她还是一名性单恋者（指你对某人产生好感之后，当他对你有同样的感情之后，你就会讨厌这种感情，讨厌他。即只喜欢不喜欢自己的人。），据说是成长经历造成的？\n来到学院是因为军方与魂器学院的合作，在布克丝口中是魂器学院的重要合作伙伴。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "少女时期的凯拉并非如今这副狂放不羁的模样，她谨小慎微，温柔美丽，小小一个人就很会过日子了。但是因为母亲的抛弃，她很快发现这样并不能保护自己，相反的，美丽无罪，怀璧其罪。身为被歧视种群的异化人，如果自己是楚楚可怜的小白花只会惹人觊觎。\n为了保护自己，凯拉逐渐变得不修边幅，刻意丑化自己，变得离经叛道，行为处事粗犷豪放，但是即使这样，仍有人前仆后继地爱上她的皮囊。凯拉一生得到的爱很少，其中大部分是虚情假意，有利所图。\n她也曾得到过少年人的真心爱慕，但那人很快在人工智能战争中逝去；她也曾得到过小动物的喜爱，但是大多数不到一周它们就进了天敌的肚子；她也曾获得过老婆婆的关照，但第二天老婆婆的房屋便起了大火。\n凯拉隐隐明白，她永远无法获得别人真心的爱，若是爱自己的人终究不得幸终的话，那自己就亲近不爱自己的人吧。",
		file_3 = "成年时加入军方的凯拉身上已经完全抹去少女时温婉柔弱的气息。她大胆狂放，身为狼之异化人常常对月高歌，引得监察署里的同事大声喝彩；她行事不羁，但却打得恶人落花流水，追击查案从无失手；她为求更强，接受军方【荷鲁斯之眼】的基因改造，忍受改造痛苦从正常同色变为异色瞳，只为了获得远超人类全息式视觉警戒恶人。\n她很仰慕鼎鼎大名的刻罗将军，她也曾远远看过一眼，只觉得真是一流风云人物，如若自己也能像她一般就好了。凯拉将刻罗视为偶像，虽然自己不能成为将军统领军队，但是自己在监察署中亦可有一番作为。\n可惜她的美梦并没有持续多久，因为容貌过于绮丽，很快在监察署中惹出风风雨雨，谣言四起。凯拉不得不仓皇离去，选择前往重型恶人关押地成为一名终日不见天空的监察者。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "魂器学院需要一个能够完美看管人工智能样品的【监视者】，而军方迫切需要监视魂器学院的【钉子】，双方一拍即合，拥有【荷鲁斯之眼】的凯拉成为最佳人选。\n与魂器学院的合作算是凯拉完全未知的体验，她融入得很快，嬉笑怒骂，吊儿郎当，从不向他人倾诉自己的苦难，与学员们迅速打成一片。一度被班长称为疯女人，被布克丝怀疑业务能力。\n最让她惊喜的是，她在魂器学院中找到了不被自己外表吸引的人——塞雅，甚至塞雅十分讨厌凯拉，天性内向冷感的她觉得凯拉十分吵闹，经常间歇性发疯，整日衣衫不整，不够可靠。而凯拉只觉得——妙极了！不喜欢我，不喜欢好，不喜欢好！！既然你不喜欢我，那我来喜欢你了！",
		level_6 = 0,
		record = "凯拉的一生都在被人抛弃。"
	},
	[201120] = {
		soulid = 201120,
		valuation = "出色的战术意识与出色的战术执行能力，织夜小姐对于场景的掌控力堪称绝佳，非常适合进行特种作战。",
		file_1 = "或许是因为职务的关系，织夜的行事风格是在这座学院中少见的严谨类型，而作为精英，少女的言辞中充满了自信。\n乍看之下是有些难以相处的类型，不过多作接触就能发现是个细心随和的人。\n织夜的审美风格与严谨的性格继承于父亲，但是习性与言辞却更接近于来自洛加尔的母亲，因此偶尔会使用一些晦涩难懂的古语。",
		level_3 = 0,
		level_4 = 0,
		resume = "织夜，受院方邀请而来的“战术家”。\n她的主要工作是为学院的战斗提供战术支援，偶尔也会参与对人工智能的敌后破坏工作。\n个性认真严谨，能够正确、精准地执行学院发布的指令。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "虽然很少见，但织夜也会携带一些淡蓝色晶格“维系者”。\n那是原本是一种纳米建筑材料，通常是用于模块固定与边界隔离。在战斗中，“维系者”能够依照织夜的想法构筑出落脚点与壁障，为织夜提供各种各样的战术便利。\n不过在日常生活中，织夜也会用“维系者”构筑便利的生活道具，诸如阳伞、发卡、扇子之类的物品，可谓是物尽其用。",
		file_3 = "【织弦舞者】：正如其名，这是一种灵巧型的魂智能武装，通过置换装备的部件能够实现织夜各种各样的战术需求。匕首、钩索、枪械乃至黑客设备，与魂器一同驰骋于战场的织夜，如同舞者一般华丽而凛冽。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在被派遣到学院后，织夜就一直过着深居简出的生活，平日中很少与其他学员接触，在大部分学员眼中，织夜是如同高岭之花一般冷漠遥远的存在。\n不过那只是表象，织夜喜欢甜点、喜欢华丽的衣装、喜欢猫。\n而她的性格也和猫一样，优雅而变幻无常。\n不过，虽然并非难以相处的存在，但接近织夜的人依旧寥寥无几，或许是那种凝视着远方，一心一意投入到理想中的气质令人敬而远之吧。",
		level_6 = 0,
		record = "人生的战术，就是将自己的每一秒都用在有意义的地方哦。"
	},
	[203720] = {
		soulid = 203720,
		valuation = "优点与缺点都十分突出，魂武【孤枪王女】是强大的一击必灭武器，但同时又十分难以驾驭。暴力输出。虽然实力强横，但团队作战一团乱麻，建议短期内派发单独侦查任务。同时班长长期负责带她融入集体，以便于以后团队作战。性格暴烈，建议选择分配性格温柔的室友。备注：不要夏洛特！",
		file_1 = "痴迷武学，诸武精通，军方称之为——巴别的猛犬。为人不拘一格，就算在诸王宴内部的战友也对其好斗的品格评价褒贬不一。有人认为她过于争强好胜不利于团队合作，有人认为她勇于挑战自身极限才能持续不断的进步。\n擅长单独作战，从幼时就是孤儿一路摸爬滚打进入巴别高层的她，天生难以融入集体，这与她巴哈姆特巴别首领的身份互相矛盾。同时与巴别无序的狂欢理念不同的是，瑟坦达主张有序的守护，她坚定地为每一位组织成员提供庇护。这导致她在甲布尼撒诸王宴成员中十分异类，麾下上任首领遗留下的旧成员也常与她争锋相对。瑟坦达常因为与组织成员的离心感到十分苦闷。",
		level_3 = 0,
		level_4 = 0,
		resume = "瑟坦达，手持红色长枪的少女，来自巴别的核心组织甲布尼撒诸王宴。出身微末的她在混杂着混乱无序的巴哈姆特通过经年累月的战斗而一步步成为巴别组织的领导高层，担任巴哈姆特巴别组织的首领。\n瑟坦达并非其原名，不如说身为出生在巴哈姆特混乱区的孤儿从一开始就没有姓名。后来她因不要命一般的狂野战斗风格在巴哈姆特闯出名声时，因其手持红色长枪，性格暴烈，作战方式犹如猛犬，在战场上所向披靡，常常孤身一人迎战，犹如凯尔特神话中的英雄库丘林，遂因此得名。\n时时刻刻握紧手中战斗的红枪是瑟坦达的生存准则。据说这把长枪出于瑟坦达年少时的师父之手。在那个充满争斗与痛苦的巴哈姆特，如野狗一般野蛮生长的少女，因与师父的相遇，走上了她一生的转折。\n也正因如此出身，瑟坦达面对悲剧与丑恶十分平静，也很容易理解弱者面对现实的悲伤。成为领导后的她尽力用她的羽翼庇护组织下的弱者，但她常做事不留名，又因为不善言辞、暴烈的性格和凶猛的战斗表现被组织成员惧怕。布克丝教授却在与她有一面之缘之后，发觉这位好战的少女不为人所察觉的一面…...",
		level_1 = 0,
		level_5 = 0,
		file_2 = "追求强横的力量是瑟坦达的执念，但无论是白天还是黑夜，总是能够看到她在演练场练习的身影，这也让她在战斗上鲜遇敌手。但是其实瑟坦达原本的战斗天赋并不优秀，在曾经的巴哈姆特街区，师父刚开始教授她战斗知识时，瑟坦达的战斗表现十分让人头痛。那时的她并不具备现在所拥有的的强大力量，这也导致了她在人工智能军团袭击之时只能眼睁睁看着师父离自己而去。\n天赋低下制约了瑟坦达的武学进步，直到她选择加入巴别并接受巴别的基因改造实验彻底扭转了这一现状。\n当时巴别的基因改造实验项目由甲布尼撒诸王宴核心成员——博士艾尤一手主导，艾尤发明制造的“狂战因子”芯片能够在战斗时极大提高被移植者能够爆发的力量，但与此同时具有严重的副作用——被移植者战斗时思维狂化，理智丧失。但当时一心追求力量的瑟坦达并不关心这一副作用，毫不犹豫选择接受了移植。\n或许现在瑟坦达暴烈的性格多多少少受到了“狂战因子”芯片的影响。",
		file_3 = "在妮妮珐加入学院后不久也来到魂器学院报道，虽然没有对外明说加入魂器学院的原因，但是众人发现她对妮妮珐的额外关注，纷纷猜测她加入学院的原因大概与妮妮珐有关？毕竟性格暴烈的瑟坦达在面对妮妮珐时却表现得稳重又平静。\n急躁的夏洛特曾经耐不住好奇心前去询问，却迎来了一场实实在在的决斗，也因这一战在学院内打响了瑟坦达好战的名声。再配上她战斗时狠厉的表情，看上去颇难相处，让许多战斗系学员避之不及。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "身在其位，便尽其事。对于瑟坦达来说，就算自己百般不情愿，依然也需担负起身为首领的职责——庇护组织下的每一个成员。不善言辞的少女意外地选择压制自己急躁的性子，磕磕绊绊地熟悉与人交往，学习如何统领下属的工作，一切本都向好的方向发展.......\n直到巴哈姆特一场让人始料未及的叛乱，叛乱首领的挑衅激起了瑟坦达的狂躁，战斗时“狂战因子”芯片扰乱了她的理智，当她拔出长枪单独与敌人在前方作战时，后方本该在她羽翼下庇护着的成员们却被她抛在脑后.......\n妮妮珐的哥哥便是在此次叛乱中不幸丧生。",
		level_6 = 0,
		record = "明明十分关心妮妮珐，但却矛盾地不敢上前与她沟通，十分不符合她果断直接的个性。布克丝教授对此挑眉一笑，感叹了一句“大概是出于内心的自责“，随后这句话随着夜色飘散在风里。"
	},
	[203820] = {
		soulid = 203820,
		valuation = "该说是不愧是托拉的领导者吗，各项表现都是出乎寻常的优秀，小小的身体，拥有大大的能量。",
		file_1 = "在十年前摩洛娜第一次见到洛可可的时候，洛可可就是一副稚气未脱的孩童模样，但是十年过去之后，洛可可没有丝毫变化。\n对此芸表示自己也曾经惊讶过，不过后来就逐渐司空见惯，毕竟这个不老不死据她自己说快两百岁，并且沉迷于研究神秘学的【女孩】身上可是长着狐耳九尾，她说不定是传说中的魔法少女？\n   胆子最大的要数黑木幸，尚武的日式教育让她对于这个看上去弱不禁风的【长辈】的实力表示怀疑，但很快她就因为轻视洛可可付出了代价——洛可可仅用一击便打败了黑木幸的偷袭，并让她在床上躺了两个月。",
		level_3 = 0,
		level_4 = 0,
		resume = "洛可可是守护文明——托拉的元老级创始人，是在科技侧极度发达的时传统文化的守墓人，是致力于研究神秘侧理论反抗未来科技的逆行者，是不老不灭的异种人类。\n除此之外的洛可可，更像是一个已经历经风雨沉淀下来的【长辈】，很奇怪是吧？明明外表只是一个孩子，但是洛可可实际上已经渡过了近两百个春秋，从蒸汽时代到人工智能时代，她在追求维护神秘研究神秘的领域内孤独前行——直至与托拉的成员们相遇。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "洛可可身为守护文明的创立者，一开始的目的仅仅是为了反抗科技的不断攀升，后来在对神秘学的研究中，逐渐迷上了这种传统文化。她尝试研究炼金术，卢恩魔术，甚至古东方的图腾传说。\n为了获取这些传统文化典籍的最真实资料，她用那娇小的身躯踏过无数山川大地，从一处处遗址中窥见人类文明的一角，从羽毛笔录到计算机记录，从未选择放弃。\n当然，她什么也没研究出来，但是她在漫长的岁月中将这些本该被历史冲刷殆尽的人类文明典籍系统地整理而出，又在人工智能战争中抢救传统文明建筑，保护了无数的传统文化遗产。",
		file_3 = "洛可可不仅外表变异成了九尾狐，生理和性格也与狐狸颇为相似。洛可可的体温常年在38.8～39.6 ℃ ，每年都会换毛一次，每到2～5月得时候，洛可可都会发热神志不清，这个时候她通常会选择把自己藏在屋里休息哪儿也不去（当然如果安娜来找她探讨维多利亚时代的服饰穿着，她也不是不会接待）。\n如果你询问和她接触过得托拉组织成员的话，无一例外会得到的信息是——洛可可脾气很大。这一点既是因为她本出身贵族拥有贵族的骄傲，另一方面也是受到变异的影响。当然，也不全是坏的，洛可可虽然随了狐狸脾性的护短，记仇，脾气大，但是也拥有了很多美好的品质，谨慎，机敏，专情。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "过于漫长的人生时光给予洛可可过多的磨练，也让她不再像年少时那般草率任性，因为长生不灭的身体，她的内心和外表拥有强烈的反差。\n刚来魂器学院的时候，她就迫不及待奔向了玉子烧和月饼，想尽办法用她们身上尽可能的获取来自神秘侧的信息。但是她可爱娇弱的外表被一些学员认为是胡闹，甚至一些喜爱毛绒绒的学员疯狂开始撸她的尾巴，就算她大发脾气学员们也只以为是小女孩在撒娇，直到布克丝院长的赶来才终止了这场闹剧。对此，她也只能长叹一声，生一会闷气后继续去做研究。\n她见证了人类世界两个世纪的文明变迁，看着传统文化逐渐凋零，所有人和事物都逐渐从她身边离去，唯有她永远停留在原地。",
		level_6 = 0,
		record = "布克丝在对她进项身体检查后，确定她身体的变异来源于辐射变异，已经全无变回的可能，但是出于不想打破洛可可的希望，院长并没有告知。"
	},
	[29820] = {
		soulid = 29820,
		valuation = "萨洛弥的身体柔韧性在学员中是数一数二的。得益于此，她能使用出不少灵活的战斗技巧。加之性格的捉摸不定，和神秘性，她能够驾驭不同属性的魂智能武器，甚至能跨属性操作，实属难得。",
		file_1 = "【晓月轮舞】是一件特殊的魂智能武器，它并不是简单的双持系魂智能武器。在与属性共鸣上，出现了难得的复数形式。迄今为止，还没有学员在适格测试与共鸣的时候，与多重属性表现出高同步率。也许这与萨洛弥的体质有很大的关系。\n于是，院长决定将原本试作的单把魂智能武器以同等规模再制作一把。虽然，形质一致。但是蕴藏的属性完全不同。\n在惊异萨洛弥娇小的身躯是如何挥动两把中型剑式魂智能武器之前，旁人就完全被她挥舞起剑的样子所吸引。魅惑而又妖异，就像是引诱人忍不住堕落的轻柔耳语。\n借助长期习舞的身体柔韧性，剑招的环式攻击、近身格挡都十分流畅。甚至，剑锋的延展范围都比肉眼所见更长一些。\n用“剑舞”来形容萨洛弥的战斗，似乎还不够准确。因为，除了物理层面的杀伤力之外，萨洛弥在精神上也有着不可小觑的威力。",
		level_3 = 0,
		level_4 = 0,
		resume = "萨洛弥来到魂器学院，像是一个意外。因为许多学员第一眼都觉得她的气质和学院的气质，完全不相符。除了校园恋爱那一方面。\n据招生办的负责老师透露，萨洛弥完全是自己申请入学的。没有父母代替申请、没有相关背景申请，甚至也没有学院内推荐人推荐。她本人所说，只是出于好奇，就想来看看。毕竟，在院校里碰到命中注定的人，机遇会大很多。比起在街头茫无目的地游走来说。但是，作为一个普通女性来说，在AI叛乱的世代里，只身一人在世界游走非常可疑。没有什么伴身技艺的话，绝不可能全身而退。\n而萨洛弥本人又呈现出一种令人无可奈何的“油滑”，认真询问的时候，她总能将话题引到恋爱、异性和情欲之上。\n我们也不知道她执着的背后，到底是为了什么。难道真的是，生物的情欲本能吗？",
		level_1 = 0,
		level_5 = 0,
		file_2 = "“你知道吗，在旧时代，有这样一种植物，它们并不是通过光合作用来获取养分，而是通过捕食昆虫来维持生命呢。”\n也许用这样的比喻来类比萨洛弥，似乎没有什么不对。因为萨洛弥走到的地方，你一定会闻到不一样的香气，甚至，远远望去还常有一群人驻足。气味，容易被感知，也容易被忽视。但是，萨洛弥对于气味，有着自己独特的追求，她认为除了初见外在体验之外，气味也能够帮助记忆凝结。\n所以，在寻找命中之人的途中她也花大价钱去购买不同品牌、不同成分的芳香制品。除了香水之外，香氛和熏香，也是萨洛弥的目标。舞蹈和香水，从什么时候开始，成为了萨洛弥认为吸引别人的“利器”。萨洛弥自己也不清楚，或许只有这些身外之物，才能暂时填满她失去真心的空虚。\n但是，依靠这些，所找寻到的人，真的就是命中注定吗？萨洛弥在某个夜晚，某个披纱起舞的夜晚，也想过这些。",
		file_3 = "萨洛弥自小，就是周围人之中最为漂亮出众的。加上优渥的家庭环境，让萨洛弥就享受到众星拱月的待遇。自然对一般的异性提不起兴趣。\n因为萨洛弥由母亲单方面抚养长大，萨洛弥在对异性的认知上产生了与常人认知上巨大的偏差。这种偏差仿佛像是来自“母亲的诅咒”，一直影响着她。这样的偏差让她无法在一个异性身上集中精力非常长的时间，很快就会产生厌倦感和躲避感。甚至只要是产生了一种恋爱感，就想把对方的生命全部占有。\n一边渴望亲密关系，一边又抵触亲密关系。在若即若离的关系之中，又渴求对方的完全忠贞和服从……我们有理由怀疑，萨洛弥会在某一程度上走向极端。也许是因为成长历程中，母亲的地位占据了上风，从而影响到婚恋观的形成。而在进行初步的心理干预治疗时，我们发现萨洛弥似乎有意地或者下意识封闭起了一些记忆。\n深究萨洛弥的人生历程，据本人口述的时间和经历，总有不同时间点询问一问题却得到矛盾或不同的回答。也许，这才是真正的“诅咒”。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "该记录为权限内容，部分内容由萨洛弥的血亲学员塔薇尔蕾特提供。\n萨洛弥所选择封闭的记忆是和她性格形成与人生观念形成密切相关。她选择了关键事件之后的记忆为主，掩盖了之前不愿接受的记忆。所以，她的记忆里只有“母亲”。\n萨洛弥之所以能够罕见的使用双属性魂智能武器，并与之共鸣，是因为她能够在无意识中通过基因序列调动与姐姐相应的部分，来达到共鸣。\n而现如今，萨洛弥的记忆里并没有兄弟姐妹的概念，一直觉得自己是仅由母亲独自抚养长大的。父位的缺失，形成性格偏执。\n其实，在萨洛弥小时候，仗着父亲的宠爱，向他要求了长大之后能和“哥哥”结婚。“哥哥”是她命中注定之人，除了他之外，其他人她都不愿意。如果父亲不应允，她就甘愿没有自己存在过。父亲对萨洛弥的宠溺，已经到了难用常人思维考量。在萨洛弥小小年纪，他就把她“哥哥”的项上人头，作为礼物送给挚爱他的萨洛弥……\n虽然受到惊吓的萨洛弥之后进行了脑叶手术，但是这个经历仍像梦魇一样缠绕着她。由于记忆的修改，也激发了萨洛弥的偏执。她迷恋于异性的头颅，因为她认为爱人的头颅是爱恋的极致，是这段关系最美的礼物。同样，当她认定了对方背叛，出于嫉妒，她也会毫不留情地斩下对方的头颅。",
		level_6 = 0,
		record = "如此热情地看着一个人，是相当危险的。"
	},
	[200820] = {
		soulid = 200820,
		valuation = "学院对学员的战斗水平考核，才用的是现行的规范。只是在魂智能武器的操作使用上，增加了特别考量。所以，蕾塔在同等水平战斗测试上完全是优异的，甚至超越常人。如果，以更高的军方标准衡量，说不定评级会更加高。",
		file_1 = "【幻想重奏】是学院里另一把特殊的双属性魂智能武器，而它的得名也是基于多重属性和强劲的进攻能力。魂智能武器的制作流程是学员先经行适格测试，得到魂智能网络的共鸣之后，学员可以依照自己的习惯和需求同院长协调来制作武器样式。\n作为军火商的长女，我们原以为蕾塔会选择以枪械、火炮之类的热兵器为制作原型。但是出乎意料地，她选择了冷兵器板斧为制作原型。\n平时，【幻想重奏】以板斧的形象做单手持握，以斧器劈、砍、剁、抹、砸、搂、截等技巧。虽然看上去简单的作战技，但是双属性合二为一的伤害还是非常可观。当【幻想重奏】分开单手双持的时候，双斧飞舞的旋风能够直接击破对方的防御和阵势。据说，在改制的时候，单片飞投以及回旋也是有在计划中的。",
		level_3 = 0,
		level_4 = 0,
		resume = "在黑色圣诞节事件爆发之后，学院跃然成为了世界的中坚力量之一。所以，为了应对世界新的势力格局，希律·安提帕斯决定将 长女蕾塔送入学院进修。\n此举虽然看上去是为了女儿的学识和能力，但是，其实蕾塔是希律为了监视新势力走向的一双眼睛。也是因为蕾塔来到了学院，学院对于新发现的“能够使用双属性魂智能武器以及和同时与不同元素共鸣”的研究，有了更多样本。\n蕾塔进入学院之后，对我们原以为她会感兴趣的经济学、数学等方面内容都兴趣平平，反而对艺术学门类充满了兴趣。\n除了学院里的学业之外，蕾塔还时常会离开学院回到耶梦加得处理一下家族事务。这个在学院里还是些特例。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "蕾塔虽然是家里的长女，但是希律一直都对她非常地严厉。从很小的时候开始，就以严苛的枪械、作战训练来要求蕾塔。并有意无意地以继承人的方式来培养她。由于军火买卖活动，从来都不是一项安全稳定的事业。希律长时间都穿梭在不同的国际城市之间，很少在家中露面。\n但是，因为主人下的死命令，训练蕾塔的教官们都没有以千金小姐的身份来对待她。父亲的缺位和严酷的训练，年幼的蕾塔的内心已经有些不同的变化苗头。而也是因为母亲的早逝，父亲的缺位，蕾塔的人格塑造期间难免碰壁或者超出常人。为了够着上一辈的嘉奖或认可，唯一存留的父亲位就在她的人生中占据了巨大的位置。\n为了获得父亲的认可和赞赏，蕾塔会为之投入极大的精力和异常的努力。甚至，如果是父亲想要牺牲她的生命，蕾塔也有可能二话不说地执行。",
		file_3 = "安提帕斯家族，耶梦加得古老的家族之一。尚武的传统，在旧时代使他们家族曾经稳坐过王侯之位。随着时代的变迁，旧制崩解，安提帕斯家族也成为有名望的旧势力成员之一。\n原来的好战、尚武，在新时代里是完全受制于新的国际体制以及人道主义精神。得益于旧时代的财富、军备以及人脉积累，安提帕斯家族很快适应了新时代的“战争”模式。商业、科技竞争，成为扼住新时代进程的技术手段。转型成为军火贸易的安提帕斯家族，很快在明处获得了耶梦加得军方的支持，也在暗处得到了巨大的潜在市场。\n随着X-Mas的爆发，安提帕斯家族虽然损失了巨大的自动化、智能化军备储藏。但是，传统的非智能热兵器的巨大储备，瞬间让安提帕斯坐拥了一座“金山”。拥有自己的制造工厂和广博的人脉，安提帕斯家族已经成为了军火市场上的领头。这也引起了基金会和军方的忌惮，有小道消息透露，军方和基金会甚至会联手阻拦一下安提帕斯。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在家族新一代里，蕾塔虽然是长女，但是在她之前，希律已经有了很多子嗣。而这些子嗣都是女孩。为了追求家族继承，这些子嗣都被老一辈的大家长以不为人知的方式“神秘失踪”了。多年后，蕾塔的出生，并没有缓解家族的焦虑。就在希律准备执行家族的密令之际，蕾塔的母亲甘愿用自己的生命交换蕾塔。当深爱的妻子离去之后，希律才下定决心斩断畸形的家族行径。\n家族传统并不是一下就能结束的。所以，蕾塔就被打扮成男孩的样子，作为家族继承人来培养，并在家族中被冠以常见的男孩名字——“约翰”。\n在启智以前，蕾塔也都一直以为自己是“男孩”而非女孩。发育之后，身体呈现出与认知之间产生的差异，也使得蕾塔一定程度上，存在着性别认知问题。她对父亲不仅充满了男性的仰慕，也掺杂着女性的依恋。\n因为心理补偿机制，当小女儿萨洛弥诞生的时候，希律把全身心的爱全都投射到了萨洛弥身上。将她奉为掌上明珠，只要是她想要的，就算是宇宙里的星屑，都满足她。更别说，希律最爱小萨洛弥在他面前跳的舞。而小女儿在启智之前，除了母亲之外，最喜欢的就是她的哥哥。她向父亲许愿，以后她要成为“约翰”的新娘，除了他之外，其他的异性都不考虑。否则，她甘愿生命到此为止，不再长大。\n希律必须为他的溺爱以及家族顽瘤付出代价。他决定“杀死”约翰，结束这些荒诞的闹剧。他将约翰“死后”的头颅，送给了小萨洛弥。当然，小小年纪的萨洛弥无法接受这个事实，却也激发了另一面的萨洛弥性格形成。\n有的人对钱嗤之以鼻，但是，的确，钱能做到很多。希律在萨洛弥受到刺激后，给她安排了脑叶手术，让她完全遗忘了这段往事。她只记得，她在寻找着命中之人，那个在她梦里只有模糊形象的意中人。\n“约翰”在安提帕斯家族消失之后，希律终于专心培养蕾塔作为家族后继者。他明着暗着都对蕾塔投入了非同以往的精力和关注。而这样的关注，也让蕾塔很快摆脱了性别转换的焦虑，转而投入塑造“父亲期望的“身份之中。蕾塔也成为了蕾塔，成为了继承家族的长女。而约翰，彻底从安提帕斯家族的生命里消失了。但，她都还一直记得，为了父亲，她愿意杀死那个以前的自己。\n传说，河马是温驯的动物，也是会为了家庭而疯狂的动物。也许【幻想重奏】能够共鸣不同的属性，不仅仅是蕾塔本身体质的特殊，也是因为曾经的她所拥有的。",
		level_6 = 0,
		record = "在一次交流会之后，蕾塔突然对派森古语的“始作俑者”有了浓厚的兴趣。"
	},
	[204020] = {
		soulid = 204020,
		valuation = "比起啸，蛟更像是智谋担当。即使是在魂武的加持下，身体也过于孱弱了……娴静时如娇花照水，行动处似弱柳扶风，大概说的就是蛟罢……",
		file_1 = "蛟长着一张一团孩子气的娃娃脸，虽然看上去身材娇小年幼，但实际上物理意义上的身体年龄要比啸还要大。啸可以说是她看着从阁主手下培育而出，当啸从营养舱内诞生之刻，蛟冥冥中感受到自己在这世间多了一份羁绊。\n尽管蛟已经十分长袖善舞，但啸的孤僻还是让她难以带她融入基金会的其他成员。不过既然啸性格难改又如此依恋自己，就这样只有阁主与她陪伴也不错。\n与啸搭档对蛟来说完全是——没有任何需要自己动手的！啸的行动能力实在是强到事事为她安排好的地步。不过好歹让蛟有些安慰的是，啸在战术方面……完全是个莽夫，而自己聪慧的大脑和智谋能为在后方为她出谋划策，可不是别人口中“美丽的废物”。",
		level_3 = 0,
		level_4 = 0,
		resume = "蛟来自世界经济流通的背后操作组织——基金会莱希。身为莱希高层——“阁主”的嫡系下属护卫，又深受其偏爱，蛟在基金会几乎没有任何约束，只需在阁主和搭档啸的保护下做自己想做的事即可。\n可能是因为克隆体催熟的原因，也可能因为被克隆原体携带基因问题，蛟几乎先天性失明，身体也十分孱弱。不过幸运的是，魂武【蛟若云兮】的巨蛇可以代替她的双眼为她传递外界景象直达大脑视觉神经。\n蛟的生活充满恬淡平静与诗情画意，就连在基金会居住的地方也是阁主悉心建造的亭台楼阁，煮茶插花琴棋书画无一不通。与啸的孤僻少言不同，蛟见人面带三分笑意，说话轻声细语，如水一般温婉多情，十分受基金会内成员的欢迎。\n然而外表如此惹人怜爱的蛟，实际上真的如同表面如此吗？切尔茜为什么突然兴起去吃啸的劲爆魔鬼小辣椒，这可不是平白无故……",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【蛟若云兮】对于蛟来说，更多是充当着眼睛和保护的作用。为了达到通过巨蛇的眼睛为她传递外界景象直达大脑视觉神经这一项功能，阁主几乎是倾其所能。\n蛟模模糊糊记得，那时“魂智能网络技术”还并不完善，魂智能武器的制作更是处于初级阶段十分困难。阁主不知与布克丝承诺了什么取得了她帮助制作魂武的承诺，以至于布克丝看着阁主的眼神向在看一个亡命徒。\n蛟明白，阁主为了保护自己和啸，为了给她们二人更好的未来已经竭尽所能，也许是为了弥补自己曾经对被克隆体做过错事的愧疚，也许是处于亲手培育她们而来的亲情。",
		file_3 = "与啸大为不同的是，蛟十分喜爱阁主教她的昆曲，闲时最大的爱好就是濛濛细雨天在楼台间唱上一曲。甚至说话间都是淡淡的戏腔，一举一动文雅有礼。\n在基金会的日子十分……咸鱼，每日除了舞文弄墨听曲唱戏间或为啸出出战术主意外几乎毫无工作。就诗歌而言，比起唐诗，蛟更爱宋词。有时她无聊是会一边散步一边尝试自己作上几曲，她爱那种清柔婉约的闲适，爱那种脉脉含情的矜持，爱那种悠然自得的恬淡。\n在蛟的世界里，这个世界是十分广大的，人生百态是有笑有泪的，她一直渴望离开阁主与啸的羽翼到外界体会多姿多彩的生活。但她自己也十分清楚，一方面自己的身体并不能支持，另一方面阁主与啸不可能赞同自己的想法。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "蛟有时在散步时，与人谈笑间，在台上唱着戏看着台下的阁主时，眼前会飞过光怪陆离的，不属于自己的记忆片段。\n“石皎皎”、“谢攻玉”、“谢筱筱”，这些熟悉又陌生的名字伴随着垂髫时的欢声笑语、摔落的茶盏、离别的飞雪划过自己的眼前。聪慧的蛟感知到，那是自己和啸的被克隆体与阁主的过去，那些过去大概让阁主痛彻心扉罢……\n在对于能够前往魂器学院这件事上，蛟十分期待，一直以来生活在保护罩中的蛟十分向往外界的生活。事实证明，来到魂器学院后的生活确实很让蛟满意。她经常兴起时与李较量一番舞剑的身姿，与芙蕾一起吟花弄月，谈笑间时不时给自己的对头切尔茜挖些坑。\n除了再也没见到阁主外，实在是没有比这更美好的生活了！",
		level_6 = 0,
		record = "对于蛟来说，阁主就犹如长辈一般，倾尽全力照顾自己和啸。在自己和啸蒸蒸日上的生活背后，是阁主每况愈下的身体。"
	},
	[204220] = {
		soulid = 204220,
		valuation = "这大概就是天生优秀的人吧，各项指标都达到了万中无一，通常我们用一个词来形容这种人，那大概就是“龙傲天”？",
		file_1 = "啸的物理意义上身体年龄是15岁，但实际人生中真正经历的时间只有两年，从克隆体培养皿产出的那一刻才是她真正的诞生之刻。\n虽然生长在基金会，但啸生长在阁主的羽翼之下，并未得到基金会成员太多关怀，天生心防颇深的啸对基金会并没有什么归属感。因为天生战斗能力的强悍，她即使是在多方势力的重重眼线下为基金会传递消息依然来去自如。\n由于是阁主亲手培育，又拥有高战力，比起其他下属，啸十分受其重视。但啸并不沾沾自喜，因为她能够感觉到阁主这一份特殊并不是对她本身，一方面是因为她能够更好保护蛟，另一方面是因为自己身上的那一抹旧影。",
		level_3 = 0,
		level_4 = 0,
		resume = "啸来自世界经济流通的背后操作组织——基金会莱希。身为莱希高层——“阁主”的嫡系下属护卫，啸无需受基金会其他领导层的管束，只需忠于阁主即可。\n作为阁主一手培育催熟的克隆体，啸的发育除味觉与嗅觉消失外，其他部分的身体机能都十分强悍。她怀疑可能是她自己这幅身体的克隆原身基因就十分强悍的缘故。\n啸是个标准的闷葫芦打手，她把自己的世界圈定在只有蛟和阁主连同他自己的三人世界里，在她眼里，她们三人就是彼此依靠的家人。\n阁主从啸幼时就教导她学习京剧，有时候她也会一边看着她一边唱上一两句。关怀的目光好像是在透过她看着曾经的旧人，啸极其厌恶这种感觉，如同厌恶阁主逼着她学习虽然喜欢但并不想学的京剧一般。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "因为自诞生以来就在阁主的保护之下，啸的生活几乎没有受到人工智能战争的太多影响。况且以她傲然的战斗力，除模拟智能系统以外的人工智能对上她实在没有什么胜算。\n在基金会中与蛟互相搭档的日子平淡又安心，可能是克隆原体的残留意念，啸对蛟有一种天然的保护欲和亲近欲。对她来说，蛟实在是柔弱不能自理，所以无论是在日常相处还是执行任务时，啸更倾向于将危险困难的事情留给自己。至于文弱温雅的蛟，啸觉得她乖乖做个花瓶美人就好了。\n啸对阁主十分敬重，对她来说，阁主亦师亦母。她并不喜欢学习京剧，但她还是愿意为了阁主开心而学习，为了听阁主在戏台上看着她陷入回忆时低叹的那句“别怕，姐姐在。”。",
		file_3 = "啸的欲望很少，没有特别厌恶的事物也没特别想要的追求，她一贯信奉简单的生活，对她来说人生中只要有蛟和阁主就足够了。对于任何有可能破坏她们三人安稳生活的不稳定因子，啸都会毫不犹豫地抹除。\n啸不爱说话，面目表情很少，情绪没有太大波动，就算是到魂器学院后与麟格斗都面不改色。大多数人对啸的评价都是感觉她情感淡漠，像一潭不会波动的湖水。实际上啸的情感十分沉重与炙热，只是习惯了沉默与隐忍的她，选择将这份感情封存在自己的心底。\n在她的理念中，只要能一直将三人这互相陪伴的生活延续下去，无论她付出什么样的代价都可以；只要能够让蛟和阁主开心，无论是让她背负最苦最难的任务还是去学习她不想学的京剧，她都甘之如饴。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在午夜梦回时，啸时常回忆起一些十分破碎的片段，那些片段中有年轻时的阁主，有不一样的“蛟”，还有无力的自己。故事的结局大概是十分悲伤的，不然自己为何每次都泪流满面的醒来呢？\n啸敏感的感觉到，这大概是“另一个自己”，或者说是那具被克隆的原身携带的记忆，那或许是阁主，“蛟”与“自己”的过去。\n前往魂器学院并非啸所愿，她并不希望平静的生活被魂器学院这个不稳定因子打破。因此她第一次违抗了阁主的命令，但阁主却十分严厉地训斥了她：“我能为你们做的不多了，这是为你们好！”然后甚至急火攻心而晕倒。\n啸不得不忍耐下内心隐隐的不安，听从命令先一步前往魂器学院打探情况，毕竟柔弱的蛟需要她提前做好安排才行。",
		level_6 = 0,
		record = "啸有时候从梦中醒来，觉得阁主很可怜，有时候又觉得她可恨，但是她也不明白为什么自己会这么认为。"
	},
	[204320] = {
		soulid = 204320,
		valuation = "幼小的身躯格外灵巧，肉眼可见长大后是个担任机动性工作的好手。攻击能力并不强，但毕竟是个孩子，也不能要求甚多……",
		file_1 = "诺比的家庭自上世纪起就在北极地区经营着矿产开发，是当地有名的富户。\n因为家庭观念开放，在诺比的教育问题上，诺比的父母和姐姐们更多采取“鼓励教育”的态度，鼓励诺比去尝试新事物，去接触新世界，这让诺比养成了勇于探索未知的性格。\n诺比能够养成现在这样赤诚待人的性格和她的家庭环境脱不了关系。她的父母从未对自己的小女儿有过多的要求，只希望她一生平安喜乐万事如意就很好。",
		level_3 = 0,
		level_4 = 0,
		resume = "诺比·奥罗拉的家乡在遥远的北冰洋沿岸，在那个冰天雪地的世界，极夜时常常可以看到波澜壮阔的极光与星空。\n诺比家境优越生活富足，是父母最宠爱的小女儿，更别说她还有五个宠妹妹的姐姐，可以说是在爱的浇灌下健康茁壮成长的小树苗。\n虽然生长在大海边缘，但诺比对天空与星辰充满好奇与向往。在第一次仰望星空后诺比就被星辰的美丽震撼，星座与银河，神秘与未知，这些隐藏在宇宙中的奥秘瞬间点燃了诺比充满探索欲的心灵。从那一刻起，小小的诺比给自己漫长的余生定下了一个大大的目标——触摸天空，征服星辰大海！\n在这个战乱年代，拥有纯真与赤诚并能健康长大的孩子如凤毛麟角，而诺比幸运的成为了其中的一个。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "诺比从小就表现出超于同龄人的懂事。虽然家中很有钱，但诺比花钱并不大手大脚，也并不理所当然地觉得家中的钱就该给自己用来实现航天梦。反而觉得自己的梦想应该只靠自己去实现。\n诺比喜欢将自己的压岁钱存起来有规划的使用——大部分花在天文望远镜的保养上了。她还很喜欢收藏一些关于宇宙星空的文化产品：漫画、小说和纪录片，在晚上藏在被窝里反复观看，可能就是因为这个原因，诺比才有点近视小小年纪就戴上了眼镜吧。",
		file_3 = "“我要成为宇航员！”——这是诺比每一次观星后都会冲着广阔星空大喊一声的台词。虽然自家姐姐大多认为自己成为宇航员畅游太空的梦想根本不可能实现，但是诺比却丝毫没有受到打击，反而愈发坚信自己终有一天能实现这个伟大梦想！\n诺比的姐姐们没想到的是，如今距离诺比树立成为宇航员的梦想已经过去三年了，这个梦想不仅没被诺比忘记，她还有模有样做出实现梦想的计划，并一步步为了梦想而前进。\n诺比是个探索欲望非常强烈的孩子，对她来说，星空充满了神秘和未知的色彩，实在是充满了吸引力，这让她愿意倾其所有精力去追寻。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "来到魂器学院后，布克丝十分鼓励诺比追求“星空梦”，特意为诺比的左眼移植了“聚焦芯片”，一只眼睛便是一架微型天文望远镜。\n凭借着外形软萌可爱，与人交往赤诚活泼，诺比很快得到学员们的喜爱。更让人意外的是，一向沉默寡言的电波少女露缇竟意外的与诺比聊得过来（虽然二人聊天从来不在一个频道），两人聊天的画面虽然滑稽可笑，但却十分和谐，院长便顺水推舟将二人安排在一块。",
		level_6 = 0,
		record = "诺比对星空的爱已经到了狂热的地步，身边的生活用品几乎都是星空主题。"
	},
	[201420] = {
		soulid = 201420,
		valuation = "近战火拼的最佳人选，剑技精巧，剑风变化多端，出招时下盘沉稳有力，不骄不躁，看得出是日日勤奋练习下的产物。",
		file_1 = "洛加尔境内充满着浪漫与绮丽的樱花郡，是藤原蝶内心深处十分珍视的故乡。在这里有她相交多年的挚友，也有她那虽没落但仍然坚持武士道的大家庭，还有永远支持她在剑道一途上前进的家人。这个地方藏着藤原蝶内心最温柔的眷恋。\n藤原蝶名如其人，当她穿着裙子挥舞着利刃穿梭在战斗场中时，犹如在山野间花丛中翩翩飞舞的蝴蝶。十年如一日刻苦的剑术练习，让藤原蝶的身形挺拔有力，轻盈灵巧，同时也磨练出她坚忍不拔的心性。\n尽管藤原蝶所在的武士家族已经逐渐没落，但武士精神还是很好地在藤原蝶的身上得到传承——“绝对的忠诚”、“绝对的坚韧”，这是藤原蝶永远不会遗忘的“本心”。",
		level_3 = 0,
		level_4 = 0,
		resume = "藤原蝶来自充满着樱花，清茶与武士道的洛加尔樱花郡，身为月和会的成员，出身于没落传统武士家族的藤原蝶从小便作为芙蕾殿下的伴读长大，与芙蕾朝夕相伴，抵足而眠。\n在年幼时与剑术因梦结缘后，藤原蝶便深深迷恋上了剑术与剑道，无论是居合斩、拔刀斩，只要是有益于精进剑术的练习，她都不畏艰苦，勤奋练习。但是天不如人意的是，藤原蝶的悟性一般（甚至可以说是很差），学习时需要花费他人十倍的刻苦努力，这让藤原蝶在剑道一途上的进步十分缓慢。\n来到魂器学院加入“双项计划”不是藤原蝶的本意，一开始的藤原蝶只是追随芙蕾殿下来到魂器学院与芙蕾相伴，并不想参与学院事务，但意外的是，一次与布克丝的偶遇让其注意到藤原蝶这个“双项计划”的优质人选……",
		level_1 = 0,
		level_5 = 0,
		file_2 = "“双项计划”是布克丝针对保障班长人身安危制定的特殊计划。由于班长在战术指导魂姬上的作用十分重要，但其本人却无法连接魂武，武力值难以在混战和暗害中自保。因此在班长又躲掉一次暗害后，布克丝宣布将从学员中选拔出最适合的两名魂姬随身守护班长，该计划命名为“双项计划”。由于随身守护工作对魂姬的危机反应力、爆发攻击力等多项指标多有要求，因此想要找到符合标准的魂姬十分困难。\n但人生总有意外之喜，出关后匆匆赶来魂器学院与布克丝偶然相遇的藤原蝶恰巧完美符合以上要求（除了智商），布克丝短暂犹豫后当机立断决定将藤原蝶作为”双项计划“的其中一位人选。\n而侍女制服的穿着来自于霓昂的手艺，据霓昂所言，守护班长应需要一定的仪式感和制服配置来坚定魂姬的信念，而且“双项计划”的人选最好能够对外隐藏身份降低敌对势力的防备，因此霓昂决定将藤原蝶打造为班长的专属侍女，侍女装也因此成为藤原蝶的学员制服。",
		file_3 = "藤原蝶自幼时做芙蕾伴读起便清楚自己资质愚钝，比起芙蕾殿下差距很大：芙蕾只需看一眼就运用自如的格斗术，藤原蝶需要反复练习；芙蕾一子就能盘活的棋局，藤原蝶读遍棋书也想不出破解之法；芙蕾随手泡出的清茶，藤原蝶无论如何也泡不出那般清香怡人的味道。\n“笨蛋美人”是藤原蝶时常听到的他人对自己的称号。也许是上帝给人关了一扇门便会打开一扇窗，尽管藤原蝶是个笨蛋，还有些洁癖、顽固、一根筋的小毛病，但她学习勤奋刻苦，做事严谨认真，待人真诚友善，俨然是最标准的“三好学生”。\n（某抠门精名言：虽然她笨，但我聪明就好了啊！)",
		level_7 = 0,
		level_2 = 0,
		file_4 = "班长曾经调侃过：”对藤原蝶来说，芙蕾是两小无猜的青梅竹马，而阿亚斯是从天而降的欢喜冤家。“\n藤原蝶一开始来到魂器学院本来是打算追随芙蕾殿下，但来到魂器学院被布克丝拉入“双项计划”后，与抠门精——阿亚斯的相遇完全打破了藤原蝶预先的规划。这个出身大贵族却异常抠门的奇怪女人，不仅风流纨绔狂傲自大，还脸皮奇厚自来熟得不行！左一句“小蝴蝶”右一句“蝶宝贝”，实在是让人不知道怎么应对！\n藤原蝶本来就是规矩守礼的女孩，十几年来亲近的芙蕾也是温柔知礼的文艺淑女，哪里禁得住阿亚斯这样混蛋的直球攻击。而且两人作为“双项计划”的启用人选，互为搭档整天抬头不见低头见，藤原蝶面对她的“胡言乱语”只得低骂她：“抠门纨绔！”",
		level_6 = 0,
		record = "“阿亚斯能不能闭嘴啊。”这是藤原蝶来到魂器学院后最常说的一句话。"
	},
	[201520] = {
		soulid = 201520,
		valuation = "学院有史以来最强的狙击手！弹无虚发枪枪致命，若是在战场上安排在远处狙击敌人，想必能够发挥意料之外的效果。",
		file_1 = "温莎皇室是尼德霍格最有历史底蕴的家族，子孙繁多且优秀，拥有数座庄园和城堡，但实际上温莎皇室历经近现代的战争和诸多改革，这个“皇”字已经名存实亡。\n在联邦军方成立前，国家尚未消失的时候，温莎皇室凭借皇室的历史威望担任各州各区的联系纽带；在黑色圣诞节爆发后，时任女皇凭借过硬的外交手段和积累下来的威望将尼德霍格各大势力松散的人心齐聚一起，共同抵御人工智能的侵犯，最终力挽狂澜。\n在最为富饶的尼德霍格，财阀林立，多方势力倾轧，世家大族彼此互不认同，但已无实权的温莎皇室仍作为精神纽带得到各大家族的尊敬。\n（比如刻罗心甘情愿做阿亚斯这个抠门纨绔的“移动的人型钱包”。）",
		level_3 = 0,
		level_4 = 0,
		resume = "阿亚斯是尼德霍格温莎皇室在逃王女，她纨绔风流，恃才傲物，曾与萨姬塔同属于游走在人类与人工智能边缘的猎兵。目前来到魂器学院后被布克丝拉入“双项计划”，用她自己的话说是掉进了狼窝。\n温莎皇室拥有丰厚的历史底蕴，在当地颇受财阀政要世家尊敬，但出身于这等家族的麻烦就是——繁杂冗余的贵族教学。出于少年时期的叛逆和对贵族规矩约束的厌恶，阿亚斯终于在16岁那年选择出逃，凭借一手冠绝天下的狙击术成为一名狙击猎兵在边境地带游荡。直到她闲暇无事追着萨姬塔来到魂器学院，对美丽的藤原蝶“一见钟情”。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "“双项计划”是布克丝针对保障班长人身安危制定的特殊计划。因为班长身份特殊，无论是人工智能还是各方势力，明里暗里想对班长不利的实在很多，为了保护班长的人身安全，布克丝决定启动“双项计划”——为班长选中两位随身守护的强大魂姬。\n阿亚斯的出色在一来到魂器学院后便被布克丝看中，轻轻松松便完成所有“双项计划”的考核测试，让布克丝更满意的是，阿亚斯的性格与另一位人选藤原蝶十分互补，简直是天生的最佳搭档。\n关于阿亚斯的执事装制服，原本霓昂想做与藤原蝶相同的侍女装，但却被阿亚斯强烈要求改为执事服，据阿亚斯原话所说“侍女和执事才般配嘛~”。",
		file_3 = "阿亚斯为人十分自负，然而她也确实有自负的资本——聪慧有才，出身显贵。无论是在才学还是武艺方面，还是人情达练，阿亚斯都十分优秀。只要是阿亚斯想做的事情，就没有不成功的，唯一的小小瑕疵，就是有个分外抠门的小毛病……但这些都无伤大雅！阿亚斯之所以当个风流纨绔，只是懒得去争权夺利罢了，恃才傲物说的就是她了。\n阿亚斯作为一个社交能力满分的风流纨绔，结识的朋友数不胜数，多年来的对头只有萨姬塔一个。在作为猎兵游历期间，阿亚斯自诩天纵奇才，算无遗策，却在一次与萨姬塔的对决中因为运气不好而失败，从此二人结下了梁子。然而二人虽在猎兵中是竞争对头，却又时常彼此较量身手，有一种淡淡的“英雄惺惺相惜之感”。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "加入魂器学院对于阿亚斯来说一开始只是个闲着没事时找到的消遣，然而真正进入后，阿亚斯发现自己确实是小瞧了这个汇集了各形各色人物的“奇葩聚集地”，不仅学员们各有所长性格各异十分有意思，就连一些新型的科技产物也是别处接触不到的奇妙玩意儿，让自诩见多识广的阿亚斯也稀罕了好一阵子。\n但即使魂器学院的生活十分新鲜有趣，但纨绔不着调的阿亚斯很快便对这样的生活失去了兴趣，正在她百无聊赖之时，她与“笨蛋美人”藤原蝶邂逅，那一刻，阿亚斯感觉到了心中有什么破土而出。对于阿亚斯来说，藤原蝶的一举一动都是那么美丽动人，在她眼中是如此与众不同。从此无拘无束的阿亚斯心中有了牵绊，可以说是——一见藤原蝶误终身（大概）。",
		level_6 = 0,
		record = "班长：阿亚斯的自信，比太平洋里的海水还要多。"
	},
	[204420] = {
		soulid = 204420,
		valuation = "不得不说，物理输出能力真的是非常残暴，明明长着一张文静秀气的脸，竟然是个暴力输出么……",
		file_1 = "佩尔从记事起就开始接触芭蕾，她本身天资出众，身体修长灵巧，在父母的精心教育下很快能够熟练演绎《林中仙女》、《堂吉诃德》、《胡桃夹子》等世界著名芭蕾舞曲，最喜欢的最也擅长的是纯美华丽的《天鹅湖》。\n在布满灯光的舞台上演绎舞曲时，佩尔徜徉在醉人的音乐中，想象自己变成了一只纯白忧郁的天鹅，旋转……旋转！抬腿，起舞！一舞结束，佩尔仿佛经历了舞曲中公主奥杰塔的故事——被人诅咒的痛苦，变成天鹅的哀伤，遇见王子的喜悦……心潮澎湃，久久不能平复。",
		level_3 = 0,
		level_4 = 0,
		resume = "佩尔·卡捷琳娜是来自北地的一名热爱芭蕾的女高中生。在地劫战争爆发前佩尔生活在父母与芭蕾舞团的保护中，那时的佩尔优雅青涩，人生轨迹是长大后继承父母的衣钵成为北地的芭蕾舞蹈大家，带领芭蕾舞团在世界各地巡演。\n可是地劫战争的爆发打破了一切，生活在温室里十指不沾阳春水的佩尔在战乱逃亡中逐渐成长，褪去了富贵娇小姐的青涩外衣。佩尔开始学会人情世故，明白在战乱中做一个只会芭蕾的娇弱少女是保护不了自己爱的人的，所以在得到魂器学院伸出的援助之手后坚定地站出来成为魂姬。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "地劫战争爆发前，佩尔处于少女心理最为敏感的时期。\n因为佩尔的舞蹈在上学时就已经很出名了，生活在校园中的她不可避免的会受到许多同学的评论。这些评价有的是中肯建议，大多数都是随意一言，但敏感的佩尔无比在意每一句有关于她的评价，并为此或欢喜或苦恼。\n在校园里生活时的佩尔一直被周围的同学称为“孤独的芭蕾女孩”。她时常独自一人在图书馆阅读舞蹈书籍，独自一人在夜晚的舞蹈室里翩翩起舞，独自一人前往餐厅，前往宿舍，独来独往，很少与人交流。",
		file_3 = "即使在逃亡过程中佩尔迅速成长了起来，但说到底，佩尔在来到魂器学院之初还只是个女高中生。出身于芭蕾世家的她优雅内敛，话少爱安静，不喜欢社交，不了解她的人会误以为她是一个高冷的女孩，其实佩尔只是不擅长表达自己而已。\n过分在意他人看法的性格使佩尔有时候活起来很累，总是因为别人的一句话而患得患失，但是她又过于内敛不想麻烦别人，这让她遇到问题通常选择自己闷着解决，导致她要多走很多弯路，真是让人头疼啊……",
		level_7 = 0,
		level_2 = 0,
		file_4 = "来到魂器学院成为魂姬后的佩尔要比从前放开很多，在霓昂、伊文捷琳和学员的开导下佩尔逐渐学会表达自己，与人交流也不是以前那样半天说不出一句话来了。\n但是佩尔还是非常容易社恐，特别是在与大胆开放的萨洛弥交流舞蹈技术时，每次都难以招架对方的热情，最后在萨洛弥的调笑下窘迫不堪。\n【天鹅之舞】是布克丝在观赏佩尔舞蹈后灵感爆发做出的魂武，它优雅纯洁犹如佩尔本人一样，并且与佩尔几乎完美适配。不过与它轻盈弱小的外观不同，佩尔在战场上使用它时可以称得上是“暴力输出”，她会一边害怕地说“抱歉”一边对敌人打出巨量伤害。",
		level_6 = 0,
		record = "佩尔在战乱逃亡中经常听到班长在世界各地救人类于水火中的英雄事迹，那时的她对班长就怀有了仰慕之心，渴望成为班长那样强大的人。"
	},
