	[21330] = {
		soulid = 21330,
		valuation = "这么冒失的女孩是怎么来到考试现场的？而且在实战测试的时候摔倒了三次，真是让人担心，不过她的枪械天赋真是和性格完全成反比，测试射击一共二十轮，期间替换枪械六种，从手枪到狙击枪，每轮都是满分，值得培养。 ",
		file_1 = "【定点移动】：将物体从固定坐标直线送到另一个固定坐标的能力，详细解释为：将接触到的物体通过各种方式发射出去，与视野范围内确定的预设点进行百分百重合的能力。是一项绝对能让能力者百发百中的作弊能力，历史上出现过该项能力的人记录在册的仅有三名，因为时间久远，许多数据都已经严重损失，故我们需要对千竹进行相应的能力测试。\n测试1 道具：年代久远的柯尔特响尾蛇左轮 内容：击中五百米外，放置在玻璃罐上的樱桃。 测试结果：命中 详细：樱桃正中央被击穿，玻璃罐完好无损。\n测试2 道具：鲁比克动力型脉冲枪 内容：遮挡住一只眼睛，在不瞄准的情况下要求击中一千米外的羽毛 测试结果：命中 详细：羽毛被烧焦，羽毛靠着的墙壁也被击穿。\n测试3 道具：一号3000型自动狙击枪 内容：关闭自动狙击模式，在遮盖双眼的前提下，击中五百米内的机器人 测试结果：未命中 详细：子弹击穿了练习场的天花板。\n根据以上的测试看来，初步可以认为，触发这项能力的条件是被视线锁定，只要搭配简单的侦查设备，千竹就是最强的狩猎者。",
		level_3 = 0,
		level_4 = 0,
		resume = "千竹，户籍派森，天真可爱，日常生活中十分冒失的九岁小女孩；喜欢帮助他人，但总会因为自己的冒失，导致自己非但没能帮上对方的忙，甚至还越帮越忙……   因为担心打击到千竹的积极性，所以一般大家都不会指明这一点，这反而使得她更加无法意识到自己的问题所在，所经之处都是一片狼藉。很容易就被原谅，也就意味着，很难得到夸奖……但愿有一天千竹可以获得他人的肯定吧。   除此之外，千竹热爱动物，虽然在这个时代有不少虚拟演算的动物，但千竹却更喜欢现实中存在的动物。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "千竹的熊猫名叫团子，从她的简述来看，团子是在一次拍卖会中，被自己解救下来的，那个时候的团子腿上还受了很严重的伤，为了让它痊愈，笨拙的千竹想了各种各样的办法，都没能成功，最后是千竹的父亲将团子的伤口治好，也许是被真诚打动，从那以后，团子便开始跟着千竹行动，千竹一直照顾着团子，一人一熊就这样一起生活到了今天。\n不过从学院内的观察来看似乎和千竹说的有所出入，团子在和千竹的行动中，十二次中有八次都是团子将她从危险的地方拉回来，另外四次则是团子抢先将危险因素排除；这个熊猫跟着千竹的理由绝对是因为放心不下吧……我们不禁这样认为。",
		file_3 = "千竹的父母都是普通人，父亲是一名兽医，母亲是普通的上班族，可以理解千竹对动物的喜欢，但【定点移动】这个能力的由来，我们却无法理解。因为千竹的家族中，并没有出现过特殊能力者的特例，整体基因趋势偏向缓和，要突变出某种能力的话，至少还要遗传八代以上才有一丝可能性。另外，派森整体并不在战争范围，辐射、空气和水质监测都是正常值，千竹一家也从未从派森往其他城市移动过。因环境造成的间接变异几乎是不可能的。\n结合【定点移动】这份能力的稀有性，我们开始怀疑，这项能力是可以继承，且有人故意把它赋予了千竹。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "结合多方影像资料和数据比对，我们得出了一个谁都无法接受的事实——千竹的能力是被团子赋予的。确实，特殊能力并不会只出现在人类身上，只不过由于动物的数量在当今社会上十分的稀少，所以有关特殊能力的动物就更加罕见了，不过正因为罕见，我们才能确定团子就是原先【定点移动】的持有者。\n根据影像资料显示，在派森的原自然公园保护区，曾出现过一只扔竹子百发百中的熊猫，后来因为盗猎者的出现，这只熊猫的消息暂时消失，大约过了一两个月，枪械天才少女的传闻才逐渐传开。\n另外用影像上熊猫身上的伤口，和团子进行比对的结果为：93.7%。\n已经基本可以确定千竹的能力和团子有着必然的关系。",
		level_6 = 0,
		record = "美少女与小可爱！"
	},
	[204720] = {
		soulid = 204720,
		valuation = "安装了腿部义肢后几乎不用担心被敌人击中的问题，身形灵巧，移动速度非常快，射击百发百中，毫无疑问是学院里的最强弓兵。",
		file_1 = "正射必中。\n虹的弓道天赋十分恐怖。在幼时虹就经常用自己制作的弹弓准确地击落天上的麻雀，使用石子儿准确击中树林中指定的一片树叶，但那时的她还没有意识到自己在弓术上的天赋。\n直到8岁时虹第一次接触到弓箭，她迅速爱上了弓道并充分发挥了自己的弓道天赋，在派森举办的许多弓箭比赛中取得第一名，等到她13岁的时候已经小有名气了。即便是来到人才济济的魂器学院后，她的弓术仍然傲视群雄。\n虹的弓术技能仿佛是与生俱来的，在她手下的弓箭矢无虚发。只要正射，则必然命中。",
		level_3 = 0,
		level_4 = 0,
		resume = "虹是来自派森的弓道天才，与莱拉同为“遗弃者”的一员。\n虽然是被遗弃的孤儿，但虹和莱拉都并没有养成阴郁自卑的性格，反而因为在派森自由的街道上彼此扶持着长大，她们都成为了善良乐观的孩子，向往自由洒脱的生活。\n与莱拉渴望成为骑士不同，虹一直向往着派森自古以来的武侠文化，渴望着成为一名在世界各处行侠仗义的侠客，拯救被邪恶势力压迫的苦难人民们，然后事了拂衣去，深藏功与名。\n但是想要成为一名侠客没有足够的力量是不行的，在这时，在发小莱拉口中时常出现的魂器学院进入了虹的视线。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "“遗弃者”的生活。\n派森街道上被遗弃的孩子们的生活并不和谐，争抢食物物资、彼此陷害和欺凌弱小的事情时有发生，有些孩子活了下去却变得面目全非，有些孩子在冬天的寒风中就此结束了在这个世界上的旅行。\n虹和莱拉毫无疑问是坚强的孩子，和莱拉在派森街道上相依相伴的日子是虹心中的一抹净土。身为被遗弃者，她们没有因为被抛弃而自卑厌世，而是选择靠自己积极努力的生活下去。\n虹和莱拉在失败时互相鼓励，在难过时互相安慰，彼此依靠取暖，逐渐由孩子成长为少女。也许虹性格中的善良乐观和理想主义正是在这种艰难却温暖的生活环境下逐渐养成的吧。",
		file_3 = "侠客行。\n成为一名保护弱小，击败邪恶的大侠，这个理想是从什么时候开始的呢？虹无数次面对朝阳扪心自问——也许是看到弱小的孩童被恶人欺负却无力抵抗时，也许是幼年的自己和莱拉被人抢走食物却无可奈何时，也许是看到“朱门酒肉臭，路有冻死骨”时。在那些时刻，成为一名治恶扬善的大侠这个理想就已经在她的心底埋下了种子，直到偶然间看到的武侠小说让它生根发芽。\n有很多人嘲笑过虹的理想，总觉得她是个老古板，这都什么时代了还想要成为一位侠客？笑话！但在虹看来，无论什么时代，侠客的精神永远存在，也永远需要有人去坚守道义。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "来到魂器学院后的故事。\n虹在拿到了布克丝为她量身定做的【百步穿杨】后就知道这次魂器学院之旅没有来错，不仅火力大，足够精巧，还完全适配她的身高力气。她明白，专属于自己的“绝世神兵”就是它了！\n不仅如此，布克丝还帮助了她进行了腿部外骨骼的二次改造，不仅减轻了重量，增加了火力驱动器，提高了机动性，还在外形上做出了与虹的完美适配。用虹的话说就是：让我的“轻功”能够更好得到施展了！（虽然布克丝很想告诉她这世上是没有轻功的）\n除此之外，她还结识了非常有侠士风范的麟，两人性情相近，可以说是相见恨晚啊。\n为了感谢魂器学院对自己的馈赠，虹决定成为魂器学院的“守护大侠”——就算她加入魂器学院后仍会去游览世界，但只要魂器学院需要她的帮助，她就会立刻来到学院贡献她的一份力量。",
		level_6 = 0,
		record = "在虹的心中，自己和自己的弓术也许会有被打败的一天，但自己心中的正义永远都不会被打败。"
	},
	[204520] = {
		soulid = 204520,
		valuation = "阿芙洛与魂武【吞噬之吻】的适配性非常十分完美，战斗时不仅仪态优美，破坏力也是数一数二的，就是摧毁敌人的方式未免简单粗暴了些……",
		file_1 = "艳光四射的联邦大明星阿芙洛在外演出时意气风华，光鲜亮丽，但当她独自一人安静呆在屋里时，那被【洛加尔】支配的恐惧便如阴冷的湖水般将她淹没。\n无法摆脱阴影的阿芙洛总以为自己仍旧伤痕累累，这导致她在追求美丽上十分偏执，几乎到了病态的地步。在无人时还用自虐来抚慰扭曲的心灵，她的腿上也因此时常留下伤口。\n阿芙洛在物质上拥有太多，然而她因为沉浸在过去阴影中导致她的精神世界堪称贫瘠。她有时会无法控制自己暴饮暴食，因为她觉得自己十分空虚需要被东西“填满”，魂武【吞噬之吻】的形象就是她部分性格的折射。",
		level_3 = 0,
		level_4 = 0,
		resume = "在风花雪月之城洛加尔的商业街上，阿芙洛·米勒的电子广告牌充斥着大街小巷。时尚杂志、红毯走秀、电影屏幕，联邦大明星阿芙洛的大名随处可见。凭借着美艳的外貌和妖娆的身段，以及优秀的表演作品，阿芙洛获得了众多粉丝的喜爱。但实际上的阿芙洛真的像大荧幕上那样无懈可击吗？\n在聚光灯照不到的地方，阿芙洛沉浸在被【洛加尔】当做间谍进行各种极端训练的过去阴影中，她被洛加尔控制去做一切自己厌恶的事，遭受各种残酷的对待，伤口、疤痕、欲望、罪恶充斥着她的前半生，她变得病态、偏执、嗜虐、强欲、暴饮暴食、为了变美不择手段……",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在未曾遇到魂器学院之前，阿芙洛是【洛加尔】制造的类人生命体，体质特殊的她无论受到什么伤害都可以愈合，【洛加尔】为了磨练她对自己忠心，打压她的独立意志，让阿芙洛遭受了各种残忍的虐待……直至魂器学院众人的到来，解救了阿芙洛繁华外表下腐烂的灵魂……\n布克丝为其打造的【吞噬之吻】的外形十分怪异猎奇，充满了阴郁压抑的气息，正如阿芙洛本人一样。事实证明，【吞噬之吻】堪称残暴的攻击方式——撕碎和吞噬与阿芙洛完全适配，它放大了阿芙洛的阴暗面，也让她在战场上无坚不摧，但这是究竟是好事还是坏事呢……",
		file_3 = "间谍——这个不光彩的词汇，烙印在阿芙洛的前半生。联邦大明星的身份给了阿芙洛游走于名利场的便利，她周旋于各个大人物之间，使尽手段为【洛加尔】窃取人类世界的情报。表面自由洒脱的她，背后却一直被一双手操控。\n阿芙洛既非人工智能，也非人类，处于边界中的阿芙洛常常感到世间只有自己一人。她不会爱人，也从未感受到被爱，充满纸醉金迷和尔虞我诈的生活让她变成一个麻木不仁的傀儡。\n欲望、欺骗、权术、阴谋诡计、【洛加尔】的非人虐待……这些生活中的负面存在让她变得阴郁多疑——直到班长犹如一枚带着阳光的利剑将她与阴暗的世界划开。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "某影视记者日记：\n2月13日\n阿芙洛小姐真美丽啊，她冲我微笑时我的心都要融化了，这世界上再也没有人能比阿芙洛小姐更美丽的电影女演员了！她生来就是为了艳光四射的！\n4月5日\n直播时的阿芙洛小姐已经很美丽了……为什么还要执着于美妆呢？我不明白……\n4月22日\n总感觉阿芙洛小姐没有她表现出来的那么开心……我意外看到她猛吃了很多东西，好像都快吃吐了，阿芙洛小姐生病了吗？\n4月28日\n阿芙洛小姐又受伤了，一定很痛吧，希望能早日好起来啊！\n8月18日\n阿芙洛小姐加入魂器学院已经有一段时间了，总感觉阿芙洛小姐自从加入魂器学院以后和以前大不相同了呢……现在的阿芙洛小姐明显更加“生机勃勃”了，阿芙洛小姐要幸福啊！",
		level_6 = 0,
		record = "来到魂器学院后，阿芙洛即使已经摆脱了【洛加尔】的控制，但过去的阴影却留在她的心中。想要治愈过去，大概需要许多许多的爱吧……"
	},
