	[205320] = {
		soulid = 205320,
		valuation = "诺娃作为一个平时足不出户的女生，她的身体能力正如我们预料之中一样差，在物理战斗能力以及持续作战能力方面只能勉强达到常人的平均值，而且她的灵匙生成的魂智能武器也相当特殊，竟然是一个键盘，据说灵匙和魂智能武器反映了一个人的精神境界，那么她的精神境界到底是什么样的呢？",
		file_1 = "诺娃的档案库中有一小段入学测验时候的录像。「入学理由啊……该怎么说呢……只是凑巧而已，当时就想着无论哪所学校都行，总之先试试考一下魂器学院吧，结果稀里糊涂地就进来了，但既然进来了，我姑且也会尽自己所能，好好努力一下，嗯，就这样。」",
		level_3 = 0,
		level_4 = 0,
		resume = "诺娃作为一位独立游戏研发者，曾参加过由知名游戏平台举办的独立游戏大赛并揽获其中含金量最高的《最佳创意奖》以及《最具影响力》两大奖项，并且在游戏公开发售的1年时间内成功达成了50万的销量，这在娱乐项目贫乏的战争时期中已经可以称得上是相当了不起的成就了。有很多游戏公司希望将她以制作人的身份进行挖角，但都被她婉拒了，关于她拒绝这些大公司的真实理由，她本人并未透露，但她却被粉丝们吹捧为了“不求名利的伟大游戏艺术家”。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "经过测试发现，诺娃拥有相当强大的想象力和逻辑思维能力，但因为头脑运转过快，所以行动往往会跟不上她的思维，这让她形成了有些容易焦躁的性格，而这一性格也让她在一般人眼中看来是个很难相处的女生，她本人也表示自己从小到现在没有多少现实中的朋友。",
		file_3 = "诺娃的打字速度是全学院最快的，平均输入速度已经达到了每分钟800次，而且使用的还是较为老式的机械键盘，不是悬浮式键盘，她本人表示，机械键盘在敲打时的手感和发出的声音都会让自己感到安心，悬浮式键盘因为太过安静了，反而缺乏了输入东西的实感。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "据我们调查，诺娃的家里人，甚至是她最亲近的父母和妹妹都不知道她制作过独立游戏，因为诺娃不想将这件事透露给家里人。教职员们也尊重她的意见，在对她的家里人进行采访时，有刻意隐瞒她做游戏的事情。采访中，教职员们得知，诺娃的家人并不清楚诺娃一直窝在房间里是在做什么，但他们相信，诺娃是个不平凡的孩子，她所做的事情一定不会是毫无价值的。诺娃的母亲表示：「其实，只要她能健康成长起来就好了，但为人父母，也会不由得担心起她的将来，所以我才向她提出了要求，让她考上一所学校，对于那孩子来说，可能考上学校只是单纯为了满足我提出的条件而已，但我希望老师们可以帮助她，让她可以像个普通的孩子一样交到朋友，渡过校园生活，今后还请老师们费心了。」",
		level_6 = 0,
		record = "传说中的美少女制作人。"
	},
