	[204820] = {
		soulid = 204820,
		valuation = "单就身体能力而言，萨拉完全可以获得A+级别的评价，但她不会说话，理解能力相比其他学员也有所欠缺，难以与其他人形成配合，在任务当中，这可以说是一个致命的短板了。好在她的危机应对能力很强，很像动物的野性直觉，虽然无法执行细致的作战方案，但在执行目标明确的作战时，萨拉可以说是毫无疑问的最强战力。",
		file_1 = "萨拉的档案库中有一小段入学测验时候的录像。「嘎呜……嘎呜嘎呜！嘎呜！（想要，为，主人，尽一份力！）」",
		level_3 = 0,
		level_4 = 0,
		resume = "萨拉很可怜，她注定无法过上一个正常女孩子理应拥有的人生，教职员们在对她进行调查时也不由得心疼起她来。不过，萨拉并没有表现出被命运所摆布的模样，虽然对班长之外的人抱有异常强烈的警戒心，但她仍然是一个开朗阳光的女孩子，充满好奇心，愿意接受新鲜事物，或许不久之后她就可以卸下心防，和班长之外的人也熟络起来。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "经过全方位的身体检查，教职员们发现萨拉无法说话的理由是她与常人不同的声带结构，即便是强行模仿，也很难发出像样的声音，除了声带以外，萨拉的其他身体部位也不一般，例如她的那对角，和已经确认存在的牛型异化人与羊型异化人的角区别都很大，反而与昆虫的触角最为相像，这让她的存在变得更加神秘，人类的外表、野兽的直觉、昆虫的器官，教职员们决定对她进行更长久的观察，以便解开她的身世之谜。",
		file_3 = "通过分析萨拉战斗时的录像，教职员们发现，她战斗的时候会习惯性地弓起腰，把自己的重心压低，利用强大的爆发力进行迅猛的突进攻击，这种姿势虽然看上去很奇怪，但却能最大效果地发挥她自身的身体能力，这是独属于她的战斗技巧，其他学员是无论如何都做不到的。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "经过详细的调查，布克丝发现了萨拉与黑暗狩猎者的组织之间似乎存在着一丝联系，而游枭本人也表示，虽然不清楚萨拉的来历，但她肯定与西奥多博士的基因组嫁接计划有所关联。萨拉自己的记忆也十分模糊，她虽然知道自己曾经待在一个十分可怕的地方，遭受试验品一样的对待，但除此以外她什么都记不得了，布克丝怀疑她的记忆有被人刻意抹除，在与游枭商谈过后，两人有了一个猜测，或许西奥多博士的研究曾经在不知不觉中被泄露出去了，有其他组织也在对基因组嫁接计划相关的内容进行研究。",
		level_6 = 0,
		record = "对班长有着近乎异常的忠诚心的女孩子。"
	},
	[23130] = {
		soulid = 23130,
		valuation = "真是出色啊，很久没有看到过这样的学生了，虽然身体的各项数值较为平均，但是那同时操作数十台机甲的身影真是让人记忆犹新。沉着冷静的性格和进退皆可的计划，比那群小混蛋都要可靠得多，暂时想不到什么意见，可以让她考虑一下当教官吗？ ",
		file_1 = "索菲亚能够制作出机器人、强化部件、武装外骨骼等各式各样的军用、民用设备。在鲁比克财团担任顾问期间，索菲亚用最少的经费开发出了世上最强的脉冲武器之一，被高层一致认为是无论如何必须要保留下来的人才。但目前，索菲亚似乎已经脱离了鲁比克财团，促使这件事发生的原因，以及脱离的手段至今尚未得知。不过通过索菲亚的个性很容易就能得出，两方在合作的期间发生了某件不愉快的事情，导致了商业关系的破裂。",
		level_3 = 0,
		level_4 = 0,
		resume = "来自奥杜因的天才少女，鲁比克财团的前技术顾问，掌握着高超的制作技巧，虽然是宅女不过性格并不内向。重视效率所以不喜欢讨论“无意义”的复杂话题。但是如果话题的内容与机械相关，那就不得了了，索菲亚对于机械的执着堪称狂热。不过如果在此时将话题转向诸如青春啊，恋爱啊之类的酸涩话题，索菲亚会马上宕机，变成只会迎合对方的机器人。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "索菲亚的行动模式十分微妙，看上去像是在为他人着想，但实际上围绕着的核心部分都是自己；举个例子：在班长入学的时候，索菲亚自告奋勇地承担了带领班长熟悉学院的工作，但是带去的地方都是自己感兴趣的……比起“导游”更像是在进行普通的社交。\n在战斗中的时候，索菲亚习惯以自己为中心操控机器人进行战斗，即使与其他学院组队，也会建立以自己为核心的战术。\n索菲亚随身携带的机器人——分别叫做麦克斯韦、伽利略与爱因斯坦，全部都是小型机体。小体型的机器人便于维护，也不会对自己的科研预算造成负担，在日常生活方面也可以提供更大的帮助，所以索菲亚几乎不会去制造大体型的机体。",
		file_3 = "以这种年纪担任鲁比克财团的技术顾问，并且在各个科研领域展露头角，索菲亚可谓是万众瞩目，如果她选择留在鲁比克财团，迟早有一天能够进入财团的核心阶层。\n然而，鲁比克财团的行为一次次地让她失望。将机器人用在地下拳击赛，结果伤及人命；把装备着强大兵器的佣兵投入到争夺地盘的乱斗中，造成大量伤亡。\n索菲亚不介意自己制造的机械被用作军事用途，她自身也非常喜欢兵器开发，但是——\n不是将她制造出的机械用作与人工智能的战争，用在保护无辜之人上，反而借此以肮脏的手段掠取财富，索菲亚对此是无论如何都不能容忍的。\n由此，索菲亚单方面解除两方的合作条约，与鲁比克财团分道扬镳。而在她的友人——鲁比克财团的大小姐爱丽丝坚持下，财团也没有对其进行追究。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "以能够自由学习魂智能网络的技术为条件，索菲亚与魂器学院定下了时长几乎是“终生”的雇佣契约。\n随后，很长一段时间里，索菲亚几乎断绝了与外界的联系，一心一意投入到科研与“工作义务”之中。\n用自由为代价，少女想要追寻的究竟是何物？\n答案是——为了找回逝去的所爱之人们。\n索菲亚的父母，亲友，老师全部在那名为“黑色圣诞”的灾难中失去了生命。\n少女想要完成能够扭转时间，或者让亡者复活的机械，将自己所爱的人们带回身边。\n哪怕那只是妄想也无所谓，如果不找到能够坚持的，能够支撑自身的事物，名为“索菲亚”的存在迟早会崩溃。",
		level_6 = 0,
		record = "“我不希望任何人从我眼前消失……不，就算是消失了也没关系，我一定把你们都找回来的！”"
	},
	[204620] = {
		soulid = 204620,
		valuation = "虽然综合成绩只能给到A-的水平，但考虑到她从第一次测试到现如今的恐怖成长速度，我们对她抱有相当程度的期待，如果她能继续保持这个成长速度的话，必将成为魂器学院当中最顶尖的战斗力。考虑到她的成长潜力，最终决定她的入学综合成绩为A。",
		file_1 = "遥的档案库中有一小段入学测验时候的录像。\n“入学理由吗？那还用问！？当然是因为这里有着铃兰姐姐大——啊，不是，是那个啦，因为魂器学院是全世界目前各方面最强的学府，这里集中着来自世界各地的高科技领域人才，是人类对抗AI的最前线，我要作为学员为魂器学院奉献自己宝贵的力量，为了拯救人类，所以……”",
		level_3 = 0,
		level_4 = 0,
		resume = "刃隐遥是一个被遗弃的孩子，在即将饿死街头的时候遇到了铃兰，在铃兰的要求下，刃隐家主把她收为刃隐一族的成员，让她跟随着其他成员修行忍术，但遥对忍术的理解和其他人相比有所差异，因此她的修行迟迟见不到成果，无论怎么努力都赶不上别人。在铃兰离开她，前往魂器学院以后，她便开始拼了命地用尽一切方法锻炼自己，为了能在下一次入学测验中顺利通过。理论上来讲，就算身体综合能力达标了，魂智能网络的适格率不达标的话依然无法入学，而魂智能网络适格率是极难得到后天提升的，没有人认为她能通过第二次入学测验，但遥做到了，她的成长让所有人为之瞠目。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "经过一段时间的观察，教职员们发现，尽管遥口口声声说铃兰要比她强得多，但实际上她的综合成绩和铃兰相差并无太多，甚至遥在某些方面的作战能力要高于铃兰，但她依然对于铃兰有着盲目的崇拜，这并不是因为她生性自卑，而是因为她一时还无法将过去脑海中那个“完美的铃兰姐姐大人”的印象全部抹除。要让她接受现实或许还需要一段时间，这期间班长可能会比较辛苦，因此教职员们也会竭尽全力保障班长的人身安全。",
		file_3 = "刃隐家主说过，他禁止遥在铃兰入学的期间与铃兰联系，其实是在为遥考虑，遥从小就太过依赖铃兰了，虽然她的表现平平，但她并不是个没有天赋的孩子，只是刃隐一族的锻炼方法不适合她，她需要忘记先失去铃兰这个错误的榜样，然后找到独属于她自己的一套成长方式。因此刃隐家主虽然感到十分内疚，但仍旧狠下心来坚持做出让她们断绝联系的决断，最终正如刃隐家主所料，遥的努力开花结果，她找到了专属于自己的变强方式。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "关于遥拼命锻炼的理由，院方最初认为单纯是因为遥对铃兰有着异常的执着，但实际上似乎并不只是这样。在对其他刃隐一族成员的询问中，他们多次提到了遥当时每天晚上都一个人偷偷跑去竹林里以泪洗面，一直到凌晨才眼睛红肿着回到宿舍。事实上，铃兰的入学让遥觉得自己被抛弃了，这唤醒了她幼时被父母遗弃的记忆，她害怕自己再度被抛弃，所以才会拼命锻炼，证明自己的存在价值。但她所不知道的是，刃隐一族的人每天早上都会为她再热一次早饭，每天都会用浸了药水的毛巾为她擦拭眼角，每天都会把她破烂的战斗服修补好。这样的刃隐一族怎么可能会抛弃她呢？",
		level_6 = 0,
		record = "遥对铃兰的尊敬程度和对班长的恨意是成正比的。"
	},
	[206520] = {
