	},
	[205220] = {
		soulid = 205220,
		valuation = "尽管已经见惯了科研出身的学员，但缇利亚的个人能力依然让我眼前一亮，或许是因为她在人体工学方面颇有造诣，所以她对于一起战斗的同伴的身体状态把控得十分到位，可以在绝妙的时机为其他人提供支援，这种能纵览全局的大局观是相当难能可贵的。",
		file_1 = "缇利亚的档案库中有一小段入学测验时候的录像。「索菲亚老师是我的偶像，也是我的人生目标，本来以为我已经快要追赶上她的脚步了，但是……在我努力的时候，她又甩开我更远的距离了……所以我也要加入魂器学院，如果不抓住这次机会的话，我可能一辈子都追不上索菲亚老师了。」",
		level_3 = 0,
		level_4 = 0,
		resume = "缇利亚出生自奥杜因的一个普通家庭当中，因为她小时候身体发育缓慢，经常沦为其他孩子取笑的对象，在想方设法加快身体发育的时候，她意外地对人体工学这门学问产生了兴趣。经过她不懈的努力，在14岁时成功加入了奥杜因的科学技术研究所，并有幸成为了索菲亚的助手，但因为当时的索菲亚依然所属于鲁比克集团，所以缇利亚担当助手的时间只有短短11天，即便如此，她也深深地被索菲亚所吸引，立志要成为和索菲亚一样，甚至是要超越索菲亚的研究者。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "院方很久之前就已经开始关注这名在人体工学领域崭露头角的小小研究员了，这次恰好有索菲亚的引荐，院方便很快和她搭上了线。缇利亚的表现可以说是远远高于我们对她的期待，作为人体工学研究员的她在入学后很快便制订好了针对学院中一些设施的优化方案，并且充分展现出了自己在作战指挥方面的天赋，深受其他学员的信赖。不过她本人慢条斯理的性格倒是没有什么改变，在投入进研究工作时依然会忘我到脱个精光。",
		file_3 = "缇利亚并非缺乏常识，但她在羞耻心方面的认知相当薄弱，院方最初尝试让她与其他女性研究员协作，以此来改善她爱脱衣服的毛病，但最终还是失败了。据她本人所说，脱衣服是下意识的行为，就和很多人在集中精力思考时会不自觉搓手一样。同时缇利亚补充了一句：“就我这贫瘠的身板，就算被看到又怎么样，哈哈……”",
		level_7 = 0,
		level_2 = 0,
		file_4 = "经过长时间的观察，教师们发现，缇利亚其实是一个相当感性的女生，只不过由于她自身个性的缘故，很多东西她都会悄悄藏在心里，比如吃到好吃的东西时，她并不会让欣喜之情溢于言表，而是会默默地吃个一干二净。在与班长相处时，明显可以监测到缇利亚的心率和荷尔蒙分泌速率出现些微的变化，并且情绪的起伏也会更加明显，而与其他学员相处时就不会这样，这说明班长在缇利亚心里是相当特殊的存在。",
		level_6 = 0,
		record = "缇利亚和缇法同样都是经常会被误当成小孩子的学员。"
	},
	[205820] = {
		soulid = 205820,
		valuation = "相比于其他学员，月并没有某项能力表现极为突出，相对的，她的整体作战能力相当均衡。虽然我早就知道她的实力在月和会当中也当属佼佼者，但最终的测试结果依然有些出乎我的意料，不得不说，月和会真是个强手云集的组织啊。",
		file_1 = "月的档案库中有一小段入学测验时候的录像。「详细的事情我都从芙蕾殿下和布克丝院长那里听说了，无需多言。如果有其他事情的话，还请长话短说，我怕枫会趁我不在的时候惹出乱子。」",
		level_3 = 0,
		level_4 = 0,
		resume = "月在很小的时候就被父母抛弃了，当时还是孩子的她几乎是拼了命才得以在洛加尔的贫民区生存下来，偶然从小混混手里解救下了一名鸟型异化人以及一名兔型异化人，当时的月是出于保护她们的心态才和她们成为的朋友，但因为月是流浪者，而另外两人生活在孤儿院，所以三人平时很难见面，某天，月和会的人突然找到月，说明今后可以由月和会来抚养她，月在得知另外两人也会去月和会的时候产生了疑心，但依然决定前往月和会，她心想如果月和会对她们做些不好的事情，自己一定要把她们从月和会带出来，但到了月和会以后，月发现那里其实是对异化人相当亲切的组织，放下心来的她本想离开月和会，但被芙蕾挽留了，从此和另外两人作为芙蕾的影子护卫一直勤恳工作到现在。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "月在加入魂器学院不久，便和食堂的阿姨产生了接触，以帮阿姨们打杂为条件，希望能从阿姨们身上学习一些料理食谱，而阿姨们也是欣然答应了。一位18岁的女孩子在后厨里跑来跑去的样子着实也为整个食堂平添了不少活力，阿姨们也很愿意将自己的独门秘方教授于月。“月将来一定会成为好媳妇嘞！和月比起来，我家那孩子就……”月在食堂阿姨之间得到了极高的评价。同时也有传闻称，自从月来了以后，商店街上的人也会经常来学院食堂吃饭了，这为学院食堂带来了相当可观的收入，其中有一个胃口很大的异化人食客给大家留下了很深的印象，因为她长相酷似哈士奇，所以获得了“小哈士奇”的爱称。",
		file_3 = "我们在对月进行了长期观察之后发现，她的责任心远比我们预料当中的更加强烈，不只是对人，就连对小动物也是一样的。某天她被学院里的野猫黏上，但因为没有什么吃的东西可以给野猫，所以野猫失望地离开了，从那天起她每次出门的时候口袋里都会至少揣上一根火腿肠。不过，最终这根火腿肠极大概率会被枫消化掉。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在对芙蕾和月和会其他人员进行走访的时候，我们意外得知，月在组织中除了担任芙蕾的影子护卫一职，还在担任异化人小孩子的保姆。其实，芙蕾她们会定期保护一些遭亲人遗弃的小孩子，而这些小孩子往往对人有着极大的不信任感，但当月接手了照顾她们的工作时，情况便有了改善，同属异化人的她很快便和小孩子们熟络起来，再加上她极其擅长照顾人，所以甚至被很多小孩子称作“小月妈妈”。“为什么不是小月姐姐？”月对这件事也并不是没产生过疑问，但她并不在意称呼这种东西，所以很快便接受了。",
		level_6 = 0,
