	[206020] = {
		soulid = 206020,
		valuation = "枫是一个十分敏捷的学员，或许是得益于她鸟型异化人的天赋，骨骼重量比一般人低一些，她可以用一般人极难达到的速度进行移动和攻击，单论敏捷性而言仅次于萨拉——但当我这么说了以后，枫立刻就表现得很激动，看来是个胜负心很强的学员啊。",
		file_1 = "枫的档案库中有一小段入学测验时候的录像。「可……可恶……考官老师居然说我的速度比那个叫萨拉的学员慢，我不会认输的！那个叫萨拉的！等着与我一决高下吧！」",
		level_3 = 0,
		level_4 = 0,
		resume = "枫不知道自己的父母是谁，从有意识起，自己就已经生活在孤儿院当中了。生性活泼好动的枫很快便成了孤儿院里面的孩子王，在她6岁的时候，一个与她同龄的柔弱小女孩被带到孤儿院，那便是泉，枫和泉的性格截然相反，但两人却很快成为了朋友。9岁那年，她带着泉一起溜出孤儿院，但却意外地被一群歧视异化人的流氓发现，就在两人被带到小巷子中，将要遭受虐待的时候，月突然出现，将流氓全部打倒，从此她们便和月相识了。之后的某天，芙蕾来到孤儿院收养了枫和泉，得知去了月和会能过上更好生活的枫和泉请求芙蕾一同收养月，芙蕾思考了片刻便应允了。去到月和会之后，枫对芙蕾的忠诚心日益增长，她决心今后要为芙蕾以及整个月和会贡献自己的一份力量。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "枫是一个相当单纯好懂的女孩子，只不过她的胜负心异常强烈，特别是在她充满自信的“速度”方面，她不想输给任何人，因此，在入学时被监考官说“速度仅次于萨拉”之后，她便对萨拉燃起了对抗心，入学第二天便立刻找到了萨拉，与其一决高下，然后立刻输掉了（比赛中的萨拉还没有使出全力），不甘心的枫立誓要打败萨拉，虽然萨拉“嘎嗷嘎嗷！”地回应了，但实际上她并不知道枫在跟她说什么。",
		file_3 = "经过长期的观察，我们发现，枫虽然表面看上去很粗野，大大咧咧，但其实她和人相处的时候很注重礼节，生活在也有很多表现得十分细心的方面，比如吃饭时候的举手投足，又或者是垃圾分类时候的一丝不苟，无不体现出她那严谨认真的生活态度。由于枫有着锻炼身体的习惯，所以校园中经常能见到她奔跑的身影，在跑步时遇到其他人也都会亲切地打招呼，所以枫的人缘比起月和泉要好很多。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "经过长期的搜寻，我们终于在大数据库中寻找到了与枫DNA匹配成功的两对DNA，经过核实，那两对DNA的持有人确实是枫的父亲和母亲，两人目前都是普通市民，生活勉强算得上安定。当我们询问枫是否要带她去见自己的亲生父母的时候，枫委婉地拒绝了，她表示，因为她从没有过一丁点关于亲生父母的记忆，所以并没有要见这两人的想法。不过，枫仍然托我们匿名寄过去了一大笔她在月和会工作多年积累下来的积蓄，至于理由，我们则并没有多问。",
