	[206620] = {
		soulid = 206620,
		valuation = "虽然形状特殊，但序构天琮是一个攻守兼备的魂智能武器，可以在保护使用者的同时发动攻击，这一定程度上弥补了玉琮自身能力不足的缺陷。虽然目前来看，玉琮本身的战斗能力并不突出，但她正值成长期，有着十分巨大的潜力，我们都很期待她今后的表现。",
		file_1 = "玉琮的档案库中有一小段入学测验时候的录像。「嗯~因为可可姐说这边有事情需要我的协助，而且能接触到古文物，对于我来说也是有好处的，所以呢，没有什么拒绝的理由吧？」",
		level_3 = 0,
		level_4 = 0,
		resume = "玉琮的父母都是钻研考古学的学者，而她的名字也是来自古代的一种名为「玉琮」的文物，因为从小时候开始，她的同学里面不认识「琮」字的人很多，所以她通常会让对方直接称呼自己为“小玉”。小玉的父母在一次地下勘探时遭遇意外而牺牲，当时的小玉完全理解不父母到底为什么对古代文明如此执着，于是便半怄气地决定自己也踏上这条道路，搞清楚父母究竟是为什么殉职。年仅14岁的她就通过自身的努力取得了派森的个人考古发掘资格证，这在派森的历史上是绝无仅有的。",
		level_1 = 0,
