		file_3 = "起初，我们担心玉琮的生活习惯和兴趣爱好会妨碍她的人际交往，毕竟和她有着相同兴趣爱好的学员几乎为零，但经过长期的观察发现，玉琮在人际交往方面十分圆滑，她能很自然地融入一个圈子，并且在圈子中始终扮演一个“外圈”角色，不会被别人牵着鼻子走，也不会主动引发话题，比起参与者，其实更像是一个倾听者或是监护人。",
		level_7 = 0,
