		valuation = "不愧是布克丝院长看中的人才，萌百娘在测试中的表现十分惊人，虽然身体能力较为平庸，但是在数据处理的相关项目上险些打破了魂器学院办学以来的历史记录，真是后生可畏啊。",
		file_1 = "萌百娘的档案库中有一小段入学测验时候的录像。「入学的理由吗？那当然是为了学到更多的知识了，为了让“萌娘百科”能更好地发展下去，不能仅靠编辑者们的热情和善良，我自己也必须努力才行！不管是打AI还是拯救世界，尽管放马过来就是了！」",
