		file_3 = "萌百娘的杂学知识十分丰富，特别是在ACGN领域，包括游戏、动漫、漫画等，只要是二次元相关的一切，她都有很深入的了解。因为会经常帮学员们解答问题，所以被学员们誉为“行走的百科全书”。",
		level_7 = 0,
