		level_3 = 0,
		level_4 = 0,
		resume = "泉的父母早在她记事之前便去世了，独自抚养泉的奶奶也在她6岁时去世，没有任何一个亲戚愿意收养的泉便被送到了孤儿院。亲近之人的离世让泉变成了一个胆小孤僻的孩子，直到枫闯入她的世界。枫常常会带着她跟孤儿院的孩子们一起玩耍，而她虽然总像是被牵着鼻子走，但其实她并不觉得厌烦。某天，枫带她出门的时候，被一些讨厌异化人的恶徒缠上，就在她们即将被带到小巷里遭受虐待的时候，月出现并对她们伸出了援手。如同英雄一般的月让泉产生了依赖心，所以在之后的某天，月和会来孤儿院收养枫和泉时，泉才会拼命请求月和会一同收养月。来到月和会，与枫和月组成小队以后，泉依然是个怯懦的孩子，依然常常被人牵着鼻子走，不过她并未对此有什么意见，只是担心自己会给另外两人拖后腿，所以一直在默默努力着。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "泉从小就很喜欢读书，因此和绝大多数人的猜想相反，泉并不是因为失去亲人的悲伤而沉迷读书的，对于她而言，书籍是可以顺利沟通的对象，不只是书中所写的故事，她还可以根据字里行间的一些细节解读出作者自身的性格和行为习惯。泉认为，要了解一个人不一定需要与其面对面沟通，因为构成人的所有“要素”会通过人的所有行为向外传递。",
		file_3 = "在长时间的观察之后，我们发现，泉对班长有一种类似对待“哥哥姐姐”一样的依赖感。虽然并不知道这份依赖感来源为何，但泉会亲近他人这点连月和枫都有些惊讶，毕竟泉就算在整个月和会之中，亲近的人也只有月、枫、芙蕾三个人而已。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "院方对泉的家族进行了一定程度上的调查，发现泉的家族中并不存在异化人，也就是说，泉和她的奶奶没有任何血缘关系，这也解释了为何亲戚们都不愿收养泉。但对于泉的来历和泉的奶奶为何要抚养她，院方没有进行进一步的调查，因为布克丝判断，无论真相如何，都不会带给泉幸福，即便亲人关系是虚假的，泉与她奶奶之间的亲情也是绝对真实而无可替代的。",
		level_6 = 0,
		record = "外观和性格都像兔子一样的可爱少女。"
	},
	[205120] = {
		soulid = 205120,
		valuation = "伊南娜的判断力和应变力十分优秀，在战场上也总能时刻保持清醒，在最恰当的时机做出最为理性的决断。说实话，比起一名医生，她更像一名士兵，但她效忠的并非为她下达指令的人，而是严格忠于自己的理性，当她判断情况不允许她执行命令的时候，她会立刻按照自己的想法去行动。虽然在测试中她的独断专行往往能达成更好的结果，但这究竟算不算得上优点，我们也无法立刻下定论。",
		file_1 = "伊南娜的入学档案中有这样一段录像。「入学理由？没什么，只是觉得如果能获得魂智能武器的话，无论做什么都会变得更有效率而已，当然，我会尽量服从安排的。」",
		level_3 = 0,
		level_4 = 0,
		resume = "伊南娜出身于巴哈姆特的一个普通家庭，接受着与一般人别无二致的教育。她完全凭借其自身的努力，在社会环境相对恶劣的巴哈姆特中成为了一名医学生，并且在实习结束后立刻被实习的医院选中，在身为学生的同时也作为医院的正式医师开始了工作。在医院工作期间，她并不会主动和其他医生或患者打好关系，基本上处于独来独往的状态，因为并不影响日常工作，所以医院的其他人也并没有对她多嘴。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "即便入学了，伊南娜也并没有去积极结交朋友，依然过着缺乏社交的生活。判断这种状态会对她今后的精神状况造成影响的教职员们也鼓励她与其他人多沟通，虽然她口头上答应了，但实际情况是——她对班长以外的人依然相当疏远。在对她进行询问后得知，就连与班长的交流，也是她认为那是“客观需要的行为”所以才进行的。",
		file_3 = "经过长期的观察，我们发现伊南娜对于其他学员多少提起了一点兴趣，不知是因为班长的努力还是她的小队——乱序王座的其他学员的努力奏效了。无论如何，伊南娜正在向好的方向进行转变，虽然目前仅止于“有兴趣”，但我们相信不久以后她也能顺利融入到学员们的集体当中。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "伊南娜从小生长在巴哈姆特的恶劣社会环境当中，父母也一直告诫她，不要和社会上的阴暗面接触，也不要太过张扬，因此伊南娜从小便成为了自立且有些孤僻的孩子。她父母的本意是让她可以平平安安，健健康康地长大，虽然就结果而言伊南娜确实顺应了父母的期待长大成人，但在某些方面她往错误的方向发展了。因为伊南娜的努力工作，家庭比原来更加富裕，但她的父母对于她的愧疚感也变得更强了，觉得自己对她有所亏欠，但又无法坦率地说出“像个普通的女孩子一样去享受自己的人生”这种话。因此伊南娜的父母委托魂器学院，也是委托班长，希望可以让她喜欢上与别人社交，并且最好能在学院里找到个好对象嫁出去。",
		level_6 = 0,
		record = "效率至上。"
	},
	[205020] = {
		soulid = 205020,
		valuation = "水原堇的战斗方式……怎么说呢，比起攻击力，她似乎更在意招式是否足够抢眼，虽然动作看起来十分流畅，但其中很多细节动作都是可以省略掉的，比如转刀和转身。在与其他学员一同战斗时往往会因为动作幅度过大且刀光太过华丽而影响到其他学员的发挥，其他教师对她的评价是「行走的光污染」。",
		file_1 = "水原堇的入学档案库中有一小段入学测验时候的录像。「入学理由？呵呵，只是各取所需罢了，你们缺少对抗人工智能的战士，而我则希望有一个能展现自我的舞台，仅此而已。」",
		level_3 = 0,
		level_4 = 0,
		resume = "水原堇出身于洛加尔的名门——水原，但她所属的只是水原家族的旁系，并非水原雾夜那样的本家，而旁系在整个家族中的地位自然比不上本家，总是会受到本家的欺压。因此，作为旁系中最为优秀的她自幼便被认为是旁系的骄傲，或许可以颠覆本家和旁系之间的势力关系，但她却并不以为意。比起努力学习和锻炼，她更喜欢看动漫玩游戏，在自由的家风之下渐渐形成了中二病的性格，并开始模仿起那些动漫角色或是游戏角色使用的招式。一开始很多人觉得她是异类，净学些花里胡哨的东西，直到她用自己花里胡哨的招式打败本家的天才水原雾夜。水原堇在家族中的风评在那之后便好转了，而她和水原雾夜之间也从此结下了梁子。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "经过我们的观察，水原堇确实会通过学习游戏或者动画中她认为十分酷炫的角色招式，并且在模仿之后，她还会在此基础上进行招式的改造，她每天的乐趣就是拿着自己的「默示录」在那里研究招式名称，招式动作，还有招式发动时要说的台词。有的学员担心水原堇这种模仿行为会带来版权上的问题，但实际上那些游戏公司和动画公司对此并不在意，他们表示「有人愿意模仿，是对我们作品的最大尊重」。出于保险考虑，教职员们向律师进行了咨询，确定了水原堇模仿游戏内角色动作的行为完完全全不构成抄袭。",
		file_3 = "经过观察，教职员们有了意外的发现，水原堇其实相当擅长画画。据她自己所说，每次她看到游戏或是动画里出现自己喜欢的招式动作时，不是用设备的截图功能，而是自己在小本本上把角色的动作分解画出来，她认为这样可以更好地理解角色的身体运动方式，但这其实并没有任何科学依据。不过也正是多亏了她的这种努力，她的绘画水平变得相当出色。经过对她画风的分析，教职员们也在网络上找到了她偷偷以网名“紫炎瞳的魔女”发布的长篇漫画。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "水原堇的父亲向我们透露，在水原雾夜成为芙蕾的护卫，入学魂器学院之后，旁系的家族成员便再也坐不住了，纷纷劝说他让水原堇成为水原家族的继承人候选，也就是下一任水原家主候选。但水原堇的父亲并不希望自己的女儿被卷入旁系与本家之间的势力斗争，成为势力斗争的工具，也不希望自己的女儿像水原雾夜那样为了月和会鞠躬尽瘁，他只希望自己的女儿可以自由成长起来，过上其自己的人生，因此他将水原堇也送入了魂器学院，明面上满足了旁系家族成员想要看到「水原雾夜和水原堇互相竞争」的想法，并且可以一定程度上拖延住这些人。而在水原堇入学的这段时间，水原堇的父亲也会竭尽全力压制住水原家族势力斗争的苗头，按照他的预测，等到水原堇从魂器学院毕业，一切都将尘埃落定。",
		level_6 = 0,
		record = "中二病拯救世界！"
	},
	[206820] = {
		soulid = 206820,
		valuation = "拉塔莉亚本身的战斗能力无可挑剔，但……在战斗中她对于其他同伴的保护欲过于强烈，总会自己一个人抗下绝大多数的攻击，作为前卫角色，能有这样的意识虽然很好，但我们担心过于强烈的保护欲也会对她造成过大的负担，使她在战斗中遭遇危险。“改善她过剩的保护意识”将会成为日后教职员们和班长的一个重要议题吧。",
		file_1 = "拉塔莉亚的档案库中有一小段入学测验时候的录像。「入学理由……吗？首领的邀请是一方面，还有一方面是因为，我无论如何都放不下小班长呢~小班长明明比谁都努力，每天都为大家而行动，而大家却都认为是理所当然的，这样下去是不行的，迟早有一天小班长会累垮，所以，就由我来成为小班长的依靠吧。」",
		level_3 = 0,
		level_4 = 0,
		resume = "拉塔莉亚出生在玛尔斯的一个偏远镇子，父母都是工人，家里还有一个比她年龄小很多的妹妹。着重工业开发的玛尔斯地区并不缺乏名为“人”的劳动力，因为重活累活全部都由机械进行作业，人力已经被取代，所以虽说拉塔莉亚的父母在工厂得到的待遇不错，但相比于其他正常上班族，收入还是有些偏低的。拉塔莉亚从小过着勤俭节约的生活，因为平时父母都要去工作，所以照顾妹妹的事情自然就落到了拉塔莉亚头上，除此以外拉塔莉亚偶尔也会去附近的牧场做帮工，久而久之的，拉塔莉亚变得越来越擅长照顾人和小动物，如大姐姐般可靠的她也成为了当地小孩子们想要依赖的对象，看似温柔平静的她其实内心也有着小小的野心，那便是——吃遍世界上所有的美食。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "拉塔莉亚在入学之后便接管了学院内畜牧饲养区的一部分工作，即便是极为挑剔的饲养区管理员也最终认可了她：“我从没见过有谁能把如此程度的爱倾注在动物们身上，此前我一直以为学员们终究只是把牛儿们和羊儿们视为食物，真是出乎我的意料啊。”现如今，拉塔莉亚不光在年幼的学员中有着极高的人气，甚至她只要踏入学院的饲养区，立刻就会被大大小小的动物们包围起来，她所散发出的母性光辉让所有人都忍不住想要向她撒娇，这是用科学都难以解释的事情。",
		file_3 = "在入学一段时间后，教职员们发现拉塔莉亚在闲暇时间经常会跑到学院食堂或是学院外面的商店街上的餐馆大吃特吃，她的平均吃饭时长会比一般的学员久一点点，但食量却接近同龄人的两倍，她本人解释称，因为平时照顾小动物比较消耗体力，所以必须要通过多吃来补充能量。但在体检当中，教职员们发现拉塔莉亚的体重确实比起相同身高的人要“重上那么一丢丢”，看来吃下去的东西也并不是全部转化为身体的能量了，也难怪拉塔莉亚喜欢穿那种修身显瘦的衣服。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "教职员们采访了拉塔莉亚的父母，得知了一些拉塔莉亚小时候的事情。拉塔莉亚小时候因为自己特殊的发色和异化人的身体特征，经常沦为同龄孩子们的取笑对象，这为她幼小的心灵带来了很大的伤害，而就在此时，有一位比她大的女生站出来阻止了其他孩子对她的欺凌并安慰了她，对她而言那个女生就像她的英雄，而那个女生也将她视作自己的妹妹一般，对她十分关照，直到有一天，那个女生病逝，拉塔莉亚再度陷入了沉痛的悲伤当中，擦干了眼泪之后，拉塔莉亚下定决心改变自己，先从不被欺负开始，再到成为一个“可以庇护弱小”的人，她开始锻炼身体，也开始去附近的牧场做帮工，在妹妹出生之后也是主动替忙碌的父母揽下了照顾妹妹的差事，而拉塔莉亚的成长也被镇子里的所有人看在眼里，没有人再瞧不起她，大家甚至开始依靠起了成长后的拉塔莉亚。但拉塔莉亚明白，照顾他人并不意味着要为这个人的一生负责，雏鸟总要学会自己飞翔，因此在妹妹可以照顾自己之后，在父母的支持下，拉塔莉亚和偶然来到镇子里的洛可可一同出发，踏上了漫长的旅途。",
		level_6 = 0,
		record = "究竟是不是哈士奇呢？"
	},
