	[206920] = {
		soulid = 206920,
		valuation = "比起正面战斗，尤利娅似乎更适合谍报任务，通过高科技与卓越手法进行的变装非但肉眼无法辨别，还可以一定程度上欺骗一些电子仪器，而尤利娅本人似乎也对这种事情乐在其中。【千变万化】是一种十分特殊的魂器，虽然外表看上去只是个普通的手提包，但其内部有着相当广阔的空间，可以储存各种各样的道具来应对各种各样的场合。因此，尤利娅可以成为战场上的移动补给站，这将在一定程度上为学员小队的战术安排带来巨大的革新。",
		file_1 = "尤利娅的档案库中有一小段入学测验时候的录像。「入学理由？嗯……是我老爸非要我入学的啦，我自己也不太懂，但感觉很有趣，所以就来了。嗯，就是这样！」",
		level_3 = 0,
		level_4 = 0,
		resume = "尤利娅是玛尔斯工业区一家大型企业的社长千金，自小生长在一个比起同龄人更加优渥的环境当中，因此也养成了有些调皮的大小姐性格。因为小时候接触到的一些动漫作品，她深深地迷上了角色扮演这种东西，并非只是外观扮演成别人的模样，她甚至想要自己真正成为别人，体验到别人的人生，但这在目前的科技水平下显然是不太现实的事情。于是，尤利娅将目光放到了虚拟主播身上，既然无法扮演成一个“现存于世”的人，那就扮演成一个全新的人，带着这种想法，尤利娅在12岁生日时向父亲要了一套虚拟主播设备和形象，开始了虚拟主播之路。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "尤利娅并不是随时随地都在恶作剧，她知道恶作剧的分寸在哪里，也不会因为恶作剧带给其他学员麻烦。与此同时，尤利娅还会用自己的魂智能武器帮学员和教职员们搬运东西，所以和教职员们最初的猜测正相反，尤利娅在学院当中还是很受到大家欢迎的。",
		file_3 = "由于尤利娅家的企业经营内容主要是高端数码产品，所以在人工智能叛乱之时一度因为市场崩溃陷入将要破产的境地，为此尤利娅的父亲将经营战略转移，一方面开始涉足中低端电子设备以维持自己的客户基础，一方面凭借人脉成功联系到了军方高层，通过为军方供给设备来获取资金。由此一来，企业不光得以幸存，甚至还一跃成为了数码产品领域的巨头。尤利娅平时使用的设备是企业生产的特制品，采用了最为先进的立体投影技术，品质甚至要高于军工级产品，之所以她能享有这样的特权，并不只是因为她社长千金的身份，即便是在企业所有的测试员当中，尤利娅的水平也是顶尖级别，因为从小就与这种高端数码设备作伴，对于现在的尤利娅来说，使用这些设备就犹如呼吸一样自然。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "尤利娅的父亲对于她找到了心仪对象这件事颇有微词，屡次在与尤利娅的通话中表示：“尤利娅的丈夫今后是要继承家中企业的，所以必须要托付给一个头脑聪明，有才华，家境优秀，样貌英俊，性格好，无不良嗜好，并且真诚地爱着尤利娅的杰出人才。“并且要求尤利娅更加谨慎地挑选对象，但尤利娅的母亲却悄悄告诉院方，其实尤利娅的父亲只是不舍得女儿出嫁罢了，只要对象是尤利娅真心喜欢的人，她就不会从旁干涉。不过，尤利娅的母亲几度希望院方可以将班长的照片和个人履历发过去以便她提前确认。但她的要求最终被尤利娅以“老妈才是真的保护过头啦！”为由拒绝掉了。",
		level_6 = 0,
		record = "喜欢变作他人来搞恶作剧的调皮少女。"
	},
	[207020] = {
		soulid = 207020,
		valuation = "不愧是在基金会的“方舟计划”中被培育出的孩子，各方面能力均衡且都相当出色，在同龄的学员当中都很难找到能在某一方面与她平分秋色的人。而且，人格辅助自律智能体——青麟在战斗中也能帮助她分析战场上的情报，以便她做出及时的应对。在这种精妙的配合之下，天瞳可以真正意义上主导整个战场，因此她也是相当适合成为指挥官的优秀人才。",
		file_1 = "天瞳的档案库中有一小段入学测验时候的录像。「布克丝，你到底和基金会高层做了什么交易？他们居然能允许吾离开设施，到魂器学院来。应该不只是需要我帮助那孩子吧？算了，无所谓，不管你们达成了什么交易都与吾无关，吾会听从你的指示行动的。」",
		level_3 = 0,
		level_4 = 0,
		resume = "天瞳是基金会“方舟计划”的最高技术结晶之一，是基金会研究员们的骄傲。天瞳并没有任何家人，她从记事之时起就天瞳小时候便被要求与人格辅助自律智能体——青麟一同行动，这并非是出于对她的关心，而是为了稳定她的精神，以形成“正常的人格”。不过在长时间与青麟的相处过程中，她对青麟的看法从“烦人”逐渐转变为了“信赖”，这位有着中年大叔一般性格的智能体如今已经成为了她最好的朋友。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "严格来说，天瞳算不上是一个擅长社交的学员，她经常会用老态龙钟的语气去训斥别人，并且希望别人将她当作老年人看待。不过，出乎教职员们预料的是，天瞳相当受到其他学员的喜爱。她经常会被其他学员缠住，又是摸头又是投喂，虽然她嘴上说着“不要把我当小孩子！”但却并没有强硬拒绝，这或许说明她潜意识中也在渴求着他人的亲近。",
		file_3 = "天瞳并非是像蛟和啸一样的克隆体，而是一个正常被孕育出的人类。不过，从天瞳记事起，便一直住在培养仓之中，借助科学设备被动地吸收着各个领域的专业知识。据天瞳自己所说，那并不是像某些动画作品中呈现出的那样富有浪漫感的东西，更像是一场噩梦。最早，研究员们尝试的是直接将“知识”灌输进实验体的脑内，但这样会导致实验体虽然获取到了知识，但却并不能用逻辑将这些知识串联起来，也就是“无法活用”。后来，研究员们开始尝试将“记忆”灌输进实验体的脑内，虽然灌输速度变慢了，但获取了记忆的实验体可以很好地活用这些知识，只不过——大部分实验体都在不久之后选择了自尽。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "天瞳并不知道自己的父母是谁，据基金会的高层所言，天瞳在刚出生后就因为患有脑部疾病而被父母舍弃，如字面意思一般“卖”给了基金会。基金会在解析了她的大脑以后发现，她的大脑构造与常人不同，于是研究员们便出于好奇将她纳入“方舟计划”的实验当中，结果她展现出了过人的适应性，成为了最成功的实验体之一。即便拥有各领域的大量知识，超出常人的肉体能力，天瞳依然没能得到所谓的“家人”。身边的同龄人一个个离去让她的心灵遭受了极其痛苦的煎熬，因此她也逐渐开始封闭自己的心灵，直到班长的到来。",
		level_6 = 0,
		record = "请叫她“瞳姥姥”。"
	},
	[207420] = {
		soulid = 207420,
		valuation = "莲对战局的掌控力体现于她对数字的敏感度上，在把战场的所有情报进行数字化之后，她可以轻松分析出战局的走向，并尝试从中介入。与此同时「咫度天衡」本身就是一把在特定距离上可以发挥额外效果的魂器，对使用者关于“距离”的拿捏程度有相当严格的要求，正是因为莲对数字的敏感度，她才可以完美驾驭这把魂智能武器。",
		file_1 = "莲的档案库中有一小段入学测验时候的录像。「学生会会计？指名我这个刚入学的人担此重任真的好吗？我知道了……既然您觉得我能胜任，那我会尽自己最大努力去完成自己的职责。」",
		level_3 = 0,
		level_4 = 0,
		resume = "莲出身于派森，父亲是传统武术家协会的会长。莲的家族也像派森其他的武术家族一样，秉承着相当传统，或者说是相当古板的家风。即便是在这样的家风培养下，莲最终也没能喜欢上传统武术。对于她而言，感受数字在纸面上的变化与跃动可比在院子里挥洒汗水有趣多了。莲在小学毕业之后便在家自学起了会计课程，同时她也在利用自己为数不多的零花钱做一些小额投资，值得一提的是，她的资产一直处于正增长状态。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "经过一段时间的观察，学生会成员普遍表示莲是一位相当尽职尽责的会计，只要是发布给她的任务，她一定会尽最大努力完成。“有责任心”这一特质让莲获得了周围所有学员和教职员的信任。很多教职员猜测，莲是有意维持这个特质的，毕竟很少有人能做到每时每刻都对分配下来的任务带有极高的热情的，心中只要有一点不满，工作的效率就难免会受到影响。但令人意外的是，莲是在无意识中做到这一点的，也只能说——她从小受到的传统家庭教育是真的功不可没了。",
		file_3 = "由于麟和李在小时候经常会跟着大人来到莲的家中，所以她们三人从小就相识了，只不过因为李的家庭原因，莲和麟在一起玩耍的时间要更长一些。麟小时候不止一次建议莲也和她一起学习传统武术，但莲表示自己更希望学习一些“能当做饭碗”的技能，而不是迟早会被迅速发展的科技完全取代的传统武术。两人因为这件事曾经大吵过一架，但麟听不懂莲所说的道理，所以直到最后，争吵也没有以任何一个人的胜利落下帷幕。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "莲在14岁的时候便肩负起了家中的财政大权，母亲在莲很小的时候就和父亲离婚，留下莲和父亲两人生活，而父亲又经常忙着协会的工作，很晚才能回家，一直都是家中的“管家”，也就是莲父亲的弟弟，莲的“叔叔”去打理家中的各种事情。管理佣人，处理来信等等，懂事的莲看着叔叔忙里忙外，自己也想为家里担负起一些事情，由此便揽下了算账一事。最初只是打理佣人们买菜和生活用品时候的支出费用，后来渐渐地整个家庭中的大小账目就都归莲来管了，她也被戏称为家里的“财政大臣”。在那之后，莲也确实没有辜负家中所有人的期望，完美地履行了自己“财务大臣”的使命。",
		level_6 = 0,
		record = "有着很强责任心的学生会会计。"
	},
	[207520] = {
		soulid = 207520,
		valuation = "尤尔夏的作战能力有些让人一言难尽，虽然整体来看各项参数都很优秀，但不知是因为什么原因，她的投掷命中率相当堪忧，比起投掷，她直接用魂智能武器去砍可能效果会更好，但无论是周围人还是辛西娅去劝，她都表示自己作为忍者，必须使用暗器。希望她的投掷技术在日后的训练中能有所进步吧。",
		file_1 = "尤尔夏的档案库中有一小段入学测验时候的录像。「在下……在下也没想到自己能入学啊……本来只是为了叫辛西娅大姐头回去的，谁知道突然就被拉来测试了。」",
		level_3 = 0,
		level_4 = 0,
		resume = "尤尔夏是拉弥亚黑街辛西娅势力中的一员，是在辛西娅刚刚崭露头角的时候便开始追随她的元老级组织成员。放眼整个组织，尤尔夏的战斗能力算不上特别出彩，这主要是因为她执著于采取忍者的战斗方式（她自己认为的）。其他成员不止一次说过，如果她用正常的战斗方式，应该能有更加出色的表现，但尤尔夏对此充耳不闻。辛西娅本来也想劝说尤尔夏，但作为组织首领又不好意思泼她的冷水，最终在辛西娅对她说了“你开心就好”之后，尤尔夏更加坚定了自己的信念，决心踏上成为最强忍者的道路。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "尤尔夏入学之后，除开和辛西娅在一起的时间，基本上都是在训练场观看刃隐铃兰和风魔胧的战斗训练。她本人称自己是在观察其他忍者的战斗方式，但遗憾的是，无论她多么认真地去观察，自己的命中率也没有得到一丁点提升。",
		file_3 = "虽说尤尔夏是拉弥亚黑街辛西娅势力中的元老级成员，但因为辛西娅组建势力的时间也不长，所以实际上和其他成员加入的时间也没差多久。不过尤尔夏一直以此为荣，认为自己很早就发现了辛西娅的领袖魅力并决定跟随她是相当明智的选择。因此在辛西娅离开黑街前往魂器学院的时候，尤尔夏受到的打击是最大的。不过她也是所有成员中最冷静的，她坚持认为辛西娅并没有抛弃黑街的大家，并努力去稳定住整个辛西娅势力，最终在她的努力下，虽不及辛西娅离开之前，但辛西娅势力大体上维持了一定程度的力量。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "有关尤尔夏，辛西娅在院长的询问下解释道：「要是让我从自己以前的手下里挑一个人接替我的位置，其实我也只能想到尤尔夏。我在离开黑街之前没有将首领的位置交给她，是因为当时她还没法让大家信服，组织成立本来就没多久，当时也有很多新成员，他们的忠诚心主要是面向于我的，在他们眼里，尤尔夏就是个整天只想着忍者的怪丫头。不过，在我离开黑街的这段时间，一直是尤尔夏和我的其他几个心腹负责打点组织的，尤尔夏对组织尽心尽力的姿态也被其他人看在了眼里。现在已经没有会怀疑尤尔夏的人了，所以我能放心地把组织交给她了。」",
		level_6 = 0,
		record = "渴望成为最强忍者的黑街少女。"
	},
	[22130] = {
		soulid = 22130,
		valuation = "伊卡洛维的实战能力很强，天生附带的异化让她可以在各种场合发挥实力，但本人的战斗意识太差，战斗风格粗暴，不适合团队作战和精密任务，想要让她成长必须要长期的思想培养。",
		file_1 = "在《弗洛伊德结构理论》中将心理拆分为本我、自我、超我三大部分。而在她这边，本我的部分要远超其他二者总和，简单来说就是想到什么就做什么，对自己没有什么较大约束，从侧面也可以看出伊卡洛维善良的本性。不过也因为这点，伊卡洛维在战斗的场合会陷入极度疯狂的状态，以至于敌我不分。 自我约束力弱的负面体现在她生活的方方面面，只要有喜欢的东西就会贴上去，讨厌的东西会马上动手解决掉。这样直率的个性不适合执行复杂的任务，建议从基础部分开始学习。",
		level_3 = 0,
		level_4 = 0,
		resume = "伊卡洛维·罗伊汀，库库尔坎出身，因过去母亲遭遇了辐射泄漏事故，导致腹中的伊卡洛维异化，具备了动物的野性与力量。但这并不属于变异的范畴，现今社会对辐射早已做到了清洁化、去污染化，所以可以断定那场事故并不是伊卡洛维异化的主要原因。 伊卡洛维十分天真乐观，身边的人对她都持有正面印象，不过因为她的精力过于旺盛，也会让人有些跟不上她。精神方面略微稚嫩，是那种在陌生环境就会不安，会主动寻找安全感的孩子。 现阶段十分依赖班长，经常跟着他出入各种场所，近期对班长的风评将会重新统计录入。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "伊卡洛维的依赖性可能是源自童年的被抛弃经历。当时，她的父母还不能接受这样的一个孩子，两人一致认为没有伊卡洛维对今后的生活会更好，所以就将她遗弃在了两公里外的一处废弃机械工厂内。 凭借着异化后的嗅觉，年幼的伊卡洛维依然找到了回家的路，因为愧疚，父母最后还是没能忍心将她再次抛弃，好好地将其抚养长大。 结果虽然是好的，但这个经历却导致了伊卡洛维心理上的孤独和恐惧。 目前，班长这一角色正好弥补了她对安全感的渴望。",
		file_3 = "从伊卡洛维身上发现了名为“野性”的东西，这就是导致她在战斗中会陷入狂暴状态的罪魁祸首。我们尝试用药物压制“野性”，但可惜因为做得太难吃了，导致她没能完整吞咽下去。 伊卡洛维的不配合，使得药物的数据采集十分艰难，希望下一次医疗部门能做出番茄味的药丸来……",
		level_7 = 0,
		level_2 = 0,
		file_4 = "对伊卡洛维的基因检查结果为：基因片段中有两组被精密的手术重新组合，导致部分身体特征出现返祖现象。 可能……伊卡洛维在无意间成为了某个组织的牺牲品，不过在调查伊卡洛维家庭背景和父母人际关系的时候，并没有找到可疑的对象；我们对此提出了两种假设：1、只是当年的某个妇科医生的一时兴起。2、某些隐藏在社会深层的势力还在筹备着属于自己的特殊军队。 无论哪种，都不是什么好事……",
		level_6 = 0,
		record = "因为什么都知道，所以才要装作什么都不知道，否则又会像小时候那样被抛弃掉吧？ 大家都在笑着，所以……哭泣的人只要有我一个人就好了。 这是什么都做不到的我，唯一能够做到的事情了……"
	},
	[207720] = {
		soulid = 207720,
		valuation = "桃子是时隔许久才出现的水性优秀的学员，各项能力虽没有特别出众的，但都在及格线之上。我们计划将她分配到刻罗的小队，但有点担心以她的性格能不能顺利融入进去，毕竟刻罗对于自己小队的管理方式有些过于严格了。顺便一提，我们发现她似乎对于自己的魂智能武器有点耿耿于怀的样子，这可能会对后续的作战带来一些负面影响。",
		file_1 = "桃子的档案库中有一小段入学测验时候的录像。「唔……如果可以的话，桃子想要更帅气一点的魂智能武器的……像伊卡洛维那样的，挥起来咻咻咻的那种。」",
		level_3 = 0,
		level_4 = 0,
		resume = "桃子是洛加尔东部地区七十七里海峡附近的一处海之家饭店老板的女儿，从小就在海边生活，与海为伴。平时要么在店里帮父母卖炒面，当服务员，要么穿上潜水服，在海边当救生员。店里的工作不忙的时候，她会自己去海边玩耍，或者窝在自己的房间里整理自己从海里捞上来的“宝物”——一些金属制品，还有一些海洋里的稀有植物。其中她最喜欢的就是自己之前从近海发现的一种奇妙的咸水迷你球藻。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "入学之后，桃子的球藻繁殖计划在拉普拉斯的帮助之下进行得十分顺利，不过后来由于球藻的繁殖速度远远超过预期，桃子不得不找拉普拉斯再做一些生长抑制剂。就结果而言，除去桃子赠送给其他学员的那部分，过剩繁殖的球藻全部都被拉塔莉亚拿走当作动物饲料了。",
		file_3 = "桃子持有洛加尔一级潜水员资格证，但这不代表她只有一级潜水员的潜水技术，只是因为年龄不够所以无法进行下一个等级的测试而已。自小生活在海边的桃子早就已经对大海了如指掌了。平时她自己也会穿上潜水服，到附近的海域去寻宝，不过，因为附近的海域早就作为旅游景点被开发过了，她也只能找到一些比垃圾略好一点的东西，偶尔捞到一些别人不小心掉到海里便决定抛弃的电子设备还能发一笔小财。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "院方经过家访发现，桃子家开的海之家饭店平时的生意相当好，这其中有很大一部分原因是桃子的努力。生活在附近的主要是在港口上班的工人或是世代打渔为业的渔民，都是本地人，他们或多或少都见证了桃子从小到大的成长，有的人也把桃子当做自己的女儿一般宠爱。所以在工作疲惫的时候，他们偶尔就会来到海之家，看看桃子充满活力的模样，让心灵得到治愈。因此，桃子家的海之家有着大批的忠实客户做基础，而在这基础之上，游客们在看到这里“顾客络绎不绝”的样子后，也会认为这是一家相当不错的饭店，在这种从众效应的影响之下，桃子家的生意一直很兴隆。",
		level_6 = 0,
		record = "酷爱寻宝的海边少女。"
	},
