	[207620] = {
		soulid = 207620,
		valuation = "安特蕾丝的综合实力并不能算得上优秀，在诸多学员之中也只能排在中等程度，只不过她相比于其他学员有着更加单纯且明确的目标和决心，并且拥有极强的正义感，因此她的成长性相当值得期待。最开始说她出身于基金会“第四银河”部队时我还有些担心，但看来是我有些多虑了。",
		file_1 = "安特蕾丝的档案库中有一小段入学测验时候的录像。「魂器学院的学员们一直在战场的最前线战斗，我也希望能加入其中，为了守护人类的和平，成为人们的依靠，我一定会努力的！」",
		level_3 = 0,
		level_4 = 0,
		resume = "基金会特殊战斗部队“第四银河”的成员，行动代号为“安特蕾丝”，亦即是天蝎座最亮的恒星——心宿二，是第四银河部队当中最后一个加入的成员。安特蕾丝从小便很喜欢看特摄剧，十分憧憬特摄剧当中每逢危难便及时挺身而出的英雄们，她也以成为英雄作为自己的人生目标。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "安特蕾丝在入学第二天就已经在商店街的甜品店注册成为会员了，并且在短短的30天内就靠消费成为了黄金会员。她对于甜品的执著有些出乎我们的意料，虽然有些学员表示“她迟早会发胖的”，但实际上经过长期的观察，安特蕾丝的身体状况一直很健康，多余的糖分似乎都被有效地转化为了能量，在战斗中消耗掉了。",
		file_3 = "第四银河是基金会的“门面部队”，基金会并不需要她们取得多大的战果，打倒多强的敌人，只需要她们在战场上足够活跃即可。通过少女们的活跃表现提高社会对基金会的印象，这才是他们的本来目的。正因是门面部队，基金会才会投入大笔资金去打造她们，为她们提供优渥的环境，并且尽量满足她们的要求，按照类似于偶像的标准去个性化定制她们的装备。因此她们也有一个带有讽刺意味的绰号——“星星公主”。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "布克丝并不觉得基金会希望让自己的门面部队参与最前线战斗，因此在私下里进行了调查，发现这次安特蕾丝的入学很可能有基金会上层的某个人士在暗中推进，但具体目的不明。只不过，安特蕾丝是真心对能入学魂器学院感到开心的，因此布克丝决定暂且不进行后续调查，但会在必要时候对安特蕾丝提供保护。",
		level_6 = 0,
		record = "憧憬着成为英雄的单纯少女。"
	},
	[205420] = {
		soulid = 205420,
		valuation = "梅尔菲娜作为异化人，本身的战斗天赋就已经相当出色了，再加上长久以来的不懈锻炼和实战经验，她在对人战中拥有相当恐怖的统治力，几乎没有学员能在一对一的战斗中战胜梅尔菲娜。",
		file_1 = "梅尔菲娜的档案库中有一小段入学测验时候的录像。「你们的事情我已经听芙蕾大人大致说过了，今后如果有需要我出力的地方尽管说就完事了，还有那啥，我对芙蕾大人挺在意的那家伙也有点兴趣，主……主要是想看看那家伙是不是配得上芙蕾大人的人！如果那家伙是个缺乏起量的小人的话，就算强来我也要让那家伙远离芙蕾大人！」",
		level_3 = 0,
		level_4 = 0,
		resume = "梅尔菲娜曾是一名弃婴，被洛加尔的黑道组织「坂上组」的组长所收养，但两人并非养父女关系，坂上组的组长也没有太多时间去照料她，因此她可以说是在整个坂上组所有人的照料下成长起来的，整个坂上组都是她的家庭成员。但梅尔菲娜知道，自己作为一名女性，在坂上组内能得到这样的待遇是相当破格的，同时内心中也对坂上组的其他人产生了强烈的愧疚感，这一愧疚感促使她想要成为他人的力量，并且每日不断磨炼自己。最后，梅尔菲娜凭借着异化人的身体优势和不懈锻炼成为了坂上组的中坚力量，因此在坂上组被整治之时，被月和会的人看中，将其吸纳进了月和会当中，成为了芙蕾的影子护卫。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "经过一段时间的观察，我们发现梅尔菲娜虽然平日总是展现出一副难以靠近的凶狠样子，但其实在她的内心深处潜藏着相当纤细的少女心，有学员见到她在一些不太会有人经过的场所盯着自己的个人终端看，时不时还莞尔一笑，也有不知名的水原堇同学表示在近期颇有名的少女漫画《被放逐的恶役公主与永生不灭的最强勇者》的单行本签售会上见到了梅尔菲娜的身影。尽管她本人对自己的少女心矢口否认，但遗憾的是，在她经常出入拉塔莉亚的动物园这件事被发现时，她的少女心就已经在整个学院当中人尽皆知了。",
		file_3 = "梅尔菲娜是直属于芙蕾的影子护卫中实力最为强大的人，因此名正言顺地排在了影子护卫中的第一位。虽说实力很强，但梅尔菲娜自身的生长环境比较独特，行事总是有些大大咧咧，给人粗枝大叶的印象。没有让实力最强的她陪同芙蕾入学魂器学院一方面是因为她的性格，一方面是因为她有任务在身。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "梅尔菲娜曾经所属的「坂上组」与其说是黑道，其实更像是当地的非官方保安组织，在洛加尔最为混乱的时期，一些较为贫困的地区的人们生活艰难，经常成为被剥削对象，而坂上组则为他们提供了庇护伞，平时也会积极帮助附近居民做一些义务劳动，深受当地居民的喜爱，但也因此，坂上组受到了其他黑道组织的打压，从平日活动到组织资金来源的房地产贸易，都变得逐渐艰难起来，在这种状况下，坂上组的组长决定寻找靠山，最终与芙蕾的家族谈妥，由月和会吸纳坂上组，对外则是宣称「被整治」以瞒过其他黑道组织。就结果而言，月和会接管后的地区更加安宁，坂上组也成为了月和会的附属组织，在市井当中为月和会收集情报。月和会为拯救坂上组所做的举动深深打动了梅尔菲娜，梅尔菲娜也为芙蕾的个人魅力所折服，在坂上组组长的支持下，梅尔菲娜便加入月和会，成为了月和会的一员。",
		level_6 = 0,
		record = "外表强横，实则少女心泛滥的可爱女生。"
	},
