	[207320] = {
		soulid = 207320,
		valuation = "最近战斗方式奇特的学员越来越多了，提可也不例外，只看她的武器完全想象不到她是如何进行战斗的，但实际上她确实能用那看上去很像喷枪的魂智能武器戏耍敌人。因为经常穿行于巴哈姆特街头进行艺术创作，所以她的身体素质比我们想象中要好很多，灵巧而又敏捷。",
		file_1 = "提可的档案库中有一小段入学测验时候的录像。「入学理由吗？没什么特别的，因为巴哈姆特那边已经不适合我待下去了，我得找个新的场所罢了。」",
		level_3 = 0,
		level_4 = 0,
		resume = "提可出身自巴哈姆特的一个普通家庭，但由于她的兴趣爱好过于特殊，经常会让父母感到头疼，但她的父母又不得不满足女儿的愿望，所以她们允许提可独自搬出去住了。在独立生活之后，提可得以有机会接触更多东西，也有了更加丰富的灵感去完成自己那前卫的艺术画作，久而久之的，她就成了巴哈姆特的一位知名前卫艺术家。有传闻说，耶梦加得的“热带水果派”二人组就是受到了提可的启发，从而开始进行街头涂鸦的。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "提可在巴哈姆特的名气始于她的立体画作和涂鸦，很多人认为她用喷枪和画笔传达出人们难以言说的苦闷，能引发大家的共鸣。但对于提可而言，那些具有特殊“意义”的画作并非刻意而为，只是因为她认为当时的氛围应当画出这样的作品，就此便可以看出提可是一个拥有艺术天赋，并且对环境很敏感的女生。但有趣的是，她能理解氛围，但却无法顺应氛围去做出不破坏氛围的事，可以说是一个毫无自觉的氛围破坏者。",
		file_3 = "提可的父母对提可的的成长感到十分开心，但也有些失落，他们总是觉得，自己二人对于女儿而言是妨碍她在艺术之路上前行的绊脚石。提可在专心投入到艺术当中时，根本无心在意周围的情况，这种极端专注的做事方式被认为是天才的特征，与学院中的索菲亚情况有些相似。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "提可离开巴哈姆特的最主要原因是担心她的父母。因为提可已经有了一定的收入，所以她想和某个公司签约，靠签约费和自己的积蓄让父母搬家到治安较好的地区，但她的父母却有些犹豫，因为搬家会带来比较大的经济负担，这些经济负担如果都压在提可身上的话，他们认为自己作为父母会心中有愧。",
		level_6 = 0,
		record = "电波系天才艺术少女。"
	},
