	[204330] = {
		soulid = 204330,
		valuation = "幼小的身躯格外灵巧，肉眼可见长大后是个担任机动性工作的好手。攻击能力并不强，但毕竟是个孩子，也不能要求甚多……",
		file_1 = "诺比的家庭自上世纪起就在北极地区经营着矿产开发，是当地有名的富户。\n因为家庭观念开放，在诺比的教育问题上，诺比的父母和姐姐们更多采取“鼓励教育”的态度，鼓励诺比去尝试新事物，去接触新世界，这让诺比养成了勇于探索未知的性格。\n诺比能够养成现在这样赤诚待人的性格和她的家庭环境脱不了关系。她的父母从未对自己的小女儿有过多的要求，只希望她一生平安喜乐万事如意就很好。",
		level_3 = 0,
		level_4 = 0,
		resume = "诺比·奥罗拉的家乡在遥远的北冰洋沿岸，在那个冰天雪地的世界，极夜时常常可以看到波澜壮阔的极光与星空。\n诺比家境优越生活富足，是父母最宠爱的小女儿，更别说她还有五个宠妹妹的姐姐，可以说是在爱的浇灌下健康茁壮成长的小树苗。\n虽然生长在大海边缘，但诺比对天空与星辰充满好奇与向往。在第一次仰望星空后诺比就被星辰的美丽震撼，星座与银河，神秘与未知，这些隐藏在宇宙中的奥秘瞬间点燃了诺比充满探索欲的心灵。从那一刻起，小小的诺比给自己漫长的余生定下了一个大大的目标——触摸天空，征服星辰大海！\n在这个战乱年代，拥有纯真与赤诚并能健康长大的孩子如凤毛麟角，而诺比幸运的成为了其中的一个。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "诺比从小就表现出超于同龄人的懂事。虽然家中很有钱，但诺比花钱并不大手大脚，也并不理所当然地觉得家中的钱就该给自己用来实现航天梦。反而觉得自己的梦想应该只靠自己去实现。\n诺比喜欢将自己的压岁钱存起来有规划的使用——大部分花在天文望远镜的保养上了。她还很喜欢收藏一些关于宇宙星空的文化产品：漫画、小说和纪录片，在晚上藏在被窝里反复观看，可能就是因为这个原因，诺比才有点近视小小年纪就戴上了眼镜吧。",
		file_3 = "“我要成为宇航员！”——这是诺比每一次观星后都会冲着广阔星空大喊一声的台词。虽然自家姐姐大多认为自己成为宇航员畅游太空的梦想根本不可能实现，但是诺比却丝毫没有受到打击，反而愈发坚信自己终有一天能实现这个伟大梦想！\n诺比的姐姐们没想到的是，如今距离诺比树立成为宇航员的梦想已经过去三年了，这个梦想不仅没被诺比忘记，她还有模有样做出实现梦想的计划，并一步步为了梦想而前进。\n诺比是个探索欲望非常强烈的孩子，对她来说，星空充满了神秘和未知的色彩，实在是充满了吸引力，这让她愿意倾其所有精力去追寻。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "来到魂器学院后，布克丝十分鼓励诺比追求“星空梦”，特意为诺比的左眼移植了“聚焦芯片”，一只眼睛便是一架微型天文望远镜。\n凭借着外形软萌可爱，与人交往赤诚活泼，诺比很快得到学员们的喜爱。更让人意外的是，一向沉默寡言的电波少女露缇竟意外的与诺比聊得过来（虽然二人聊天从来不在一个频道），两人聊天的画面虽然滑稽可笑，但却十分和谐，院长便顺水推舟将二人安排在一块。",
		level_6 = 0,
		record = "诺比对星空的爱已经到了狂热的地步，身边的生活用品几乎都是星空主题。"
	},
	[208720] = {
		soulid = 208720,
		valuation = "相比于其他20岁以上的学员，娜塔莎的身体素质相当优秀，这或许与她在孤儿院的时候经常下地做农活有关。体力方面几乎无可挑剔，战斗方面的嗅觉稍有欠缺，但这应当只是缺乏经验导致的，希望能通过日后的训练弥补她的弱项。（监考官碎碎念：娜塔莎不是以宿管的身份被招进来的吗？连宿管都要这么卷，那我们……）",
		file_1 = "娜塔莎的档案库中有一小段入学测验时候的录像。「我知道你们并不欢迎我，但这是我的任务，希望魂器学院的各位能够理解。我会尽量不给大家添麻烦，做到自己所能做到的一切，但……但是！如果我发现这个学院存在不纯洁的男女关系，一定会出面制止的！」",
		level_3 = 0,
		level_4 = 0,
		resume = "娜塔莎来自耶梦加得的图里昂孤儿院，在身为孤儿院院长的同时，娜塔莎也是归属于教廷的修士。她有着对教廷信仰的忠诚，却也明白只靠单纯的信仰无法改变人们的生活，因为孤儿院中的孩子们便是如此。即便如此，娜塔莎也不得不依靠教廷给出的微薄资助金生存。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "入学一段时间后，学员们对于娜塔莎的态度有了很好的改善，因为这位大姐姐虽然总是絮絮叨叨，但却是真心实意地在关心着她们，作为宿管的能力无可挑剔。因为在孤儿院时就经常成为孩子们倾诉的对象，娜塔莎在来到魂器学院以后也经常作为倾听者去开导学员们，化解学员们之间的一些小矛盾。",
		file_3 = "娜塔莎曾毕业于耶梦加得一所知名学府，原本可以拥有一个更加光明的未来，但她选择了继承父亲的孤儿院。那之后不久，娜塔莎的父亲病逝，但现实没有留给她太多为父亲的离世而感到悲伤的时间，打理孤儿院的重担立刻便压到了娜塔莎的身上。为了维持孤儿院的正常运作，娜塔莎白天不得不外出干活，或是打打零工，或是整理田地，晚上回到孤儿院照顾孩子们，其中年龄较大的孩子主动分担了一部分打扫的工作，年龄较小的孩子也十分懂事，不会耍性子。这让娜塔莎省了很大的精力，在感谢孩子们的同时，娜塔莎内心的自责感也更加强烈了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在教廷与魂器学院产生接点之后，教廷需要一个在名义上所属教廷，却又对教廷无关痛痒的人作为教廷的特派监察员监控魂器学院，而执行这一任务的最好人选就是把柄握被抓在教廷手里的娜塔莎。不仅是金钱方面的把柄，教廷甚至可以用孤儿院的孩子们当人质进行威胁，娜塔莎根本无法忽视他们的命令。但在班长的努力之下，现在已经没有这种担忧了。",
		level_6 = 0,
		record = "经营着贫穷孤儿院的修士。"
	},
	[209020] = {
		soulid = 209020,
		valuation = "又是一位来历相当奇怪的学员，身体能力出奇的差，最基础的俯卧撑和仰卧起坐都做不了，又不像是有什么疾病缠身的样子，想来一定是过于依赖科技从而疏于提高自身的身体素质。并且她的性格十分狂妄，喜欢嘲讽敌人，很容易被敌人集中攻击，我有些担心她能不能在战场上存活下来。",
		file_1 = "档案已被黑洞吞噬。",
		level_3 = 0,
		level_4 = 0,
		resume = "档案已被黑洞吞噬。",
