	[209820] = {
		soulid = 209820,
		valuation = "真是不可思议的力量，此前我们一直以为洛加尔的神社巫女拥有神秘力量只是个传说，没想到竟然是真的。即便不借助魂智能武器，真寻也能运用名为“结界术”的力量保护别人，虽然暂时还缺乏实战经验，但她已经展现出了相当程度的实力，期待她以后的表现。",
		file_1 = "在巳守真寻的档案中有一段关于她入学时的采访——「入学理由吗？因为我觉得自己的力量能帮到大家——说好听点是这样吧，但我也并不是没有一点私心，如果能通过我的努力让大家知道洛加尔仍有一些神社存在，或许神社以及和神社相关的文化就能传承得更久了。」",
		level_3 = 0,
		level_4 = 0,
		resume = "巳守真寻的老家是位于洛加尔的巳守神社。神社至今已经有几百年的历史，原本是附近地区的居民每到新年都要前去参拜的地方，但随着时代的推移，会去参拜的人已经越来越少了。而其他神社中，有相当一部分新一任家主放弃继续维持神社，所以至今为止洛加尔境内的神社已经寥寥无几，“巫女”更是成为了旧时代文化的代名词，仅仅出现在动漫等影视作品当中。巳守真寻正是在这个时代背景下接替了巳守神社巫女的职位，从小接受巫女教育的她拥有很强的正义感和奉献精神。在天赋与努力的结合之下，她很小便掌握了巳守一族的结界术，时至今日，她的结界术已经抵达了历代巫女中数一数二的水平。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "据巳守真寻的父母讲述，巳守真寻小时候是一个相当顽皮叛逆的假小子，也是当地知名的孩子王。起因是她偶然看到一群和自己同龄的孩子欺负一个年纪更小的孩子，于是出手教训了他们，自此她便作为大哥被当地的孩子们仰慕着，直到她上了初中，穿上校服以后，那些孩子才彻底知道她其实是女生。",
		file_3 = "因为小时候的巳守真寻对于神社相关的事情相当反感，其父母一度认为神社的未来可能会断送在这一代，但从巳守真寻的妹妹出生以后，巳守真寻的性格就变得慢慢乖巧起来，就连她的父母都不知道她的心境产生了怎样的变化。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "巳守真寻对于妹妹——巳守千寻可以说是相当溺爱，从小时候帮妹妹换尿布，一直到妹妹长大点了以后接送她上幼儿园。不过因为巳守千寻从小就很懂事，并且相当早熟，所以她那“好姐姐”的形象并没有保持多久。",
		level_6 = 0,
		record = "是赛博巫女。"
	},
