	[209620] = {
		soulid = 209620,
		valuation = "霓昂是首个使用定制版“素体”的学员，在实战表现中的成绩相当出乎我们的意料，借助素体的强力机能，霓昂可以发挥A级以上水平的身体能力，在保证自身安全的状态下走上战场，同时因为霓昂拥有极高的魂智能网络适性，即便是通用魂器，她也可以将其能力发挥到极致。可惜素体目前制作成本较高，并且可使用时长会根据魂智能网络适性变化，等解决了这两个问题，战争的格局应当会出现翻天覆地的变化吧。",
		file_1 = "目前，整个学院当中能24小时不间断使用素体的人只有霓昂，其余学员都会依据自身魂智能网络适性在2-4小时内出现头晕的状况，不得不远程脱离，考虑到在欧西利亚联邦这一陌生地区展开调查行动，并且要保障班长的安全，布克丝不得不允许霓昂以战斗成员的身份一同前往。",
		level_3 = 0,
		level_4 = 0,
		resume = "霓昂是拉姆齐集团的大小姐，但她的过往经历却有很多难以查明的地方。并从小就被确定患有极其罕见的“超忆症”，即便是在所有超忆症患者之中，霓昂也属于相当特殊的一类，她本人，包括她的父母和亲戚都不曾知晓到底是什么因素导致的。在身体每况愈下，距离脑死亡只有一步之遥时，布克丝提出将她的身体冷冻，通过将她的意识接入“战斗用素体”来延续她的生命。在得知班长将要前往欧西利亚联邦时，她表示自己也要一同前往。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "据霓昂的父亲所说，霓昂小时候为了治愈超忆症而被送到了自家旗下的一家医疗机构。但因为长时间治疗无果，病症甚至还加重了，于是霓昂的父亲便将霓昂接了出来。在那之后，为了他们又辗转多家医疗机构为霓昂进行诊断，也找了专门研究超忆症的领域专家，当时专家得出的结论是：“除了超忆症以外，还有一种神秘的疾病在不断蚕食霓昂的大脑。”",
		file_3 = "随着年龄的增长，霓昂的大脑所承受的负载也越来越大，为了减少这一负载，霓昂的父亲将她送到魂器学院，布克丝用手术为她植入了可获取视觉信息的芯片，如此一来就可以在不影响她对物体颜色分辨能力的前提下让她的视野变成黑白色。在确定有效果后，布克丝也为她的其他感官安装了类似的设备，比如可过滤掉绝大无用声音信号的助听器，可阻断嗅觉信息向大脑传递的神经装置，以及伪装成棒棒糖的可以暂时性麻痹味觉的药物。除此之外，布克丝还为霓昂制作了一个可以实时监控情绪波动的装置，也就是霓昂手腕上带的小灯泡，在检测到霓昂的强烈情绪波动时，会发出光亮来提醒她，以防止强烈情绪下产生的记忆为她的大脑带来不良影响。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "霓昂的魂智能网络适性是有史以来最高的，但她的灵匙却无法顺利生成魂智能武器，布克丝也不清楚究竟是什么原因导致的，只能认为是霓昂所患有的另一种神秘的疾病所导致，并且直到今天也在不停进行研究。",
		level_6 = 0,
		record = "唯独你，是她无论如何都不想忘记的。"
	},
