	[209720] = {
		soulid = 209720,
		valuation = "解构心核从能力上来讲，其强度应该取决于作用的机械，但实际上据贝尔本人所说，解构心核并不能适用于所有机械，我们最初预想的让她开着Tis-35单兵作战坦克进入战场的计划无法执行，只有她亲手打造出来的机械才能与解构心核产生共鸣，也就是说，随着贝尔的不断学习和成长，她的实力也会得到相应的提升，就成长性而言，贝尔应该是魂器学院中最值得期待的学员了吧。",
		file_1 = "在贝尔的档案中有一段关于她入学时的采访——「我知道，我家里很穷，我自己又没什么特长，像魂器学院这样的地方能免除学费收我入学，这样的机遇肯定是我一生中都不会再遇到的，我一定会好好珍惜这次机会，努力学习的！」",
		level_3 = 0,
		level_4 = 0,
		resume = "贝尔原本出身于玛尔斯，但在人工智能叛乱期间被父母抛弃。被一位素不相识的老妇人收养之后，随着老妇人一起来到了欧西利亚联邦的里德。天性阳光的她并没有因为被父母抛弃而沉浸在悲痛当中，从她到能帮忙做家务的年纪开始，她就一直希望为收养了自己的“奶奶”做些事情。由于她的梦想是成为机械工程师，所以她平时就有在用垃圾场里收集到的金属废料拼装一些小玩意，并且把这些小玩意放到奶奶的小卖部里进行售卖，一方面能锻炼自己，一方面能减轻家里的经济负担。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "据院方调查，贝尔在学校里的成绩算不上优秀，准确来说她是一个极度偏科的孩子，数学的成绩始终维持在年级第一，但其他科目的成绩就一直维持在中等水平，因为并没有到需要“特别提醒”的程度，所以学校老师只是略微有些关注这个有些特别的孩子。",
		file_3 = "贝尔在机械工程方面有着相当高的天赋，并且经常向索菲亚和缇利亚请教技术相关的问题，深得两人的喜爱。爱丽丝打算向贝尔抛出橄榄枝，她表示如果贝尔能一直坚持不懈地学习下去，等到她从魂器学院毕业的时候，就把她引荐给鲁比克财团旗下的工程部负责做航空器相关的技术研发。对于贝尔来说，这也算是未来的出路得到了保障，即便只有10岁，贝尔也知道自己能走到这一步，得到这么多人的青睐是多么来之不易的一件事，每天更是加倍努力地学习，甚至到了让人有些心疼的地步。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "贝尔的奶奶也不是欧西利亚联邦的本地人，而是在战争中从耶梦加得移居过来的战争难民，因为掌握了一点人脉，并且是首批在里德城居住的人，所以在当地居民中有颇有名望，能维持小卖部的运作也是全靠了移居到其他城市的人提供的货源。虽然挣得很少，但要维持和贝尔两人的生活并不困难。不过近几年，贝尔的奶奶身体日渐虚弱，虽然没有大毛病，但小毛病不断，对她这个年纪的老人而言也是相当吃不消的，所以贝尔一直想着以后挣大钱，带奶奶去大城市。不过，贝尔的奶奶并不希望离开里德，至于是什么原因，贝尔的奶奶并没有明说。",
		level_6 = 0,
		record = "腿粗是异化人的种族因素！"
	},
