	[210720] = {
		soulid = 210720,
		valuation = "露露姆的魂智能武器十分特殊，并非像其他绝大多数学员的那样偏向战斗，而是更偏向于生产。生产型的魂智能武器目前为止学院中也仅有以索菲亚、缇利亚等人为首的廖廖几个，我们最初对她的魂智能武器抱有相当高的期待，但最后发现她的魂智能武器只能生产出一种特殊的焦糖，可以治愈被焦糖喷洒到的人，但问题在于它和一般的焦糖一样，也会让粘上的人变得黏黏的，所以其他学员对于被露露姆治疗这件事颇有微词。",
		file_1 = "露露姆的档案库中有一小段采访时候的录像。「诶？是说我有魂智能网络适性？啊这……我对这种没什么了解，这是比较幸运的，值得高兴的事情对吧？没什么实感啊……总之，如果是入学魂器学院的话，我爸妈应该也会同意的。」",
		level_3 = 0,
		level_4 = 0,
		resume = "来自洛加尔的天才甜品师，在去年举办于洛加尔的世界甜品师大赛中脱颖而出。虽然由于个中原因导致一些世界知名甜品师没能参赛，但露露姆能在比赛中拔得头筹也是相当值得称赞的。露露姆的父亲经营着一家蛋糕店，露露姆从小便在给父亲打下手，并逐渐对甜品产生了浓厚的兴趣，梦想是将来可以开一家自己的蛋糕店，用甜品将幸福分发给全世界的每个人。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "露露姆对甜品的兴趣始于小时候父亲在她因为生病而哭个不停时亲手给她做的甜甜圈。甜甜圈的美味甚至让当时的露露姆连哭都忘记了，等她全部吃完以后，她才意识到这一点。自此，露露姆便产生了“甜品是给人带来幸福”的认知，并正式开始学习甜品相关的知识。",
		file_3 = "露露姆参加的世界甜品师大赛曾经是每年都要举办的，但在XMAS事件之后，出于安全和时局状况考虑，主办方宣布暂时停办。在后来魂器学院等各方势力的努力下，时局逐渐稳定，世界甜品师大赛得以重新举办。但此时主办方向世界各地知名甜品师送去的邀请函却大多都吃到闭门羹，对方给出的理由是“考虑到自己的人身安全，本次选择不参与”。因此这一届世界甜品师大赛也被认为是最没有含金量的一届。话是这么说，但仍旧有来自全世界的235名甜品师参赛，其中不乏一些知名餐厅的甜品师，而能在这之中脱颖而出，足以见得露露姆自身的天赋与实力。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "露露姆的父亲其实一直希望她能继承自己家的甜品店，但露露姆却表示继承父亲的店没有任何意义，她要自己新开一家只属于自己的甜品店，然后把父亲的甜品店干倒闭。",
		level_6 = 0,
		record = "为了让别人更好地记住自己，露露姆特意去做了挑染。"
	},
