	[210820] = {
		soulid = 210820,
		valuation = "佐久夜的表现完全看不出来是在家里宅了很久的样子，不光拥有极高的身体素质，还有相当敏锐的战斗直觉。值得一提的是，佐久夜对于切断敌人没有丝毫的犹豫，更不要说抵触了。很难想象她曾经其实是一个相当温柔腼腆的孩子。",
		file_1 = "佐久夜的档案库中有一小段采访时候的录像。「命运，我相信一定是命运的引导，我才能和我的白马王子相遇！我绝对不会放手的，我们要一生都在一起,呵呵~」",
		level_3 = 0,
		level_4 = 0,
		resume = "来自洛加尔的一位外表看上去很普通的少女，初中时期曾经遭遇校园欺凌，因此变得闭门不出。后来经过心理医生的治疗，精神创伤得到了好转，也渐渐愿意走出家门了，但性格却产生了巨大的转变。走出家门的佐久夜变得看上去外向了一些，也开始喜欢穿着打扮了，但其实她身边的所有人都清楚，她现在的状态有些不正常，或者说已经到了病态的地步……",
		level_1 = 0,
		level_5 = 0,
		file_2 = "佐久夜对于班长的执著已经到了有些病态的地步，她那扭曲的情感并非是“爱”，更像是其他某些感情的体现。事实上，佐久夜并非不会站在他人的角度思考问题，她只是在对方的感受和自己的主观认知中选择了遵从自己的主观认知，明明知道对方会因此而感到困扰，但仍然选择了按照自己的做法行事。这种扭曲的心理才是让佐久夜看上去病态的罪魁祸首，目前已经调用了学院的心理医生对她进行辅导，不过效果微乎其微。",
		file_3 = "佐久夜的父母对于佐久夜的精神状况一直有些担忧，他们虽然也希望佐久夜恢复正常，但担心过于强硬的矫正会导致佐久夜的精神再度恶化。对比起那个一直窝在家里日渐消瘦的状态，佐久夜的父母还是觉得她现在的样子更能接受。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在经过一段时间的观察后，院方对佐久夜的危险程度有了全新的认知，她其实并不像其他有类似精神障碍的人一样会产生极高的破坏欲（特指诺诺妮娅和玛姬），不涉及班长的情况下，她的表现几乎和正常人一样，也会很温柔地对待学院里年纪小的学员。也就是说，她的病态其实主要体现于“爱”（她自认为）这个点。到底是什么让她变成这样的呢？",
		level_6 = 0,
		record = "佐久夜不受影响。"
	},
	[210920] = {
		soulid = 210920,
		valuation = "茅山的道士无论是肉体还是精神都相当过人，这个传闻确实不假。晓春的身体能力在目前所有学员当中也是能排得上前列的，这和她以前在山上修行过很长一段时间有关。据晓春自己所说，她的师父对她平时相当严厉，每天要做相当大量的锻炼以维持，但她也同样每天会吃大量的食物来填补能量缺口，这大概就是她的身体如此强健的原因吧。",
		file_1 = "晓春的档案库中有一小段采访时候的录像。「在我穷途末路的时候不光给我吃给我喝给我住的地方，还愿意包养我，真的太感谢班长了！」",
		level_3 = 0,
		level_4 = 0,
		resume = "一位自称是“正统道士”的少女，据她所说，她的师父是曾经在江湖上赫赫有名的人物，茅山道士这一名号也是从她师父那里继承来的。晓春在山里修行的时候每天被师父教育，做着一般人难以想象的艰苦修行，这对生性懒惰的她而言相当难捱，但好在她平时可以把压力转化为食欲，因此修行也逐渐有了成效（尽管她比以前胖了不少）。山上的修行告一段落，晓春的师父总算允许她下山见见世面了，兴高采烈的晓春立刻就启程前往了城市，但因为住在山里太久，晓春的认知早就和时代脱节了，并且作为道士的身份也被很多人质疑，没有挣钱的手段，因此生活过得也不顺利。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "晓春是一名孤儿，自小就被师父逢雪道人收养，在茅山上进行修行。师父对晓春十分严格，每天都要她做大量的训练，比如俯卧撑300个，蹲起500个，最初晓春觉得道士应该不需要做这么多肉体锻炼，而是要更着重精神力的磨炼，但师父却一再教育她「对于道士而言，在绝大多数场合最有用的就是拳头。」因此晓春即便觉得很累，也一直坚持了下去。",
		file_3 = "虽说运动多了食量也会变大，但晓春的食量依然有些不正常，每顿饭都要吃掉别人几倍的食物，让人不禁开始思考那些食物到底装在身体的哪里。因为实在是太能吃了，晓春也被其他同僚嫌弃了，因此只能自己住在稍微远离道馆的地方，饿了的时候会去外面找些花花草草吃，冬天也会跟松鼠抢夺它埋在地里的存粮，有时候也会把松鼠抓来烤了吃。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "道士的法术或是咒法——或者说道术，其存在本身曾经饱受质疑，绝大多数人认为江湖上的道士都是些招摇撞骗的神棍，最近几年通过为自己更换义体来声称自己拥有神力进行诈骗的案件也屡见不鲜。但晓春确确实实拥有能被称为“道术”的力量，而这一力量的根源其实也与虚数碎片有关。晓春即便不借助魂智能武器，也能和虚数碎片实现高频共鸣，换句话说，晓春的身体就可以称之为一种魂智能武器。布克丝院长对这一现象很感兴趣，并计划在后续研究中投入资金，来进行“人形魂智能武器”的研究。",
		level_6 = 0,
		record = "穿着连裤袜的大腿肉肉的道士。"
	},
