	[211020] = {
		soulid = 211020,
		valuation = "作为和凯拉学员一样的狼型异化人，阿塔兰塔同样有着超乎常人的战斗天赋和野性直觉。虽然性格让人觉得有些冷冰冰的，但她的魂智能武器却是以火焰喷射器的原型诞生的，像这种魂智能武器与本人性格完全相反的情况我们还是第一次见，不过……究竟是不是真的与她的性格相反呢？这一点还需要教职员们的观察。",
		file_1 = "阿塔兰塔的档案库中有一小段采访时候的录像。「入学理由吗……最初是芙蕾大人命令我这么做的。不过我并不反感，因为在这里打工能拿到很多钱，这样我就能尽快把欠芙蕾大人的钱还上了。」",
		level_3 = 0,
		level_4 = 0,
		resume = "芙蕾在地下拍卖会上带回来的少女，和凯拉同为狼型异化人。阿塔兰塔平时沉默寡言，很少直白地表露出自己的情绪，但出于血脉中的集群意识，她对于同伴的存在有相当强的依赖性，很喜欢静静地待在同伴们的身边。与此同时，阿塔兰塔对于小孩子有着很强的保护意识，本身的脾气秉性也相当讨小孩子们的喜欢，会很有耐心地陪小孩子们玩耍。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "阿塔兰塔出生于洛加尔的一个普通家庭，父亲是普通的人类，母亲则是狼型异化人，阿塔兰塔在拥有狼型异化人特征的同时更多继承了母亲的外表。据调查，目前已登记于大数据库的狼型异化人有1371名，因为数量较为稀少，并且绝大多数的狼型异化人都有被当地机构保护，所以像阿塔兰塔这种普通的有着狼型异化人的家庭就很容易被一些心怀不轨的人盯上。",
		file_3 = "阿塔兰塔的父亲在接触了某些被禁止的成瘾性药物后性格日趋怪异，与阿塔兰塔的母亲几度发生激烈的争执，两人的夫妻关系也渐渐变得冷淡。某天，阿塔兰塔的父亲为了筹集购买成瘾性药物的钱而接触了高利贷，落入了圈套，眼见家庭就要分崩离析，阿塔兰塔接受了高利贷方的条件，以自己签下合同的形式将父亲欠下的债转移到自己身上，某种意义上讲，就是将自己卖掉来偿还这笔欠款。但阿塔兰塔自己也很清楚，即便这么做了，自己的家庭也会支离破碎，父亲和母亲再也无法重归于好了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "阿塔兰塔的母亲在得知阿塔兰塔被芙蕾买下后立刻赶来了魂器学院，和阿塔兰塔见面后便激动地流下了眼泪，一个劲地感谢芙蕾，并主动提出筹钱补偿给芙蕾，但她这一提议被芙蕾谢绝了。阿塔兰塔的母亲也知道，比起将阿塔兰塔放在自己身边，让她待在魂器学院，得到多方势力的保护更为安全。对于芙蕾的安排，阿塔兰塔的母亲没有任何意见，毕竟从今往后阿塔兰塔又能随时和她联络了。至于阿塔兰塔的父亲，即便月和会已经通知了他阿塔兰塔的去向，他也因为对女儿的愧疚而谢绝了与女儿的会面，但他现在已经彻底戒掉了成瘾性药物，并且找了一份稳定的工作，定期也会给阿塔兰塔寄来生活费。只不过，阿塔兰塔的母亲并没有打算原谅这个曾经将女儿卖掉的男人。",
		level_6 = 0,
		record = "温驯的灰狼。"
	},
	[211520] = {
		soulid = 211520,
		valuation = "爱琉的魂智能武器和普通的抓娃娃机不一样，能从外面抓东西然后塞到储藏区域，因此可以存储一些战斗补给物资。强而有力的抓钩可以伸得很长，在战斗中用处十分广泛，比如可以将敌人抓过来以干预战场，又或者可以将友方拖离战斗区域，无论是歼敌任务还是救援任务都能完美胜任。只不过，关于爱琉的性格……希望教职员们可以进行恰当的引导吧。",
		file_1 = "爱琉的档案库中有一小段采访时候的录像。「不用想太多，我只是来魂器学院给履历镀金的，虽说是世界最顶尖的学府，但看上去也不过如此嘛~」",
		level_3 = 0,
		level_4 = 0,
		resume = "来自洛加尔TC集团的董事长千金。爱琉父亲的公司涉及影视、游戏等多个领域，并且在电子产品市场也颇有话语权。爱琉的家里摆满了各种各样的电子设备，大到能顶到天花板的抓娃娃机，小到能戴在手腕上的体感游戏手环，从小就在这种环境熏陶下的爱琉也接受了精英教育，这带给了她相当强的优越感。也因此，爱琉的自信心也是日趋膨胀……",
		level_1 = 0,
		level_5 = 0,
		file_2 = "爱琉是真正意义上养尊处优的大小姐，因为父母平时忙于工作，没多少时间照料她，家里的管家又对爱琉唯命是从，所以最终爱琉就变成了这样一个狂妄的性格。话虽如此，但她也确实有狂妄的资本，爱琉至今为止无论是在学习还是在一些其他领域的表现都远超同龄人，在其他同学的家长眼里，她是名副其实的“别人家的孩子”。",
		file_3 = "爱琉的父亲送她来魂器学院的主要目的也是要挫挫她的锐气，让她在和自己同水准，或者是比自己水准更高的同龄人的圈子中尝到失败的滋味，理解自身的不足。「现在她的状态，我很难放心把公司交给她啊。」爱琉的父亲希望爱琉从14岁起就能开始参与公司的各项事务，并在成年的时候继承公司。在外人听来这也许是在给尚且年幼的爱琉背负上不符合其年龄的重担，但对爱琉的家族而言似乎是习以为常的。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在经过了一段时间的观察后，正如教职员们最初所预想的，爱琉体验到了被真正的天才“碾压”的感觉。无论是学习还是运动，亦或者是她很自豪的电子游戏方面，和她同龄的学员都能凌驾于她。教职员们本来很担心这样一剂“猛药”会不会对她的精神方面造成过于沉重的打击，但最后看来这只是教职员们多虑了。爱琉最初确实有受到打击，但她很快就振作起来，寻找起自己能胜过那些天才们的领域了。",
		level_6 = 0,
		record = "狂妄的小鬼就该被狠狠地教训啊！"
	},
	[211620] = {
		soulid = 211620,
		valuation = "卡特琳娜毕竟是专业的保镖兼教官，在对人战方面可以说几乎是全学院最强的存在，但在对抗AI的时候就显得有些手足无措了。不过，由于她本身的战斗直觉很强，学习能力也很强，相信用不了多久就能成为学院当中的主力。",
		file_1 = "卡特琳娜的档案库中有一小段采访时候的录像。「诶？连作为教职员的我都要做入学采访吗？哎呀~魂器学院还真严谨啊~」",
		level_3 = 0,
		level_4 = 0,
		resume = "卡特琳娜是TC集团安保部门的教官兼爱琉的贴身保镖。外表看似懒散羸弱，实则技艺高超，精通CQC等格斗术，是对人战中的专家。TC集团正通过和一些企业联合开发可用于多领域的“变装道具”，尤莉亚父亲所经营的企业自然也位列其中。在进行保镖行动时，卡特琳娜往往会变装成路人，司机等形象来伪装自己，但她的伪装技术确实有待提高。“明明每天都在看电视剧，演技居然还这么差”——尤莉娅和爱琉经常吐槽这一点。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "原本卡特琳娜是要以教职员的身份入学的，但因为爱琉父亲的建议，最终卡特琳娜以学员身份入学了，理由似乎是「两个人一起学习也会让爱琉更有动力。」虽然卡特琳娜最终还是抱怨了一两句，但因为要拿着TC集团的工资过活，所以该接受还是得接受。",
		file_3 = "卡特琳娜作为保镖的实力毋庸置疑，除此以外她确实就像一个平凡的女大学生或者刚上班的女白领一样，生活平淡，作息规律。除了看电视剧以外没有什么其他的兴趣爱好，因为化妆技术不精，所以只能淡妆出行。偶尔也会看一些很能诱发少女心的爱情小说，并且会积极推荐给其他学员，因此和其他学员的关系也相当融洽。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "事实证明，卡特琳娜作为“同学”确实有对爱琉的学习生活起到促进作用，卡特琳娜的成绩在大学组也是名列前茅（其实主要原因是大学组里面有很多和卡特琳娜一样对学习不认真的人，而这其中天赋稍微强一点的卡特琳娜自然就取得了比较高的名次）。自己平时一直瞧不起的卡特琳娜表现优秀，这激发了爱琉的竞争心，她也因此开始努力学习，虽然最后没能取得好成绩，但也因此得到了教职员们的喜爱。",
		level_6 = 0,
		record = "反差萌也是萌。"
	},
	[212020] = {
		soulid = 212020,
		valuation = "玄珑的各项指标都远远超出了一般人类的范畴，这个描述并不夸张，而即便是取得了这样的成绩，玄珑仍表现得游刃有余，很难想象她使出全力会是什么样的感觉。她的体检报告被列为第二级机密事项，所以我无从查阅。",
		file_1 = "玄珑的档案库中有一小段采访时候的录像。「“恩义”，我和我的旧友都常常把这个词挂在嘴边上。请放心，既然说了要向你们报恩，我一定会全力以赴。」",
		level_3 = 0,
		level_4 = 0,
		resume = "玄珑是来自派森地区的一位知名收藏家，也是托拉在派森地区的名誉顾问。虽然很多人都认识她，但大家对她的唯一认知就是“有很多钱”，即便是在托拉组织内，知道她真实身份的人也屈指可数，但布克丝院长似乎早就和她相识了。在与年纪小的学员相处时会展现出相当强烈的母性，平时很成熟稳重，但偶尔也有孩子气的一面，因此大家对她的印象都很不错。但是似乎有传闻说，从来没有人见过她疲惫的样子，也从来没见过她休息……",
		level_1 = 0,
		level_5 = 0,
		file_2 = "玄珑平时表现得相当成熟稳重，但偶尔也会有孩子气的一面，特别是在讲到自己以前陪同尤希雅的母亲一起冒险时的故事时，她的话匣子一打开就很难关上了，但她兴致勃勃地讲故事的样子看上去又相当可爱，让人根本不忍心打断。",
		file_3 = "尽管玄珑并不是很了解母女关系的定义，但她仍认为自己应当成为尤希雅的母亲。在尤希雅患病在床的期间，她经常会抽空去探望尤希雅，对于尤希雅来说，这个偶尔来探望自己的温柔大姐姐虽然并非自己的母亲，却有一种难以言喻的亲近感，就好像是在和母亲的姐妹相处一般。因此，尤希雅也渐渐开始黏上了玄珑。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "玄珑本身就是一个魂智能武器，作为虚数能量的容器，她承载着已经离世的尤希雅的母亲的意志。因为实在放不下尤希雅，所以便委托了洛可可和布克丝制作一具可以供她以人类身份行动的身体——这也是霓昂等人在前往欧西利亚联邦时所使用的素体的灵感来源。",
		level_6 = 0,
		record = "小道消息称，管玄珑叫妈妈似乎会让她很开心。"
	},
	[212120] = {
		soulid = 212120,
		valuation = "梅林作为魔术师，身体的柔韧性、灵巧度、协调性都堪称完美，像她这样能适应各种恶劣地形的学员在现如今本就已经相当罕见了，梅林还是这其中更难得一见的“远距离”类型魂智能武器持有者。因此我们对梅林的能力测试给出了极高的评价。梅林的魂智能武器外型是一把旧式的燧发枪，但也仅仅只有外型如此，在火力方面丝毫不输其他魂智能武器。",
		file_1 = "梅林的档案库中有一小段采访时候的录像。「我终于找到了值得我奉献自己的一生去跟随的人。」",
		level_3 = 0,
		level_4 = 0,
		resume = "来自耶梦加得的知名魔术师，演出遍及世界各地。梅林在科技如此发达的时代仍旧选择用技巧而不是科技辅助来进行魔术演出，像她这样的人被称为“传统派”魔术师。梅林是传统派魔术师的代表之一，不光是因为她那精湛的手法，还有她那极佳的演技和表现力，以及对舞台的掌控程度。梅林可以在十分恰当的时机调动观众的情绪，因此她的演出一直饱受好评。“能看穿人心”的魔术师——这也是很多观众在目睹过梅林的魔术表演后给出的评价。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "梅林在进入魂器学院之后就几乎停止了在外面的魔术巡回演出，可即便如此，她的名气也丝毫不见衰退。人们纷纷猜测这个在魔术界曾经如同恒星般璀璨的魔术大师又会在什么时候，以什么样的姿态再次出现在舞台上，带给观众更大的惊喜。",
		file_3 = "梅林对班长的态度与其说是“爱”，更像是“忠诚”，她对于班长并未产生情欲，但如果班长有所索求，她也能把自己的羞耻心摆在忠诚心之后，以遵从班长的意愿为优先。因此她和佐久夜等人完全不一样，属于心智上并未出现明显“缺陷”的一类学员。不过，至今为止她都没有说明过自己是为什么如此忠于班长的，我们也将保持对她的行为观察，希望能借此找到答案。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "梅林在一次和索菲亚讨论时说过，她认为虚数碎片是“上层次元”泄露的能量块，这一说法和布克丝目前的研究成果从某种意义上讲是一致的，对于一个没有系统学习过能量理论，甚至才刚刚接触魂智能武器和虚数碎片的人而言，能迅速得出这个结论显然是不正常的。要么就是她的想象力天马行空，要么就是她确实接收到了一些常人所不能及之物。",
		level_6 = 0,
		record = "拥王者。"
	},
	[21921] = {
		soulid = 21921,
		valuation = "沟通起来太累了……我开始心疼她的队友了，一码归一码，安娜的异能还是相当厉害的，如果不总是大喊招式名字，对敌人进行过长的说明的话，基本上还算是个不错的战士。",
		file_1 = "安娜自称弗拉德十七世，弗拉德这个名字来自古老时代的罗马尼亚传说，是夜族的代名词。幻想自己是夜族的安娜，做出了许多匪夷所思的事情。 1：明明黑色最能吸热，但却怕热的安娜依然选择了拿着黑色的阳伞外出。 2：用红葡萄水伪装成别的东西吞饮，却把伊卡洛维吓得不轻。 3：经常白天睡觉，夜晚醒来，但又会因为寂寞去睡回笼觉。 对于以上情况，我们对安娜提出了一些意见，嗯……仅仅只是意见罢了。",
		level_3 = 0,
		level_4 = 0,
		resume = "安娜，背景不明，身份不明，过往记录暂无，唯一得知的仅是她来自耶梦加得。平时喜欢以夜族自称，但并没有摄魂行为，睡眠时间日夜颠倒，为她安排对应的课程有些困难，目前针对安娜的课程安排都是由人工智能进行的。  性格上虽然会他人着想，但那也只是在自己的身份被对方认可的情况下，在来学院之前就和莱拉互相认识，两人存在一些因缘。  暂时无法理解安娜的模仿行为，因为这些行为并没有为她带来任何能力上的增幅，通过调查发现似乎在很久之前有过一种叫做“中二病”的心理疾病，这种病会带给他人过度的幻想和对现实的否定，为了安娜的健康，我们必须继续观察。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【幻想具现】：不知道是中二病影响了安娜，还是这份能力让安娜得了中二病，总之安娜确实使自己的妄想产物变成现实，大部分。\n其实安娜本身的具现能力比较弱，充其量只能具现出小型的火球，但能力的稀有程度确实是顶级的。\n通过适格者测试后，布克丝博士对安娜的精神波动进行过一段时间的观测，为安娜制造了魂器【幻想魔伞】，本质上是对精神增幅的装置。\n目前藉由魂器辅助，安娜的具现能力有了飞跃性的增长，能力范围与精准程度都有所提升。是自由度很高，十分便利的一项能力。",
		file_3 = "安娜对学院内的一些贵族活动产生了兴趣，经常沉迷于插花、茶会等活动。由于个人原因，无法准时地参加，本人对此也有些困扰，所以最近已经将起床时间改成了下午三点。当然……这个时间还是赶不上大部分的课程，不过算了，这也是相当大的进步了。\n另外本人对莱拉的称呼似乎是骑士，一开始认为两人只是中二病的同类，但后来发现里面似乎有些复杂的原由；在询问了莱拉之后得知，曾经安娜在自己最失落的时候用自己的方式安慰了自己。 另外在询问了更多人的意见后，我们发现安娜或许并不是单纯的中二病，那些行为很有可能只是出于关心他人的掩饰。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "关于安娜的部分记录在云端内被追踪到：日期：xxx 下午16:51分：海岸线附近发现大量鲸鱼搁浅，且无论用任何方式诱导都毫无作用。    日期：XXX 正午12:14分：小部分强化人突然失控，对周围的环境大肆破坏。 日期：XXX 下午15:19分：一位外形与安娜相似的小女孩于耶梦加得·七区回收站附近被发现。     能够找到的大致只有这三条，目前我们暂且无法得知在安娜身上究竟发生过什么，只能粗略地计算她能力觉醒的大致时间段。    如果有新的线索的话，我们将会持续上传到云端的。   ",
		level_6 = 0,
		record = "中二病是人对现实的逃避，是对幻想的渴望，安娜却并不是如此，她比谁都接受现实，也比谁都喜欢幻想。喜欢行走在没有阳光的夜晚，那也是因为她对太阳的不认可。她虽然在模仿夜族，可心里却比大多数人类要更了解自己，单方面的理解并不是真正的伙伴；而安娜需要的不是同好，也不是朋友，而是对她做出正确评价的能陪伴在她身边的人罢了。"
	},
