	[212520] = {
		soulid = 212520,
		valuation = "由于早些时候的营养不良，碧娜的身体相对于同龄的孩子要更加瘦弱一些，直到新墨格尔成立，生活条件变好，她才渐渐像个普通的孩子一样成长起来。因此，碧娜的各方面身体能力只能说是普通人的水准，几乎全部的战斗能力都靠魂智能武器来进行补足。不过，她的魂智能武器相当强力，完全可以弥补她的身体能力，让她发挥出远超其他人的战斗力。",
		file_1 = "碧娜的档案库中有一小段入学测验时候的录像。「烧尽世间所有的邪恶——这就是我成为魔法少女的意义！」",
		level_3 = 0,
		level_4 = 0,
		resume = "碧娜来自新墨格尔的一所孤儿院。和其他孤儿不同，碧娜并没有因为过往的经历而陷入消沉，反而主动充当起了引导其他孩子们的“大姐姐”，据她本人所说，她是在电视上看到布兰琪的比赛后对格斗产生了兴趣，从此便以加入魂器学院作为自己的人生目标。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "碧娜是一个充满了热情且拥有极强正义感的女孩子。就如同童话故事中的勇者或是英雄一般，碧娜不经意间的言行举止往往具备振奋人心的力量。可这样的性格也存在一些缺点，那就是“爱钻牛角尖”，碧娜认定正确的事情，除非你能从各个角度完全说服她，否则她是不会改变主意的。教职员们采访了一下和碧娜有过交流的学员，得到的反馈中有多数提到了“和碧娜相处起来很累”这一点，这也符合了教职员的猜想。",
		file_3 = "在碧娜童年最黑暗的时光里，是布兰琪的拳击比赛带给了她直面人生的力量。自那以后她就把布兰琪视为偶像，想要像布兰琪一样在拳头中贯彻自己的正义。可实际上，布兰琪本身并不像在舞台上那么光鲜亮丽，是个私生活一塌糊涂的人，可惜碧娜并不知道这件事。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "作为星光魔法少女的一员，碧娜担任了团队中的氛围发动机，在危机关头也往往是最先采取行动的。如果要说星光魔法少女里面谁最出名，最受孩子们的憧憬，那肯定就是碧娜了，可碧娜对此却并不感到开心，她认为自己的拳头还无法彻底贯彻“正义”，有愧于大家对她的期待。对此，芙洛丽亚表示——「这样就好，她已经很膨胀了，如果再膨胀的话我们可就真应付不来了。」",
		level_6 = 0,
		record = "对敌人使用炎拳吧！"
	},
	[212420] = {
		soulid = 212420,
		valuation = "作为新型魂智能武器的适格者，芙洛丽亚表现出了超乎我们想象的水准。与依靠蛮力挥舞武器的碧娜以及认真耿直的艾莉卡不同，芙洛丽亚最强大的武器是她的想象力，不光是直接与敌人战斗，她还想到了使用这股力量帮助同伴的方法，连设计出这类魂智能武器的布克丝院长都颇为震惊。",
		file_1 = "芙洛丽亚的档案库中有一小段入学测验时候的录像。「入学的理由？谁知道呢……也许是我爸爸想让我不要整天在家待着，出来见见世面吧。」",
		level_3 = 0,
		level_4 = 0,
		resume = "作为巴哈姆特当地某黑帮家的大小姐，芙洛丽亚的性格反而与一般人对黑帮的刻板印象大相径庭。平日待人随和，喜欢种些花草，特别是对“吃”有着特殊的追求，是个名副其实的吃货。在学员之间流传着一个传闻——芙洛丽亚生起气来极其恐怖，所以不要招惹她。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "芙洛丽亚出身自巴哈姆特当地的一个黑帮家庭，从规模上来看，她家并没有其他黑帮势力大。与其他黑帮势力相比，芙洛丽亚家只能算得上是普通的后起之秀，在比较看重资历的黑道上得不到多少话语权。与其说是黑帮，不如说就是一帮抱持着传统思想的人所组成的集团，平时在芙洛丽亚父亲名下的公司工作，闲暇时间会去社区里面到处走访，也经常能见到他们和当地的老年人侃侃而谈的样子。",
		file_3 = "入学一段时间后，教职员们发现芙洛丽亚和露露姆走得很近，经过询问，两人似乎在很久以前就已经相识了。露露姆当时参加了一场举行于巴哈姆特的甜品比赛，两人就是在那个时候认识的。当时芙洛丽亚询问露露姆有没有成为她专属甜点师的想法，露露姆婉拒了，表示自己有更加远大的梦想，而芙洛丽亚也认可她的这一梦想，两人因此成为好友。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "据芙洛丽亚的父母所说，芙洛丽亚的心理存在一点小小的问题，虽然外表看上去相当温柔善良，但在生气时，她又会展露出不像这个年纪的女生该有的冷酷。“芙洛丽亚生起气来很可怕”——这个传闻就是因此得来。会出现这样的情况大概是因为芙洛丽亚小时候被父亲拉着看了不少的黑帮电影。芙洛丽亚的父亲经常会因为此时被妻子斥责，迫于压力，他十分希望能得到魂器学院的帮助。",
		level_6 = 0,
		record = "吃货魔法少女。"
	},
	[212320] = {
		soulid = 212320,
		valuation = "在与魂智能机兵的协作战斗中展现出了极高的天赋，值得培养。",
		file_1 = "认识到人工智能具备无限的发展可能之后，艾莉卡理解了父母是在为人类造福的伟大事业献身。于是立志成为一名受人尊敬的机械师，为了能帮上父母的忙，也为了将来设计出像喵球一样优秀的人工智能，陪伴跟自己一样孤独的人。所以经常可以看到，艾莉卡乖巧地待在父亲的家庭工作室里，一声不吭的自己鼓捣着做一些玩意儿。不仅活跃了思维还提高了创造力和想象力，看到自己亲手做出来的成品后内心也会充满了成就和自豪感，并发展成了爱好。",
		level_3 = 0,
		level_4 = 0,
		resume = "艾莉卡的父亲是一位小有成就的智能人工智能工程师，在地劫战争之后，与艾莉卡的母亲一起成立了一家科技公司，致力于研发独立于之前的人工智能网络，能为人类造福的新型高智能人工智能。因为工作繁忙，父母渐渐减少了对艾莉卡的陪伴。为了弥补对女儿的情感缺失，艾莉卡的父母专门设计制造了一款具备中级智能的人工智能—————喵球，让喵球代替自己陪伴艾莉卡。配备了情感感应系统的喵球能分析和同步艾莉卡的情绪，只接受来自艾莉卡的命令。在父母不在家的时间里，可爱而富有灵性的喵球成了艾莉卡的唯一玩伴。也是在与喵球的接触中，艾莉卡对人工智能产生了浓厚的兴趣，从而学习起了关于人工智能的知识。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "平静的日子没有过多久，一只人工智能军队攻入了城市，开始肆意破坏、袭击人类。暴走的人工智能闯入了艾莉卡家中，艾莉卡的父母为了保护她，被人工智能残忍的伤害了。人工智能本来想连同艾莉卡一并除去，但喵球挡在了幼小的艾莉卡面前，此时人工智能像是收到新的命令一般，放下了屠刀，突然扬长而去。艾莉卡茫然地看着双亲一动不动的样子，任凭如何呼喊也无法唤醒，原先开朗、活泼的性格已经随父母的逝去而消失不见。",
		file_3 = "经历过失去父母和失去喵球的痛苦，艾莉卡留下了难以抹去的心理阴影。变得有些孤僻，甚至害怕社交活动。在同情艾莉卡遭遇的同时，院长发现一款自律型魂器与艾莉卡产生了共鸣，但对喵球仍抱有感情的艾莉卡不愿接触新的机器人。最后院长突发奇想，想要将喵球残存的记忆芯片和情感模块移植到自律型魂器身上。艾莉卡得知后十分高兴，院长仿照喵球的原型，改造了魂器，在院长和艾莉卡的共同努力下，移植工程完成得十分成功，喵球最终在另一个身体中获得了重生。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "因心理创伤的问题，艾莉卡拒绝了学院安排照顾她的人，只接受喵球的照顾，导致过度依赖而失去自信甚至自我判断能力，遇见什么事都要与喵球眼神交流以后才能拿定主意。虽然时不时会哭一下鼻子，但艾莉卡的承受能力是很强的，面对他人语言甚至是身体上的攻击绝对不会反击。可一旦超过了她所能接受的范围，艾莉卡会陷入极度的自我封闭，以这种心理防御机制来回避环境以降低挫折感。",
		level_6 = 0,
		record = "请问有看到我的猫球吗？"
	},
	[212820] = {
		soulid = 212820,
		valuation = "安布洛希亚本身并没有什么特殊的能力，在距离其武器影月荆棘较远的情况下，其与正常人类没有区别，但随着与影月荆棘的距离越近，其就会拥有更强大的能力，肉体的速度、力量都会得到巨大的提升，直到本人接触到影月荆棘时，能力提升达到最大。",
		file_1 = "安布洛希亚非常的喜欢喝红茶，尤其是南派森红茶，这种红茶对于她来说能起到类似酒精的效果，换句话说就是，喝茶会醉，我们尚不了解这其中的原理是什么，但是对其本人的观察结果来说，并无大碍。",
		level_3 = 0,
		level_4 = 0,
		resume = "根据对其作战记录的分析，我们发现时间的早晚、月亮的阴晴圆缺都会对安布洛希亚的作战能力产生影响，简单点解释就是，当月亮越圆越亮越明显，对其作战能力的增幅就会越大，但满月似乎与其持有武器的暗月教会有所冲突，我们不清楚所谓暗月为何物，以及当这个“暗月”出现时，会对安布洛希亚产生什么影响。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "不知道是和其童年在教会的经历还是暗月的影响，安布洛希亚的性格有些有些古怪，其会对班长产生一种奇怪的依赖性格，但这种性格并不会产生额外的破坏欲或受虐欲，也不会对其他学员的靠近产生厌恶，其更像是，将班长当做了一种信仰？类似于神父或者主教？目前我们仍在观察当中。",
		file_3 = "其并不想黛西亚或是摩洛娜那样三句不离神或是信仰，她并没有表现出太多的宗教倾向，也不会对其他宗教与无神论者产生争执，不过如果我们结合档案2的猜想，将班长看做是神或者信仰，那么安布洛希亚的宗教狂热可能远超前二者。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "最近班长办公室的物品失窃情况比较严重，起初还只是笔和橡皮等消耗品，后勤处还以为是丢了，但直到最近，连班长的椅子都出现了丢失的情况，在保卫处调取监控后发现，安布洛希亚有在办公室无人时频繁出入的情况，并且对安布洛希亚寝室的秘密调查中也发现了被“供奉”起来的班长遗失物品，目前对安布洛希亚这种诡异行为的调查还在进行当中。",
		level_6 = 0,
		record = "暗月的法则，群星的时代……"
	},
	[211220] = {
		soulid = 211220,
		valuation = "在苏樱雪眼中，与伙伴同行的每一段记忆都值得被永久珍藏。通过收集散落的记忆碎片，苏樱雪可以汇聚时间魔力，让珍藏的记忆片段再临。",
		file_1 = "一则在异界都市中传播的流言：红瞳是恶魔的象征，会给周围的人带来不幸。流言出处无从考证，但当地居民都对此深信不疑。",
		level_3 = 0,
		level_4 = 0,
		resume = "一张破旧的病例单，上面写着：重度抑郁和精神分裂。不过如今的苏樱雪并未表现出上述症状。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "一幅埋藏在回忆最深处的画面：有着淡蓝色双瞳，身着淡蓝色衣裙的女孩伸出手，白色长发在微风中轻轻舞动，恬静的脸上笑容和煦。",
		file_3 = "一条来自行刑者间的谈话记录：红色瞳孔可以人为创造。找到容貌相似的受害者抵命，就能弥补追捕失利的罪行。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "一张在异界都市中传播的简报：强权家族声称遭受樱之魔女的诅咒。但有可靠消息称苏樱雪早已前往人间，排除作案可能。故无人在意该家族的结局。",
		level_6 = 0,
		record = "樱之魔女。"
	},
