	[213520] = {
		soulid = 213520,
		valuation = "身体能力超群，作战经验丰富，在各种情况下都能游刃有余地完成任务。",
		file_1 = "获得性语言障碍，俗称失语症。由于这种疾病，年幼的丽塔失去了声音，只能依靠手语表达自己的想法。雪上加霜的是，在一次车祸事故后，丽塔的双臂被截肢，从此，她便丧失了与外界沟通的手段。直到某一天，IMTH项目的负责人向丽塔和她的家人抛出了橄榄枝。无论哪个时代，人体改造都是相当敏感的话题，而IMTH项目的负责人自诩为时代的开拓者，为丽塔阴暗的生活带来了一丝希望。从手术台上下来的那一刻，丽塔是幸福的，她不仅重获了失去的双臂，还久违地开口说了话。但丽塔不知道的是，未来，她将为现在的幸福付出巨大的代价。",
		level_3 = 0,
		level_4 = 0,
		resume = "以“治疗”为名被骗进IMTH项目的少女。通过人体改造而重获手臂与发声能力，但也因此成为研究所的特工，执行着各种水面下的任务。X-MAS爆发后，丽塔意识到自己的大脑也受到了改造，并开始对自己被用作杀人工具的声音和手臂感到自卑。只有在与AI抗争时，她才能短暂地逃避对自身的怀疑。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "IMTH不是慈善机构。在治疗之前，丽塔签署了一份条约，使得她需要长期担任研究所的特工。依靠义体的性能，丽塔总能巧妙地完成各种工作，这也让过去一直被当成累赘的她有了不小的成就感。“或许就这样留在研究所也不错？”下班的丽塔时常这么想着，却不自觉地忽视了弥漫在空气中、刀刃间，以及自己身上的血腥味。直到X-MAS爆发，在研究所遭到入侵的同时，丽塔的大脑像是被电流穿过，她重新记起了一切。",
		file_3 = "在接受手术前，IMTH项目的负责人额外提出，想要取得对丽塔大脑的改造权。从事后丽塔失去了这段记忆可以推断出，当时的她应该是同意了。作为一个心智正常的人类女孩，丽塔本不可能去执行那些残忍的工作，了解到这一点的研究所对丽塔的思维进行了调整，让她失去了大部分的道德感和同理心，变成了一个方便操控的“道具”。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "现在的自己还是不是自己？重新认识到自己过去行为的丽塔，开始对身上机械的部分感到羞愧和恐惧。她发现，自己长久以来一直在用虚假的声音说话。但无论如何回忆，丽塔都想不起自己原本的声音。为了转移注意力，丽塔开始帮助库库尔坎的民众，抵抗暴乱的AI，并顺水推舟地加入了魂器学院。但在丽塔心中，或许只有找回自己原本的声音，才能让她真正与过去和解。",
		level_6 = 0,
		record = "虚伪与真实...台词与声音。"
	},
	[213620] = {
		soulid = 213620,
		valuation = "都市末刃作为一整套战斗系统来说，并没有多大的亮点，但更强大的是，其体内的可控的AI自动演算进化装置，其可以不断的在战斗中对对手的动作进行捕捉、演算、应对、学习。对于都市末刃来说，所有的错误，永远都只会犯一次，并且越犯错误越不容易犯错误。",
		file_1 = "IMTH项目，既智能机械改造人类项目，意图在将人体进行机械改造，使得人类液获得X-MAS的自我演算进化能力，在X-MAS爆发之后，库库尔坎率先沦陷，军队的慌乱撤离遗忘了仍处于实验室中的杰西卡，当AI进入实验室，妄图控制杰西卡时发现，这杰西卡的意志并不直接与Eden相连，而是依旧处于人类大脑的控制下。",
		level_3 = 0,
		level_4 = 0,
		resume = "原本只是在平民窟中的孤儿，在即将饿死之际，与X-MAS项目研发实验室签订了实验体契约，再次之后陷入了很长时间的昏迷，直到X-MAS爆发，在醒来之后，杰西卡并不适应都市末刃的战斗系统，但其体内的AI却在自动学习敌人的出招方式，并一步步引导杰西卡的大脑学会了战斗。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "都市末刃赋予杰西卡的超强学习能力让她也能够适应很多别的作业，例如维修、烹饪、制造，只要找到一些视频资料，就可以很快的学会，并且会在失败的过程中积累经验，也可以从成功的过程中举一反三，纵向发展。利用这种能力，杰西卡在库库尔坎中建立了一座不小的基地。",
		file_3 = "我们一直很好奇，为什么杰西卡如此执着于撤出库库尔坎的平民，起初我们认为是她作为人类的同情心驱使。直到后来一份来自库库尔坎戍卫部队的作战记录表示，他们在通讯系统完全被AI瘫痪之前，发出的最后一条指令就是“尽可能帮助库库尔坎的平民撤离”。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "更具档案3我们得知，都市末刃的AI系统，很可能与军方的作战指挥系统相连。但这个系统早在X-MAS爆发初期就被AI彻底摧毁，所以之后的都市末刃的指挥权限就被分属到了库库尔坎戍卫部队手里，在戍卫部队被歼灭后，其指挥权限就变更为自主决策，并默认执行最后生成的命令。",
		level_6 = 0,
		record = "都市铁血……"
	},
	[213720] = {
		soulid = 213720,
		valuation = "“一人成军”这个词，用在艾缇娜的身上是再合适不过了。坚韧的仿生皮肤包裹了她的全身，让她可以在许多极端环境下生存。隐藏在皮肤之下的武器多种多样，在艾缇娜的使用下甚至能对敌人进行重火力压制。毫无疑问，只要向她下达了命令，艾缇娜总会有办法完成。",
		file_1 = "艾缇娜从何而来？她的父母是谁？在研究所已经毁灭的现在，我们无从知晓。只知道她最初的记忆，是研究所里沉闷的空气，各种说着复杂话语的大人们，以及躲在房间角落的，冷冰冰的自己。",
		level_3 = 0,
		level_4 = 0,
		resume = "自出生起就在接受改造的少女，就连行为举止也表现得像是机器人。在研究所的训练下，艾缇娜对收到的命令采取绝对服从的态度。如果手头没有任务，她反而会变得焦躁不安，等待着别人对自己下达命令。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "根据学院的分析，在过去的十几年里，艾缇娜身上的各个部件经历了一轮又一轮的替换，就像是一个被反复拆解又组装的人偶。研究所对于改造艾缇娜这件事似乎并没有一个明确的目标，而是根据眼下的情况，不时她的身体进行新的调整。或许，对于研究所的人来说，艾缇娜的身体从一开始就只是一个平台，一个供他们试错用的平台。",
		file_3 = "出乎意料的是，艾缇娜的大脑十分完好，没有任何改造过的痕迹，这让我们看到了使她重归正常生活的希望，但艾缇娜本人似乎并不想改变现在的生活方式。究竟是什么样的经历，才让一个普通的女孩变成了现在这样？学院的老师曾试图通过心理咨询的方式疏导艾缇娜，但对于自己的过去，艾缇娜并不想提及，而班长也无意命令她开口。经过综合考虑，我们最终决定，与其强行按照所谓“正常”的标准改变她，不如尊重艾缇娜的意愿，让她以自己习惯的方式生活。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“解答——因为他看上去像是这里的老大。”对于将指挥权限交给班长的理由，艾缇娜如是回答。在与艾缇娜第一次接触时，她还处于迷茫和焦虑不安的状态，只是盲目地跟随着丽塔和杰西卡的脚步。在见到班长后，她仿佛刚出壳的小鸡一般，认定了班长为新的长官。说实话，鉴于事情进展的顺利程度，我们曾一度认为这里面有诈。但由于眼下没有更好的处理方法，我们也只能让这位少女跟在班长的身边。直到艾缇娜逐渐熟悉了学院的生活，我们才得以从她口中知晓另一项隐情：“因为班长的身上，有熟悉的味道......”",
		level_6 = 0,
		record = "改造人艾缇娜，今天也在战斗着。"
	},
	[213020] = {
		soulid = 213020,
		valuation = "机械光棱的用途包括但不限于：切割、测距、焊接以及攻击，在加装了悬浮遥控模块后，其10组微型光棱发生器可以按照阿卡丽的指令进行调度，从而对多个敌人发动进攻，同时该型武器可以聚焦光线，遂具有远程攻击的能力。",
		file_1 = "除了研究的时候，阿卡丽其余的时间全部蹲在寝室看特摄片，这也是学院将她挖来的条件之一；就连吃饭阿卡丽也是叫外卖放到寝室门口，等外卖员走了之后再开门拿进来。",
		level_3 = 0,
		level_4 = 0,
		resume = "出于对阿卡丽隐私的保护和其本人的意愿，我们没有向阿卡丽原本所在的学校和地区所要阿卡丽的生平信息。我们甚至都没有见到这个孩子的父母，但根据阿卡丽无比坚定的答复，我们得知，她并不是孤儿。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "据说在洛加尔首都大学的时候，校长要求她必须遵守校规，按时到教室上课、去食堂就餐、参加研讨会等等等，这让她无比反感，但又出于某些事情，她好像又不得不依照校长的要求去做，而且当魂器学院的院长提出要挖她走的时候，她也是一直摇头，但当院长说出她可以在研究以外的时间就只待在寝室的时候，她便毫不犹豫答应了。",
		file_3 = "阿卡丽14岁的时候就被保送进了洛加尔首都大学，同教室的学生面对这个比他们小的多的女孩子，一直都觉得她是一个超级关系户，否则怎么可能这么小就被保送进了洛加尔最好的学府，虽然阿卡丽用事实证明了她的天才资质，但很多人还是认为，她上面绝对有人。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "根据阿卡丽自己的描述，她是在爷爷奶奶家长大的，爷爷的房间里有很多陈旧的特摄片录像带，在用家中仓库里的老电视机，一看就停不下来了，还经常趁着没人的时候模仿特摄片中演员的台词和动作。但当爷爷和奶奶过世之后，她就被接回了父母家中，她的父母一直觉得她看特摄片会耽误她的前程，也觉得就是因为她从小看特摄片才变得不喜欢社交，遂一直在寻找解决办法，那一年她14岁。",
		level_6 = 0,
		record = "光棱步兵？"
	},
	[213120] = {
		soulid = 213120,
		valuation = "相比于其他魂姬的表现，莱拉要更接近一般人，实力大致和强化人士兵相同，在战争的情况下很难成为扭转中战局的士兵，不过她的大部分标准都符合某件魂器……暂且挂名进入学院吧。",
		file_1 = "严格来说，莱拉是Abandoner（遗弃者）的受害者，在父母都是Abandoner的前提下，莱拉从出生便是他们一员，即便是渴望电子仪器，也没办法接触。童年仅有一本记载着游侠的古书陪伴，在同龄人在玩虚拟现实类戏的时候，莱拉却只能拿着木棍进行角色扮演。就算如此，莱拉还是度过了一个较为欢乐的童年。正义感是那本古书带给她的，也是我们这个信息碎片化时代里稀缺的名为感染力的东西。莱拉继承了书中所写的游侠精神渴望着用自己的方式去拯救世界，包括身边的那些遗弃者。",
		level_3 = 0,
		level_4 = 0,
		resume = "莱拉来自派森，是Abandoner（遗弃者）的一员，性格乐观善良，喜好骑士和游侠文化……为了找到游侠和骑的词条，工作人员翻阅了大量的历史文献，通过补充对历史的了解后，终于能客观地评价这点，简单地说就是位渴望着行侠仗义和潇洒行事的一位小姑娘。天真善良是好事，但这份善良在这个时代里什么用都没有，对敌人和伙伴都会伸出援手这一点真希望她可以改改，除此之外，由于过于追求潇洒反而有些本末倒置，做事再稍微认真一些的话会更好。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "莱拉和安娜曾于耶梦加得相遇，根据安娜的描述，那个时候的莱拉正处于情绪低落期，对自己的目标和正义感产生了疑问，甚至一度认为自己只是在自我救赎而已。 对于这样的莱拉，安娜表示实在看不过眼，于是告诉了她：没有办法救赎自己的人，也肯定没办法拯救他人如果需要理由你才会行动的话，那么就成为我的骑士吧。这句话使得莱拉的情绪安定下来，并对自己的目标有更深层次的了解。也是学院里总是以安娜的骑士自居的原因。",
		file_3 = "莱拉期待着潇洒的结尾，比如漂亮地完成了委托之后，拒绝他人的金钱，说着“那就请我喝一杯吧”，又或是在队友走投无路的时候，自己突然从天而降；然而在大部分时候，都会一些小瑕疵，导致莱拉无法做到潇洒；转身想要留下背影，却因为用力过猛原地旋转两圈什么的……作脱帽礼却飞出一只鸽子什么的……因为太过羞耻，那些事情大多数都成为了莱拉的黑历史。像这样不太可靠的她却承担起了学院风纪委员的工作，稍微有点令人担忧……另外，我们察觉到莱拉在帮助他人的时候，会爆发出极高的物理战斗力，但本人却对此毫无察觉，那之后重复测试，数据也和最初的幅度不大。我们推测，莱拉的体内隐藏着一份恐怖的力量，而这份力量仅能为他人使用。 【莱拉的物理作战能力已经重新评估。】",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【正义之刺】：主色调为红黑色的一把骑士剑，但并不能发挥出作为剑的所有特性，其剑内被赋予了骑士的项精神，只有在符合这些规则的情况下，正义之刺才会发挥出作为魂器的巨大威力。因为这件魂器只是院长心来潮的作品，所以在被制造出来的三个月内，完全没有人可以与这件魂器共鸣。这并不是说这件魂器的共鸣条件有多苛刻，只是在这个时代里，骑士本来就是一个罕见的词汇。【记录】：仅一次共鸣，莱拉就彻底掌握了件魂器，并且能轻松地发挥出它最大的威力，无法相信这是由那个最不像骑士的骑士做到的。我们猜测，有着力量却只能为他人所用的莱拉，威力巨大却只能由骑士使用的正义之刺，二者绝对有什么地方是相似的。",
		level_6 = 0,
		record = "生错时代的勇者哟，请怀揣着正义，大步向前吧。"
	},
	[213220] = {
		soulid = 213220,
		valuation = "因果的能力十分平均，几乎每项测试成绩都卡在及格边缘，某种程度上来说，这也非常厉害了。",
		file_1 = "赌场是库库尔坎最常见的场所之一，在穷奢极侈的销金窟里，没有人相信那个闯入的少女是为了寻找钱包的失主。 但事实就是如此。\n 因果捡到了钱包，一路追着失主来到赌场，又阴差阳错上了赌局，对规则一窍不通的她被诓骗着压上全部身家。赌徒们幸灾乐祸地围观着这场好戏，他们喜欢圈套中的猎物一无所有时流露出的挣扎和崩溃。\n 一切出乎意料。少女奇迹般地赢下了赌局，同时获得了令人眼红的财富，人们不甘心地称呼她为“幸运儿”，以此安慰自己的嫉妒心。然而“幸运”并不意味着安全，穷凶极恶的赌徒们盯上了因果，城市阴暗的巷道中上演着追逐。\n 高空摔下的花盆离她一步之遥，飞速行驶的车辆和她擦身而过，连穷途末路之际都意外出现了转机，少女似乎总是和幸运随行——正在库库尔坎执行任务的风魔胧顺手救下了因果，两人一起回到魂器学院。",
		level_3 = 0,
		level_4 = 0,
		resume = "客观来说，在一众优秀学生之中，因果的个人能力并不突出。\n很多人认为因果身上有着神秘的幸运力，但我们不能以这类无实际根据的因素来对她进行评判。不过，有一点是可以确定的——无论“幸运”是真是假，这种说法的存在为团队中的部分成员带去了信心和激励，从而在某些时刻激发出她们更多的潜力。除此以外，因果天真善良的性格让她拥有不错的人气，这无形中增强了同伴之间的凝聚力。\n或许她本人没有察觉，当身处团队中，她将发挥出无与伦比的价值。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "自从因果加入学院，学员中不知不觉流行起了“考前幸运传递仪式“，具体的流程如下：\n 一、沐浴更衣，净手焚香。\n 二、寻找因果，以手触碰她身体的任意部位。（注意征得本人同意，不可引发同学矛盾。）\n三、诚心感谢，虔诚祈祷考试顺利。\n根据大家的反馈，因果同学的幸运传递非常灵验，但我们更希望魂姬们通过平时扎实的训练和积累来取得优异的测试成绩。",
		file_3 = "总是好心办坏事的千竹向因果取经，究竟怎么样才能真正帮助到别人？于是因果担起了千竹的半个“师父”，两人经常一起完成日行一善的目标。\n某次，千竹在帮助老人搬运一株月季花的过程中不小心把花盆摔碎了，再次将事情搞砸的千竹十分沮丧，为了让她打起精神，因果偷偷找到那位老人，恳请他撒一个善意的谎言。\n ——花盆是去世的妻子留下的，她还在其中藏了一封家信。如果千竹没有失手将花盆打破，老人永远无法解开和妻子的心结。\n单纯的千竹相信了老人的话，并重新振作起来，更加积极地帮助他人。事情却没有就此结束，老人受到因果的启发，真的在妻子的遗物中找到了什么，那不是书信，而是最后留给老人的真情告白的特别录音。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "因果的日记本里记载了日行一善的内容，但其中还有一个秘密——从日记本的最后一页翻起，上面记录的是因果做的恶事。\n 我们摘取了部分文字：\n 2月20日，我饿得晕倒在库库尔坎的小巷里，浑身黑色的流浪猫叼着一条香喷喷的烤鱼放在我面前。抱歉，我忘记说“我开动了”就把烤鱼吃得一干二净。\n3月7日，我拿到打工的报酬啦！我给小黑买了两条烤鱼，趁着它吃鱼的时候偷偷摸了耳朵。抱歉！毛茸茸的手感实在太好了，忍不住多揉了几下，小黑瞪了我好久。\n…………\n……",
		level_6 = 0,
		record = "根据因果的叙述，目前为止，她经历过最幸运的事是……在红苹果抽奖环节抽中了唯一的一箱青苹果。"
	},
	[213420] = {
		soulid = 213420,
		valuation = "同时拥有多个火枪的的梅莱拉，既可以交替对单个目标进行持续的火力压制，也可以操控多个火枪对多个目标进行打击。经过魂器学院改造过得魂器：天主之铳，拥有不逊于军队制式步枪的精度、火力、威力，在梅莱拉熟练地运用下，将成为非常强大的远程支援武器。",
		file_1 = "哈布斯家族：一个几百年前的帝国的皇室，帝国在战争中战败，由于种种原因，帝国便从此分崩离析，而皇族也从皇位上退下，一开始他们还被一些帝国遗老捧起来，但渐渐地，就没有人在把他们当皇族对待了，而哈布斯家族也很看的开，也慢慢的融入了平民百姓中，干着各行各业的工作，仿佛除了姓氏，很难看的出来，他们身上还有着皇族的血脉。",
		level_3 = 0,
		level_4 = 0,
		resume = "有着皇族血脉的梅莱拉，相比于隔壁身为尼格霍德大贵族的金百莉，履历就寒酸的多了。童年在巴哈姆特的一座很一般的小学中度过，家里的经济情况也只是刚刚糊口，没有上过什么兴趣班，玩伴也是周围邻居的孩子，直到X-MAS的爆发，在逃亡一年后加入魂器学院。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "梅莱拉的全名其实非常长，全名是：弗朗茨·阿瑟·梅莱拉·伯特·玛利亚·安妮·卡特·马斯克·奥德海姆·希斯特·克萨斯·费勒舍·雷克萨斯·路特斯·艾思坦·皮特·哈布斯公主。这在她电子身份上长达四行的名字也证明了，她确实是皇族。",
		file_3 = "梅莱拉大多时候并不想提及她皇族的身份，因为大多数人也不相信，但她总是以“余”自称，因为她想对于学院里面各怀绝技的学员来说，几乎什么都不会的她，貌似也只有皇族的身份了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "梅莱拉自幼收到祖训的教导，虽然帝国已然崩溃，皇族已然退下，帝国已然不是皇族的帝国，但人民还是帝国的人民，皇族要为人民的选择负责，就像长大的雏鸟，挣脱了父母的束缚，但父母依然要在它的身后护航，直到被彻底遗忘。",
		level_6 = 0,
		record = "因为其过于寒酸的经历，所以其皇族的身份被广泛质疑。"
	},
	[213820] = {
		soulid = 213820,
		valuation = "达芬奇本身并没有战斗的能力，而是完全依靠神来之笔所生成的“召唤物”的战斗力，而这便完全取决于操作者的想象力，但还好这位少女并不愧对达芬奇这一名字。但是她的这些”活过来“的作品，并不能长时间存在，根据不同的作用和使用方式，有着不同的有效时间。",
		file_1 = "布克丝院长最初是在一家蛋糕店的门口发现达芬奇的，那时她正趴在橱窗上望着里面一盘刚做好的拿破仑蛋糕，然后就被前来讨债的人围住，其中还有不少人骂她是利用全息投影的骗子。随行霓昂上前暂时缓解了局势后，达芬奇便不依不饶的缠住霓昂，让其购买她的作品，但当布克丝院长看见她和她的作品后，便瞬间明白，那才不是什么全息投影。",
		level_3 = 0,
		level_4 = 0,
		resume = "我们刚刚发现达芬奇时，她是在巴哈姆特的大街上靠着卖画和卖艺过着风餐露宿的生活，尽管本人一直声称自己是达芬奇，但绝大多数人都不会相信一个几百年前的传奇艺术家会在这个时代以女孩的样貌出现。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "达芬奇拒绝交待其原本的名字，且坚称自己是达芬奇，这一点让学院的工作人员为难无比，但是我们派人查阅了巴哈姆特的人口数据，却发现不了一点这位少女曾经的痕迹，于是我们便将信将疑，将其等级为列昂纳多·达·芬奇。",
		file_3 = "有关于她手中的画笔，布克丝院长早年认识的一位同僚对该项技术有着深刻的研究理论，但在X-MAS爆发后，布克丝院长便失去与这位同僚的联系。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "根据我们的调查，这位少女是突然在MAX-S之后不就出现在巴哈姆特的大街上的，没人知道她的具体来历，有几位和她一起睡过桥洞的“讨友”提到，她曾经应该是一个体面的人物，因为其好不容易赚来的大部分钱都被用于洗澡或购买一些卫生用品了。",
		level_6 = 0,
		record = "啊……今晚桥洞被占满了……去看看公园吧……"
	},
	[214120] = {
		soulid = 214120,
		valuation = "海洋是佩莎莉娅的主战场。在单兵作战中，她能利用魂器的火力，对水面敌人实施强而有力的压制。而当战斗来到了水下，佩莎莉娅便会钻入魂器内部进行驾驶，犹如海洋中凶猛的鲨鱼，在敌人间自如地穿梭，将障碍物逐一撕碎。",
		file_1 = "佩莎莉娅称，自己是因为军队的工作太多，想要找个地方安心钓鱼，所以才申请来到魂器学院。但是很明显，耶梦加得仅有的八名大将之一不可能会以这么随意的理由请到假，佩莎莉娅的到来肯定有更深的隐情。我们派人以护卫之名跟随这位不速之客，并时刻向我们汇报她的动向。但过了一个月，我们对她的疑惑反而变得越来越深。她似乎真的只是重复着每天去河边钓鱼，然后回学院休息的日常，一点也不像是有什么阴谋的样子。顺带一提，坐在佩莎莉娅旁边的老爷爷时常因为同情她的钓鱼技术差，而将自己钓到的几条鱼送给她。",
		level_3 = 0,
		level_4 = 0,
		resume = "佩莎莉娅的资料在耶梦加得早已公开，其父亲是前任海军元帅，母亲是鹭月教会的红衣大主教。佩莎莉娅从小就参与军队训练，在第四舰队的潜艇部队中服役了近十年，并凭借出色的表现一路晋升。在地劫战争爆发后，耶梦加得海军的内部构成发生了极大的变动，年纪轻轻的佩莎莉娅也在此期间被破格提拔为了大将。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "由于常年在潜艇中生活，佩莎莉娅的骨骼发育严重受到水压的影响，导致她在这个年纪依旧只有小学生般的身材。如果像正常人一样生活在陆地上，她现在理应拥有多出30厘米的身高，以及不输给任何超模的魔鬼身材。（以上内容来自佩莎莉娅的自我陈述，不具备任何科学依据。）",
		file_3 = "耶梦加得第四舰队，又称虎鲸舰队，曾多次击退本地以及来自库库尔坎的AI军团，守护了耶梦加得北部海域的安全。考虑到自己很大程度上是靠关系当上的大将，加之手下的船员们总跟自己保持着微妙的距离，佩莎莉娅曾一度以为，自己受到了船员们的排挤。某天，佩莎莉娅在部下的桌上发现了一枚印着自己头像的徽章。循着这条线索，一个隐藏在第四舰队内部的神秘组织逐渐浮出了水面。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "佩莎莉娅粉丝团，其成员几乎覆盖了整个第四舰队。组织内有着严格的等级制度，依据等级高低，成员被允许与佩莎莉娅大将有不同程度的接触，目前只有等级最高的20级成员有资格在早晨打扫大将的办公室。多年后的今天，当佩莎莉娅再次谈到当初发现这个组织的感想时，她已经能够露出淡然的微笑：“就当没看到吧......”",
		level_6 = 0,
		record = "才不是萝莉！"
	},
	[214320] = {
		soulid = 214320,
		valuation = "通过魂器，雅诺拉可以源源不断地从家族的武器库中调用装备。从强化近身战斗能力的外骨骼装甲，到远程火力压制所需的激光炮，为了向客户展现艾奎利伯家族的商品质量，这点损耗都在预算之中。当然，从家族的角度来说，还是希望她能把要卖的那部分留下来。",
		file_1 = "自打幼时起，雅诺拉的性格就十分内向。在家族聚会中，平平无奇的她从没有引起过大人们的关注。由于后代众多，艾奎利伯家主有时甚至会忘记这个孩子的存在。六岁那年，雅诺拉的一个妹妹死于果汁中的毒药。此后，恐惧和猜疑的链条便在家族中传播开来，家族的候选继承人们开始一个接一个因不明原因死去。为了远离这场血腥的纷争，雅诺拉被她的母亲带到了一处偏僻的住宅中生活。因此，虽然生于本家，但与她的兄弟姐妹们不同，雅诺拉度过了一段相对无忧无虑的童年。雅诺拉本以为，自己可以像这样做一辈子的家里蹲，直到那一天，老旧的电视画面中播放出了AI暴乱的新闻。",
		level_3 = 0,
		level_4 = 0,
		resume = "关于雅诺拉的信息，民间众说纷纭，很难分得清真假。目前可以确定的是，在继承人的身份公布前，雅诺拉几乎没有在正式场合露过面，而艾奎利伯家主此前重点栽培的几位儿女则在雅诺拉的亮相后销声匿迹。其余情报几乎都是没有凭证的流言，难以进行核实。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "雅诺拉共有12名兄弟姐妹，其中3人死于AI暴乱，3人死于帮派火并，1人死于坠楼，1人死于中毒，1人死于车祸，1人下落不明，还有2人在监狱服刑期间莫名死亡。身为家族中仅存的继承人，年纪轻轻的雅诺拉被火速接回本家，并受到了来自家中众人的期待，从小落下的厚黑学以及商业学课程也被迅速安排了起来。但很快，大人们的期待便落了空。他们似乎忘了，雅诺拉之所以一直被家族所忽视，正是因为她从来不具备管理一个家族的能力。",
		file_3 = "未来的领袖是一名家里蹲，这种事如果让分家的人知道，必然会引起一场声势浩大的下克上。届时，本就因AI暴乱而元气大伤的艾奎利伯家族，恐怕就难逃分崩离析的命运了。为了避免最糟糕的事态发生，即便没有相应的能力，雅诺拉也被要求扮演成一名合格的家族领袖，但在发现就连这样的要求都有些强人所难后，家族方面只好给雅诺拉设下最低程度的标准——只要，别让人看出你是个家里蹲就行了......",
		level_7 = 0,
		level_2 = 0,
		file_4 = "将雅诺拉送进魂器学院，从各方面来说都是一步稳棋。对外，艾奎利伯家族宣称这是对未来家主的一次历练，同时也是家族与魂器学院交好的象征。于内，他们清楚学院可以保证雅诺拉的人身安全，如果运气好，说不定真的能让这位不谙世事的大小姐学到什么东西。当然，即使雅诺拉什么都没学到，把她安排到学院里也至少可以为家族争取时间，尝试寻找其他解决困境的方法。",
		level_6 = 0,
		record = "脸戴铁面具，心覆钢铠甲。"
	},
	[214520] = {
		soulid = 214520,
		valuation = "在战斗中，艾可充分发挥了她对声音的掌控。通过对不同声音样本的调试、排列组合，艾可能使魂器发出功能各异的音波，从而应对各种场合的需要。",
		file_1 = "在大众眼中，理论家与创作者似乎向来是两条平行线，而艾可成功地将两者结合了起来。仅出道第一年，艾可就获得了2个国际音乐节奖项，11次提名，并以第一作者的身份在尼德霍格科学院顶刊发表了论文。虽然两头跑的生活经常让艾可忙得晕头转向，但她心中更多的还是成果被认可的喜悦。很快，电子音乐学会便向这位勤奋的姑娘抛出了橄榄枝。",
		level_3 = 0,
		level_4 = 0,
		resume = "佐迪亚家族是尼德霍格有名的音乐世家，在从小的耳濡目染下，艾可对音乐有着远超同龄人的灵性。作为电子音乐学会历史上最小的成员，艾可的研究成果为尼德霍格乃至全世界都带来了帮助。但在X-MAS爆发后不久，艾可便因不明原因离开了学会。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "过去的艾可一直幻想着，那个人才辈出的电子音乐学会究竟是一个什么样的组织。她如果加入其中，又能收获多少知识。但现实十分乐于给每位理想主义者一记耳光，作为一个受到尼德霍格资助的组织，学会内部论资排辈之风严重，不仅在研究方向上不顾社会实际需求，就连研究结果有时也能受到操控，先射箭再画靶子的情况在这里时有发生。作为一个年轻人，即便此前有过诸多亮眼的成果，艾可在学会里也依旧毫无话语权，好在学会新人之间的关系都相对融洽，不少有类似遭遇的人都跟艾可成为了朋友。从她们那儿，艾可学到了很多应付老教授的技巧，同时也对整个学会有了更加深入的了解。此后，在教授们的眼中，艾可就是一个听话且不起眼的小孩，对他们不会有丝毫威胁。但只有少数艾可的朋友知道，这个女孩绝不像她外表上那样人畜无害。",
		file_3 = "X-MAS爆发后不久，艾可便因声音样本的录制而申请退出电子音乐学会。她在离开前发布的最后一篇论文是关于声音能量场中的模因效应。该研究的目的原本是为音乐治疗提供理论指导，但论文一经发表，学会的其他成员就注意到了这个理论中蕴含的其他可能性。如果能制作出以声音为媒介的模因武器，现代战争的形式将会被彻底改变。学会的许多成员或直接，或旁敲侧击地向艾可提出了合作邀请，希望能一起完成这一可能在历史上留名的创举，但艾可对他们的回应从来不会变化。\n“比起为后世所恐惧的武器，我更希望留下能抚慰人心的音乐。”",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【艾可背包中的某个音频文件】\n“听说了吗？隔壁出大事了！”\n“那个全是老古董的电子音乐学会？算了吧，在那地方是龙得盘着，是虎得卧着，但凡你想搞出点名堂，就会有人出来打压你。”\n“针对的就是老古董。隔壁有个女孩，把她的导师举报了！”\n“我还以为什么事呢...理由是压榨学生？还是学术造假？没什么区别，那女孩的导师只要随便打点一下关系就能截下举报信，然后连带着她的学术生涯一起丢进碎纸机里。”\n“问题就是没截下来。也不知道那家伙是怎么想到的，她没把举报信交给任何官方组织，而是拿去给了鲁比克财团的千金。我们的爱丽丝小姐也是真配合，直接把举报信转交给了老总。”\n“嗯？这我得坐起来听了，然后呢？”\n“举报信里附带了一份录音文件，那老家伙怕是说了什么不该说的。总之，他已经在尼德霍格销声匿迹了。”\n“祸从口出啊......真可怕。”\n“可不是吗，不过那女孩前两天也离开了学会。可惜了，我还期待她能整出更大的动静呢。”\n“别开玩笑了，如果真要搞大清算，咱们两个能逃得掉？”\n“咱有会长罩着，有什么好怕的。要是会长跑了，我做污点证人也......怎么了，表情那么严肃...？”\n“说起来......你刚刚是不是提到——录音？”\n“是啊，有什么问题吗？”\n“那如果，我是说如果...我们现在的对话，也有人在录音的话......”\n“......哈哈，不会吧。“",
		level_6 = 0,
		record = "一起来艾可艾可吧。"
	},
	[213920] = {
		soulid = 213920,
		valuation = "倪克斯有着高超的剑术，这点毋庸置疑。但在拿上暗夜孤星后，她的剑路与身法会发生极大的改变，仿佛不是她在使用剑，而是剑在操控着她。然而，每当战斗结束，我们问起倪克斯的状况时，她总是表示自己一切正常。",
		file_1 = "鹭月教会的传说，即便是耶梦加得以外的人也有所耳闻。他们信仰着一位无名的神，关于这位神的一切都成谜，只知道当祂显现时，天空将挂上一轮蓝月。令人困惑的是，鹭月教会的传说在世界各地有相似却不同的版本。奥杜因的烛月教会认为月亮将变成红色，洛加尔的戏月教会认为月亮将变成黄色，而已被X-MAS破坏的胧月教会则认为月亮将变成黑色。从光学和天文学的角度看，他们的说法显然都有问题。但毕竟是传说，一定程度的偏离事实也在情理之中。",
		level_3 = 0,
		level_4 = 0,
		resume = "倪克斯，鹭月教会收养的孤儿，生父母下落不详。通过自幼的刻苦训练，倪克斯成为了新任的异端审判官，受教会高层的调遣执行了诸多任务，并在红衣大主教的引荐下，作为特使来到了魂器学院。由于从小过着远离网络的生活，她似乎对电子产品的使用一窍不通。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "倪克斯自幼展现出惊人的战斗天赋，深受鹭月教会高层的赏识。同时，她真诚的性格也使她结交了不少朋友。传言称她与红衣大主教的女儿、现任海军大将佩莎莉娅是旧识。不过，从佩莎莉娅对她的回避态度来看，这个传言的可信度并不高。在教会的精心培养下，倪克斯很快成为了教会的异端审判官。",
		file_3 = "何物当斩，何物不当斩，倪克斯心中有着明确的界限。在鹭月教会中，每位审判官都需手持教典，作为其判决遵循神意、公正不阿的象征。然而，倪克斯是个例外。自从接手暗夜孤星后，教会便取回了倪克斯的教典，并且从未对这一行为做出过解释。尽管倪克斯的内心对此仍感困惑，但能空出手来无疑是战斗中的一大便利。依靠着铭记于心的教义，倪克斯义无反顾地投身于教会赋予的使命中。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "加入学院后，因为学院的氛围与教会中截然不同，倪克斯一开始并没能很好地适应这里。有传闻说，在隐秘的角落里，倪克斯会偷偷跟自己的剑说话。学员们都以为这是因为倪克斯过于孤独而出现了幻想，为了帮助这位新同学，大家纷纷来邀请倪克斯一起玩，倪克斯也顺利融入了学生们的群体。但不知为何，偶尔仍有学生看到倪克斯在和自己的剑对话。",
		level_6 = 0,
		record = "试问，你就是我的班长吗？"
	},
	[214420] = {
		soulid = 214420,
		valuation = "刚开始，我们并不打算让端木参与前线作战，因为很难想象麻醉师能在对抗AI的前线发挥什么作用。然而，端木的表现出乎了我们的意料。在战斗中，端木能够快速锁定敌人的位置，并射出阻断电信号传输的“对机械用麻醉弹”来使敌人无力化。遇到生物型敌人时，端木的麻醉手段则更加多样化。许多敌人前脚刚踏进战场，后脚就在带铁窗的房间里醒来了。",
		file_1 = "“学霸中的学霸”、“卷王中的卷王”。\n提到端木，身边人往往都会给出上述的评价。这也难怪，作为自入校起专业排名就没掉下过第一的校园传奇，端木的形象在同学们的心目中早就超越了人类。每逢考试周，都会有学生在宿舍里拜端木的照片，希望能藉此沾上一点学霸的气息。当我们询问端木本人对这种现象的看法时，她只是轻描淡写地回了一句——\n“我没意见。”",
		level_3 = 0,
		level_4 = 0,
		resume = "端木研，派森大学医学部研三学生，吃苦耐劳，品学兼优。师承自生命科学院的白杨教授，目前正在申请攻读博士。作为魂器学院与外界学术交流的一环，来到魂器学院进行交流学习。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "“你就是端木吧。我的指导很严格，你可得跟紧了。”\n研究生阶段，端木师承于派森生命科学院的白杨教授。作为医学界的泰斗级人物，白杨一直是端木崇拜的对象。端木也暗自期望，自己能够在这位教授的指导下学有所成。\n“现在开始我们的第一节课——学会放松。”\n“放松？”\n“看好了，这招我从来不外传。”\n面前的年长女性翻身躺到沙发上，仅用了2秒时间就睡了过去。根据白杨事后的补充，她一直在尝试挑战0.93秒入睡的世界纪录。\n“唔......好了，现在换你。第一次不用太紧张，争取在3分钟内睡着吧。”\n“......”\n现在换导师还来得及吗...？向来循规蹈矩的端木，在与白杨第一次见面时，也不禁产生了这样的想法。",
		file_3 = "虽然过程充满波折，但端木的学业姑且顺利地推进了下去。白杨教授在学校里总是行踪不定，因此每当端木的研究卡壳，她都需要先想方设法找到导师的位置，才能请教问题。久而久之，端木总结出了一套寻找白杨的方法论，并将之整理成册。\n出乎意料的是，由于导师在各种重要会议中也时有缺席，这本《白杨行为指南》受到了许多生命科学院教授们的欢迎，端木也意外地间接靠导师拓展了人脉。很快，端木明确了自己的研究方向，并申请到了充足的经费。在与导师的斗智斗勇中，三年很快就过去了，端木在自己的研究方向上得到了可观的成果，她也开始打算在毕业后继续攻读博士学位。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“魂器学院......是吗？”\n临毕业时，白杨为端木准备了一份申请书，内容是与魂器学院的交流学习。根据端木的理解，一段海外高校的研学经历能为自己的博士申请带来优势，所以她没有犹豫就接受了。\n“端木，知道我为什么安排你去魂器学院吗？”\n“为了在白天睡觉时不被人叫醒。”\n“......我希望你在继续深造之前，能看清自己目前欠缺的东西。”\n虽然要考虑到导师嘴硬的可能性，不过端木还是将白杨的话记在心中，出发前往了魂器学院。作为自己求学之路的一环，端木在心中期待着，这次交流学习能为自己带来什么样的收获。",
		level_6 = 0,
		record = "飞鸟看向何处？或许只是空无一物的远方。"
	},
