	[214620] = {
		soulid = 214620,
		valuation = "由于蕾贝莉亚较少外出，她的身体状况并不适合前线战斗的要求。因此，我们安排她在后方从事医疗工作。在专业人士的教导下，很快她就掌握了医疗设备的操作技术，为团队在后方提供了有力的支持。",
		file_1 = "【蕾贝莉亚的日记·其一】\n    今天，窗外下着绵绵细雨，或许是要入秋了。我在书架前看了许久，想找点什么来打发时间。书不少，但都不是我想看的。\n    下午，我尝试着自己写点东西。然而，每次提笔时脑子里却一片空白。想到我过去读的那些书，心中不免感到羞愧，或许我没有成为作家的天赋吧。\n    傍晚，佣人们告诉我，晚餐准备了我爱吃的料理。但他们并不知道，其实我不喜欢吃鱼，也讨厌生姜的味道。我试着旁敲侧击地暗示我的口味已经变了，希望他们能明白我的意思。\n    平凡的一天很快就结束了。有时候我会想，如果能有个朋友该多好啊，哪怕让我在家里养只小猫也好，至少它会蹭蹭我的腿，让我知道我不是一个人。但母亲大概是不会同意的吧，毕竟猫咪没有家庭、身份这样的软肋，有的只是与生俱来的野性。这种无法掌握的生物，她是最讨厌的。\n    而且，她对猫毛过敏。",
		level_3 = 0,
		level_4 = 0,
		resume = "蕾贝莉亚，欧希莉亚联邦首领格兰的女儿。由于长年被格兰关在家中，外界几乎没有关于她的资料。在艾尔薇特，蕾贝莉亚对班长表现出了极大的友好度，并在之后的菲尼克斯节晚会上帮助班长等人逃离追杀。离开欧西利亚联邦后，蕾贝莉亚加入了魂器学院，成为医疗组的一员。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【蕾贝莉亚的日记·其二】\n    今天，一个佣人打扫房间时发现了我的日记，我久违地感受到一点紧张。那个笑容瘆人的家伙曾经告诉我要把日记藏好，但我没有照做。\n    不想任由她摆布只是一方面。另一方面，这么久以来我时常幻想，如果有人发现了这一切，如果有人拆穿了这场骗局，现在的生活会不会因此变得一团乱？或者，变得稍微有趣一点。\n    但不出意外，佣人根本没有关注那本日记。即便她看了里边的内容，大概也不会做多余的事情，只会默默将日记放回原位吧。他们正是这样，所以我才敢把日记堂而皇之地放在外面。\n    下次把它丢到院子里吧，兴许布谷鸟会喜欢我的秘密。",
		file_3 = "【蕾贝莉亚的日记·其三】\n    今天，那家伙又来了。她总是悄悄从门缝的阴影中出现，但我已经不会被吓到了。今天她是来检查之前交代给我的任务的。还没等我动手，她就擅自拿起了桌上的日记。\n    没过多久，她就确认完了这一个月的内容，还带着坏笑吐槽我的流水账，明明这是她要求我写的。不过，她对日记的内容本身没有发表任何意见，因为她比谁都清楚，这座宅邸中的生活有多么单调无趣。临走时她提到，这样的日子不会持续太久，变化即将发生，但这大概只是她惯用的骗术。当初我正是因为相信她的话，才会落入现在的境地。\n    算了，现在想这些也没用，还是睡觉吧。\n    希望明天，能发生什么有趣的事情。\n",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【入学影像】\n“你说...你认识我？”\n“是的，布克丝院长。刚才见面时我还吓了一跳呢，这么多年，您的外貌真是一点也没有变化。”\n“......我们以前有见过面吗？”\n“您或许没有直接见过我，因为我那时总是从窗户外悄悄偷看你们的实验室。”\n“如果不是研究所的安保出现了问题，我想你应该是某位研究员的家属。”\n“是的，妈妈那个时候一直忙着工作......”\n“格兰吗...我对其他部门的构成不怎么关心，原来她也是X-MAS的相关人员。”\n“......”\n“抱歉，刚刚只是我的自言自语。你在艾尔薇特帮了小布丁许多忙，仅凭这一点，我们就非常欢迎你的加入。”\n“谢谢您，院长。母亲犯下的错误，我会尽可能弥补的。”\n“你不用考虑这些...算了，我也没资格说这话，你就按你认同的方式去做吧。”\n（蕾贝莉亚再次向布克丝道谢后，离开了院长室。)\n“......”\n“......‘母亲’？",
		level_6 = 0,
		record = "天空没有留下翅膀的痕迹，但我已经飞过。"
	},
	[214720] = {
		soulid = 214720,
		valuation = "通过「绀红夜曲」的能力，湘湘能够扫描并完美复现他人的所有特征，包括容貌和声音。不过，这项能力限制颇多，无法随意使用。对湘湘来说，最简单的启动方法便是与目标签订契约，用合理的价格“买下”对方的一切。",
		file_1 = "嘿，小家伙。\n走错路了吗？怎么会来这种乌烟瘴气的地方？\n这里可不是你这样的大小姐应该来的地方，快点回去吧，你家里人该担心了。\n什么？你有想买的东西？\n哈哈哈！原来如此，原来是客人啊！\n是我失礼了，女士，你想要买什么？\n“刺激”...？看来你是第一次来到黑市啊，这位娇小的客人。\n这里的人，每天都过着把脑袋吊在裤腰带上的生活，刺激是这里最廉价的东西。\n你在笑什么...？你觉得这很有趣吗？\n真是疯了......\n喂，先别走。\n把你的名字告诉我，免得哪天你横尸路边，却没有一个人知道你是谁。\n“......”\n“湘湘。”",
		level_3 = 0,
		level_4 = 0,
		resume = "湘湘，班长等人在欧西利亚联邦执行任务期间认识的黑市商人，真名不详。她自称是联邦的地下统治者，掌握整个黑市的商品动向。在潜入艾尔薇特及随后的系列行动中，湘湘为魂器学院提供了许多帮助。另外，湘湘也是班长和蕾贝莉亚相识的中间人。但对于湘湘的真实情况，没有人能给出确切的信息。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "这个是什么？\n能让您变强壮的东西。\n这个又是什么？\n能让您变美丽的东西。\n买了，买了，\n我们喜欢你的诚实，我们喜欢你的贪婪。\n你是快乐王子的眼睛，是梅菲斯特的酒杯。\n大地自愿献出自己的赠礼，\n欧西利亚的阴影开始滋养鲜花。\n听，那是硬币的声音。\n叮铃，叮铃。\n馥风中回荡着低声细语，\n是了，她徘徊在夜里。\n——《欧西利亚民间诗选》",
		file_3 = "一件事情的价值有时并不在人们通过它获得了什么，而在于人们为它付出了什么。\n你说我是骗子？朋友，我可是在帮他们啊。\n喝咖啡是猫的哲学，从饮干的酒杯中倒出的，才是我们的生活。\n我售卖美梦，售卖葡萄与布鲁塞尔。\n小美人鱼可以从我这儿获得双脚，胡桃夹子......唔，勉强能修。\n有传言说我像乌鸦一样，逮着什么吃什么。\n我澄清一下，那是真的。\n那么，都聊到这里了，也该跟我讲讲你的事了。\n想要成为我的上帝吗？说出你渴望的，然后在这里签下名字。\n谢谢。\n果然，你们的信任，才是我最宝贵的财富。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "关于湘湘的一切信息都难以辨别真假。我们所了解的她的背景、人际关系，乃至现状大多源自她自己的叙述。唯一能确认的是，湘湘与多个城市的组织，包括黑手党、教会等都有所牵连。我们曾试图通过欧西利亚的黑市搜集更多信息，但得到的只是些模糊不清的流言蜚语。所幸，在艾尔薇特期间，我们认识一位了解湘湘并且值得信赖的人。虽然对方并未透露太多细节，但她给出了这样的提醒：\n“你们所知道的，关于她的一切——全都是假的。”",
		level_6 = 0,
		record = "我既是旁观者清，亦是当局者迷。"
	},
	[215020] = {
		soulid = 215020,
		valuation = "由于禄存小姐的娇小体型，时常有人忽视了她的能力。禄存拥有控制周围时间流速、使其加速或减慢的特殊能力。结合手中的远程武器，她在战场上能够施展多样化的战术组合。为了确保禄存有足够的作战空间，队友们通常会着重保护她；当然，这种保护也可能是出于单纯的疼爱。",
		file_1 = "「时间」从来不在我们的掌控之中。\n为了让授时尽可能精确，我们创造了闰年和闰秒，为我们理解时间的规则打补丁。然而，总有那连一秒钟都不到、几乎可以忽略不计的时间，无声地游离在我们的认知之外。我不知道该称之为「它」还是「它们」，但这种讨人厌的存在，就像一首和谐乐曲中的弦外之音，令我感到十分焦躁。\n我喜欢授时中心的工作。在这里，我每天都能跟时间打交道，用世界上最先进的仪器捕获那些困扰着我的杂音。或许是思想上的差异，有人说我不知变通，我将其作为称赞接受了。在我看来，变通毫无必要，正如我们所研究的时间。时间是死的，是任何意志都无法左右的概念。或许，在亲眼看到那可能一生也无法算尽的时间方程的那一刻，我才真正意识到，自己有多么热爱这个巍然不动的高洁存在。\n是的，「时间」从来不在我们的掌控之中。因为最短的缝隙之间，往往也是最难架起桥梁的地方。",
		level_3 = 0,
		level_4 = 0,
		resume = "禄存，派森科学研究院授时中心主任，兼任附属大学物理哲学系讲师。通过学术交流来到魂器学院，不过因为外貌太像儿童，进入学院时被工作人员误登记为了学生。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "禄存女士的一天总是十分忙碌。\n清晨，当同事们还在犹豫今天该选哪种咖啡时，她早已坐在实验室里。她对时间的安排总是要精确到分钟，以至于想与她交谈的人不得不跟着她一边走一边聊。不过，由于她的步伐较小，走路的时间往往足够双方把话说完，不知道这是不是她计划中的一部分。\n作为教师，禄存深受学生的敬爱。相比那些习惯拖堂的老师，她的上下课时间总是严格遵守学校的规定，连她的讲课速度似乎也经过精细调整，总能在下课铃响的那一刻准时结束。然而，这种对时间的严谨有时也让学生颇为头疼。对于许多老师而言可以睁一只眼闭一只眼的迟到和作业晚交，在禄存看来必须专门抽出时间进行一场严肃的说教。起初，有些调皮的学生会故意迟到，只为看看这位可爱的老师是如何进行说教的。但当禄存将时间的重要性真正传达给他们后，大家逐渐收起了嬉戏的心态，开始认真地遵守时间规划。\n另外，禄存似乎很在意自己的年龄。夸她年轻的话，会让她很开心。",
		file_3 = "【派森大学校园论坛】\n小学生真是太棒了：今天是我上学的第一天，但我知道我来对地方了。\n对闪光防御：又疯了一个。\n小学生真是太棒了：是真的！我在这里遇见了我的真命天女！！\n最上川：哪个哪个？是化学系的天才美少女？还是医学部的冰山女王？\n小学生真是太棒了：中午买早餐的时候看到的，她当时火急火燎地就从我面前走了过去，如果不是我刚好低头差点就没看到她。\n最上川：？\n最上川：她多高啊。\n小学生真是太棒了：不到一米四的样子。\n对闪光防御：不是兄弟。\n对闪光防御：[图片]\n琉璃单推人：我大概猜到你说的是谁了。\n最上川：我也想到了...\n小学生真是太棒了：真的吗！有她的联系方式吗？拜托了，义父！\n琉璃单推人：私你了。\n对闪光防御：？\n对闪光防御：没问题吗？把女生的电话给不认识的人。\n最上川：放心。\n（十分钟后）\n小学生真是太棒了：兄弟们，有《时间简史》吗？",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【公开情报-派森科学研究院】\n由派森政府资助，国内外著名科学家组成的组织。经历了时代的变迁，不断扩大规模，并与多所大学展开了深度合作。\n研究院下设物理科学院、生命科学院、传播科学院、过程工程院、天文台、授时中心和金属研究所七个部门。过去曾有人工智能研究所作为第八部门，但在地劫战争后彻底关停，相关人员也已全部遣散。\n目前，研究院理事长已经传至第二十代。二十代理事长上任后，对研究院的规章制度进行了大刀阔斧的改革。例如，取消各部门的论文数量指标，举办大型会议前需先说明其必要性，减少学术评估的频率。这些政策确实受到了研究员们的欢迎，但也有部分人担心其对研究院的长期影响。此外，理事长还提出了一些令人费解的规矩，例如为每个下设部门的主任授予专属称号，并要求他们每周参加理事长主持的茶会。",
		level_6 = 0,
		record = "班长，你还记得自己熬过多少次夜吗？"
	},
	[214020] = {
		soulid = 214020,
		valuation = "伊文捷琳的魂器适应性绝佳，但是几乎都集中在辅助方面的能力上了，她自身的战斗能力勉强能算是一般标准。",
		file_1 = "伊文捷琳母亲是隶属于教会的医护人员，如果让伊文捷琳说说自己对母亲的印象，那肯定是“天真”。 明明是成年人，但是毫不犹豫地将爱与希望挂在嘴边，受她影响，伊文捷琳也逐渐成长为温柔善良的少女。 伊文捷琳的母亲依靠先进的医疗技术救治了许多病人，在使用科技救治病人身体的同时，以信仰和温柔的言语治愈他们的心。 出于憧憬，伊文捷琳从小就立志成为母亲一般优秀的医护人员和信徒，为了达成这个目的，首要的目标是克服自身内向的性格，变成母亲那样开朗又招人喜欢的样子—— “小伊文现在这样不是挺好的嘛！”——来自当事人的母亲。",
		level_3 = 0,
		level_4 = 0,
		resume = "伊文捷琳，原籍耶梦加得。和大多数耶梦加得人一样拥有宗教信仰，跟随其作为医护人员的母亲学会了高超的医术，在“模拟智能网络”爆发时救治了诸多生命。 战后，学院对其发出了魂器适应性测试的邀请，伊文捷琳被测试出具有极其优秀的资质。对救治他人一事抱有使命感的伊文捷琳赞同学院的理念，故选择加入魂器学院医疗班，进行医疗方面的辅助工作。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "伊文捷琳的性格比较内向，平时与友人的交流更加倾向于倾听而不是对话。她几乎从不会与人辩论，但是如果有必要，她还是会平静地指出对方的问题。比起纠正现有的错误，伊文捷琳更加不想因为辩论制造出新的争端。对于是否要加入战斗，伊文捷琳也略显犹豫——不过只要看到有人受伤，她就会放下犹豫，全力投入到对他人的救治工作中去。 考虑到伊文捷琳这样的个性，院方将其安排到了医疗支援部队中，而且其产生的效果非常显著。在世界各地的救护行动中，伊文捷琳作为魂器学院派遣的医疗人员救治了无数的伤患，将学院的正面形象传播到了全世界。",
		file_3 = "“模拟智能网络”爆发后，耶梦加得同样陷入了人工智能反叛造成的混乱中，残酷的斗争迫使伊文捷琳拿起武器，加入到对抗人工智能的序列之中。 不过比起与敌人战斗，伊文捷琳更加擅长、也更加喜欢抚平他人的伤痛。 依靠过人的天赋与母亲悉心教导的医疗知识，伊文捷琳在战争期间救治了无数的伤患，甚至获得了教宗的嘉奖。 不过比起这些虚名，少女更加开心的是自己能够帮助到他人的事实，以及自己距离母亲更进一步的实感。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "实际上，一开始收到学院的入学邀请，伊文捷琳产生了犹豫。 获得了学院的支援，自己可能可以帮助到更多的人，这样的道理伊文捷琳也懂。但凭借自己的力量，仅仅是守护身边的人就已经是极限——伊文捷琳偶尔会冒出这样的想法。 “在这里妥协的话，放弃了那些在等待被你拯救的生命哦。”被母亲这样教育后，伊文捷琳终于下定了决心。 就算被说成自我满足也无所谓，自己能够帮助他人——这样的事实让伊文捷琳找到了自身的意义与使命。",
		level_6 = 0,
		record = "“虽然可能有点不切实际……但是我想要努力去拯救所有人！”"
	},
	[215020] = {
		soulid = 215020,
		valuation = "由于禄存小姐的娇小体型，时常有人忽视了她的能力。禄存拥有控制周围时间流速、使其加速或减慢的特殊能力。结合手中的远程武器，她在战场上能够施展多样化的战术组合。为了确保禄存有足够的作战空间，队友们通常会着重保护她；当然，这种保护也可能是出于单纯的疼爱。",
		file_1 = "「时间」从来不在我们的掌控之中。\n为了让授时尽可能精确，我们创造了闰年和闰秒，为我们理解时间的规则打补丁。然而，总有那连一秒钟都不到、几乎可以忽略不计的时间，无声地游离在我们的认知之外。我不知道该称之为「它」还是「它们」，但这种讨人厌的存在，就像一首和谐乐曲中的弦外之音，令我感到十分焦躁。\n我喜欢授时中心的工作。在这里，我每天都能跟时间打交道，用世界上最先进的仪器捕获那些困扰着我的杂音。或许是思想上的差异，有人说我不知变通，我将其作为称赞接受了。在我看来，变通毫无必要，正如我们所研究的时间。时间是死的，是任何意志都无法左右的概念。或许，在亲眼看到那可能一生也无法算尽的时间方程的那一刻，我才真正意识到，自己有多么热爱这个巍然不动的高洁存在。\n是的，「时间」从来不在我们的掌控之中。因为最短的缝隙之间，往往也是最难架起桥梁的地方。",
		level_3 = 0,
		level_4 = 0,
		resume = "禄存，派森科学研究院授时中心主任，兼任附属大学物理哲学系讲师。通过学术交流来到魂器学院，不过因为外貌太像儿童，进入学院时被工作人员误登记为了学生。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "禄存女士的一天总是十分忙碌。\n清晨，当同事们还在犹豫今天该选哪种咖啡时，她早已坐在实验室里。她对时间的安排总是要精确到分钟，以至于想与她交谈的人不得不跟着她一边走一边聊。不过，由于她的步伐较小，走路的时间往往足够双方把话说完，不知道这是不是她计划中的一部分。\n作为教师，禄存深受学生的敬爱。相比那些习惯拖堂的老师，她的上下课时间总是严格遵守学校的规定，连她的讲课速度似乎也经过精细调整，总能在下课铃响的那一刻准时结束。然而，这种对时间的严谨有时也让学生颇为头疼。对于许多老师而言可以睁一只眼闭一只眼的迟到和作业晚交，在禄存看来必须专门抽出时间进行一场严肃的说教。起初，有些调皮的学生会故意迟到，只为看看这位可爱的老师是如何进行说教的。但当禄存将时间的重要性真正传达给他们后，大家逐渐收起了嬉戏的心态，开始认真地遵守时间规划。\n另外，禄存似乎很在意自己的年龄。夸她年轻的话，会让她很开心。",
		file_3 = "【派森大学校园论坛】\n小学生真是太棒了：今天是我上学的第一天，但我知道我来对地方了。\n对闪光防御：又疯了一个。\n小学生真是太棒了：是真的！我在这里遇见了我的真命天女！！\n最上川：哪个哪个？是化学系的天才美少女？还是医学部的冰山女王？\n小学生真是太棒了：中午买早餐的时候看到的，她当时火急火燎地就从我面前走了过去，如果不是我刚好低头差点就没看到她。\n最上川：？\n最上川：她多高啊。\n小学生真是太棒了：不到一米四的样子。\n对闪光防御：不是兄弟。\n对闪光防御：[图片]\n琉璃单推人：我大概猜到你说的是谁了。\n最上川：我也想到了...\n小学生真是太棒了：真的吗！有她的联系方式吗？拜托了，义父！\n琉璃单推人：私你了。\n对闪光防御：？\n对闪光防御：没问题吗？把女生的电话给不认识的人。\n最上川：放心。\n（十分钟后）\n小学生真是太棒了：兄弟们，有《时间简史》吗？",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【公开情报-派森科学研究院】\n由派森政府资助，国内外著名科学家组成的组织。经历了时代的变迁，不断扩大规模，并与多所大学展开了深度合作。\n研究院下设物理科学院、生命科学院、传播科学院、过程工程院、天文台、授时中心和金属研究所七个部门。过去曾有人工智能研究所作为第八部门，但在地劫战争后彻底关停，相关人员也已全部遣散。\n目前，研究院理事长已经传至第二十代。二十代理事长上任后，对研究院的规章制度进行了大刀阔斧的改革。例如，取消各部门的论文数量指标，举办大型会议前需先说明其必要性，减少学术评估的频率。这些政策确实受到了研究员们的欢迎，但也有部分人担心其对研究院的长期影响。此外，理事长还提出了一些令人费解的规矩，例如为每个下设部门的主任授予专属称号，并要求他们每周参加理事长主持的茶会。",
		level_6 = 0,
		record = "班长，你还记得自己熬过多少次夜吗？"
	},
	[214920] = {
		soulid = 214920,
		valuation = "伊琳卡对于魂器的适应性远超我们的预料，同时也超出了她自己的预料。第一次拿到魂器时，她轻松地理清了其内部构造，并尝试进行改装。在布克丝院长的许可下，我们没有阻止她改装魂器的行为。结果，她的魂器很快变成了能投射出五彩灯光、并倒出各种饮料的古怪派对用具。虽然不合规矩，但这些改装并未影响魂器在战场上的正常运作，所以我们也只能默认了伊琳卡的做法。",
		file_1 = "「奇怪，头好痛......」\n少女最初的记忆，是陌生的天花板。身着白衣的护工来去匆匆，直到少女尝试着坐起身，才被其中的一位发现。\n「我...是谁......？」\n\n「这种情况我见过，是失忆。」\n少女想要摸一摸自己的脑袋，但在注意到头上还缠着的绷带后便放弃了。\n「请问该如何治疗呢？」\n「不清楚。」\n「您不是说见过这种情况吗...？」\n「嗯，在晨间的连续剧里。」\n「这样就下诊断真的没问题吗！？」\n「放心吧，这种症状不会危及生命。而且你已经很幸运了，外边的大部分伤员可不是简单打个绷带就能治好的。」\n「哈...说的也是...」\n「实在不行的话，就去这个地址看看吧，说不定会对你有所帮助。」\n「这里难道是...我家？」\n「这是个非常灵验的许愿池，你可以试着在那里找回记忆。」\n「您真的是医生吗！？」\n\n之后，少女在许愿池边意外遇到了自己的家人，并从他们口中得知了自己的名字——伊琳卡。然而，当她想回去向那位医生道谢时，却发现救治站里已经没有了那位医生的踪影。",
		level_3 = 0,
		level_4 = 0,
		resume = "伊琳卡，阿尔贝娅集团的千金。地劫战争期间随家人一起逃亡至欧西利亚联邦，途中因事故而失去记忆。在艾尔薇特生活期间，意外发现了自己有着当司仪的天赋，随后便往返于各个社交场合，构建了自己的庞大人脉网。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "伊琳卡原本是阿尔贝娅财团的千金。在地劫战争期间，阿尔贝娅财团整体迁移到了欧西利亚联邦。伊琳卡在逃亡过程中与家人失散，并且受伤导致她失去了记忆。这就是家人们告诉伊琳卡的，关于她的经历。\n\n「我有问题，妈妈。」\n「说吧，我的宝贝伊琳卡。」\n「能给我看几张我小时候的照片吗？」\n「......在迁移过程中，全都弄丢了。」\n「那能给我讲讲我小时候的事情吗？」\n「那、那个...对了！你小时候...曾经一个人赶跑了闯进家里的小偷哦。」\n「这样啊...」\n\n「这帮家伙，是把我当成笨蛋了吗...」尽管心中有着这样的想法，但伊琳卡眼下也别无选择，只能先陪着家人们继续这场漏洞百出的过家家游戏。至于为了打发时间而成为派对司仪，那又是之后的事情了。",
		file_3 = "【伊琳卡的笔记】\n第一次进学院的时候，真是吓了我一跳。那个坐在书堆上的小女孩看到我以后，突然上来捏我的脸蛋，还问我为什么变得这么年轻。我以为她是谁家的调皮小孩，把她抱了起来，但是在班长介绍后，我才知道她是所学院的院长。\n进入学院以后，怪事就更多了。那个拿着双刀的短发小妹妹，一看到我就会后撤步并摆好架势。还有那个双马尾小姑娘，时不时在说话时将我称为老师，明明我也没比她大几岁。\n我敢打包票，这里绝对有人知道我的真实身份。但是当我想打探自己的过去时，她们又都变得三緘其口。要想从她们口中探出情报，看来得另辟蹊径才行了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【权限资料】\n坎佩尔·锡兰，认知科学家，耶梦加得理工大学软件工程学教授，演化系统研究中心总负责人，同时还兼任了多家企业和研究机构的技术顾问。\n地劫战争前夕，曾在阿拉斯加研究所参与EDEN的研究，在地劫战争中下落不明，推测已经遇难。\n\n「我不明白，院长。伊琳卡想要的应该就是这个吧，为什么不直接把这份资料给她看？」\n「我们的工作不是满足学员的愿望，小布丁。让她保持什么都不知道的状态，对大家都好。」\n「...那如果对象是我，你也会这么做吗？」\n「......」\n（微弱的叹气）\n「明知故问。」",
		level_6 = 0,
		record = "派对要开始了！"
	},
	[215120] = {
		soulid = 215120,
		valuation = "综合实力相当之强，能够使用世界上所有类型的格斗技巧，体能测试结果非常接近玛琉的数值，她也打破了魂器学院曾经的纪录，在各方面表现也相当优异。",
		file_1 = "表面上塞雅表现的非常冷漠，但是内心还是一个极度温柔的少女。她会常常帮助那些需要帮助的魂姬，但塞雅却很少与魂姬们交流，除了玛琉。 也许是因为曾今的一些事情才导致塞雅如今性格吧。她不想过于亲近她人，也许是不想再见到友人在自己面前倒下吧。 对了，塞雅好像与玛琉的能力非常接近，但又不完全一样。塞雅各项能力指数相对于玛琉的能力指数要相对弱一些。 虽然同为“强化人”，但塞雅还是明显弱于玛琉，这是为什么呢？",
		level_3 = 0,
		level_4 = 0,
		resume = "塞雅·瑟尼欧里斯自卑而温柔的少女，心思单纯，容易轻易信服别人，自小在孤儿院长大，因为自己的能力而被孤儿院驱逐，后加入卡莱克尔防卫部。害怕给别人添麻烦，认为自己给周围的人带来了不幸，因为卡莱克尔防卫部收留了自己而对防卫部的人尤其是部长感激有加。 早期一直在孤儿院生活，孤儿院的生活很痛苦，塞雅甚至不能哭泣，后来因为觉醒了能力，破坏了孤儿院的设施而被赶出（塞雅本人并不知道自己的能力），之后一直在卡莱克尔城区里流浪，直到遇到了卡莱克尔防卫部部长。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【变式-Ⅱ】试剂与原型【变式】能够赋予人类的能力近乎相同，唯一区别是它弱化了与人类细胞相结合的突变速度。 变式能够通过重新组合生物遗传因子的特性，来使得人类获得新的潜力，但它所造成的二次突变却导致了人类在转为“强化人”过程中的突然变异。 就人类而言，有承受试剂力量体质的人，数千万人之中最多只有1个。 但是为了量产“强化人”，卡莱克尔的科学家优化了试剂对人类细胞的突变速度，能够更安全的转变为“强化人”。 不过能够承受新型试剂力量体质的人，数百万人之中最多只有1个。",
		file_3 = "以下为塞雅在学院内三个月以来的实战记录：       \n【记录一】 塞雅对战布兰琪   场地：虚拟城区   结果：压倒性的优势击倒了布兰琪（胜利）\n【记录二】 塞雅对战斯卡兰斯   场地：虚拟沙漠   结果：塞雅与斯卡兰斯一开始战斗时表现五五开，在长时间的高温环境下，斯卡兰斯无法适应酷暑而倒下。（胜利）\n【记录三】 塞雅对战玛琉   场地：虚拟城区（雨天）  结果：在玛琉面前，塞雅的表现并不是很出彩，所有招式都被玛琉所看穿（战败）        \n根据以上记录，我们发现了塞雅拥有常人远所不及的力量、敏捷、敏锐度、体格。而且加上她以前是一名出色的战士，这使她在模拟训练中表现的极为出色。   \n但是在与玛琉对战中表现得相对弱势，虽然两人同为“强化人”，塞雅的能力明显弱于玛琉，而且在战斗技巧上也稍逊于玛琉。       ",
		level_7 = 0,
		level_2 = 0,
		file_4 = "塞雅最痛苦记忆莫过于“6.13”行动，这次行动主要是剿灭准备袭击卡莱克尔得武装团伙，但是似乎这次行动情报被武装团伙所窃取。 塞雅的队伍到指定地点，就受到了来自武装团伙的攻击，除塞雅外其他人员都在这次行动中失去性命。 而塞雅被不法分子（其他城区）用榴弹炸伤，后被赶来来的玛琉小队带回医院，在生命垂危的时候，“变式-Ⅱ”拯救了她的性命。 不仅如此试剂还使得塞雅极强的再生能力、力量以及速度。当塞雅在病床上醒来的时候，询问护士其他小队成员还安好吗？ 护士只是让她冷静，好好休息，塞雅似乎是明白了什么，她只是静静的躺在床上开始默默的哭泣。",
		level_6 = 0,
		record = "如今明明拥有了一切，却对此无知无觉，而是愚蠢地沉浸在过去的伤痛里。"
	},
