	[215520] = {
		soulid = 215520,
		valuation = "凭借多年来对人体的深入研究，莉莉亚可以将客户“化妆”成指定的外貌。同时，只要提供的信息足够，就连特定的体型、声音也可以完美地复现出来。但莉莉亚的能力与整容不同，终归是昙花一现的产物。如果客户想要维持这张虚假的皮囊，就只能一次又一次地敲开美容院的大门。",
		file_1 = "尼德霍格的上空总是笼罩着一团黑影。\n小的时候，莉莉亚问自己的父母，为什么他们不能活在阳光下？父母笑着告诉她，正是那团黑影让他们衣食无忧。莉莉亚不理解父母的意思，只知道，黑影是朋友，自己应该学着接受它。\n随着年龄渐长，莉莉亚像身边的同龄女生们一样，开始喜欢打扮自己。而莉莉亚在她们之中也相当特殊，学术世家的风气让她对任何事情都投以极端的认真。莉莉亚在课余时间系统地学习了造型艺术和美体艺术，她喜欢将自己当作“小白鼠”，在身上实验刚刚得出的“学术成果”。所幸，在莉莉亚染指整形技术之前，她的父母就发现了女儿的异常，并将她引导至更加“适合”她的方向——生物医学。",
		level_3 = 0,
		level_4 = 0,
		resume = "莉莉亚·奥古斯塔，尼德霍格一家美容院的老板。通过为客户提供几乎完美的易容服务，莉莉亚在暗巷中获得了不小的名气。不过，每当赚到一定的经费时，莉莉亚就会从客户们的视野中消失一段时间。据她所说，自己是为了帮好朋友拍摄电影而时常外出，但有不少人怀疑，拍电影只是幌子，她的离开另有所图。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "莉莉亚的想法很容易就会被引导。在大学里，她只是听了导师的几句未来展望，就决定将仿生学作为自己的研究方向，并全身心投入了导师公司旗下的义体开发中。\n「许多人会得到我们的帮助，这是一项造福世界的事业。」\n莉莉亚对这些话深信不疑，但她的学长们早早看出了端倪，劝导莉莉亚不要将这份工作想得太伟大。\n不久后，莉莉亚的实验室研发出了新一代义体。各大媒体纷纷前来采访祝贺，莉莉亚的导师也对她大加称赞，新闻里称他们是拯救残疾人的天使，一切似乎都在往好的方向发展。但时不时地，莉莉亚会想起学长的话，并在夜里思考其中的含义。",
		file_3 = "「天底下没有免费的午餐。」\n「我明白这个道理，老师。可是您定的价格也太......」\n「这是他们努努力就能够到的价格，你不要再管这件事了。」\n新一代义体的性能十分优秀，在媒体的吹捧下更是被传得神乎其神。然而，过于昂贵的定价让大部分人都无福消受这款跨时代产品，莉莉亚自知干涉不了导师的决定，只好默默地准备起下一项研究。\n但是，事情的发展逐渐变得奇怪。自从莉莉亚他们研发的义体上市，其他义体品牌就一个接一个下架，连打价格战的打算都没有。莉莉亚想起了学长的话，她很快发现，自己的导师正在打压其它义体品牌，以此形成自己的垄断。\n「生意场就是这样，不是你死，就是我活。」\n「但是您做的太过了，老师。」\n「......莉莉亚」\n看看你拥有的一切吧。你也是获利者，不是吗？",
		level_7 = 0,
		level_2 = 0,
		file_4 = "尼德霍格的上空总是笼罩着一团黑影。如今，莉莉亚总算认清了它的真面目。\nX-MAS爆发后，实验室毁于一旦，对于义体的研究也被无限期搁置。但在莉莉亚看来，这一切却像是解脱，她终于能放开手脚，做自己想做的事情。\n\n「欢迎光临~请问你想要什么样的造型？」\n「听...听说你这里能把我化妆成任何样子...我要变成这样，能做到吗？」\n莉莉亚接过皱巴巴的海报。在无视掉那些庸俗的标语后，她很快理解了客户的需求。\n「没有问题，一切都交给我吧~」\n客户坐在化妆镜前，期待起了不久后焕然一新的自己。但她并不知道，自己在不知不觉中，已经成为了砧板上的鱼肉。\n\n贪婪的愿望，渺小的愿望，二者的价值或许没有本质上的不同，但在遮天蔽日的黑影下，价值的概念早已被扭曲。莉莉亚时而怀疑，自己是否拥有裁定价值的权力？但她不会后悔自己的决定。毕竟，这一切都是在既有的规则下进行的。\n毕竟，天底下没有免费的午餐。",
		level_6 = 0,
		record = "事实上，钱才是最好的化妆品。"
	},
	[215920] = {
		soulid = 215920,
		valuation = "妮妙学员自身的作战能力完全依靠那个兔子玩偶形状的魂智能机兵，虽然在远程控制与操作能力上显露出了天赋，但本身并不是适合战斗的类型。反之，作为辅助人员或许是不错的选择。",
		file_1 = "妮妙的父亲是玩具制造商，母亲是VR系统工程师，两人皆是工作繁忙。为了不冷落乖巧的女儿，在那个虚拟现实盛行的时代，两人共同为妮妙在“Avalon”上创造了童话一般的王国，“巴特莱尔”则是为了管控妮妙的教育与网络生活而创造出的人工智能管家。虽然与现实世界的接触减少，但完美的人工智能教学与生活规划并不会令妮妙产生与现实世界的隔阂，在VR网络上是享受着高端教育、劳逸结合的精英子女，在现实中是落落大方、惹人喜爱的大小姐，妮妙的人生轨迹一帆风顺——本来应该是这样的。",
		level_3 = 0,
		level_4 = 0,
		resume = "来自基金会，内向乖巧的大小姐。时常携带着叫做“巴特莱尔”的兔子玩偶，这个兔子形状的魂智能机兵时不时地就会在主人与他人交谈的时候插上几句嘴，将话题导向有利于主人的一面。作为接受了精英教育，被另一位基金会大小姐爱丽丝视作宿敌的天才，妮妙熟悉大多数基金会的尖端科技，能够熟练掌控大部分运用在魂智能机械中的基底技术。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "虚拟城市“阿瓦隆”，是在“星光系统”上建立的VR交互环境。设立之初，基金会将“把人们的日常生活以全新的方式展现在虚拟城市中”、“即使分处两地依旧能够零距离接触”作为口号进行宣传活动。实际上，“阿瓦隆”的存在的确为人们带来了极大的便利，近乎真实的工作、生活体验和多样化的娱乐系统使其轻易地获得了大量的用户。患有先天疾病、身体残疾乃至身体机械化的义体人，同样可以在这里享受到完整的生命。对于人类来说，在“阿瓦隆”中享受天堂一般生活同时，也能够不冷落现实的人际关系，这也是妮妙的父母放心地将少女“寄宿”在这里的原因之一。",
		file_3 = "如果说“模拟智能网络”对现实中的城市造成了巨大的混乱与破坏，那对于“Avalon”造成的就是毁灭性的灾难。虽然与完全将精神投射到“Starlight-System”义体人不同，自然人的躯体不会直接遭受来自“模拟智能网络”的攻击，但来自精神上的冲击依旧足够使人发狂。被封闭在虚拟的城市中，无法依靠自己的意志离开，一次又一次地遭受着现实中同样正在发生的苦难。当现实中的救援队以强制手段将妮妙的意识唤回时，妮妙已经患上了失语症，性格也变得与过去大相庭径。虽然妮妙的精神状态在之后的细心治疗中有所好转，但是原本天真活泼的少女已经变地孤僻，再难与人相处。但是，事情在某一时点迎来了转机。在疗养院接受着治疗的妮妙，忽然有一天收到了幼时玩伴的邀请而久违地踏出了房间，少女的目的正是爱丽丝所在的地方——魂器学院。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "实际上，妮妙怀中的布偶并没有内置人工智能系统，陪伴着她一同长大的人工智能程序“巴特莱尔”早在“Avalon”被叛乱人工智能控制的时候就已经为了保护妮妙而被破坏。现在的“巴特莱尔”仅仅是学员为妮妙量身定制的魂智能机兵，所有看似“兔子”的发言都是由妮妙假装成“巴特莱尔”发出的，无论是谁只要与她相处久了都能发现这一点。这里面既包含了妮妙对于陪伴自己长大的“兔子管家先生”的不舍，又有因为自信被摧毁产生的社交障碍的因素。",
		level_6 = 0,
		record = "来吧，游戏继续。"
	},
	[215720] = {
		soulid = 215720,
		valuation = "因为有雇佣兵时期的作战经验，黑卡蒂的战斗能力极高，即使在没有魂器的情况下，她也能徒手与持械敌人战斗。持有魂器时，她的身体能力会得到大幅提高，这让她能更好地面对情况多变的战场。",
		file_1 = "参与过尼德霍格前线作战的军人里，有不少都见过黑卡蒂。他们有的说她作战能力高超，是个优秀的队友；有的说她难以沟通，像一个没有感情的机器。但毫无疑问，作为一个穿梭于各个战场的雇佣兵，黑卡蒂给每一个见过她的人都留下了很深刻的印象。\n黑卡蒂的接单标准很明确，她不在乎报酬的多少，只要是与AI的战斗，她就愿意参加。很多人认为，她大概是地劫战争的受害者，还遭遇过亲人被AI杀害之类的事情。在那个年代，战场上时时能看到有这样悲惨过去的雇佣兵，以至于许多人已经对此感到麻木。而黑卡蒂身上那股阴暗的气质，让不少初出茅庐的新兵感受到，自己正身处战场。",
		level_3 = 0,
		level_4 = 0,
		resume = "黑卡蒂·露易丝，地劫战争时期曾充当雇佣兵，参与过拉塔托斯克战役、纳斯特隆德战役以及尼德霍格夺回战。尼德霍格解放后，在影视街作为自由摄影师活动，会接受各个片场的委托，其摄影水平在行业中评价颇高。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "黑卡蒂的雇佣兵生涯不长，她也不曾跟任何人提起自己在战场上的故事。当我们认识黑卡蒂时，她已经是一名穿梭于各个片场的摄影师，凭借圈内积攒的人气源源不断地接受工作。\n凯瑟琳对黑卡蒂的水平赞不绝口，据她所说，黑卡蒂就像是会读心一般，是少数能实现她剧本上奇怪描述的人。我在接过凯瑟琳递上来的东西后，一时间误以为这是一张包过三明治的废纸，但经她说明后，我才知道这就是刚刚谈话时提到的“剧本”。\n「她的想法并不难懂。」\n「真...真的吗？你是说这张纸上面的不是油和调料滴上的污渍，而是传达了某种意义的文字？」\n「......」\n黑卡蒂的沉默让我们有些紧张，或许艺术方面的事并不是我们能插嘴的，刚刚的话可能冒犯到了她和导演。\n「这个剧本是她吃三明治的时候，灵机一动写在包装袋上的。」\n重洗了一次手后，我在黑卡蒂的帮助下解读出包装袋的符号。虽然不想承认，但那确实是一个感觉会很有趣的剧本。",
		file_3 = "黑卡蒂的摄影技术毋庸置疑，许多业内人士都给出了极高的评价，甚至有人想要把她招入自己的公司，但其中绝大部分都被黑卡蒂拒绝了。\n是的，绝大部分。最终，黑卡蒂在明面上还是加入了一所公司，虽然那是一所难以称之为公司的不正经的地方，公司的老大也允许了黑卡蒂像以往一样接私活，不过黑卡蒂确实有了一个能公之于众的身份——“环城影业”的首席摄影师。有了这层背景后，来招募黑卡蒂的人明显变少了，毕竟大部分人都不想在圈子里留下挖别人墙角的坏名声，也不想招惹那个有名的怪导演。总之，黑卡蒂确实因此得以排除外界干扰，专心于摄影工作。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "「黑卡蒂...啊，她已经死了，在尼德霍格解放的那一天，跟那群AI一起。」\n「什么？你说她还活着？她在哪里！？」\n「如果她还活着，那就是活着的传说啊！她单枪匹马闯进了科算中心，在一场爆炸中跟对方的首脑同归于尽了，本来应该是这样的。她要是活着，应该被授予一枚...不对，十枚勋章！然后作为尼德霍格的英雄受人景仰...所以，她在哪里？」\n「环城影业...？你是说那个英雄...现在成了一个烂片摄影师！？」\n「别说笑了，如果真是那样，那我还不如相信她死了！」",
		level_6 = 0,
		record = "我将来，想当摄影师。"
	},
	[216020] = {
		soulid = 216020,
		valuation = "机密档案不可查看",
