	},
	[215620] = {
		soulid = 215620,
		valuation = "露米埃尔的能力，简而言之就是读心。但她完全无法操控这个能力，导致各种各样的声音总是在她的脑海中交织在一起，形成了某种诡异的噪音。不过，露米埃尔并没有意识到自己的能力，她把脑海中的声音当作自己天然的体质，将偶尔一闪而过的话语作为电影的灵感而接受。通过专业的训练，露米埃尔可以在一定程度上控制读心的能力，但大部分时候，她还是会放任自己的能力暴走，并享受这种大脑被噪音填满的感觉。",
		file_1 = "杰克是一名年轻的穷画家，他在一次搭船出行中遇见了贵族少女罗丝。罗丝早就厌倦了贵族生活，她与杰克相爱，并暗中约定终生。但天有不测风云，某天晚上，轮船撞上了路过的鲨卷风，罗丝被卷入其中，生死未卜。愤怒的杰克引爆了轮船，与鲨卷风同归于尽，成功救出了鲨鱼腹中的罗丝。但船已经开始下沉，最终杰克把生存的机会让给了罗丝，因此罗丝得以存活，将这段故事传递给后人。\n「......这是什么？」\n「剧本。」\n「你确定这种东西有人看？」\n露米埃尔对着投资人轻笑一声，扶了下摆架子用的墨镜。\n「一定会流行起来的。」",
		level_3 = 0,
		level_4 = 0,
		resume = "露米埃尔·凯瑟琳，尼德霍格著名导演。不过，她的著名不全是正面意义上的。每当电影海报中出现这个人的名字，观众们就能明白，这不会是一个规规矩矩的电影。浪漫喜剧中突然爆发的丧尸危机，科幻片里误入的西部牛仔......露米埃尔的电影总是充满了让人意想不到的情节，这些作品在许多业内人士看来完全是比学生电影还不如的胡闹，但也有部分观众热衷于享受这种荒诞的感觉。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "来拍电影吧！\n这很可能是你此生绝无仅有的机会，只要参加试镜，就有机会加入到史上最伟大的剧组里，拍摄近一年来最完美的电影。我们拥有行业领先的高端设备，专业实力过硬的团队，以及感人肺腑的剧本。现在我们缺少的只有一位主角，而你——或许就是我们正在寻找的对象。\n「可以，海报的内容就这么写吧。」\n「......我说，既然你的牛都吹得这么大了，为什么还只是近一年最完美的电影？」\n「哼哼，那还用说吗？」\n凯瑟琳扶了扶墨镜，似乎打算把这作为自己的招牌动作。\n「因为我的下一部电影，肯定会更加完美。」",
		file_3 = "经过学院鉴定，露米埃尔的大脑在她能力的影响下已经发生了一定的功能紊乱。对于在这种情况下依旧能够和人正常交流的露米埃尔，学院的医生们都感到很惊讶。\n「我？病了？怎么可能~」\n「几乎没有人能在这样的噪音下保持理智，虽然我们很好奇你是怎么做到的，但出于职业素养，我们还是要先将你治好。」\n「你是说...这个声音之后会消失掉吗？」\n「没错，我们得先让你恢复正常人的知觉，之后的康复还需要...等等！？你去哪？」\n「观众们还在等着我的新片子呢，我怎么可能有空让你们捣鼓我的脑子。不过...精神病院和人体实验...这说不定是个不错的题材~」\n露米埃尔潇洒地离去，还用手扶了扶她鼻梁上根本没戴着的墨镜。我们没有资格强迫她接受治疗，只是在那之后又为她安排了几次检查，并尽力延缓她的病情。对于这名导演来说，她所感受到的世界或许并没有我们想象的那么疯狂。但也有可能，露米埃尔早就失去了判断能力，在她眼中，反而那个充满了混沌与噪音的世界才是正常的。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "「您喜欢电影吗？」\n「当然，电影可不只是工作，它更像是我的精神食粮，我的生活，我用来反映自己的镜子。」\n「能说说您第一次拍电影的契机吗？」\n「那是一个忧郁的夜晚，我正因为头疼而睡不着觉，这时我看到了外面两只流浪猫在打架。我拿起手机录制它们的身影，并在之后的几天持续拍摄它们，为它们的行动思考合理的可能性，最终把拍到的画面按我的想法剪辑成了半个小时的片子。」\n「那部片子讲了什么呢？」\n「一名间谍和一名守卫，抛弃组织与国家，从相杀到相爱的过程。当然，主演全是猫。」\n「哈...听上去似乎...挺有意思的呢。」\n「何不聊聊我的新作呢？想必你们也是为此来采访我的吧。」\n「不，我们这是街头采访。」",
		level_6 = 0,
		record = "每个人都会死,但不是每个人都真正活过。"
	},
	[216120] = {
		soulid = 216120,
		valuation = "风魔 胧的单兵作战能力非常强，擅长潜入，能够胜任远途的机密任务——在地形不复杂的情况下。",
		file_1 = "天赋异禀的胧对父亲教授的知识吸收的很快，不知不觉间已经具备了成为一个正式忍者的资格，胧的表现也一直没让父亲失望过。 “是时候考验一下胧的所学所得了。”父亲给胧夜安排了一场成为正式忍者的试炼——————让胧夜远离家门，只身前往自己同为忍者一族的前辈家中，挑战实力在自己之上的前辈。 在短暂的告别女儿后，父亲安然地等待着前辈那里的消息，“亲爱的你难道就一点都不担心自己的女儿吗？这可是她第一次出远门啊！”一旁的母亲非常担心自己的女儿。 “会有什么问题？不管能不能战胜自己的前辈，这对她来说都是一次成长，而胧是一定不会让自己失望的。”父亲对自己的教育充满了信心。 母亲白了父亲一眼，似乎早就知道会得到这样的回答，终究是放心不下胧，还是按照为人父母的规范，事先将忍者家族的名号和联系方式写了下来包好交给了胧夜。 常理说应该是不会出现什么问题，直到高傲的父亲接到了自己女儿从某个商场里打来的求助电话———————胧迷路了…… 在父亲眼中近乎完美的胧，在方向感这方面却意外的很差，很快就迷失在了这个独立于家门以外的世界，而糟糕的是自己居然连回去的路都不记得了。 加上由于城市化的发展，多年未出过家门的胧更加不认识这条已经被现代化科技改造的面目全非的大街，在这条大街上转了不知道多少圈后，还是没有找到回去的路，东张西望的样子甚至被路过的警官当成了可疑人员。 警官拦下了胧进行盘问，了解情况后，问她父母有没有在临走的时候交给她什么东西，胧便拿出了一个写有应急两字的锦囊。之后就是警官带着胧去商场打电话的故事了…… 无论忍术方面有多么高的造诣，胧还是个彻头彻尾的路痴，这一点连看着女儿长大的父亲也没注意到。",
		level_3 = 0,
		level_4 = 0,
		resume = "风魔 胧的家庭源自一个没落的忍者世家。为世人遗忘的忍者一族，虽早已退出历史舞台却仍然想在这充满战争和动乱的世界找回一席之地。 胧的父亲就是深受这种宿愿影响，认真而严肃地要求胧也成为和自己祖先那样优秀的忍者，将来扬名立万，为家族做贡献。 于是，在父亲严苛的教育和训练下，胧慢慢成长为一个见习忍者，一切似乎都在朝着令人满意的方向发展，胧夜父亲对自己的女儿充满了期待。 被寄予厚望的胧最终被迫切断了和同龄伙伴们之间的来往，终日沉浸在无休无止的封闭式训练和忍者意识培养中，渐渐养成了独来独往的性格。 “她会成为一个出色的忍者的！”除此之外，都不是父亲会关心的事物。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "打完电话后，警官嘱咐好胧夜待在原地不要走动后便离开了。过了一会儿，胧夜等待了父母许久，有些无聊，便张望起了四周。 衣食无忧、一切都在父亲管控之中的胧夜自然不会知道商场这种东西是做什么用的，只看到进去时两手空空的人们出来时却带着各种道具满载而归，看着人们幸福的表情，胧夜很好奇这个地方究竟有什么魔力。 于是，身为忍者的胧夜没能忍住对新鲜事物的好奇，跨入了通往“异世界”（商场）的大门，在琳琅满目的货架间和如迷宫般魔幻的走廊里，觉醒了某个不得了的属性。 等到父母赶来，公用电话前早已没了胧夜的身影，最后在工作人员的指引下，她们在商场的角落里找到了正抱着一堆刚从货架上拿下来的，精心包装好的商品不肯放手的胧。",
		file_3 = "胧的父亲也试过了很多方法，比如带着女儿四处走走，熟悉熟悉街道和环境；买了手机，安装了最新的定位导航系统；拜访了最权威的医生…… 但依然没有效果，熟悉完街道后，过几天胧再走一遍，又忘了个精光；使用导航系统虽能一时派上用场，但毕竟不是长久之计，危急关头总不能停下来慢慢盯着手机引路吧；就连医生也是摇摇头，说是此病无药可医…… 独自战斗的确没什么影响，但撤退、追击、寻敌等等都是问题……看到胧这个状态，父亲无奈的明白，这样的胧或许是个优秀的忍者，但可惜的是依然不能独立作战，还是需要团队的支援。 然而家族这边都是独来独往的作风，一旦行动起来根本无暇顾及胧。随着胧的成长，父亲能教的已经不多了，自己对胧的教育似乎陷入了瓶颈，可是又找不到合适的前辈接替自己教育。 可是该上那里去找一个实力过硬，对女儿的成长有益的团体呢？胧的父亲烦恼着，直到看到了魂器学院的招生广告……",
		level_7 = 0,
		level_2 = 0,
		file_4 = "入学后的胧虽有和同学们打好关系的意向，但不愿刻意表现自己的性格且不知如何表达感情的胧夜一直是班上比较文静的学生，相对于班上那些经常闹得击飞狗跳的同学，胧夜的存在感一度低的可怜。 加上独来独往的习惯使她经常缺席一些团体活动，以及忍者特有的气质，胧成为了一个幽灵学员的存在。",
		level_6 = 0,
		record = "嘘，暗夜的使者降临了。"
	},
	[215220] = {
		soulid = 215220,
		valuation = "露可以操控目所能及的水流，并做到诸如祈雨、呼唤海浪等大规模的战术动作，这在海战中总是能为她的舰队带来巨大的优势。然而，露的船员们都很害怕她，毕竟在遮天的巨浪面前，谁都会担心其将自己脚下的船也被一并吞没。事实上，船员们的担心不无道理。随着露的身体机能逐年下降，她也愈发难以把控施法的力度。如今，如果不依靠专业的测算设备，露的一次失手就可能会将身边的一切卷入海底。",
		file_1 = "露在海军中的声望极高，这源于她过往的战功和对下属温柔的态度。在八名大将中，如果新兵们被问到最想要去哪个人的麾下，那么露的排名绝对会在前列。比起过于让人捉摸不透的弗兰西丝卡，露的性格沉稳，做事井井有条；比起对纪律严格到有些恪守陈规的艾琳，露对士兵们的态度要温和许多。佩莎莉娅在人气上虽然和露不相上下，但潜艇部队的生活环境实在是让人不敢恭维。至于奥莉维亚以及另外几位男大将，只能说担任他们的部下，会非常符合人们对于士兵生活的刻板印象。",
		level_3 = 0,
		level_4 = 0,
		resume = "露·斯巴达克出生于耶梦加得一个渔民家庭，在一场灾难中，整个村庄毁于海啸，只有露被救出。重伤的露接受了军方的实验，在头上安装上了特殊的器官。凭借实验带给她的能力，露在海军中战功累累，很快被提拔为了大将。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "加入学院后，露的人气也和在海军时不相上下。毕竟，谁会讨厌一个和蔼可亲，又擅长照顾人的大姐姐呢？不过学院内毕竟有各种各样的势力存在，某些与耶梦加得海军不对付的人自然是很难与露打好关系，不过露并不会因此失落。据她所说，自己本就明白不可能和所有人和睦相处，但既然是在和平主义的学院里，表面上的功夫自然还是要做好的，想必对方也是因为明白这个的道理，才没有在学院里做出对露出手的举动吧。",
		file_3 = "露的身体检查即使来到学院也还继续着，时不时地，她就需要返回处在耶梦加得的科学实验室，在那里记录下自己身体上的各种变化。虽然具体的细节她几乎不会透露给我们，但只要和她相处的时间够长，就会清楚地明白传闻中不断失去知觉的疾病是真的，不仅是内脏活动这些难以察觉的地方，就连视力、听力这些明显的地方，我们也察觉出了露的衰退。我们很想帮助露进行治疗，但露的体内充满了耶梦加得的官方机密，所以十分无奈，我们只好打消这个念头，转而在日常生活中尽可能地照顾她。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "「实验结束，辛苦了。」\n随着培养室的舱门打开，露缓缓坐起了身。\n「视力的弱化率被控制在了0.5%以内，接下来一段时间应该都不会有问题。新陈代谢方面......」\n各种数据掠过露的耳边，但她没往心里去。和那些纸面化的信息相比，还是自己的感觉更能反应身体的状况。\n「我的味觉......」\n「啊...那个......」\n年轻的研究员有些窘迫，看来露之前向她提的事情还看不到希望。\n「对不起......明明您是我们的英雄，我却连这点事都做不到......」\n研究员口中的英雄很快换上了与之相称的服装，她并没有感到惋惜。已经失去的感官是无法恢复的，这一点她早就在无数次的尝试中验证过了。\n看到眼前的年轻人依旧沮丧地低着头，露伸出手，轻轻摸了摸她的头。\n「不用在意。」\n军方用了十余年给自己安装的设备，这名略显青涩的研究员仅仅半年时间就把结构厘清楚了，她的才能毋庸置疑。眼下露的身体一日不如一日，或早或晚，耶梦加得都会失去自己最坚实的盾牌。但如果这个国家的未来能有一群才华横溢的年轻人做支撑，或许露也就能......\n「大将...？」\n回过神来，露发现自己一直摸着少女的头。她将手收回，拿起了自己最后的一件配饰——象征着海军大将身份的肩章。\n「下一次检查再见吧。」\n大门开启，走廊斜射的灯光拖长了大将的影子，像一条蛟龙，又像一根拐杖。明暗恍惚间，露看到了昔日战友们的身影，他们似乎在彼岸招手，但说的话却让人一个字都听不清。\n一定是我已经听不见了吧。\n露微笑着，穿过了自己的幻觉，从容走向下一片战场。",
		level_6 = 0,
		record = "有传闻说，露头上的角是可拆卸的。"
	},
	[215320] = {
		soulid = 215320,
		valuation = "艾琳的战斗水平在大将之中并不突出，她的实力更多体现在智慧与谋略上。艾琳对战场形势的判断总能快人一步，敌人所有自认为隐秘的手段，其实早就相当于摆在了阳光下。同时，艾琳会对己方情报做好相当严密的保护工作，只要有她在队伍中，就完全不需要担心遭受埋伏或暗算。",
		file_1 = "经艾琳对我们的口述，她出身于耶梦加得的富商家庭，自幼便在家族的熏陶下成长，对商业运作有着远超同龄人的理解与洞察力。然而，地劫战争的爆发不仅摧毁了她的家族产业，更让她的父母从昔日商业巨擘变成了无家可归的普通人。物质上的损失是可以弥补的，对于这个家庭来说，最大的困境实际上是信心的缺失。面对这样的形势，艾琳没有沉沦，而是凭借自己的智慧与勇气，从零开始，重建了一个小型的行商团队，试图重振家族的荣光。",
		level_3 = 0,
		level_4 = 0,
		resume = "艾琳·菲洛斯卡，现任耶梦加得海军大将之一。她的出身、经历都受到了严格的信息管控，外界几乎无法掌握艾琳的任何信息，只知道在耶梦加得海军中，有一位无所不知的大将存在。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在商业领域的初步尝试，虽然让艾琳积累了一定的经验与财富，但也让她深刻认识到了人心的复杂。她本以为自己亲手找来的团队成员全都忠实又可靠，但实际上，仅仅因为一些蝇头小利，他们就能果断地背叛自己的老大。艾琳意识到，真正的成功不仅仅依赖于个人的能力，更需要一个忠诚可靠的团队。带着这份领悟，艾琳做出了成为她人生转折点的决定——报考海军学校。凭借着过人的智慧与不懈的努力，艾琳以满分的成绩脱颖而出，正式步入了海军士官体系。",
		file_3 = "艾琳深知，作为一名大将，不仅要具备高超的战术水平，更重要的是能够赢得手下的信任与尊重。因此，尽管她对下属的要求近乎苛刻，但同时也会给予充分的信任和支持，鼓励他们在各自的岗位上发挥出最大的潜力。艾琳的这种领导方式，使得第三舰队内部形成了良好的竞争氛围，每个成员都愿意为了共同的目标而全力以赴。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "「海军档案库-联络情报」\n总帅：\n这些事情本应该在军事会议中向您提出，但鉴于目前海军内部令我不安的氛围，请原谅我将手头的信息通过书信形式向您传达。在过去的几次战役中，北部战线得到了四十海里的推进，这确实是足以鼓舞人心的战果。但作为前线人员，我必须指出那些在战斗中隐约发觉的异常。我们的敌人——那些可恨的AI，它们在近几场战斗中远不像过去那样智能化，甚至可以说是愚蠢。将这种感觉归因于海军实力的增强自然是符合常理的想法，但客观事实让我难以得出这样积极的结论。不仅是本人麾下的第三舰队，海军中大半舰队的情况我都有所了解，结合目前掌握的信息，可能性有以下两种——\n一、敌方的实力变弱了。\n某种意义上这当然是好消息，但考虑到敌人的性质，我们恐怕不得不考虑这种不知缘由的“弱化”是否意味着战场上的不稳定因素。\n二、我们受到了敌人的诱导。\n我知道这是一个令人为难的可能性。如果能查明原因，那我们在整顿之余还能着手于额外的战略安排。但目前没有任何与之相关的情报，贸然停止进攻很难称得上是明智之举。\n现在，战局仍是由我们主导，几处前线也处于相对缓和的状况。这正是个恰当的时机，我提议，除了驻守在本部的奥莉维亚和巴比伦外，联系在外的大将，安排时间进行一次最高级别的正式作战会议。\n如果没有记错，这个本应是每年例行的安排，已经因紧张的战事而有了三回的轮空。即使不考虑会议的内容，其举办本身也宣示着海军正逐渐摆脱地劫战争的阴影。对于前线的士兵和后方的民众来说，他们需要的，或许正是由我们给予的信心。\n最后，再次为我突然的来信致歉。您无需回复这则信件，近日第三舰队将返回本部休整，对于上述事宜，我会重新通过最高委员会进行申请。这套流程虽然缺乏效率，却已经是我能想到最合适的做法了。因为我比任何人都清楚，现在高层之间缺少的，不是枪弹与火炮，而是面对面的交流。\n艾琳·菲洛斯卡",
		level_6 = 0,
		record = "念念不忘，必有回响。"
	},
	[215420] = {
		soulid = 215420,
		valuation = "丽贝卡拥有身体液化的能力，并且她能在一定程度上控制液化的程度。当需要穿过细微的窗缝、门缝，丽贝卡就会完全化成水。但如果只是想要防弹、防刃之类的简单功能，她也可以化成史莱姆状的粘稠液体。根据液化程度的大小，丽贝卡需要的恢复时间也越长。另外，在液化状态下掉入水中是非常危险的。如果构成身体的水被冲散，丽贝卡就会面临无法复原的风险。",
		file_1 = "由于父母失踪得早，丽贝卡几乎没有对他们的印象。好在，海贼团的大家都把丽贝卡当家人对待，丽贝卡没有因为父母的不在而感到孤单。只是，自从丽贝卡记事起，伊莎贝拉海贼团就航行在海岸边，故事书里的冒险一次都没有发生在她的身边，这让丽贝卡时常感到疑惑。\n该不会，我们其实是打着海贼团名号的渔民吧？\n丽贝卡无心的话语打击了部分老船员的自尊心，但海贼团的秘密不能轻易地告诉一个孩童。无奈之下，他们用了很长的时间向丽贝卡灌输关于大海的恐怖故事，这才让她渐渐打消了出海的念头。",
		level_3 = 0,
		level_4 = 0,
		resume = "丽贝卡·以实玛利，伊莎贝拉海贼团预备成员。其父母都是伊莎贝拉海贼团的老手，在地劫战争前曾与海军有过多次战斗。地劫战争前夕，丽贝卡的父母下落不明，二人的女儿由海贼团的成员们共同抚养长大。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【丽贝卡的午后·其一】\n我一直觉得，大海在诱惑我们。\n似有似无的稀世珍宝，无数流传至今的冒险故事，说不定都只是大海向我们投出的饵料。它们金光闪闪的外表下，一定隐藏着比大人的谎言要更黑暗，更混乱的东西。凡是想要探究大海本质的人，最后都会葬身海底......\n对了，我的名字！你就叫我丽贝卡吧。\n快看那儿，小海鸥。甲板上出现了新面孔。他们一定也是被大海诱惑，糊里糊涂就投身进来了吧。哼哼，真是可怜，我敢打赌他们撑不过三天就会哭喊着要下船，以后见到海鲜就要吓一跳！\n诶？他们怎么朝这里来了？快逃，小海鸥！我们已经是好朋友了，我可不想在餐桌上见到你！",
		file_3 = "【丽贝卡的午后·其二】\n小海鸥，是你吗？\n已经好久没见了吧？呼呼，这段时间我可是成长了不少，已经不再是以前的那个小女孩了！\n你知道吗？大海好像没有我想象的那么恐怖！我听希艾姆姐姐说了，出海是世界上最棒的事情！海上的探险非常刺激，有各种各样的敌人，也能遇到许多伙伴，在那边的每一天都是不一样的！唔...可惜大人们马上就把姐姐拉走了，有好多故事的后续我都还没听到呢。\n小海鸥，你觉不觉得，这里的生活好像什么变化也没有？虽然我们好像也算在航行吧，可是陆地一直就在不远处。这个样子，根本一点也不自由！\n如果有机会的话，我也要出海！我要像姐姐那样潇洒地面对各种各样的冒险，然后把我的故事再传递给别人。没错，这才是我要的生活！",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【丽贝卡的午后·其三】\n啊...是小海鸥啊。\n你知道吗？我已经出过海了哦。哈哈，虽然我是偷偷溜上船的，最后还被人家送回来了。姐姐说的没错，大海确实不可怕。只要我坐的船足够大，海面上的那点风浪就根本不足挂齿。\n是啊，可怕的从来不是大海，我完全理解错她的意思了\n不...或许是我只听了我想听的东西吧。大海上存在着各种各样的人，他们的想法互相交织，构成了比大海本身还要深邃的东西。我越是往里窥探，就越是恐惧，好像再往前一步就回不来了。\n别担心呀，我这不是回来了嘛。我也按照约定，回来和你讲我的故事了哦。没办法，谁让你是我的好朋友呢，哈哈...\n......\n所以，你不是我认识的那只小海鸥吧。\n不知道为什么，最近我开始分辨的出来了，明明之前都做不到的...对了，你应该还不知道我的名字吧，我叫丽贝卡。\n呐，海鸥先生，你以前有见过我吗？\n如果有的话，你觉得我有哪里变了吗？",
		level_6 = 0,
		record = "女孩子都是水做的！"
	},
	[216220] = {
		soulid = 216220,
		valuation = "出色的战术意识与出色的战术执行能力，织夜小姐对于场景的掌控力堪称绝佳，非常适合进行特种作战。",
		file_1 = "或许是因为职务的关系，织夜的行事风格是在这座学院中少见的严谨类型，而作为精英，少女的言辞中充满了自信。\n乍看之下是有些难以相处的类型，不过多作接触就能发现是个细心随和的人。\n织夜的审美风格与严谨的性格继承于父亲，但是习性与言辞却更接近于来自洛加尔的母亲，因此偶尔会使用一些晦涩难懂的古语。",
		level_3 = 0,
		level_4 = 0,
		resume = "织夜，受院方邀请而来的“战术家”。\n她的主要工作是为学院的战斗提供战术支援，偶尔也会参与对人工智能的敌后破坏工作。\n个性认真严谨，能够正确、精准地执行学院发布的指令。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "虽然很少见，但织夜也会携带一些淡蓝色晶格“维系者”。\n那是原本是一种纳米建筑材料，通常是用于模块固定与边界隔离。在战斗中，“维系者”能够依照织夜的想法构筑出落脚点与壁障，为织夜提供各种各样的战术便利。\n不过在日常生活中，织夜也会用“维系者”构筑便利的生活道具，诸如阳伞、发卡、扇子之类的物品，可谓是物尽其用。",
		file_3 = "【夜袭魅影】：学院最新为织夜开发的战斗套装，为夜间特种行动专用。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在被派遣到学院后，织夜就一直过着深居简出的生活，平日中很少与其他学员接触，在大部分学员眼中，织夜是如同高岭之花一般冷漠遥远的存在。\n不过那只是表象，织夜喜欢甜点、喜欢华丽的衣装、喜欢猫。\n而她的性格也和猫一样，优雅而变幻无常。\n不过，虽然并非难以相处的存在，但接近织夜的人依旧寥寥无几，或许是那种凝视着远方，一心一意投入到理想中的气质令人敬而远之吧。",
		level_6 = 0,
		record = "人生的战术，就是将自己的每一秒都用在有意义的地方哦。"
	},
	[216320] = {
		soulid = 216320,
		valuation = "对于应天，我们没有什么好评价的。想要知道她的能力，只需要看看如今的派森京城即可，距离X-MAS爆发这么多年过去了，派森大部已撤退至西南山岭一代，而京城却成为了距离“国土”1000多公里外的“飞地”，且随着AI的进攻，愈发固若金汤，这何尝不是应天能力的最好体现。",
		file_1 = "应天在16岁时就在派森科举考试中中举，考入京城国子监武学堂，18岁时以优异成绩提前毕业，并直接被调入派森陆军都督府任总兵幕僚。X-MAS爆发时，AI刺杀了许多派森的高级将领，为了填补空缺，应天很快被提至陆军参将。",
		level_3 = 0,
		level_4 = 0,
		resume = "应天——出生于派森京城\nX-MAS爆发前任派森陆军都督府总兵幕僚，后提至陆军参将。AI进攻京城时，由于前军溃败速度过快，导致城内将领几乎全部出逃，遂紧急临时担任京卫指挥使司指挥使，统领京城防务。这一举措却使得其在京城守卫战中大放光彩，重创AI军队，后升至正三品兼任兵部左侍郎。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "实际上，京城守卫战，并非应天的第一次实战也不是第一次与AI交战，X-MAS刚刚爆发的时候，还是总兵幕僚的应天，就曾负责在京城内指挥神机营特战部和锦衣卫肃清城内部分区域的AI。",
		file_3 = "应天出生于京城的一个传统的军队世家，但其父母都是老来得子，应天出生时已年过半百，并且在X-MAS爆发前就已经过世。我们对其知之甚少，但从一些京城国子监的校友中得知，应天的父亲可能是前神机营总兵官，其母亲则是前三千营总兵官。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "京卫指挥使司和锦衣卫的关系似乎非常微妙，一方面，锦衣卫不隶属于任何机构，而是直接对派森万和殿负责。但自京城守卫战爆发后，万和殿的高层几乎被AI全部暗杀，而迫于城防兵力短缺，锦衣卫不得不听从京卫指挥使司的指挥，实际上不属于六部之一的锦衣卫，现在似乎却成为了兵部的一部分，这让其他五部尤为不满。",
		level_6 = 0,
		record = "我大派森，天下无敌啊！"
	},
	[216420] = {
		soulid = 216420,
		valuation = "根据京城内市民的口供，秋时似乎能够一个人杀穿城内AI的仓库，且有人见过秋时直接将一个AI手撕成两半。我们对此表示怀疑，并认为这其中肯定有添油加醋的成分。",
		file_1 = "据不可靠小道消息，秋时似乎是一个在京城下水道（京城地下城）被发现的孤儿，在一次锦衣卫的人口买卖搜查中被救出，后被锦衣卫收养，最开始锦衣卫的相关负责人想把她培养成无情的暗杀机器，但后来却在这一过程中与其产生感情，打消了那种念头。",
		level_3 = 0,
		level_4 = 0,
		resume = "秋时——没有出生讯息\nX-MAS爆发前任派森北镇抚司镇抚使，后迁至锦衣卫总指挥使。秋时是锦衣卫历史上最年轻的镇抚使和指挥使，但对于其出生我们知之甚少，甚至她什么时候当上北镇抚司镇抚使的，我们都不知道，似乎锦衣卫内部的消息保密措施做的太好了。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "秋时第一次进入大众视野，则是在X-MAS爆发后，率北镇抚司的锦衣卫，与神机营特战部配合，肃清城内的AI并保护政府要员。似乎手撕AI的传闻，就是在这时产生的。",
		file_3 = "京城地下城：一个庞大的由京城下水道组成的地下城网络，内部充斥着黑市、黑道、非法角斗、人口买卖等不法勾当。由于派森京城有着上千年的历史，其地下网络之繁杂，已非常人能够熟悉，锦衣卫所了解的区域也不过占这庞大地下城的30%左右罢了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "秋时对于锦衣卫现在实际上由京卫指挥使司指挥并不在乎，她在乎的，只有派森以及这座拯救她的城市和锦衣卫的兴亡。",
		level_6 = 0,
		record = "猫耳锦衣卫？"
	},
	[216520] = {
		soulid = 216520,
		valuation = "据说，如果你作为外宾来到派森，负责接待你的不是千叶，那这便是你此行最大的悲剧，四舍五入等于你没有来过派森。千叶在接待外宾时，总能整出一些花活，让外宾无比惊喜和意外，从而促成交易和谈判。",
		file_1 = "千叶第一次参与接待外宾是X-MAS爆发前派森与鲁比克财团的一次会晤，其欢脱和放荡不羁的性格以及异常有意思但由不失派森传统风格的外宾宴会，很快得到了当时鲁比克财团大小姐爱丽丝的喜爱，并挥手签下了巨额军火订单，并附赠索菲亚一年的科学技术指导。也因此为礼部打开了一条新的思路。",
		level_3 = 0,
		level_4 = 0,
		resume = "千叶——出生于派森\n是千竹的堂姐，但由于X-MAS爆发的原因，千竹很早就去了魂器学院，并没有见过几次这位古怪的堂姐。不过千叶似乎对这位在魂器学院的妹妹格外在意，自从知道了千竹在魂器学院，学工处的电话已经要被派森礼部的外交专用电话打烂了。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在京城守卫战时，千叶召开了不少的祈祷、祭祀、募捐以及征兵和号召活动，极好的重振了京城内低迷的士气以及让逐渐绝望拖家带口准备逃亡的市民重燃希望。",
		file_3 = "和千竹普通人家庭不同，千竹父亲的弟弟也就是千竹的叔叔，很早就娶了派森的礼部尚书，抱上了富婆的大腿。而千叶也是在礼部大院中长大的富家子弟，不过她的性格却格外特殊，而其父母也没有过多抑制，居然还让她负责起了接待外宾的事宜。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "整个派森内阁，都极为反对让千叶担任礼部尚书，遂其母亲直到现在都未能退休。部分官员认为，兵部左侍郎-应天是比千叶更好的担任下一任礼部尚书的人选，但碍于AI战争和京城守卫战，这一提议并没有进入商讨环节。",
		level_6 = 0,
		record = "千竹什么时候有的虚空堂姐。"
	},
	[216620] = {
		soulid = 216620,
		valuation = "由于童年时期的经历，安妮的内心仿佛筑起了一座坚固的城堡，城门紧闭，似乎无人能够真正走进她的内心世界。然而，正是这份内心的防御力量，成为了她独特能力【幻梦壁垒】的核心。【幻梦壁垒】不仅能够保护她免受外界的伤害，还能延伸至她周围的人，成为一道无形的守护屏障，抵御一切威胁。这座内心的城堡，既是她的庇护所，也是她力量的源泉。",
		file_1 = "安妮·敦刻出生于尼德霍格的贵族家庭，作为敦刻伯爵的独生女，她本应拥有无忧无虑的童年。然而，贵族间的明争暗斗和孩子们之间的欺凌，让她的童年充满了痛苦。由于敦刻家族在政治上的中立立场，其他贵族的孩子将安妮视为“异类”，常常以捉弄她为乐。",
		level_3 = 0,
		level_4 = 0,
		resume = "在其10岁时，与其父亲敦刻伯爵，才加了位于尼德霍格中央宫殿的盛大贵族宴会，结果在宴会的准备阶段，就被其他贵族孩子锁在了厕所里。在这件事发生后，安妮一直躲在尼德霍格北部的城堡里几乎不再外出。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "安妮的父母——敦刻伯爵夫妇，对女儿的遭遇深感愧疚和自责。他们曾试图通过举办小型聚会或邀请其他贵族孩子来城堡做客，帮助安妮走出阴影，但每次尝试都以失败告终。安妮的沉默和抗拒让他们意识到，她的心结远非简单的社交活动能够解开。",
		file_3 = "在魂器学院，安妮的能力逐渐觉醒。她的内心城堡从一种心理防御机制，转化为一种具象化的力量——【幻梦壁垒】。这种能力以她的精神力为基础，能够在她周围形成一道无形的屏障，抵御物理和精神的攻击。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在魂器学院的生活，让安妮逐渐打开了心扉。她结识了几位真诚的朋友，他们的陪伴和理解让她开始尝试走出内心的城堡。尽管她依然沉默寡言，但她的眼神中多了一丝坚定和希望。",
		level_6 = 0,
		record = "自闭少女"
	},
	[216920] = {
		soulid = 216920,
		valuation = "单论破坏力还是相当可观的，可是伦茨完全不明白瞄准目标的意义，总是闭上眼睛就一头撞上去了……如果将目标替换成移动的敌人，例如：121自律型卫兵的话，成绩可能要比现在还要差吧。 ",
		file_1 = "发现了伦茨携带的小型机器人为未确认型号，本来打算好好研究一番的，考虑到其对伦茨的重要性，不得不暂时放弃这个想法。但在一次偶然的机会，我们发现了索菲亚所持有的某个小型机器人·编号11的外形与伦茨的机器人大致相似，所以特别邀请了索菲亚进行确认。 确认的结果为：该机器人确实是索菲亚早期研发的私人型号·编号库洛01，主要应用在心理疾病方面，由于索菲亚本人的私心，库洛01内部也配置了不少武装设备，其中包括：生火设备、脉冲以及自爆程序。 让这样一个危险的机器陪伴在一个患有自闭症的孩子身边……到底是要怎么样啊…… 目前对索菲亚的风评将会在近期进行调整。",
		level_3 = 0,
		level_4 = 0,
		resume = "伦茨·黑尔姆特，嗯……说实话，我们很难猜测她在想什么，一天到晚都站在随机的地点一动不动，最高时长记录居然有四个小时三十六分钟……她头顶的那个玩意在太阳底下很快就会变热，要是那样一直站在太阳底下，很快就会中暑，为了防止那样的情况发生，我们打开了所有的户外加湿器…… 我不清楚应该在她的履历里要写些什么，如果说有什么和她类似的东西的话，大概就是那种设定好时间的机器人吧，天哪……我可不是为了做保姆才来到这种地方的，如果情况在未来一个月还没有任何改变的话，我就要辞职了……",
		level_1 = 0,
		level_5 = 0,
		file_2 = "对伦茨的心理评测的结果为：中等程度的抑郁症，神经敏感，容易被小事刺激。 明明只有九岁，却有着这么严重的心理疾病，一定是遇到了十分难过的事情吧。为了让伦茨的状态往更好的方向发展，我们准备了许多心理辅导课程，可是她似乎并不感兴趣，只愿意和库洛01进行沟通和交流。虽然这个机器人在一定程度上缓解了她的心理疾病，但如果继续这样保持下去，可能会发展成其他的沟通障碍。 好在班长入学之后，伦茨的现状开始有所改变，虽然大致还是和以往差不多，但已经开始愿意和身边的人进行简单的交流了，不过……在伦茨见到班长的时候，总是会兴奋得一头撞上去…… 在回忆起伦茨实战的画面，我们开始为班长的生命安全表示担忧。",
		file_3 = "伦茨的父母消逝于黑色圣诞节，人工智能叛变爆发的第一夜，据说当时救援队找到伦茨的时候，她父母的遗体就在十米范围内，这是大概就是她心理疾病的根本原因，在那之后，为了让伦茨得到更好的康复环境，救援队将其安置到了尼格霍德五区的一家病院，身体虽然逐渐康复，但精神却并非如此，伦茨依然被过去束缚着……当时刚刚脱离鲁比克财团，回到奥杜因的索菲亚听说了这件事后将自己制作的小型机器人·编号库洛01送给了她…… 以上就是这个孩子的过往，而随着和班长的交流愈发频繁，我们逐渐开始了解这个小女孩，害怕陌生的人和环境、害怕别人大声说话、害怕打雷……几乎是什么都害怕的状态，和他人交流需要靠得特别近，不然很难听到她的声音；另外她似乎喜欢捉迷藏，并且总是将自己扮成机器人，然后融入到环境里，虽然从我们的视角来看，那种行为只是单纯地站在那里…… 另外对于亲密的人，就会一股劲地冲到对方的怀里，是的……一股劲。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "记录上显示，黑色圣诞节当晚，虽然耶梦加得大部分地区陷入了战争状态，但伦茨所在的区域却是安全的。救援队也表示，当时周围确实出现了部分伤亡，但只有伦茨家呈现出了遭受到恶意爆破后的样子……具体的情况我们还需要更多的资料，不过根据伦茨父母的部分记录，基本上可以推断，这绝对不是什么意外事件。",
		level_6 = 0,
		record = "“大家的吉祥物，看上去软绵绵的好可爱。”"
	},
