	[217020] = {
		soulid = 217020,
		valuation = "缇法对于各类枪械的运用程度极度娴熟，也再次让人惊叹于她的武器改造能力。 随机应变的能力也极其出色，临场制作武器和小型爆破物的速度很快，就是对各种网络系统尚在摸索阶段。",
		file_1 = "【绝斥双星】是由缇法亲自设计开发的魂武，外观上来说和通贩的近未来枪械没什么不一致，相较于异型的武器，缇法还是更加中意顺手程度。 不过内部构造足够复杂，缇法从一开始就是冲着制作究极魂武进行的设计，理论上来说拥有现阶段最高的能量准换效率，以及隐藏其中的微缩斥力场的应用。 是连布克丝博士都赞不绝口的设计，也有传闻说这两人经常可以就魂武的开发问题畅聊到深夜。 然而虽然作为现役的魂武，缇法似乎对其仍有不满意的地方，经常抱着【绝斥双星】往返于宿舍与实验室，一副行色匆匆的样子。 世上不存在究极完美的武器，这件事情其实缇法比任何人都要明白，但仍然在追随这个目标并为之努力。 用她本人的话来说：已经没有任何事能让她停下脚步了。",
		level_3 = 0,
		level_4 = 0,
		resume = "很难想象这是个18岁的女孩子，我是指身高，以及讲话的口吻，极度不会说话。甚至很难让人体会到这个年纪女孩子应该有的温柔，或许这是我个人的偏见，但是缇法的个人经历确实影响着她的性格，辗转各处汲取武器尖端知识的期间，通过贩售奇怪的各式小装置赚取生活费用柔弱女生温柔的态度，大抵是在这个世界里是生存下去最不需要的东西。缇法对于武器的理解非常深刻，可以说拥有这方面的绝对领域。 成为适格者，进入学院的第一件事，就是向院长申请独立开发自己的魂器，并要求资源上的帮助。 战斗或许已经是家常便饭的事情，但缇法永远只有一个努力的目标，就是制作究极完美的武器，单纯就难度上来说与突破物理法则的难度无异。 另外，缇法对于网络的理解，说实话糟糕的不行，后续要好好让她进行学习。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "关于缇法出生的组织，已经查明是驻扎地在巴哈姆特的小团体，并非多有影响力的组织，甚至在最初的一段时间组织成员的生存都成为问题。 后来缇法制作的改造品在黑市上逐渐变得受到欢迎，组织在这段时间才发展起来并拥有稳定的生活来源，对于天才少女缇法带来的收益，组织的人由一开始的感恩，到渐渐富裕后变得贪得无厌，或许就是穷怕了，但这依然让缇法感到人性的可悲与黑暗。 于是一方面为了追求究极的武器制作，一方面也是为了逃离组织，缇法开始了独自一人的旅程，并在过程中逐渐变得不会说话起来，大概也是本人保护自己的一种方式。 据说曾有被组织追捕的过程，推测身体停止发育也和逃亡过程中没有足够营养摄入有关.....大概..... （#修正不严谨的档案内容，缇法本人的停止发育与放射性物质的接触有关，抑制了生长激素的放出）",
		file_3 = "缇法的武器改装技术，完全是自己摸索出来的基础，加上后续各处吸收的知识和大量的实验数据积累，缇法在圣诞节事件后发现人工智能的自我进化和高速演算使得武装能力得到了提升，于是设计了一场掠夺，精准执行了自己拟定的诱导作战，一次性获得了大量的机体部件。 改造的困难比想象的要多，可惜的是提法虽然在物理拆解上非常精通，破解人工智能的晶片电子锁是绝对的苦手，也就是传统意义上的电脑白痴。 导致大部分的武器并不能正常投入使用，即使没有限制，在实战过程中还是会被X-MAX的主系统检测到并锁定，缇法随即放弃了这个想法。 有了这段经历，后续的制作缇法或多或少的开始有意识地针对人工智能进行不可逆破坏的武器开发，不知道算是研究狂的报复还是......",
		level_7 = 0,
		level_2 = 0,
		file_4 = "对于网络，缇法的掌握程度是毁天灭地性质的差，可以说完全没有基础，甚至和“遗弃者”的网络使用水平相差无几。 可以理解在巴哈姆特的贫民窟没法接触网络，但缇法在脱离组织之后也并没有对网络的操作上心，慢慢成长为彻头彻尾的电脑“白痴”。 发现自己无法破解电子锁的窘迫境地后，缇法在军方的实验室稍微进行了一番研究，但是脱离网络的时间实在是太长了，缇法发现自己很难适应之后暂时搁置了学习计划，来到魂器学院后，得知使用魂智能网络是自由开发武器的前提后,再次开始一段困难的学习历程。",
		level_6 = 0,
		record = "安静一点，白痴，别打扰我的研究工作！"
	},
	[217320] = {
		soulid = 217320,
		valuation = "爱丽丝的单兵作战能力极其薄弱，在面对两到三名普通士兵时就已经呈现出明显的劣势；不过在军事上，爱丽丝表现出了惊人的实力。  单靠指挥就让五名原型机体歼灭了二十架人工智能机兵，且在战斗中还在不断进化，学习能力高，值得期待。",
		file_1 = "鲁比克财团是世界知名的尖端科技开发集团，总部于尼格霍德，其势力范围包括：耶梦加得、莱希和库库尔坎，综合影响力排行第一，据说现在学院内的多项计划也有鲁比克财团的参与，目前学院已经有被渗透的可能性，故爱丽丝的部分档案转移到下一层。 爱丽丝的天才性是毋容置疑的，但这份天才却不是这个年纪应有的，她能看到比别人更多的东西，也更能受到外界的影响，不过好在交友环境的优良，让她变扭的个性在一点点被矫正，又或者……被刻意隐藏？ 优秀的成绩是她的证明，也是天才的附属品之一，目前推荐爱丽丝参与到院方某项计划的申请已提出。",
		level_3 = 0,
		level_4 = 0,
		resume = "注意：爱丽丝出身于鲁比克财团，因鲁比克财团对魂器学院的投资比例高达百分之三十，故部分资料转移至深层档案Ⅱ及以下，请权限不够的人员不要故作尝试， 否则将会面临：账号冻结、人事调动、撤销职务、短期监禁等风险。 爱丽丝是一位年龄尚小且可爱自立的小女孩，在无聊的时候喜欢玩魔方，对不可思议的事物表现出高度的好奇心。除此之外，不知是否和家庭环境有关，爱丽丝总是喜欢在言语中隐藏攻击和讽刺，在利用年龄和外表作为武器的前提下，也没有多少人会将爱丽丝的话放在心上；但是我个人认为这是个非常不好的习惯。 现阶段于战略指挥班学习，已和魂器共鸣契约。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "根据多项资料判断，爱丽丝是家族所特意培养出来的试管婴儿，基因当中的学习与智慧的钥匙被适当调整；从上次体检的结果来看，这种调整会给爱丽丝带来发育缓慢、失眠等多种影响，且这些影响可能会伴随其一生。 处于人道角度和多方因素，目前这件事并没有告之爱丽丝本人。",
		file_3 = "在早期，常常能看到爱丽丝在各种地方玩魔方，起初认为只是兴趣，但后来发现，爱丽丝的魔方上有着许多英文字母；根据人工智能的观察记录推断，爱丽丝喜欢问魔方问题，并随后用高超的魔方技巧拧出自己想要的回答，是一种极度寂寞的外在表现。 幸好随着爱丽丝朋友数量的增加，这个行为的次数在逐渐减少。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "鲁比克财团让爱丽丝入学的要求有以下三点：    1：确保爱丽丝的生命安全以及多项正常学生的权利，不可过多限制其发展和自由。 2: 必须参与二至三项学院方的核心计划当中，并承担计划中的重要角色。 3：在学院授业时间内至少要取得多项成绩，并且授业结束必须立即返回家族，不能以任何原因被滞留到学院中。 我们同意了第一条和第三条的要求，但对第二条依然有所存疑，经过多轮谈判，我们将参与到核心计划的数量减少到了一项。    让一名毕业就会脱离的学生参与核心项目原本是不可能的事情，但出于对爱丽丝的肯定，我们还是决定让她参与到部分计划当中。 ",
		level_6 = 0,
		record = "正如误入不可思议国度的那位爱丽丝一样。 这边的爱丽丝也渴望着不可思议的事情，那是她唯一还像个孩子的地方，也是对奇迹的某种期待。"
	},
	[217620] = {
		soulid = 217620,
		valuation = "妮妮珐对于作战的策略仿佛没有什么概念，她真正感兴趣的还是研究灵魂和制造人造机器战斗对她来说只是获得灵魂的一种途径而已，但通常她不会主动出手获取。",
		file_1 = "【红粉甜心】与其说是魂器，不如说是妮妮珐定制的灵魂处理的一体式仪器，当然还是具备一定程度上的作战能力的，能够配合妮妮珐的异能转化出带有恢复治疗能力的“灵魂”，在开发阶段就被称为是移动的灵魂工作站，能够做到高纯度的能量转换。 因为考虑到仪器的精密性和功能性，这件魂器很难得的基本全程由医疗部进行开发跟进，算是为数不多的并非为了战斗开发的魂器。 根据目前已知的情报来看，这台仪器除了采集，储存和释放等基础功能外，后面的箱子还可以进行灵魂的解析和灵魂的制作妮妮珐本人对这件魂器爱不释手，但是考虑到安全问题，目前妮妮珐也只有得到许可后才能开启使用。",
		level_3 = 0,
		level_4 = 0,
		resume = "出生于混乱之城巴哈姆特的妮妮珐，所属组织不明，或许也可能没有组织，这正是这个小姑娘让人感到费解之处根据学院的档案来看，年仅11岁的妮妮珐却是巴哈姆特附近大小“战场”的常客，并非直接参与的人，准确的说，妮妮珐大部分的战场行为都是在进行采魂作业或者对伤员进行“救治”。 说是救治也只是把随身携带的“灵魂”强行输入伤者体内，好在并不是什么致命的东西，大部分伤员被发现后，都由正规的医护人员救了回来。现在正在考虑有必要对妮妮珐进行正规的医学知识教学，防止她在灵魂问题上乱来，希望她都能认真学习。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "巴哈姆特这座城市异常混乱，每天都有帮派的大小斗争生产灭亡，对于一般人来说会产生剧烈不适感的场景，对妮妮珐而言不过是家常便饭，很难想象妮妮珐是怎样在如此混乱的地区生存下来的，但可以确定妮妮珐的性格也逐渐开始受到强烈的影响，一旦话题涉及到了伤员和灵魂，妮妮珐的言语举止就会变得极其“糟糕”，达到必须要有人出面制止的程度，但除了完全不符合年龄的表现出对“灵魂”的强烈兴趣外，妮妮珐在各个方面都是正常的11岁心智，偶尔也会做些小孩子的举止，让人完全搞不清楚她的行动准则。现在拟定班长作为监督人员，希望阻止并尽可能纠正妮妮珐的扭曲性格。",
		file_3 = "虽然妮妮珐本人拥有很不错的异能攻击资质，但鉴于妮妮珐对伤员表现出的积极治疗欲望，以及她危险的救治手段，院方暂时决定将妮妮珐安排在医护班系统性的学习相关的医疗知识，有必要时跟随指示行动，并不允许单独进行医疗活动，由伊文捷琳担任妮妮珐的医务知识教师。目前看来，虽然妮妮珐表现出对课程学习的不满，但是灵魂相关知识的掌握有了非常大的提升，至少已经明白了不能随意输液这件事。同时对“灵魂”的制作方法产生极大的兴趣，在本人的强烈....病态的要求下，姑且在一定范围内给予了一间实验室部分设备的使用权，但经常有学生目击妮妮珐抱着什么东西进了实验室之后，一个人空着双手出来了，正在讨论有无必要进行干涉。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "深度调查后，我们得到了一些妮妮珐幼年时期的信息，她由哥哥带着一起在某个组织的庇护下生活，在某一次的小规模的械斗中，哥哥受伤过多却没能得到足够的输液治疗，作为医护人员的哥哥最后只是希望要有足够的生命力。 妮妮珐在后来将这句话作为行动准则开始以自己的方式大量甚至偏执地收集灵魂，身边若是没有足够的灵魂就会陷入慌乱的境地一旦身边的人出现受伤的情况，妮妮珐会不顾一切的为其输送“灵魂”，虽然输的液体大部分情况下只是类似抗生素的东西。 大概，是不想在失去身边的人了吧。但还是必须严肃地指出，危险的救助行为是禁止的！",
		level_6 = 0,
		record = "啊~你消亡了呢~鲜红的灵魂流淌而出~多么绚丽，但是不行！请接受我的治疗！我会很温柔的~"
	},
