	[216720] = {
		soulid = 216720,
		valuation = "亚裘拉的主要武器是乱破影刃，能够生成幻影苦无进行投掷攻击。这种武器不仅具备极高的隐蔽性，还能在战斗中制造混乱，迷惑敌人。作为乱破师，亚裘拉擅长潜入敌后，破坏通讯设施、暗杀政要、制造混乱。本人性格寡言且莽撞，但在执行任务时表现出极强的冷静和专注。",
		file_1 = "亚裘拉出生在战乱不断的奥杜因边境地带，亲眼目睹了无数战斗的惨烈景象。她从小便接触到兵器和战术，对战争的残酷有着深刻的认知。早在14岁时，亚裘拉便被奥杜因的军队选中，接受了乱破师的训练，成为一名专门负责“肮脏工作”的战士。她的战术更多是依赖潜行、暗杀、和破坏，而非传统的正面战斗，这也让她在战场上如幽灵般游走，令敌人心惊胆寒。",
		level_3 = 0,
		level_4 = 0,
		resume = "在X-MAS爆发前，亚裘拉是奥杜因的乱破师，承担着一些正规军无法执行的任务，尤其是在战场上作为“杂工”的角色，负责执行暗杀、破坏、侦查等任务。她专注于破城战术，潜入敌方城市，破坏基础通讯设施、暗杀政要，并制造混乱和恐慌。在战争的阴暗面，她如幽灵般潜行在敌人之间，成为让敌人无法忽视的存在。\n然而，随着X-MAS爆发后，奥杜因部落的战争突然停滞，亚裘拉也失去了她的使命。战争的结束使得她失去了作为乱破师的职责，而这份失落与迷茫迫使她开始寻找存在的意义。她决心离开曾经的战场，踏上了寻找奥杜因战争碎片的旅途，意图在残破的世界中重新定义自己。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "X-MAS爆发后，奥杜因的部落战争戛然而止，这突如其来的平静令亚裘拉陷入了深深的迷茫之中。作为乱破师，她的任务曾经是与战争的进程息息相关的，然而战争一旦结束，她便失去了存在的意义。这个突如其来的空白让她开始反思：她到底是在为谁战斗？战斗本身，还是战争中那些被摧残的生命？她的身份，仿佛在一夜之间失去了支撑。\n在战争的废墟中，她踏上了寻找奥杜因战争碎片的旅程。她寻找的不仅仅是物理上的碎片，更多的是一种存在的意义——她希望从中找到自己的人生价值，或者说，她期望通过探寻战争的残留痕迹来重新定义自己。",
		file_3 = "亚裘拉的乱破影刃是一种高度定制的武器，其设计融合了传统的苦无与现代的高科技幻影技术。每一把乱破影刃的苦无都由特殊材料制成，能在投掷过程中形成多重幻影，从而迷惑敌人。使用者可以通过精神集中与能量调动来增强幻影效果，甚至使敌人产生错觉，从而制造出战术上的巨大优势。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "亚裘拉与他人的关系较为冷淡，她对任何形式的感情和依赖都保持着高度警惕。由于乱破师职业的特殊性，亚裘拉长期处于孤立状态，习惯了与他人保持距离。她的人际关系几乎为零，除非在特殊的任务中不得不与他人合作，否则她通常独自行动。",
		level_6 = 0,
		record = "是不是还会有个背着棺材的少女？"
	},
	[217220] = {
		soulid = 217220,
		valuation = "靛青械拳使用了与机械光棱同源的远程操控技术，其4组浮空机械拳也能够按照樱的指令进行调度，且可同时应对多个敌方单位。且可以作为远程武器发射。",
		file_1 = "从樱的口中我们得知，阿卡丽的父母就是洛加尔首都大学的校长和副校长，而樱的诞生也是由其父母一手推动的。理由似乎颇为简单？只是想再要一个女儿？",
		level_3 = 0,
		level_4 = 0,
		resume = "樱的诞生并非绝密，而是洛加尔首都大学各个教室通力合作的结果，且阿卡丽也知道自己的这个“妹妹”。由于樱在诞生时便是以阿卡丽的人格作为模板，且诞生后的初期适应阶段也与阿卡丽一直待在一起，遂在许多事情上与阿卡丽颇为相像。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "樱会自发的模仿周围的人说话的方式，就像在樱出生的大部分时间中都和阿卡丽待在一起一样，樱的说话方式和阿卡丽较为相似。但自从阿卡丽离开首都大学来到魂器学院后，樱便开始模仿其他人说话的方式。",
		file_3 = "值得一提的是，无论再怎样轻量化，樱的骨骼以及部分储能装置也需要使用金属，从而很难保持与阿卡丽体型一致的情况下体重也一样。并且阿卡丽本人也希望这个“妹妹”能在某些部位上略逊于自己，所以在其身材上做了一些取舍。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "由于是机械生命，所以樱在刚刚诞生时依然不能很好的模仿人类的社交方式，需要有人照顾使其快速的熟悉这个世界。而阿卡丽也自告奋勇的照顾起了这个“妹妹”。",
		level_6 = 0,
		record = "人工机械生命体"
	},
	[217520] = {
		soulid = 217520,
		valuation = "魔法控制能力：A-\n嘉伊薇娅在法术控制方面展现出超龄的精准度，能够快速完成复杂法阵的构筑与拆解。尽管她尚未达到导师级别的能量掌控力，但其“枪械式法术释放”大幅提升了实战应用效率。\n战术素养：B+\n拥有良好的战术判断力和应急反应能力，擅长在混乱局面中快速做出最优决策，但由于缺乏团队协同训练，独自行动时更能发挥实力。\n适应能力：A\nX-MAS事件后迅速适应了动荡环境，在失去导师的情况下依然保持自律与学习热情，展现出极高的心理韧性与恢复力。\n近战能力：C\n因专攻法术领域，体术训练相对薄弱。配备的法术机杖虽兼具物理打击力，但近战时需额外保护。",
		file_1 = "嘉伊薇娅将“寻找导师”视为人生目标，但真正支撑她前行的，是导师曾对她说过的一句话：\n“你不是在学习魔法，而是在决定魔法未来的模样。”\n她内心深处对导师的感情已超越单纯的师生关系，那是一种几乎等同于父亲的依赖。而她坚定的行动逻辑，既是信念，也是一种无声的自我救赎。",
		level_3 = 0,
		level_4 = 0,
		resume = "生于奥杜因南部小镇，自幼展现出强烈的魔法亲和力。\n13岁通过全国统一选拔，进入奥杜因大学魔法研究学院特招班。\n被知名魔法技术导师选为唯一徒弟，参与法术机杖原型开发。\n16岁时遭遇X-MAS事件袭击，在混乱中独自将法术机杖转移至安全区域，与导师失散。\n自那之后持续沿着被破坏的数据链与战后痕迹追寻导师，成为“幸存者学徒”的象征人物之一。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "她的衣着风格几乎总是以“白色”为主，这是对导师研究室的怀念——那里是白色砖墙、白色魔法阵、白色书架的空间。她执着于“白”，也象征她试图保持纯粹、避免情绪的杂质干扰她对魔法的理解。",
		file_3 = "嘉伊薇娅最喜欢的食物是“传统面包”，但其实她并不喜欢它的味道。她选择这个食物，是因为那是导师在实验间唯一会吃的东西，也是她第一次感受到“实验室之外还有生活”的日常片段。她不说这些，只是机械地一再复刻这份习惯。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "尽管总泡在图书馆，但她并非不解人情世故。她在校内小型演讲比赛上曾说过：\n“魔法并不是解决一切的答案，但如果哪天我能用它找到我的导师，那就足够了。”\n这句话成为了新生教材里的“现代魔法观”例言之一。她的坚强并非无懈可击，而是一种温柔包裹的伤痕累累。",
		level_6 = 0,
		record = "关于法术机杖原型「Eidetic Rod - Type: 03」\n嘉伊薇娅携带的法术机杖为第三代原型，搭载记忆构图模块，可储存并多次释放高复杂度法阵，部分能量轨道采用枪械式定向引爆方式，是少数在战场上能“精准点杀”的魔法装备。"
	},
	[218120] = {
		soulid = 218120,
		valuation = "佩特里夏对魂智能武器的使用有些不太稳定，有时状态绝佳，有时极不协调，她需要学会更好地掌控武器。",
		file_1 = "佩特里夏擅长打扫、插花、烘焙……这些都是跟母亲学的。此外，她的飞镖玩得很好，甚至蒙上眼睛也能准确投中靶心。为此，学院试图挖掘她的射击能力，例如使用弓箭、枪支等。但遗憾的是，除了飞镖，佩特里夏玩转不了其他武器。\n至于佩特里夏的魂智能武器——碎裂回旋，她似乎是将它当做特殊的回旋镖来使用的。",
		level_3 = 0,
		level_4 = 0,
		resume = "佩特里夏拥有超群的记忆力，与此同时，她对方向有着天生的敏锐度。即使是陌生的场所，佩特里夏也能迅速熟悉，并摸清转角、出口等关键地点，这在战场上非常有利。\n佩特里夏的耐心和毅力都很优秀，这大概是从她喜爱的拼图游戏中锻炼出来的，但她的耐心会在遇到人工智能时化为乌有——我们注意到，佩特里夏将人工智能视为“绝对错误”，她憎恶那些家伙，并一定要将其纠正。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "佩特里夏很少主动与人交流，但她对外出执行任务非常狂热，每个月的外出任务统计次数中，她总是高居前三。一旦回到校内，佩特里夏就窝在宿舍，不太乐意出门了。\n我们在例行查寝的过程中发现，她的房间摆满了各式拼图，连地毯的形状都是一块一块拼凑而成的飞镖靶子。但有一处不同寻常：整洁的墙面上挂着一张巨大的残缺拼图，分辨不清原貌，或许是她还没有完成的作品吧……",
		file_3 = "加入魂器学院后，佩特里夏新学了一门技术——机械组装。佩特里夏可以将拆卸掉的枪支、机甲等迅速组装还原，在她看来，这和拼图的过程十分相似。据相关人员反映，佩特里夏在机械组装上非常有天赋，甚至能够改装出性能更加优异的器械，目前，她对作战时使用的新型防护罩进行了改良，提升其承受物理攻击的上限，效果理想。\n有传言称，佩特里夏一直想拆卸一次小机器人阿基米德，不过总是在伦茨哭天喊地的叫声中败下阵来。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "佩特里夏出生在一个普通家庭，尽管生活不是那么富裕，但她拥有非常幸福的童年。\n父亲回家的日子是佩特里夏最期待的时光。每个月的这一天，母亲会早早打扫干净屋子，为窗前老旧的花瓶插上新鲜花束，然后烘焙好香喷喷的奶油面包，准备好甘甜的百花蜜，陪着佩特里夏一起等待傍晚来临。父亲总是踩着夕阳回到家中，他会给佩特里夏带大大小小的礼物，尤其是拼图玩具。佩特里夏没什么玩伴，但她并不感觉孤单，拼图变幻莫测，她喜欢将散乱的一切恢复成规则的感觉。\n佩特里夏遇到了挑战，那是一份有着万张单片的拼图，也是父亲送给她的生日礼物。佩特里夏花了近一个月的时间才拼凑出完整图案，她看到了海洋、森林、山脉、城市……世界的风景如画卷般展现在少女的眼前，她激动地想向父亲炫耀成果，但那个傍晚，父亲没有回来。整座城市陷入了前所未有的恐慌，人工智能肆无忌惮地残害人类，母亲的肢体浸透了那份破碎的拼图。\n世界成了碎片。\n每个人，每个人工智能，每个物体都是一块单片，如果将所有错误的单片纠正回正确的位置，一定能拼凑出那个和父母共同生活着的安宁和平的世界吧？",
		level_6 = 0,
		record = "在加入魂器学院前，佩特里夏去过的地方很少，对她而言，世界曾经是新奇而未知的。"
	},
	[217820] = {
		soulid = 217820,
		valuation = "梅耶尔本身不拥有任何特殊的能力，其身体素质与正常人无异，但在魂器学院为其特殊开发的这一套对“学员”特攻的镇暴装备的加持下，梅耶尔和她的小队在几次特殊事件中的表现都非常让人满意。",
		file_1 = "梅耶尔X-MAS之前为库库尔坎见习警察学院的学员，曾参加过X-MAS初期的一些AI骚动的镇压，后进入尼德霍格皇家警察学院进修，并在X-MAS爆发前不久以优异成绩毕业。X-MAS之后，梅耶尔曾参加了多次针对AI叛变的镇压，并在行动中有着两眼的表现。后在布克丝院长的邀请下，加入魂器学院。",
		level_3 = 0,
		level_4 = 0,
		resume = "梅耶尔率领的治安分队的第一次任务就是应对因为误解了班长的意思而暴走了的诺诺妮娅（灭火行动），同样参与了本次任务的魂器学院消防站的卡米拉，曾对这支新建立的部队，做出了高度评价。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在他们首次出动（灭火行动）前，学院里大部分的学员对这支部队，且尤其是梅耶尔本人，可以说完全没有好感。因为这支部队从建立之初其实就是为了针对学员的，大部分的学员对其抱有戒心也是情有可原的。但在灭火行动时，梅耶尔及其部队的英勇表现却让许多学员刮目相看。",
		file_3 = "梅耶尔及其部队的第二次任务也是最具挑战性的一项任务，就是前去营救被妮妮珐掳走当试验品的班长（夺宝行动），其以零伤亡将班长完好无缺的救出和在不伤害妮妮珐的情况下将其成功逮捕的亮眼表现，刷新了其在众多学员中的看法。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "除开学员内的紧急治安任务，梅耶尔的部队有时也会作为学院快速反应部队，参加其他地区针对AI/营救平民/支援学员等一系列任务，在墨格尔的“击锤行动”中，梅耶尔的部队成功完成了营救被AI包围的班长一行人，并摧毁了AI瞄准巴哈姆特市区的生化大炮。再次推翻了学院中对梅耶尔“窝里横”的流言蜚语。",
		level_6 = 0,
		record = "“为学员的生命而奋斗”-特别事件应对小组"
	},
	[217920] = {
		soulid = 217920,
		valuation = "布洛芬自身并不具备任何战斗相关的能力，其身体素质也处于普通水平。但在魂器学院所配发的“医护天使”急救装备加持下，她能在极短时间内完成复杂的急救处理操作，包括止血、骨折固定、休克处置等高难度医疗行为。尤其是在高压与混乱的战场环境中，她的临场应变与伤情判断能力屡次超越预期，甚至一度被后方医院认为“这还能算临时处理吗？”。此外，布洛芬在处理伤员时展现出的情绪控制和效率，令医护小队在多次行动中表现亮眼。",
		file_1 = "布洛芬在X-MAS事件爆发前原本就读于一所偏远地区的自然疗养学院，主修药草学与基础医疗。但因意外卷入区域性混乱而提前中断学业，被魂器学院作为紧急转校对象接纳。在入学初期，她因社交障碍常常沉默寡言，甚至几度申请退学，但在一次校内实验事故中，她独自完成了3名重伤员的初步治疗，由此被特别事件应对小组留意，成为医护分队的重点培养对象。",
		level_3 = 0,
		level_4 = 0,
		resume = "布洛芬的首次出勤任务是在「演武祭爆炸事故」中为前线伤员提供紧急支援。在那次任务中，她面对连续不断送来的伤者，不仅迅速展开处理，还一边指挥其他学员协助救治，被教职组评价为“堪比专业应急队长”。此后她陆续参与了“真理之影”事件、“幻痛市集踩踏事件”以及“墨格尔化学走私事件”中相关的医护任务，均展现出极高的医疗水准与责任感。尽管性格腼腆，她的职业素养已获得大多数应对小组成员的认可。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "布洛芬的医疗能力在学院内部本已小有名气，但由于其“事后就会立刻崩溃”的反差行为，使得不少学员误以为她是“精神状态不稳定的危险人物”。因此在医护分队初成立时，甚至有学员联名请求将她调离一线岗位。直到“X-MAS”事件中，她一人独自照顾十余名伤员整整三天三夜，期间未曾离开岗位一步，这份执着与责任心才逐渐改变了人们对她的印象。",
		file_3 = "布洛芬在“巴哈姆特市集踩踏事件”中临危受命，与治安分队梅耶尔协同作战。她不顾自身安危进入尚未封锁的商场废墟深处，仅凭随身药箱救下了7名被困伤员。行动结束后，她全身多处擦伤，嗓音嘶哑，但仍坚持完成最后一份伤者记录再行离场。这一事件让众多学员第一次明白，那个害羞、躲在人群后的女孩，是用命在守护他人。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在墨格尔地区发生的“击锤行动”中，布洛芬作为随行医护随梅耶尔小队一同出征，支援前线作战学员。面对因AI攻击而大量感染特殊神经毒素的伤员，她临时以当地草药调制解毒剂，为十余名学员稳住病情，争取到后方医疗队抵达前的宝贵时间。后经调查证实，她使用的草药确实具备缓释毒素活性，此一事件后，她也被正式认定为魂器学院“战地救护能力优先级S”的医护人才。",
		level_6 = 0,
		record = "「别怕，我一直都在」——魂器学院特别事件应对小组・医护分队"
	},
	[218020] = {
		soulid = 218020,
		valuation = "“王室魔剑”不仅是物理攻击武器，更是一件魔力生成器。在战斗中，福克斯能够通过施展特定的法术，快速形成强大的魔力剑气进行远程攻击。她的剑术与魔法的结合非常高效，能够根据战斗需要迅速调整战术。尽管如此，福克斯的魔力并非无穷无尽，她在长时间高强度的魔力消耗后会出现虚弱，因此她通常会根据战斗的节奏谨慎选择何时全力施展魔法。",
		file_1 = "“王室魔剑”是第三代“法术实体化”武器，相较于前代大幅提升了生成物的强度。它能够迅速生成多种武器形态，但需要持续消耗魔力来维持其实体的存在。而且，该武器只能生成提前预设的“实体”，无法像第二代武器那样具备完全的自由度。",
		level_3 = 0,
		level_4 = 0,
		resume = "福克斯是奥杜因大学法术教室的实习生，作为一名天赋异禀的魔法剑士，她被认为是最适合装备“法术实体化”武器的学生之一。她在学术界和实战中表现出色，展现了她在魔法与剑术结合方面的巨大潜力。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "第二代“法术实体化”武器，与第一代几乎无异，所生成的“实体”强度较低，通常不能称为真正的“武器”。然而，它的优势在于不需要持续消耗魔力，且可以生成任何使用者想要的物体，但这些生成的“实体”会在一定时间后自动消失。尽管如此，它的局限性使得它尚无法成为主流武器。",
		file_3 = "福克斯外表看似轻松古怪，但内心却承载着巨大的孤独感。她的父母一直希望她能成为家族的继承人，但她却更喜欢自由和冒险。福克斯常常感到自己被束缚在家族的期望中，虽然她不喜欢直面这些情感，但她对自由的追求几乎成了她不断前行的动力。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "福克斯最喜爱的食物是煮虾子。她第一次品尝煮虾是在“城堡”附近的一座旅者小屋，那里是她在闲逛时偶然发现的。煮虾子的简单却美味的口感让她一试成主顾，每天都会去小屋购买这种食物。然而，在X-MAS爆发后，小屋的主人便离开了奥杜因。流言称他现在在巴哈姆特附近卖煮螃蟹，而福克斯仍时常怀念那份曾经带来简单幸福的味道。",
		level_6 = 0,
		record = "伟哉奥杜因！"
	},
	[218220] = {
		soulid = 218220,
		valuation = "具备高效环境清洁与作战压制双重能力，主武器“齿轮人偶”可实现范围旋转牵制与远距压迫推进，适合非致命战斗与学生保护任务。其内置精密运算模块使得她在高压情况下依然保持判断冷静，对保护目标反应极快，尤其擅长人群防控与空间封锁。",
		file_1 = "琳并非完全依照代码执行命令的标准人形，她展现出对个体情绪变化的自主感知与“同理行为”，特别是在面对阿卡丽逃避清洁或晚归时，她会选择更温和但不妥协的方式完成监督任务。",
		level_3 = 0,
		level_4 = 0,
		resume = "制造厂商：洛加尔学术院・人形机维开发部\n\n投用身份：第七学区直属宿舍管理人（代号：LIN-09）\n\n附属职责：负责阿卡丽与樱的宿舍生活起居、课程监护、特殊任务回报\n\n备注：无攻击性记录，具备学生监护权及紧急封锁权限",
		level_1 = 0,
		level_5 = 0,
		file_2 = "据记录，琳曾在一次学生演习中在未接到指令的情况下保护“阿卡丽”免遭意外重物砸落。她的反应速度和选择路径超出标准协议，疑似出现“情感性行动反馈”。",
		file_3 = "与主武器“齿轮人偶”的同步率常年维持在99.4%，可实现非言语操控、延迟0.01秒以内的战斗行为指令。被认为是当前同型号宿管人形中最稳定的执行个体。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "阿卡丽时常“逃避琳的管理”，曾一度企图将其程序手动封存，但琳并未因此反击或申报异常，反而在暗中调整清扫路径，确保不打扰她的“反抗”情绪。对此，学院内部评论为“理性中的柔软异常”。",
		level_6 = 0,
		record = "时间，滴答滴答就消逝了。"
	},
	[218620] = {
		soulid = 218620,
		valuation = "具备高效环境清洁与作战压制双重能力，主武器“真空雷洁”可对范围内环境利用雷电进行清理，真空不仅可以吸纳灰尘，更可喷洒高压雷电对敌进行压制。对于近战敌人，玛奇也可施展天生怪力与机械改造成果使用武器对敌近战。适合高强度高密度作战，尤其擅长近距离作战。",
		file_1 = "玛奇接受的改造程度表面上看不出深浅，但据布克丝教授研究后得出以下结论：玛奇接受的改造几乎是绝无仅有的，内部的身体构造与器官已经完全改变了，虽然改造出的生命系统并不完美，但几乎走出一条新的科技路线。",
		level_3 = 0,
		level_4 = 0,
		resume = "玛奇更早的信息现如今已经无从知晓，目前已知的情报仅有来自库库尔坎城市改造实验室以及后续受布克丝教授邀请加入学院，接受学习成为魂姬。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "玛奇曾经接受了超高规格的身体改造，不仅在改造时承受剧烈疼痛，改造后也依然要忍耐折磨的幻痛。由此产生了她暴躁的性格与行为方式。",
		file_3 = "玛奇的生命系统虽然并不完美，需要时常补充能量，但却可以带来惊人的战斗力与爆发力，库库尔坎实验室的科学家认为，除却拥有感情之外，玛奇几乎可以做到一切战斗类AI可以做到的事情，甚至做的更好！",
		level_7 = 0,
		level_2 = 0,
		file_4 = "玛奇堪称糟糕的性格源于曾经遭受的非人对待，长期非自愿的接受改造并承担莫大的痛苦使她几乎对所有的事物都带有防备心理，但完全可以确认的是，玛奇的内心是一个善良的人，并且对于班长保留着完全的信任。",
		level_6 = 0,
		record = "才不是偷电技工！"
	},
	[218720] = {
		soulid = 218720,
		valuation = "黑木幸的单独作战能力是无可挑剔的，精准快捷地结束战斗是她的特色。和热能匹配的相性也给她的作战助力许多。但是，在面对多敌人的情况之下，就可能暴露出控制能力不足问题。",
		file_1 = "【赤影】若是存在以前的时期，定会被称之为妖刀，通体乌黑，闪烁着赤红色的妖异光芒。 但是，这把传闻的妖刀，在幸的手里就像温顺的小兽。体格娇小的幸，却能用【赤影】施展出多样的刀术。 虽然幸能够用它使出不同的刀术甚至剑术的变体技，但是幸仍旧偏爱以必灭的一击结束战斗。 快速，精准，不拖泥带水是幸的战斗信条，也是幸对传统剑道的传承。 当【赤影】出刀的时候，就像夜幕中红色的下弦月初现，眨眼间幸就出现在敌人背后，完成从背到前的致命一击“宿业两断”。",
		level_3 = 0,
		level_4 = 0,
		resume = "黑木幸的家庭环境和之前受到的训练，形成了她高冷话少的性格。她像忍者，也像军人一样，对命令完美执行。 不该问的不问，不该说的不说，除非必要，交流多以肢体语言代替。要开口说话的场合，也是简洁有力的对答，很少有过多的语气词。 幸虽然喜欢和式点心大福，喜欢振袖，但觉得传统的和服过于笨重，又不喜欢忍者服装的拘谨，所以偏爱宽袖的便服。 进入学院之后，幸对于洛加尔地区的学员和喜好武技的学员表现出了很大的好奇，经常和她们进行联合修行，来提升自身技力。 幸的战斗风格干净利落，以迅速完美完成任务为首要目标。用敌人无法反抗的必灭一击完成宿业两断。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "幸在击倒敌人后，从来不回头看敌人是否还能行动。她对于自己的一击致命有着十分的自信。 诚然，到现在为止，暂时还未记录到受到幸致命一击的对手还能继续存活的样本。 至于，模拟战中对战的学员和一同修行的学员为什么没有受到致命一击，大概是因为幸还未完全爆发出她的凶意。 传闻当幸在对敌人爆发出完全的凶意的同时，魂器【赤影】的性能也会有一定的改变，幸的必灭斩击会带有撕裂和吸魂的效果。 即使，仍旧一息尚存的敌人也会因为持续伤害而毙命。",
		file_3 = "目前尚不明确幸在战斗机动性上的作战技巧来源于潜行还是日式忍道，但是她和胧的行动能力能达到不相上下的地步。 幸的战斗学习天赋是难以估计的，在和秋、薰之间的模拟训练的时候，通过观察能很快地学会对方使用出相对简单的技术。 通过研究观察，幸的眼睛是她学习快速，精准定位对方的强有力武器之一。 借助双眼的观察，在和麟的切磋之中，幸的魂器【赤影】在应对敌人近距离贴身攻击的时候，幸也可以借助刀柄的力量击退对手。 同时，幸自身的战斗力量也不可小觑，在脱离魂器白刃战中，尚未观测到幸所使用的格斗技巧流派。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "黑木家族长久以来，都是洛加尔地区背后的影武者。担任保护权要，执行狩猎计划，秘密任务等，权利背后的活动。 到现在，黑木家对于家族成员的训练已经告别传统日式忍道以及剑道的专门培养，在重视传统技术的培养之外，还注重对多种战斗技术和作战知识的培养。 他们对新技术、新科技知识的接纳也与传统守旧有很大的差别。而且在家族成员出生之时，家主就注重成员观察双眼的训练和培养。 双眼观察术对于黑木家来说，是除了战斗技艺之外的核心机密。\n同样，黑木家族也是以统一世界语言为目的的世界语组织——“托拉”的支持者。 自1887年柴门霍夫创造世界语，以期统一世界语言的时候，组织托拉就在背后运营而生。组织主要是在柴门霍夫博士背后保证世界语计划的推进。 各国许多宗教团体都确认世界语作为官方语言来使用，并用世界语翻译了许多典籍。 当人工智能事件发生之后，组织托拉察觉到其背后暗流涌动的复杂势力，其中除了“军方”“基金会”“暗影”等已知的势力之外，潜藏在阴影里的组织“巴别塔”也露出了尾巴。 对于学院和魂器以及人工智能的高度关注，组织托拉也派遣了他们的先遣队进入学院，完成秘密的任务。",
		level_6 = 0,
		record = "据统计，幸在开心的时候，最常用的回应就是，点头和“好的”。据班长描述，当幸将嘴巴用衣服高领遮住的时候，是害羞了。大概。"
	},
	[218920] = {
		soulid = 218920,
		valuation = "和其他学员相比，艾丝翠德的体力实在是太低了，在一场半小时的物理测试中，足足有十五分钟都在休息，不过，她对战局的把控、方案的制定、战术的变化以及危机的处理都做到了极致，有培养的价值。 ",
		file_1 = "截止到黑色圣诞节时间爆发前，艾丝翠德所发布的游戏攻略便超过了五百篇，其中有不少内容涉及到利用简易游戏漏洞黑入电子脑（赛博人工智能），达到短时间的失明、体感时间加速等多种效果，由于这些效果危险性太高，所以大部分内容都被网站管理者封禁掉了。",
		level_3 = 0,
		level_4 = 0,
		resume = "艾丝翠德出生于耶梦加得，父母是普通的公务员，平时热爱游戏，曾制霸数款类型完全不相同的游戏，是游戏界有名的王者；因为她有着制霸某款游戏就会马上抛弃的习惯，所以对她的数据采集和追踪工作十分艰难，我们的工作人员曾用线上留言、寄出实体邀请函等多种方式，但全都失败了。黑色圣诞节爆发后，艾丝翠德主动联系了学院，据说本人回答加入学院的理由是：想要在乱世中依然能玩到游戏。这使得艾丝翠德的监考官在考试结束后的一段时间都十分郁闷。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【体感时间加速】：是一种通过仪器将大脑的运动指令绕开复杂的神经系统直接传达到肢体的技术之一，常见于义体和电子脑持有者，但由于信息本身的直接传达不会给予肌肉组织缓冲时间，所以会导致多项意外伤。是一项并不完善，且违反人体规律的技术。\n而艾丝翠德却能不依靠任何外接设备，做到毫无损伤的【体感时间加速】，这个能力使得她轻松就能做出各种不可思议的反应；用她的说法大概就是：在意识到攻击之前，身体就开始行动起来将其回避，自己所要需要考虑的只有反击。可惜的是，艾丝翠德的体力太差，这份能力并不能维持太长时间。",
		file_3 = "艾丝翠德在日常生活中经常会把游戏和现实弄混，这类人在体感游戏泛滥的年代里十分常见，所以一开始大家也并不在意。但后来，后勤人员发现，她的状态已经严重影响到生活……甚至是生存的程度了，经过院方的初步讨论，决定禁止艾丝翠德游玩有关虚拟现实类的所有游戏。\n就算如此，艾丝翠德还是能够靠着老旧的PC端游戏维持娱乐，并且每天依旧保持着八小时的游戏，从健康的角度上来说，十分让人担心。不过，目前为止并没有艾丝翠德因病倒下的记录，故申请剥夺艾丝翠德游戏权的请求暂时无法提出。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "以下为艾丝翠德部分异常的言行记录：  \n艾丝翠德：那片云……绝对是素材的重复利用吧？\n调查结果：那片三角状的云朵在未来一个月保持着从经度163°，维度70°平移到经度165°，维度98°的运动，该现象一直维持到下一场人工降雨后。\n艾丝翠德：为什么要和NPC打招呼？反正很快就会被其他人替换掉吧？\n调查结果：那位被称作NPC的员工在五天后和其他人员进行了简单的工作交接后便离职了。\n结论推断：艾丝翠德的特异性或许只是一种巧合，但这份巧合并不符合科学规律，超级计算机的计算结果表明：艾丝翠德的话语有某种引导性的力量，能够将73.51%的事物引导到自己渴望的结果上；但是……究竟是艾丝翠德将那份真实摆到了我们的面前；还是因为艾丝翠德的话语才导致了这样的结果，我们尚且无法得出结论。 不过好在科学得出结论之前，布克丝院长先用了一种比较通俗的说法让大家很快就理解了她的特异性。\n即：乌鸦嘴。",
		level_6 = 0,
		record = "已发现艾丝翠德企图通过隐藏实力来逃避任务分配，目前对于艾丝翠德的【思维处理能力】已重新评估。"
	},
