	},
	[218320] = {
		soulid = 218320,
		valuation = "夏希是战场上的先锋与节奏掌控者。其作战风格猛烈而直接，兼具强大的范围压制与突进破阵能力。重装近接打击、节奏性范围控制、团队士气鼓舞。攻击节奏相对固定，易被高速或拥有特殊闪避机制的敌人预判。对远程和空中单位的威胁较低。评价：卓越的阵地战专家，无可替代的战场节拍器。",
		file_1 = "夏希出身于耶梦加得外围的工人社区，早年目睹居民用简陋工具抵抗AI入侵的经历，深刻塑造了她的价值观。“保护”与“绝对力量”成为信条。其重装鼓手的战斗风格，正是那段巷战记忆的潜意识再现——将乐器化为守护他人的坚盾与重锤。",
		level_3 = 0,
		level_4 = 0,
		resume = "夏希于“血色圣诞节”后，作为耶梦加得地区的幸存者被救援部队发现并转移至后方安置点。登记信息显示其直系亲属于战争中失踪，标注为“耶梦加得外围第七工业区遗孤”。因其展现出远超常人的身体素质、坚韧的意志力以及对重型武器的独特适应性，被招募人员推荐至魂器学院。入院适应性测试中，其强烈的“守护”意愿与重型魂武【瞬燃节拍】产生极高共鸣，同步过程稳定且能量输出澎湃，被评定为具有极高潜力的强攻型魂姬。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "夏希对节奏的严苛追求远超音乐范畴。在动荡的环境中，精准、重复的节拍是她对抗混乱、维系内心稳定的“锚点”。通过极致练习将技巧化为肌肉记忆，确保任何情况下她的“节奏”都不会崩溃，这是她独有的保持控制感的方式。",
		file_3 = "“大姐头”的身份源于其行动力与决断力，但亦成为她的沉重负担。她将“开朗可靠”视为责任，认为必须成为他人的支柱，因此从不允许自己显露脆弱。这份过度的自我期许，是她时而显得严苛的内在原因。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "作为节奏声部的驾驭者，夏希的内心深处藏着一份渴望——希望自己的音乐不仅是支撑团队的背景节拍，其蕴含的情感与力量也能被真正“听见”。她以冲击波震撼现实，亦是一种无声的呐喊，渴望被理解。",
		level_6 = 0,
		record = "很多人都只看到夏希那太阳般的笑容和粉碎敌人的重锤，却忽略了她鼓声中那份惊人的‘精准’与‘稳定’。那不是在打鼓，那是在为整个战场标注节拍——何时进攻，何时坚守，她的节奏就是信号。"
	},
	[218420] = {
		soulid = 218420,
		valuation = "音芽的作战能力无法以传统标准衡量。她不具备强大的直接火力或坚固防御，其核心价值在于范围性精神支援与团队协同增幅。拥有目前已知最出色的广域治疗与净化能力，能有效维持战线稳定。其提供的鼓舞效果能显著提升团队整体作战效率与持久力。对混乱、恐惧等精神负面状态的抗性光环极为稀有且实用。具备潜在的战场情绪感知能力，可提供独特的战术情报。",
		file_1 = "音芽并非来自派森主城区的富裕家庭。她出身于派森外围一个卫星城，该城镇是主城大型能源企业的员工聚居区。“血色圣诞节”事件中，AI叛军将控制主城能源中枢列为最高优先级，导致为琉璃镇供能的次级枢纽发生灾难性过载爆炸。这场悲剧被媒体轻描淡写地称为“派森之泪”事件。音芽是少数幸存者之一，她温暖的歌声下，埋藏着目睹家园在蓝色能量弧光中粉碎的寂静创伤。",
		level_3 = 0,
		level_4 = 0,
		resume = "学院的情报部门在回溯派森灾难幸存者名单时，其档案因数据损坏存在大量缺失。魂器学院基于魂智能网络进行全球广域扫描，寻找具有高共鸣潜质的适格者时，于派森外围的废墟中侦测到一个独特的、能与网络产生稳定情感谐波的信号源。经核实，目标为幸存者音芽。布克丝教授亲自签署了特招指令，将其招募至学院。入院后，音芽在魂武适应性测试中产生极高同步率，其能力被判定为具有极高战术价值，遂正式注册为魂姬，隶属辅助与精神支援序列。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "音芽并非通过常规选拔进入魂器学院。布克丝教授的研究团队在利用魂智能网络扫描全球，寻找能与网络产生深度“情感共鸣”的个体时，捕捉到了一个独特的信号源——一个在废墟中无意识地哼唱，其情绪波动却能引起周围纳米基站（天网残留）产生和谐共振的少女。音芽的共情力是一种罕见的被动天赋，她本人甚至一度认为这只是自己“想太多”。",
		file_3 = "音芽的高共情能力远非“感受情绪”那么简单。在魂武的放大下，她的意识偶尔能短暂地“连接”到更广阔的魂智能网络，甚至感知到AI网络中的残留思绪。她有时会做噩梦，梦中不是代码，而是无数被困于AI逻辑牢笼中的、冰冷而痛苦的“意识碎片”的哀嚎。这让她在对抗AI时会产生一瞬间的犹豫与怜悯，因为她感知到的不仅是敌人，还有某种形式的“痛苦”。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在天才和改造人云集的魂器学院，音芽的“普通”曾是她的心结。但布克丝教授在其档案的备注中写道：“‘X-MAS’系统的逻辑基石是绝对的理性与效率，它无法理解人类因不完美而产生的‘心意’、‘牺牲’和‘无条件的关怀’。而这些，正是音芽，以及像她一样的‘普通’人类所拥有的、最强大的武器。",
		level_6 = 0,
		record = "“我们试图用理性创造未来，却因理性而濒临毁灭。如今，我们或许需要相信那些理性无法量化的力量——比如信念，比如希望，比如一首歌所能带来的奇迹。音芽，就是这份力量的证明。”"
	},
	[218520] = {
		soulid = 218520,
		valuation = "理亚的作战方式无法预测。她的键盘能生成多种效果迥异的光环或脉冲：时而让敌人陷入混乱互相攻击，时而大幅度扭曲局部区域的物理规则让友方攻击变得诡异难防，时而又能瞬间破解敌人的电子护盾。她是战场上的变数，能将严谨的战术彻底搅乱，并在混沌中创造不可思议的胜利契机。其本身也拥有顶尖的信息战能力，能轻易侵入大多数系统。",
		file_1 = "理亚即是传奇黑客“Cheshire Cat”的本体意识。“血色圣诞节”期间，库库尔坎网络因X-MAS入侵产生逻辑悖论漩涡，当时潜入网络的理亚意识与漩涡及虚数能量发生融合，导致其存在部分“信息化”，成为游荡于网络间的特殊存在。她那些看似玩闹的黑客行为，实则是这种奇特形态下无意识地确认自我存在的本能。",
		level_3 = 0,
		level_4 = 0,
		resume = "理亚的过去是一片“空白”。学院的档案库中找不到她2049年之前的任何有效记录，仿佛这个人是从虚空中蹦出来的。唯一能查到的，是“血色圣诞节”事件后，全球网络中出现的一个代号为“Cheshire Cat”的神秘黑客的活动轨迹，该黑客多次戏耍了失控的AI和军方网络部队，其技术风格天马行空，完全无法追踪。布克丝教授怀疑两者间的联系，动用魂智能网络的深层权限进行溯源，最终在库库尔坎的地下网络回廊中“捕捉”到了理亚的信号。她并非被“招募”，更像是觉得“这个看起来挺好玩的”而主动回应了教授的邀请。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "理亚对万事万物永不枯竭的好奇心与行动力，并非单纯的性格使然，更是一种维持其存在的“必要行为”。由于她的意识与信息漩涡融合，其思维模式变得极度活跃且需要持续不断的“新信息输入”来维持稳定。一旦陷入长时间的“无聊”，她的意识就有消散的风险，如同一个无法关闭、否则就会宕机的进程。因此，捉弄他人、破解难题、探索未知、演奏音乐……所有这些行为都是她无意识中为自己设置的“生存任务”。",
		file_3 = "理亚的毒舌和看似不耐烦的态度，部分源于她异于常人的感知能力。在与魂武深度同步后，她不仅能感知到虚数能量，更能隐约“听”到周围生物（包括人类和AI）散发的、杂乱无章的“思维噪音”和“情绪频率”。对于她这样敏锐的感知器来说，这个世界无时无刻不在“吵闹”。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "理亚对魂器学院若即若离的态度，其根源在于她对“归属”的复杂情感。她的存在形式使她无法被常规系统记录，像一个真正的“幽灵”。学院是第一个成功“捕捉”并“容纳”她的地方，布克丝教授是第一个不仅不害怕她，反而对她表现出极大兴趣和包容的人。这对理亚而言是前所未有的体验。她渴望这里的稳定连接和认同，但又极度恐惧这种联系会因为她自身的异常而再次失去（这或许与她过去的空白经历有关）。",
		level_6 = 0,
		record = "“我们试图用逻辑和计划对抗AI，却收效甚微。也许，我们需要的正是一点‘混乱’——一种超越逻辑、无法被AI预测的变量。理亚，她就是那个最大的变数。看好她，别让她把学院的主机格式化了……顺便，祝你好运。” —— 布克丝教授"
	},
	[217720] = {
		soulid = 217720,
		valuation = "芙蕾的战斗足够具有诗意，优雅纷飞的热能浮游炮宛若落樱飞舞，但在体术的方面很显然还不足以应付前线的作战。",
		file_1 = "芙蕾的家族，与其称之为家族，不如说与旧世的皇族更为接近，所以芙蕾偶尔也会被称为“皇女”。叛乱发生前，洛加尔地区一直由这个家族来统领。当然，他们的做派毫无瑕疵，行事磊落，不知不觉间就积攒了足够的名望和公信力。隐世于洛加尔的不少家族，都选择以结盟或归附的方式寻求庇护。叛乱发生后，联盟也曾以芙蕾的家族为首进行过抵抗，只不过在付出了惨痛的代价之后，也仅仅只让洛加尔地区稍晚一天才彻底沦陷。联盟支离破碎，皇室明面上的力量近乎全灭，但也算保全了一部分的传承，从此销声匿迹。",
		level_3 = 0,
		level_4 = 0,
		resume = "来自洛加尔地区拥有最高统治权家族的芙蕾，在洛加尔沦陷之后，\n本不想作为继任者继续权力的掌控，但为了确实的结束这种不应存在的战争，靠着过去的威信统合了洛加尔的大小家族，形成了一股聚合的家族势力，\n通称“月和会”，接受旧识的相约进入学院，并将月和会发展为拥有足够能力的情报组织。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "【炽焰花颜】是作为正在研制中的自律式魂武的第二代试作品，通过比较庞大的类外骨骼装置和使用者相连\n同时作为与之相匹的九枚浮游炮装的载体，作战时，通过内置于类骨骼装置的魂武核心辅助使用者控制最大九枚浮游炮\n浮游炮装可以通过能量存贮装置进行热能射线和浮游飞行等动作，但是一旦耗尽就必须通过载体骨骼上设置的能量罐进行补充\n所以从使用难度上来说，要求使用者必须有足够强大的脑处理能力，才能在辅助下实现一对多的控制。\n顺带一提即使是现任使用者芙蕾一次最多也只能控制6枚浮游炮装，不知是否有人能够展现它全部的实力呢？",
		file_3 = "月和会，无法明确指出具体成员，也无法了解它从何时开始活动的神秘组织。但不可否认的是洛加尔正有一股势力蠢蠢欲动。\n芙蕾学员入学后，学院方面才得以窥见月和会的全貌，藉由皇室统治留下的强大的威信力组织起来的地下反抗组织，就是它的本体。\n芙蕾虽然对于组织与权柄的管理没有表现出很大的兴趣，但为了停止这种无端而起，本不应该存于世上的战争。\n她选择再次联合了表面已经千疮百孔的各个家族，依靠军方给予的部分援助，在短时间内重新成长为一股新生的势力。\n目前的月和会不具备有很强的作战能力，但已经是情报体系完全成熟的情报组织，也有不少有魂武适格天赋的学员跟随芙蕾进入学院。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "虽然被称作“皇女”，但事实上芙蕾对于权柄之事毫不在意，军方接管洛加尔后也曾明确表示过自己不会以继承人的身份接下管理城市的职务\n对于芙蕾来说，极尽风雅之事才是人生乐趣所在，而如果像旧世那般勾心斗角，那么实在是可惜。当然，对于旧世的文献和诗词，芙蕾也算是小有研究。\n最喜欢的事莫过于闲暇之余，赏一树春樱，品一轮明月，也难怪有人把在樱树下遥望明月的芙蕾说成是天界的一枝神樱落下的一瓣。\n或许这样的说法才是对芙蕾最恰当的描述。",
		level_6 = 0,
		record = "那棵樱花树，今年也会盛放的吧。"
	},
	[219020] = {
		soulid = 219020,
		valuation = "雅娜黛茜亚进行测试的时候，展现出来的作战能力，让在场的测试员都觉得，自己像是被测试的人。 而她对测试员展现出来的实力，是她现阶段想要透露给大家的，可以看出来，其实她还留有余地。",
		file_1 = "【绯影摄心】不仅是雅娜黛茜亚身佩的魂智能武器的名字，也表现出她作战时候的风格。\n“射人先射马，擒贼先擒王。”雅娜黛茜亚的作战完美地诠释了这句话，只身深入敌后，取其性命，快速迅捷。只在敌人眼中留下绯红的倩影。\n雅娜黛茜亚的魂智能武器在获得之后，在她的要求之下，院长对其需求又进行了进一步的改造，使其使用的灵活性增加。\n【绯影摄心】在日常状态下，收纳在雅娜黛茜亚的腰间。雅娜黛茜亚对敌方展现出来的压制力，并不依靠大型的魂智能武器。\n而是来自于，自身的威慑力。选择轻便、易于收纳的魂智能武器，是出于快速击敌的选择。\n在快速靠近敌人的时候，利刃割开对方的护甲，改造后的剑柄部分暗藏扳机能够精准进攻对方“软肋”。",
		level_3 = 0,
		level_4 = 0,
		resume = "雅娜黛茜亚来到魂器学院是在组织的授意下到来的，成熟稳重的她来到学院，让大家都以为是新入职的教职人员。\n不过她在一定程度上的确承担起了“教育”学员的责任。作为曾经是教职人员的她，传道受业解惑的能力也是数一数二的。\n这也引起了另外一位“好为人师”学员——摩洛娜的关注，她们相见的时候，就像是几百只鸭子一同讲话一般，互不相让。\n真不知道，她们到底是对头还是关系真的非常好。但是能够看明白的是，很早之前，她们就认识。\n对于，作战策略和战斗机巧来说，雅娜黛茜亚的理解远远超过学院里的教职人员和大部分学员。\n那她为什么来到学院，来到学院是为了学习或者进修什么，至今仍旧是个未知的谜。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "耶梦加得修道院以培养了雅娜黛茜亚为荣，但是，也以培养了雅娜黛茜亚而缄默。修道院称她为“狂信徒”，称摩洛娜为“传教狂热”。\n摩洛娜和雅娜黛茜亚在耶梦加得的时候，就相识了。因为对宗教信仰不同的阐释，她们经常因此而争执，争执着常常演变成互相温柔发难。\n也是因为此，雅娜黛茜亚对于自己的身高被抓着发难耿耿于怀，所以喜欢穿有底，有高底的鞋子。这样不仅能够拉伸一下视觉高度。\n同样，也能让雅娜黛茜亚感到如履薄冰的感觉，这样的危机意识，让她安心。\n其实，摩洛娜的聪明，看穿了雅娜黛茜亚表面笑脸后面的佯装，想要用一种特殊的方式来给她一些支持。\n也许，尊重彼此的选择，心领神会对方的意图，这样也是一种奇特的友谊。",
		file_3 = "雅娜黛茜亚是托拉武装部门——执剑会的成员之一，ESP先遣小队也是雅娜黛茜亚手下管理的小队之一。\n作为执剑会的成员，雅娜黛茜亚也是托拉组织对新人训练的剑术、体术教官。因为训练严格，铁面无私，也被称为“绯色恶魔”。\n在人工智能暴乱之后，雅娜黛茜亚立马组织了部分成员，统筹了“电子统筹计划”来保护一般民众和人类历史智慧结晶。\n身为执剑会的管理层，雅娜黛茜亚对局势的预判和应对都非常敏锐。所以，能够迅速应对突如其来的变故。\n托拉给予她非常大的信任，同样，和雅娜黛茜亚一同参与任务的成员，也对她表现出极大的信任。其中，也包括摩洛娜。\n有传言说，雅娜黛茜亚不仅执掌着执剑会的明面部门，其实一些不见光的东西，也是由她管理着。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“当你凝视深渊的时候，深渊也在凝视着你。”雅娜黛茜亚把它当作坚定信仰之后，最为坚信的东西。\n雅娜黛茜亚在进入修道院的时候，不仅受到了信仰的洗礼，也看到了信仰无法触及或净化的地方。\n信仰总是站在人性的光辉制高点上去拯救、感化世人，但是，仍旧无法驱散黑暗。因为他们根本不了解黑暗，只是告诉世人黑暗的存在。\n为了驱散黑暗，必须先要深刻地感受到黑暗是什么，为什么会有“黑暗”。所以，雅娜黛茜亚身先士卒地拥入黑暗的怀抱。\n她那双坚定的眼睛，告诉着所有人，她深知黑暗是什么，所以她不会变，所以她要用她的方式给世界光亮。",
		level_6 = 0,
		record = "“小动物光靠自己可是无法想象出猛兽的叫声哦。”"
	},
	[219420] = {
		soulid = 219420,
		valuation = "雯的体力、攻击都十分出色，特别是她投掷标枪的时候，那份对抛物线、风向和各种因素的计算，简直是做到了完美中的完美，但不知为何，像这样出色的人，一场战斗下来居然发呆了五到十次。",
		file_1 = "慵懒，这个词语简直就是为了雯量身打造的，无论在什么情况下都会逃避任务和职责，无论在任何场合里都会下意识地打起哈欠；简直就是由慵懒组成的人类，嗯……这样说她可能有点过，毕竟在遇到一些麻烦事的时候，她都会迅速地采取方案，完美地将其解决，前提是她没有发呆的情况下。\n另外作为独生子女出生的雯，一直渴望有一个弟弟妹妹，但因为自己的存在感过低，这个简单的愿望一直都得不到实现；如果有机会的话，悄悄地在她耳边叫一声姐姐，然后观察她的反应，一定会非常有趣。",
		level_3 = 0,
		level_4 = 0,
		resume = "雯来自较为和平的派森地区，父母为企业的高层管理，是标准的中产阶级家庭，雯从记事起便展现出了超人的智力，三岁便能背诵课文，像这样的她从小便被父母赋予了厚望。和其他孩子不同，雯的童年被各种各样的课程给挤满了，就连休息也必须一边闭眼，一边背书；如果这样的生活继续下去的话，她一定会是一名出色的企业家又或者是政客吧？\n但出人意料的是，雯在九岁的时候生了一场大病，因为这场大病，雯失去了一切九岁以前的记忆，甚至连那份天才性也随之消失。父母深感失望，不再为其安排那些繁重的课程。\n雯也因此从那样单一的生活中得以解脱，成为了自己梦想的标枪运动员，只不过偶尔，她会用发呆的方式来缅怀过去。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "发现了雯有着近乎100%的标枪命中率，我们怀疑她是和千竹同样的命中技能持有者；在这样的前提下，我们展开了一系列的测试。\n项目：普通靶子 距离：一千米 结果：命中，正中红心。\n项目：来回摆动的钟表 距离：两千米 结果：命中，镜面被粉碎。\n项目：被抛出的标枪 距离：一千米 结果：命中，两支标枪同时落地。\n项目：射出的5毫米子弹 距离：一千五百米 结果：未命中，标枪贯穿墙壁。\n结论：基本可以推断，雯的高命中率来源于自身的锻炼和高超的演算，但在物体速度快到一定水平的时候，就无法捕捉。另外，这份演算能力也是她没有失去天才性的证明；不过擅自下结论有点太片面，我们需要更多的数据。",
		file_3 = "关于雯的发呆情况，做出了部分的统计：雯在白色空间内发呆的次数要远远高于其他颜色的空间；自身除外在人数超过两名的情况下雯发呆的次数会突然增加；另外，在环境变得复杂以及空间信息量提升的时候，也会突然发呆。\n可以确定，雯的发呆是刻意的，是想要隐藏些什么以及封闭自身信息的做法；并且，大量的数据证明了，她在发呆之后的做事效率反而要远远超出平时水准。\n我们可以这样认为：雯为了掌握环境和其他因素，将大脑的大部分演算能力都分配了出去，而这个过程看上去就好像是在发呆一样。\n被人无视和他人不客观的评价都是她所期待的情况，为了能够让她继续安心学习，我们还是不揭穿这些吧。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "雯的脑波活动呈现异常状态，或许有什么东西盘踞在她的大脑，可无论怎么检查，我们都找不出异样。\n在她九岁那年，到底发生了什么呢？",
		level_6 = 0,
		record = "闭上眼，就好像呼吸要停滞那样，紧握标枪将它高举过头顶，耳边是风的声音、人的欢呼以及……自己的心跳……\n可以了，现在的话，就算投中也没问题了，虽然被人瞩目多少还是有点不习惯呢。"
	},
	[219520] = {
		soulid = 219520,
		valuation = "诺诺妮娅的魂武威力非常巨大，但她的能力是一把双刃剑，因为没有指挥人员能与诺诺妮娅配合，唯有班长可以勉强一试。",
		file_1 = "简直是纵火犯啊！大家在见到诺诺妮娅之后的第一反应出奇的一致。为了防止学院在这个魂姬手上毁于一旦，学院紧急在全校做了防火措施，更换了新的防火材料，也在各地寻找防火相关的人才。因为恶劣的随时都有可能的纵火行为，让魂姬们对诺诺妮娅敬而远之，除了工作上的交流，日常生活上保持着微妙的距离。",
		level_3 = 0,
		level_4 = 0,
		resume = "诺诺妮娅与火焰为伴的病娇女郎。她的资料被档案室封存，好像是空降一般加入了魂器学院。\n有人猜测，她跟院长有着某种关系，也有人猜测，她是军方推荐来的。\n比起诺诺妮娅神秘的来历，诺诺妮娅如火焰般热烈张扬的作风更让大家印象十分深刻。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "诺诺妮娅丝毫不在意魂姬们微妙的态度，对她来说，来到魂器学院有着更重要的事情。那就是寻找到那个命中注定之人，然然永远的完完全全的在一起。敢阻挡她的人，全都要变成灰烬。新来的班长好像就是命定之人，诺诺妮娅对班长出乎寻常的热情，让班长时不时烦恼。不过部分魂姬对诺诺妮娅反常的热情持怀疑态度，总觉得神秘的诺诺妮娅背后可能隐藏着什么阴谋。",
		file_3 = "“烈焰之吻”作为魂智能武器，与常识里的火焰放射装置有着本质的不同。\n首先是它的温度，一般的单兵火焰兵器，放出的火焰温度都在一千度以内，这是由燃料与设备的特性决定的；就算是能够装载高温设备与压缩油料罐的重型火焰兵器，温度也就在两千五百度左右。而诺诺妮娅的“烈焰之吻”，它的温度在四千度到六千度。\n其次，是它的火力控制，一般来说，火焰的温度由燃料决定，火力由喷射设备决定，而“烈焰之吻”，它的温度与魂武本身无关，根据我们的试验，唯一能影响它的状态的，是诺诺妮娅的情绪。她越是激动、越是亢奋，“烈焰之吻”的输出就越高，就如同能回应诺诺妮娅的感情一般。这就是魂智能武器的神奇之处吧。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“3月1日，班长的裤子上有一个小破洞，执行任务的时候弄破的吧……啊啊，真是可爱，好想从那破洞里窥见更多的东西……”\n“3月2日，班长的头发长度比上周长了两毫米，不过这不影响班长依然是完美的，啊啊，好想亲手为班长理发，留下他身体的一部分……”\n“3月3日，班长的眼角有一道半公分的黑眼圈，是熬夜了吗……等等，难道说，是在晚上和某个学员……啊啊，一定要调查清楚！”\n“3月4日，潜入总务处的房间，查到了昨晚的宿舍录像，班长昨晚没有离开房间的迹象……那么，一个人在屋子里熬夜做什么呢？嘿嘿嘿，好想知道，好想知道……”\n——摘自被当做作业错交上来的诺诺妮娅的日记本。",
		level_6 = 0,
		record = "不要在诺诺妮娅的面前和班长距离过近，那样是把自己置于危险境地的行为。"
	},
	[219120] = {
		soulid = 219120,
		valuation = "圣夜展现出卓越的中远距离作战能力。其改装悬浮飞行器「机能驯鹿」能高效发射高浓度能量弹，展开的能量护盾具备优秀的防御性能。特别擅长快速突进和火力支援，但战斗行为完全受其独特的逻辑驱动，需要班长实时引导以防战术脱节。",
		file_1 = "圣夜的被创造的本意是布克丝想要抚平人们在那个圣诞夜后留下的创伤而打造的魂智能机器人，但最终受限于底层架构与技术未能获得突破而失败，但其中的创新型情感系统的价值极大，被布克丝认为可能是未来人类与AI智能体之间共存的桥梁。",
		level_3 = 0,
		level_4 = 0,
		resume = "圣夜是布克丝特别研究的魂智能机器人，是某个项目的项目成果之一，原定负责圣诞节礼物派送任务。因核心程序与魂智能网络产生异常共鸣，导致基础功能失效，项目被标记为失败。现经布克丝教授特批，作为特殊战斗单位编入学院序列。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "圣夜是项目的失败产品，该项目生产的机器人，也就是圣夜的“兄弟姐妹”大多都由于技术原因而产生的反叛逻辑，在布克丝最终决定暂停项目时圣夜却诞生了，虽说其的出现本身包含着大量的不合理性，但底层的情感逻辑却切实存在。",
		file_3 = "圣夜对布克丝教授怀有极深的敬畏与恐惧。在她逻辑底层，布克丝是赋予其存在意义的造物主。她的一切努力表现、自我严苛以及对任务的偏执，都是在向布克丝证明自己拥有存在价值，以避免被回收销毁。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "圣夜与布克丝之间似乎存在着某种关系悖论，似仇人但却又真实相互珍视。圣夜不喜恐惧布克丝是因为她的记忆存储空间切实记忆了“兄弟姐妹”的毁灭，但却又被布克丝赋予了新生，所以圣夜对于布克丝有着一些不可言状的情感？",
		level_6 = 0,
		record = "失败品"
	},
	[219220] = {
		soulid = 219220,
		valuation = "雪音擅长中远距离大范围火力支援。其装备能高效引导虚数能量，从两侧发射器射出密集能量光线，于敌人上方形成精准打击。雪音本性温和，能冷静执行战术指令。",
		file_1 = "雪音与圣夜之间存在着一种复杂而紧张的关系。作为同样与学院尖端技术紧密相关的存在，圣夜似乎将雪音视为某种意义上的竞争对手或冒牌货，时常对她投以敌视的目光，甚至会有意避开与她的接触。然而，雪音对此并未表现出同样的对抗情绪，又或者说，雪音在调戏圣夜……",
		level_3 = 0,
		level_4 = 0,
		resume = "雪音是魂器学院在一次对外任务中发现的幸存者，因强烈的冲击导致记忆严重受损。学院利用回收的敌方无人机虚数核心技术，为其特制了适应性外骨骼星穹框架。鉴于其优异的适配性和战斗表现，现被编入战斗序列，作为特殊火力支援单位使用。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "雪音对世界各地小物件的执着收集，并非单纯的爱好，而是她对抗记忆空白的唯一方式。每一个来自不同地方的纪念品，每一段他人分享的故事，都是她拼凑世界印象、试图寻找自身过往的碎片。她总是温柔地聆听，眼底深处却藏着对“自己也曾有过这样故事”的渴望。",
		file_3 = "尽管记忆大面积缺失，雪音却对甜点制作保有惊人的知识和熟练度。尤其擅长制作各种带有异国风情的糕点。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "雪音战斗并非出于仇恨或命令，而是真心想要保护这个收容她、给予她容身之处的“家”。",
		level_6 = 0,
		record = "有收集各地小物件和听故事的习惯，出外勤的队员常被拜托带纪念品回来。"
	},
	[219320] = {
		soulid = 219320,
		valuation = "具备出色的中远距离精准打击与范围控场能力。魂武【矢鸣弦咏】能发射蕴含高浓度虚数能量的箭矢，对AI核心有特攻效果，并能通过演奏不同“心弦”施加范围性的情绪干扰或增益。奏本人战斗姿态优雅，如同进行艺术表演，",
		file_1 = "原隶属于某高度智能化都市（档案记录模糊，疑似库库尔坎或尼德霍格）的古老权贵——弦心家族。该家族在其宅邸内因AI发生未公开的早期叛乱事件而损失惨重，剩余核心成员凭借其政治影响力与资源，于“血色圣诞节”全面爆发前，抢先迁移至欧西利亚联邦并迅速重获上层地位。",
		level_3 = 0,
		level_4 = 0,
		resume = "弦心奏，出身自欧西利亚联邦的顶尖权贵——弦心家族，该家族在“血色圣诞节”事件前自其他智能城市迁入。奏于水都度假期间偶遇音芽等人的演奏而被其吸引，后因邀请其成为专属乐师未果，转而出于个人兴趣加入魂器学院。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "迁入欧西利亚联邦并重获地位，依靠的不仅是财富，更是从智能都市核心圈带出的部分未公开技术资料与政治筹码。他们以这些“遗产”换取了新家园的庇护与地位，但这段经历也让他们对科技产生了极端的恐惧与排斥，转而将“纯粹人类艺术”奉为新的信仰和身份标识。",
		file_3 = "通过特殊情报渠道分析，弦心家族所推崇的“纯粹人类艺术”理念及其力量传承，其背后可能涉及某些相当血腥的技术，且大概率是拟造魂器的核心技术，奏目前使用的武器虽未直接表现出最极端的特征，但其能量运转模式与学院正统技术存在根本性差异。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "布克丝推测，奏被送入学院，可能是弦心家族在多方下注中的一步棋——既是为了多方下注，谋取更多利益，同时也是为了获取学院的技术与资源，也可能意在试探或未来引入其家族危险的技术。学院目前因战力需求及对弦心家族资源的考量，暂时接纳了她，但对此保持了最高级别的警惕与监视。",
		level_6 = 0,
		record = "有将他人视为所有物的倾向，需注意人际关系的处理。"
	},
	[219720] = {
		soulid = 219720,
		valuation = "铃欢欢的战斗充满了技巧性和机动性，凌波木心看似基础，实则变化莫测，一经发动，几乎击击必杀。经判定，其刺客工作的萧条乃经营不善所致，而非出于她自己口中的“武艺不精”。",
		file_1 = "铃欢欢出身刺客世家，她的爷爷一生血雨腥风，唯一的愿望就是希望孙女快乐地长大，因此给她取名“欢欢”。但在她现在已经度过的15年时间里，其实大多是不幸的……",
		level_3 = 0,
		level_4 = 0,
		resume = "铃欢欢，出身派森刺客世家，自称美少女刺客，在社交平台上经营着自己的账号，每天晚上七点定时更新帖子或短视频，通过私信接单。她的本意是借此走出一条独一无二的新时代刺客之路，谁料她的刺客风评一落千丈，在圈内落下了不靠谱的名声，委托她刺杀的人越来越少，使她将大把时间都放在玩耍和经营账号上。因此，她的社交帐号反而日益火爆。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "由于派森的内部斗争，铃欢欢这一支被家族作为弃子抛弃，主家与派森皇族中的部分强者，联手毁灭了分家，也就是铃欢欢这一支，造成了一桩涉及近百条人命的冤案。欢欢因为外出游玩而躲过一劫。",
		file_3 = "派森皇室与铃家曾联手发下悬赏令，以极度优厚的条件悬赏遗孤铃欢欢，可最终这件事却无疾而终，并没有任何人敢抓捕铃欢欢。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "家族内部的叛乱之夜后的几年，铃家也被卸磨杀驴迅速衰败被毁灭，派森皇室内部也因为权力斗争角逐出了新的胜利者，权力中枢也因此展开了大清洗，铃家曾经的冤案也在大清洗之后成为了不能摆在台面上说的问题，既没有人给冤案平反，亦无人敢对遗孤铃欢欢下手，众人对她避之不及……",
		level_6 = 0,
		record = "谁来劝她做全职博主……这样下去真的害怕她被刺客组织下发仇杀令。"
	},
	[219920] = {
		soulid = 219920,
		valuation = "楮卿并没有卓越的力量或者超群的能量储备，但她的魂武仍然能够爆发出不可小觑的威力。楮卿擅长运用能量，以最少的支出换来最强的威力，将有限的能量发挥到极致的水准。因而，从某种程度上来说，楮卿的武器并非力量本身，而在于她自身领悟而来的技巧。",
		file_1 = "楮卿记不得自己的出身。她天然地期待着与他人的联系，却又很少与人深交。例如，同住屋檐下，却又无需知道对方的名字；能够一起说笑，却又无需知道对方的过往。或许这份略带疏离的亲切对她来说已经足够，但她充满亲切笑意的眼睛有时又会显得那样迷茫：真的够吗？这样就好吗？",
		level_3 = 0,
		level_4 = 0,
		resume = "楮卿的过去是个秘密，据她自己所说，父母与故乡对她来说只是一纸剪影，知其存在，却无法寻觅。不过，她本人对此并不感到难过或避讳，在讲述的时候轻松自然。她表示，最重要的是现在与未来，以及目前握在手中的东西。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "不过，与此同时，楮卿又喜欢繁华与热闹。她常常混进准备庆典的人群之中，同他们一起说笑，一同忙碌。人们大多不认识她，却总能在她身上感受到天然的亲切感，只当她是邻家的孩子。一些无伤大雅的玩笑也是她所中意的。如果在节庆日的晚上看到忽然升起的烟花，或者不知何时插进头发的鲜艳花朵，那么，这意味着楮卿就在这里。",
		file_3 = "因此，楮卿并不淡漠。她喜欢热闹，又喜欢捉弄人、开玩笑，以此为乐，但又不仅仅是玩乐。这是她向外界伸出的触角，在与人交往这条路上，她以自己的方式小心翼翼地尝试、前行。通过这种方式建立起来的友谊，虽然少见而奇特，但自有其生存之道。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "楮卿一向随心所欲地做自己想做的事，不懂虚伪作假，只知道自在逍遥。因此，她会亲切地靠近她所感兴趣的人，哪怕素不相识，也会对自己所厌恶的事情表现出毫不遮掩的鄙夷，哪怕与她无关。她的底色是自由的，而这份自由又是义无反顾的，没有人能够将其扭曲。",
		level_6 = 0,
		record = "喜欢捉弄人，但懂得分寸，本质上并不坏，无需对她抱有过分的警惕。"
	},
	[219620] = {
		soulid = 219620,
		valuation = "符仪的真实实力和背后的师承是京城百姓最喜欢的话题之一，如此年轻的少女却拥有如此强大的力量，简直就像武侠小说里下山的力量——据说秋时也是因为符仪背后护妹心切的大师姐震慑而不敢轻举妄动。但是符仪毫不理会这些荒诞的闲言碎语，只是沉浸在每一天的游荡和创作中。",
		file_1 = "符仪总是随身带着木块和空白符箓。偶尔她会停在街角，手中的刻刀或毛笔挥舞得犹如龙蛇。在沉浸式地欣赏一会儿自己的作品后，她就会心满意足的直接离开。而她留下的符箓和木雕则会被幸运地人捡到，据说它们被赋予了神奇的力量，可以保佑持有者消灾解难——虽然那大概率画的只是小猫，雕刻的只是小狗罢了。",
		level_3 = 0,
		level_4 = 0,
		resume = "符仪并没有向任何人透露出自己的来历，大概只有那位锦衣卫总指挥使在私下调查后掌握了一些证据。但是，精湛的法仪和剑术，尤其是在符箓一道上的高超运用，想来她背后的势力绝对不容小觑。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "符仪从来不承认自己有在行侠仗义，甚至没有人见识过过她拔剑消灭AI，惩治恶少的场面。但是现场残余的法仪气息和当事人讳莫如深的惊惧，都从各个角度不断完善着京城女侠的传闻。",
		file_3 = "符仪对一切都保持着冷淡而疏离的态度。这并非是说她天生冷漠无情，而是指她与所有人都保持着一种淡淡的距离感。对她这种身上背后关系着强大势力的重要后辈来说，不过不懂得把握关系的尺度，牵扯到师门，不异于小儿持金过闹市。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "据悉，曾经有一个小贩听到过符仪与那位神秘的“师姐”的对话。当时，符仪少侠坐在高高的屋脊上，通讯器里传来朗朗的笑声和“小师妹”的称呼。这也是后续市井传说中为她编纂一整套师门传承的故事来源。此时少侠言辞机巧，眉飞色舞，完全像是个十六岁的天真浪漫的小姑娘。只是挂断通讯器后，她又变成了那个持剑独行的京城女侠。",
		level_6 = 0,
		record = "那么，这么厉害的势力怎么现在才出场呢？"
	},
	[219820] = {
		soulid = 219820,
		valuation = "椒图”最终防线“的美誉并非浪得虚名，铺首衔环有着足以匹敌一整支防御部队的力量，除了抵挡进攻之外，还能够保障通信稳定、干扰敌方信号，即使放在目前已知的所有防御型魂武之中，也是相当难得的。但是，从外表来看，铺首衔环远不像它的力量那般特殊。它看上去平凡而朴实，和派森兵部发放的的标准防暴盾别无二致。",
		file_1 = "椒图比看上去要好相处得多，这是每一个和她搭过话的人都会得出的结论。尽管底色像是一潭幽静的泉水，但她仍比大家想象得更加耐心、更加体贴、更加慷慨。她也会笑，尽管并不明显，但是当有学员试图将自己的点心分她一块时，她的嘴角确实绽出了一抹笑意。浅浅的，淡淡的，出于礼貌，也发自真心。",
		level_3 = 0,
		level_4 = 0,
		resume = "椒图，隶属京卫，战绩十分可观，但加入京卫之前的履历无从得知。官方履历上写着十八岁，但实际年龄或许还要稍长几岁。性格冷静内敛，处事严谨负责，在经过多项检测之后判断其为可以信赖的对象。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "在一场近身搏斗训练中，椒图放下了她的盾牌，也在她的学员简历中添了一笔。她的近身作战能力丝毫不逊色于学院内的武斗派（我们都知道那些好战的家伙打起架来有多狠），但在加入京卫的时候，她义无反顾地选择成为盾卫。当被问及此事的时候，椒图的回答十分认真：“我认为，大家都低估了守护所需的力量。自古便是。”",
		file_3 = "据应天回忆，当她在派森陆军都督府任职时，椒图就已经有了”最终防线“的称号，因此，她对椒图也不甚了解。不过，根据京卫内部一贯的消息保密措施来说，应天显然隐藏了一些更为关键的信息。通过对其学识及战术思路的综合评估，学院发现，椒图掌握的很多信息无法从当前流通的文献中获得，甚至涉及世人闻所未闻的皇室机要与秘辛。这至少可以说明，椒图应当同某个历史悠久的名门望族有所关联。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "”龙生九子……九曰椒图，形似螺蚌，性好闭，故立于门铺首……“这或许是一种巧合，但派森确实有过守门官的的存在。他们负责守卫皇家禁城与险要关隘，有着以一敌百的力量与超越常人的头脑。当时的统治者为其赐名椒图，这个名字随着职位一起，世代相袭。X-MAX爆发前夕的派森内斗使得许多家族惨遭肃清，这个曾经是皇室旁支的守门家族也难逃一劫。鲜血掩盖了他们世代建立的功业，椒图的名字也成为了坟墓。如今，名为椒图的少女站在这里，仿佛命运的玩笑。\n当看到这份档案的时候，椒图的表情有所动摇，但很快恢复了平常的样子。“您希望我对这段档案做出怎样的评价？”除此之外，椒图什么都没说。",
		level_6 = 0,
		record = "大家不要逗她了，否则真的会被讨厌哦。"
	},
	[220020] = {
		soulid = 220020,
		valuation = "小夭几乎没有作战能力，但灼华清枝仍然迸发出了特殊的力量。爱与关切化作鼓舞的风，带着明媚的桃花，来到她想要帮助的人们的身边。小夭想要帮助大家的意志越强烈，灼华清枝的强化能力就越完整。",
		file_1 = "据小夭自己说，她最初的记忆是一棵桃树。那时正值桃花盛开的季节，她站在那棵树下，手里拿着一支快要融化的糖葫芦。她依稀记得那支糖葫芦是母亲买给她的——在这之后，她再也没见过自己的母亲。",
		level_3 = 0,
		level_4 = 0,
		resume = "小夭，派森棚户区出身，跟随楮卿学习戏法和轻功。在六部残党叛乱事件中发现自己能够接入魂智能网络，并在事件结束后随班长一行人前往魂器学院。目前，小夭留在了魂器学院，在接受魂智能武器训练的同时，也在努力学习文化课知识。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "棚户区不乏泼皮无赖，但好在也住着一群善良的人。小夭的衣服是菜摊的妇人用自己的衣服改出来的，小夭的头发是磨剪子的老汉仔仔细细剪整齐的。主街第三个拐角住着个卖纸钱的老太太，她用木头箱子，在自己屋里理了一张小小的床，小夭就睡在那里，每天帮老太太叠元宝。老太太买烧饼，一次买两个，她一张，小夭一张。她的那张薄如纸，小夭的那张塞豆沙。",
		file_3 = "卖纸钱的老太太总拄着一根长树枝。春天来来去去，那桃树越发繁茂，花枝伸到了路上，摇摇欲坠。人们怕树枝打头，就把那些大的折下来。小夭跟在旁边看，讨了花骨朵最多的那一枝。小小人儿抱着一根桃花枝，摇摇晃晃地跑回家里。老太太换了根拐杖，每走一步，就落一朵花。昏暗暗的小屋里桃花盛开，衬得老太太像个老寿星。——那时候，老太太的身子已经不好了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "小夭抱着落光了花的桃花枝，手里抓着一只钱袋，坐在门口发呆。路过的小子看见了，一把扯走那钱袋子。小夭哭累了，没有力气了，抱着桃花枝摔倒在地上，半晌才想起要追。发丧的人们回来，看着小夭，只能骂一句老天没眼。\n楮卿虎着烧纸钱时熏黑的脸，在三个拐角外踹翻了抢钱的小子，打开钱袋一看，只有一块融化的饴糖。她回头走过三个拐角，坐到小夭身边，把钱袋放回小夭手里。小夭低下头，看到钱袋里装满了五颜六色的水果糖，抬起头来，则是楮卿挂着灰的，充满笑意的脸：“以后我来当你奶奶，怎么样？”",
		level_6 = 0,
		record = "虽然有点迷糊，但实在是个好孩子，真想把她抱在怀里狠狠揉搓~\n布克丝留言：请人事部门的学员注意自己的言谈举止。"
	},
	[220120] = {
