		file_4 = "档案被黑暗扭曲了。",
		level_6 = 0,
		record = "档案被黑暗扭曲了。"
	},
	[220220] = {
		soulid = 220220,
		valuation = "虽然成功击败了训练用的人工智能，不过战斗本身并没有可取之处。就旁观者看来只不过是利用了电击的特性达到了机械特性的敌人，只是取巧而已。至于物理攻击力……非常符合年龄与外表。",
		file_1 = "芭荼荼在学院任职预备风纪委员，但从她的执勤记录来看，芭荼荼所做的早已超过了这个职务应承担的工作强度，甚至要比一般的风纪委员还要更加尽职尽责。\n高强度的工作实际上很难获得他人的认可，目前已经有部分学生对她有所微词，觉得她的做法是严重的越级行为。\n我们所采取的做法是：将她的部分工作转移到其他的风纪委员身上，但芭荼荼很快就陷入了情绪低落的状态，我们得为这孩子想想办法……\n记录：班长入学一周后\n我们委托了芭荼荼帮助班长熟悉学院的环境，看样子她对十分喜欢这份新工作，现在已经完全黏在了班长身边，心情也改善了不少；……虽然这一切都是建立在牺牲班长的前提下。",
		level_3 = 0,
		level_4 = 0,
		resume = "芭荼荼·伊万·伊万诺夫，来自尼德霍格未被战火波及的区域，目前仍有大量的人居住在那个区域，通过严密的审查，可以初步确认芭荼荼没有间谍、特工的可能性。\n性格上，芭荼荼偏向严厉，喜欢遵守规则，并且也会要求别人也遵守规则，是那种喜欢用自己的标准去要求别人的类型，但这同时也表示，芭荼荼绝对不会勉强别人去做自己做不到的事。整体而言是个对自己定位清晰的孩子，但或许是太过清晰了，芭荼荼总是将自己未来的规划提前放置到自己身上，这也就导致了，她对自己过于严厉，总是不满意。长期下去，会逐渐引发各种心理上的问题，建议为她寻找一个可倾诉的对象。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "对芭荼荼上午的观察记录：\n六点四十分：起床 七点二十分：洗漱和早餐 七点四十分：在寝室门口等待班长 八点三十分：打断了班长和伦茨的独处 九点二十五：体育课依然观察着班长 十点三十四：假装和班长同一时间下课 十一点十分：游泳课记录缺失 至此上午结束，下午集体转移至实战设施。\n结论：嗯……是不是有点像是跟踪狂？不如说几乎把所有的活动时间都放在盯着某个人身上了，如果不是两人之间的交流太过正常的话，或许我会申请风纪仲裁吧。\n附录：来自布克丝的音频记录：管理员10492，如果下次还看到你调用学院内的监控设备做这种无聊事情的话，你就自觉地注销管理员身份吧。",
		file_3 = "【记录】管理员10492：无论怎么看，芭荼荼·伊万·伊万诺夫都只是一位普通的十二岁小女孩，她在实战中所表现出来的能力要达到及格线也有些困难。更别提就这样堂而皇之地成为学院的一员了；虽然布克丝院长叮嘱过我，绝对不可以再进行有关芭荼荼相关事件的调查，但那也只是针对她的过去，在学院内的数据还是能调用的吧？\n【记录】管理员10492：没有充能记录……芭荼荼手中的电击棒并没有任何充能的记录！这也就意味着，她本身能够提供对应的能量，等一下！究竟是将部分能量转换成电流，还是她本身就能产生电流？那支电击棒能释放的电压可是有一百万伏特的啊！就算异能者再怎么强大，那也只是体表的程度，体内的细胞又怎么可能承受那么强大电压？必须要和布克丝院长提出相关的测试申请才行！\n附录：来自布克丝的音频记录：不用申请了，你被开除了。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "【院长亲自编辑的词条】\n芭荼荼为基金会所属的成员，是我和基金会达成某种协议的附带品，虽然那个协议里大部分都是对我不利的地方，但……能够将这个孩子带到学院的话，一切都算是值得的。管理员10492差点就接触到了真相，我必须在这之前将他开除，否则将会对今后的计划产生不确定因素。\n没错，芭荼荼·伊万·伊万诺夫……啧，这名字真是拗口，总之这个孩子确实能够产生人体所不能承受的超级电压，并存储到细胞当中，而那支电击棒里所释放出的仅仅只是体内电流接近饱和后，所溢出的少量电流罢了。这份能力，如果反过来运用的话，甚至能够做到吸收掉外界的高压电流，然后将其重复释放；只要能做到这一点……夺回那个大部分被人工智能攻陷的发电之都·奥杜因就不是难事了。\n夺回奥杜因的话，那么今后的一系列计划都不需要走弯路了。",
		level_6 = 0,
		record = "那副天真，究竟是本性还是伪装，也许……就连本人也无法解释吧，只有一点可以确定，那就是她对班长的那份心情，远比闪电还要耀眼。"
	},
	[220320] = {
		soulid = 220320,
		valuation = "或许是绘画天赋的缘故，伊织在使用【裁梦之绘】的过程中展现了惊人的细微操控能力，巨大的裁纸刀在她手中像是画笔一样轻松写意，游刃有余地对敌方的薄弱位置造成精确打击。",
		file_1 = "伊织并非洛加尔的战争遗孤，实际上根据调查，她的生物学父母尚且在世。但是关于联系他们一事伊织表现了强烈反对，乃至要拔管出院逃跑，因此学院只得放弃了该计划。后通过洛加尔官方渠道报备，以“特殊人才引进”身份完成入学注册。",
		level_3 = 0,
		level_4 = 0,
		resume = "伊织并没有什么复杂的背景，背后也并没有牵扯什么大势力布局，她仅仅只是因为忘记吃饭，低血糖晕倒在了学院的洛加尔办事处而已……适逢班长是班长来此出差，将她带到了医院。或许这也是伊织同意加入学院的重要原因——毕竟再晚一点她可能就要在春雨中失温了。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "伊织性格并不算孤僻，实际上对于她在学院中新交的朋友来说，她甚至有些话痨，对于某些话题能滔滔不绝地聊一整个晚上。不管怎么和伊织成为朋友或许是个新的问题……绘画？战斗？家庭？总之，至少伊织不是那么有警惕心、拒人千里之外的人。",
		file_3 = "关于伊织的绘画天赋这件事情，她自称是小时候捡到过一些被丢弃的绘画教材，大概是《一个月教你怎么画画》之类的入门级兴趣书，但是伊织仅仅凭此和省钱买来的劣质画具，很快就展现了在色彩和形体上的天赋，通过网上接单获得了第一笔收入。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "在某次会谈中，伊织提到自己的父母早已离婚，双方都放弃了对她的抚养义务——直到她后来因为插画在网上火了，他们又争着希望接她回家。但是伊织已经习惯了自己独自生活，不过从把自己饿晕在洛加尔办事处门口以至被收留这件事来看，伊织的生活习惯真的很糟糕……",
		level_6 = 0,
		record = "要时刻注意伊织到底有没有认真吃饭，避免她再次低血糖晕倒。"
	},
	[220420] = {
		soulid = 220420,
		valuation = "火力压制评级S+，战场指挥评级E。虽然她发出的指令没人听得清，但在她那毁天灭地的炮火掩护下，任何战术都显得多余。",
		file_1 = "学院里害羞的女孩，平时总是低着头贴着墙根走路，如果不小心撞到人，会连续鞠躬道歉三分钟。",
		level_3 = 0,
		level_4 = 0,
		resume = "在学院的人才筛选测试中，朵儿因为极度紧张，在射击评估时全程闭着眼扣动扳机。然而，她凭借惊人的直觉（以及想要快点结束测试回家的愿望），在盲射状态下打出了100%的压制覆盖率。系统因此将她判定为“极其自信且冷酷的重装射手”，直接分配到了最前线。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "朵儿极其宝贝她的红旗。这面旗子不仅是引导工具，更是她的防具——紧张时用来遮脸。",
		file_3 = "其实私下里会在宿舍对着镜子偷偷练习大声喊口令（“全、全军出击！”），但往往喊完两句就会因为觉得太羞耻而蹲在地上抱头破防。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "朵儿并非天生拥有神力，她的“怪力”其实源于她极度紧绷的肌肉神经。因为害怕世界，所以她强迫自己去掌控能够摧毁恐惧的力量。",
		level_6 = 0,
		record = "下达指令时声音尽量轻柔，不要拍她的肩膀，否则可能会走火。"
	},
	[220520] = {
		soulid = 220520,
		valuation = "该学员展现出了极强的精神控制与战场干扰能力。她能用诡异的低语和无法观测的力量瓦解敌人的斗志。不过，由于她本人也极度缺乏干劲，必须合理安排她的工作时间。",
		file_1 = "大众眼里的艾莉诺雅总是带着慵懒而迷人的微笑，仿佛看透了世间的真理。她随身携带的巨大魂武不仅是慑人的武器，更是她的移动豪华单人床。在阳光明媚的下午，你经常能看到神像的盖子半开着，里面传出平稳的呼吸声，偶尔还有几根暗紫色的触手探出来，帮她把滑落的毛毯重新盖好——据传那里面不是封印着什么东西吗？",
		level_3 = 0,
		level_4 = 0,
		resume = "入校时填写的信仰是伟大之潜水意面神。凭借着一手出神入化的催眠（物理砸晕与魔法蛊惑）技巧，以及浑然天成的优雅气场，她随随便便就通过了学院的战术测试，成为了常驻摸鱼人员。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "这位散发着危险魅力的主教大人是个不折不扣的海鲜重度爱好者兼生活废柴。她一直念叨着的不可名状的触手，其实是由虚数能量具象化而成，经常被她召唤出来当做全自动按摩仪、零食搬运工，尽管在艾莉诺雅看来那是她可爱的仆从们，但是更多的时候学员们只看到一团东西围绕着她飞来飞去，像是闹鬼了一般。",
		file_3 = "艾莉诺雅过去在某份工作中经历了极其惨无人道的007压榨。在一次边赶工边打瞌睡的顿悟中，她忽然顿悟，砸烂了教堂的钟楼，决定成立自己的实力。她决心要让全天下的人都享受到摸鱼的快乐，任何试图阻止她睡懒觉的人，都会受到沉湎之海的物理严惩。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "音频分析表明，艾莉诺雅的低声呢喃其实是一种特殊频率的声音，受试者在极短时间时间内都表现出了困意。经过长时间的实验观察后，刻录下的艾莉诺雅呢喃光碟已经成为了学院最紧俏的抢手货，据说多名顾客都因此解决了失眠问题。",
		level_6 = 0,
		record = "建议不要安排她在早上十点执行任何任务。"
	},
	[220620] = {
		soulid = 220620,
		valuation = "爱之法庭具体的充能、使用和维护都是秘密，或许真正的资料只存在于尤斯蒂娅和布克丝院长的脑子里，但是我们仍能从都市传说中依靠推理得出这位神秘的法官的真实能力。",
		file_1 = "尤斯蒂娅长期通过非官方渠道获取过去的的情感纠纷类卷宗和言情小说，其私人藏书室的规模已远超法院档案室的法律类目。值得注意的是，即便她的案件调解率在联邦最高法院中一骑绝尘，但心理评估仍显示她对此类工作保持着非典型的高昂热情尚未发现其整理行为与魂武充能之间存在直接关联，但布克丝院长建议持续观察。",
		level_3 = 0,
		level_4 = 0,
		resume = "尤斯蒂娅在欧西利亚联邦司法系统中拥有极高声望，其调停成功率在联邦最高法院常年居于首位。当常规法律程序在情感纠纷与遗产继承等复杂案件中陷入僵局时，她所持的精神干涉型魂武「爱之法庭」将被作为特殊裁决手段启动。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "天平的一侧摆满了黄金与殷红的玫瑰，而另一侧则空空如也。被裁决者或哀痛，或哭喊，抑或无动于衷……但是会议并不能直接带来什么，尤斯蒂娅也记不清自己多少次在使用过爱之法庭后依然要做出最终的审判，或许人类本身就是这么淡漠的生物呢。",
		file_3 = "因为尤斯蒂娅对爱之法庭的约束，使其作用仅限于司法场景，但该魂武的本质属于精神干涉武器，理论上可对任何具备复杂情感记忆的生物目标生效。鉴于目前的局势越来越严峻，学院必须要做好最低限度的应对措施。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "爱之天平在通过诱发神经元的活跃，来刺激被裁决者陷入不设防的回忆之中。但这只是表象。如果在意志力层面被裁决者输给了尤斯蒂娅，则还会被她直接窥伺到那些回忆……从这个角度讲，她真是个危险的人物。",
		level_6 = 0,
		record = "绝版的言情小说是赠予尤斯蒂娅的最好礼物。"
	},
	[220720] = {
		soulid = 220720,
		valuation = "贝茵妮拥有与刺客身份不符的强悍正面作战能力，却又恪守猎手的谨慎原则。擅长利用地形进行长时间观察与布局，待猎物步入无可逃脱的罗网后才予以致命一击。其武器附带的神经毒素虽对高危目标效果有限，但在消耗战中颇具价值。",
		file_1 = "用动物来比喻贝茵妮，大概是蜘蛛、狞猫、鹰隼与毒蛇的混合体。她有着蜘蛛的蛰伏与织网耐心，狞猫玩弄猎物的恶劣习惯，鹰隼对制高点的执着，以及毒蛇般一击必杀的冷酷效率。然而这种“残忍”的背后，并非反社会人格或施虐倾向，而是一种近乎常识缺失的淡漠——她很难理解为什么会有人以战斗为乐，就像常人很难理解她为何能如此平静地等待猎物咽气。",
		level_3 = 0,
		level_4 = 0,
		resume = "贝茵妮出身于某个未被公开的地下杀手组织，自幼接受狩猎与肃清训练。她并非组织中最出色的刺客，却凭借怪力与野兽般的狩猎直觉摸索出了一套稳定的生存法则。某次任务失败后，组织派遣监督者对其执行灭口，她在濒死之际被魂器学院的外勤势力所救。鉴于其魂武适格性以及特殊的作战经验，学院将其收容并转入学员序列，接受正规化教育与训练。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "贝茵妮的作战方式源于她独特的狩猎美学。她习惯占据制高点或隐蔽角落，以近乎偏执的耐心观察目标的行动规律，编织一张涵盖猎物所有退路的巨网。只有在确认万无一失后，她才会现身。这种作风让她看起来心思缜密，但经过本人叙述学院发现，那并非源于天赋的精密计算，而是一个怪力少女在无数次生死边缘无意中摸索出的、仅能供她一人适用的土办法。",
		file_3 = "猎袭之影是一柄与她身形不相称的巨型镰刀，刃口渗出的神经毒素理论上足以放倒一头成年大象。但贝茵妮本人对毒素的实战效果并不抱期待——她面对的目标往往远超常规人类的耐受极限。她真正依赖的，是猎物在察觉中毒后逐渐蔓延的恐惧与自我怀疑。她并不享受鲜血与哀嚎，甚至对杀戮本身缺乏常人想象中的狂热；她只是觉得，如果猎物能自己放弃挣扎，便能最大限度地节省她的体能。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "任务失败后的灭口行动给贝茵妮留下了难以察觉的心理烙印。被曾经的归属抛弃并追杀，让她对任何组织都保持着一种本能的距离感。魂器学院是她第一个不需要担心背后刀刃的容身之所，但她尚未学会如何信任这种安全。她仍在用狩猎的直觉审视着周围的一切，只是如今那张巨网的尽头，不再通向死亡。",
		level_6 = 0,
		record = "她是不是朝着班长办公室的方向看上一整天了？"
	},
	[220820] = {
		soulid = 220820,
		valuation = "紫惜具备优异的空间封锁与中距离控制能力。她能同时操纵多组魂丝，在狭窄地形中制造近乎无法破解的绞杀阵，并以节刃完成牵引、卸力、缴械和斩击。她的正面爆发不算突出，但在行动中呈现出超越实力的战局影响力，适合担任伏击、护卫、追缉与撤离掩护任务。",
		file_1 = "紫惜的亲近方式带有强烈的占有欲。她会记住他人的脚步声、作息、常用路线和说话时的小动作，再用开玩笑的语气把这些观察说出来。这种近似于威胁的社交方式已在紫惜的认知中形成固化，“被记住”意味着“不会被遗弃”。她尚未完全领悟普通社交的距离感，因此需要明确、稳定且不带惩罚意味的边界引导。",
		level_3 = 0,
		level_4 = 0,
		resume = "紫惜出生于派森一个以绳术和机关术传家的旁支。家族曾负责为当地防线制作魂能索具，却在一次据点清洗中被迫转入地下。年幼的紫惜被训练成“结师”，负责用魂丝捕获逃亡者、封锁门径、回收失控魂器。由于她对命令表现出异常顺从，长期被当作不会反抗的工具使用。一次回收任务中，紫惜故意放走目标并割断了象征家族束缚的主绳。学院外勤队在追踪失控魂能反应时发现她，并将其带离派森。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "螭节绞煞的魂丝并非单纯武器，而是紫惜用来感知世界的外延媒介。凭借于此，她能通过丝线的状态判断敌人的动向——即使是背后也一样。她会先投出数枚节刃作为锚点，再将魂丝藏入阴影、缝隙或队友行动路线后方。阵型完成后，紫惜只需轻轻收指，就能让敌人的冲锋变成自投罗网。",
		file_3 = "紫惜看似喜欢戏弄别人，其实对疼痛和束缚极为敏感。她能精准控制魂丝不伤及同伴，却很难忍受别人粗暴拉扯她亲手编好的结。学院心理评估认为，这与她早年制作索具的经历有关。松散与过紧都让她喘不过气，因此态度总在亲近与逃开之间摇摆。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "加入学院后，紫惜第一次获得了可以自由解开的绳结。她仍会在夜里检查门窗，仍会把备用节刃藏在袖口，却开始尝试把魂丝用于战斗之外——例如那条未织完待送人的围巾。她还没有完全放下过去，但已经学会用丝线量体裁衣。",
		level_6 = 0,
		record = "她笑着问你能不能系一个“防丢绳结”，请务必谨慎回答。"
	},
	[220920] = {
		soulid = 220920,
		valuation = "柚铃具备优秀的高速机动与中近距离火力压制能力。魂武“跃电双铳”可将魂能转化为脉冲弹道，并通过辅机“铃子”完成锁定、校准与战场讯号转接。她的单点破甲能力不算顶尖，但反应速度、走位修正和连续射击稳定性突出，适合担任突击、牵制、护卫与移动火力支援任务。",
		file_1 = "柚铃习惯用活泼的语气掩盖紧张。她越是在任务前开玩笑，越说明她对此次任务的重视。这种重视往往会让她在实际作战中紧盯目标，而忽视队友的位置。学院建议在编队中为她配置明确的撤回信号，避免过度深入敌方阵地造成不必要的伤亡。",
		level_3 = 0,
		level_4 = 0,
		resume = "柚铃出生于巴哈姆特外围的轻型魂器维护站。她从小跟随工程班接触巡检无人机与魂能枪械，对机械的声音和电流波形极为敏感。一次防线演习中，维护站遭遇失控机械群突入，柚铃临时接入尚未定型的双铳魂器，用不完整的校准程序保护了避难通道。学院外勤队在回收战斗记录时注意到她与魂器的高适配反应，随后将她带回魂器学院接受正式训练。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "跃电双铳的核心并非单纯的双枪，而是枪体、魂能回路与辅机“铃子”组成的协同系统。双铳负责输出高频脉冲，铃子负责收集回波并实时修正弹道。当柚铃高速移动时，系统会在她脚步落点前预判下一次射击角度，使她能够在跳跃、侧翻和换位中保持连续命中。",
		file_3 = "柚铃对“故障音”非常敏感。普通人听不出的电流杂音会让她立刻停下交谈，转而检查附近设备。测试显示她本人也具备异常细致的听觉辨识能力，若设备在她面前损坏，她会表现出明显焦躁，并倾向于独自修复。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "加入学院后，柚铃拥有了完整的战斗校准与同伴支援体系。铃子不再提醒队友距离较远，取而代之的是班长冷静的指挥，与同伴们并肩作战的身影。但战场最危险的地方，柚铃的身影一定会出现，甚至快过电磁的噼啪声。",
		level_6 = 0,
		record = "辅机已更新，标识班长为柚黄色。"
	},
	[221020] = {
		soulid = 221020,
		valuation = "茂生秘典不仅可以使其中封存的植物以肉眼可见的速度生长，更能赋予使用者与植物沟通的能力。被催生的植物将成为使魔，那些粗壮的藤蔓令行禁止，令使用者兼具攻防一体的战力。",
		file_1 = "芙洛莉丝的耐心源于植物自身的漫长生长周期，即使有了茂生魔典后，她也不会强行加快其生长。她会等待种子发芽、等待病叶恢复，也会等待他人把话说完。正因如此，她在安抚受惊植物和受伤同伴时都显得格外可靠。",
		level_3 = 0,
		level_4 = 0,
		resume = "芙洛莉丝来自尼德霍格，自幼便表现出异于常人的植物亲和力。进入魂器学院后，她被安排协助管理温室花园，并参与濒危植物的保护与记录工作。由于年龄尚小，学院通常不让她执行高危外勤任务，而是作为相关方面的专家来研究那些灾变后的变异植物。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "芙洛莉丝珍惜每一株植物，有时甚至会在战斗中因此犹豫。即便明知藤蔓可以阻挡敌人，她也会担心过度催生会伤到植物本身。",
		file_3 = "芙洛莉丝很信任班长。如果班长在身边，她愿意把秘典翻到还没有完成的那一页，也愿意说明自己真正担心的事情。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "茂生秘典中封存的种子并不只是武器素材，也是芙洛莉丝长期试图构建的植物图鉴库。当她情绪不稳时，藤蔓会比平时蔓延得更快；当她冷静下来，植物也会重新变得柔软而有秩序。",
		level_6 = 0,
		record = "温室借阅记录显示，芙洛莉丝经常把植物图鉴、标本夹和甜点食谱一起借走。话说温室里为什么会有甜点食谱？"
	},
	[221220] = {
		soulid = 221220,
		valuation = "根据边境村庄村民的反馈，小红帽是一位深受大家赞不绝口的可爱女孩。虽然外表看起来柔弱无害，但她体内流淌着霍普一族的血脉，具备极强的净化魔法天赋。在面对黑森林的复杂危机和未知魔物时，她展现出了超越常人的战斗智慧、勇气与冒险精神，绝非普通的边境少女。",
		file_1 = "在边境村庄的大众视野里，小红帽是个可爱、热情且总是带着欢声笑语的女孩。她日常乐于助人，对村里人赞不绝口，深受大家的喜爱。她的生活轨迹简单，每日与外婆相依为命。然而，她也对冒险有着浓厚的兴趣，日常行为中隐隐透露出不凡的智慧和远超同龄人的胆识，是个内心强大的少女。",
		level_3 = 0,
		level_4 = 0,
		resume = "在一个月圆之夜，小红帽为了寻找失踪的外婆，毅然踏上了前往黑森林的冒险旅途，在得知魂器学院拥有强大的情报网络、丰富的异能记录以及一流的魂器训练设施后，她以特招生的身份正式入学。她希望在这里磨炼自己的追踪与潜行技巧，在变强的同时，借助学院的力量追寻外婆的线索。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "小红帽在“潜行与追踪”专业课上表现极其惊艳，几乎从不缺勤。课余时间，她最喜欢待在学院的公共厨房里研究甜点。虽然外表看起来有些清冷和警惕，但只要有人夸奖她的苹果派，她就会露出属于这个年纪的温和笑容。",
		file_3 = "小红帽有着令人心疼的童年经历。她属于霍普一族，因母亲发现了教会在黑森林中进行残酷实验的阴谋，母亲惨遭教会迫害。外婆只得带着年幼的小红帽和黑天鹅在月圆之夜开始逃亡。直到小红帽长大到能够独自生活，外婆才选择独自去为女儿复仇，这使得小红帽被迫卷入这一场宿命的寻亲旅程。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "冒险的最后，小红帽得知了母亲被害的真相，但黑森林的污染在此刻爆发。一直暗恋小红帽的小木匠为了拯救她而不幸失踪。为了得知小木匠的下落并拯救他，小红帽决定在愿望之夜前往神秘的山洞，试图通过许愿来获取线索。这处神秘的山洞与黑森林的污染源头，正指向世界最深处的秘密…",
		level_6 = 0,
		record = "小红帽随身携带的“怀表”似乎承载着霍普一族特有的净化魔法，在净化污染时有奇效。"
	},
	[221320] = {
		soulid = 221320,
		valuation = "作为镜中的记忆模式的主宰者，镜子魔女拥有极强且诡异的“镜像之力”。她精通魔药学，能够利用坩埚调配出提取记忆的禁忌魔药。学院评估其战斗力与精神威胁等级极高，她能够轻易将敌人拖入镜中世界并进行精神与记忆层面的剥夺，是一位极其危险的魔法掌控者。",
		file_1 = "在外界的大众视野中，镜子魔女是一个冷酷无情、没有人类情感的邪恶存在。她日常隐匿于镜技场中，通过建立残酷的规则收集棋手们的记忆。她极度享受人们面对镜子自我审视时滋生的怨言和悲伤情绪，日常行为模式多表现为对着坩埚研究各种新奇且危险的魔药，冷漠地观察着诱饵们。",
		level_3 = 0,
		level_4 = 0,
		resume = "镜子魔女对真理与魔法的极致有着近乎偏执的追求。魂器学院那浩瀚的藏书库，以及关于魂器与精神共鸣的尖端学术课题深深地吸引了她。为了能够自由使用学院的高阶实验室，并与同龄的优秀法师交流，她欣然接受了学院的邀请，成为其中的一员。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "人们面对镜子时的怨言滋生了镜子魔女，魔女没有人类的情感，直到一位阳光自信的男孩发现了她，他们相爱了，生下了儿子米偌。由于丘比特的失误，米偌的爱人另嫁他人。镜子魔女不忍看到失去爱情的儿子日渐消瘦，便用魔法抽走了儿子所有的记忆。米偌确实不再悲伤了，他变成了一座没有感情的石像。为了拯救化为石像的儿子米偌，镜子魔女决定诱骗人类进入镜中世界，以便她来抽取这些诱饵们的鲜活记忆填补米偌空虚的心。她建立了镜技场，收集棋手们的记忆......",
		file_3 = "无论镜子魔女如何调配比例，几次记忆的注入均以失败告终，米偌仍是那具沉默的石像。累积的失望悔恨还有思念终于在此刻爆发了，桌上的器具被镜子魔女一并挥袖扫落，暴雨般砸向地面。其中一瓶还未调配的记忆滚至墙角，应声破碎，淡蓝色的记忆蜿蜒着浸湿了一旁端坐的木偶。“您好？”被记忆濡湿的木偶不知怎的拥有了生命，笨拙地向镜子魔女打了个招呼。它有些迷糊地环顾四周，尝试起身。然而随着身体表面记忆的迅速干涸，它又恢复成一具没有生命的木偶。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "镜子魔女爱怜的拿起木偶看了又看，这短暂获得生命的，儿子米偌亲手制作的木偶竟奇异地带给了她一丝安慰。她想起米偌还是孩子的时候，常常会举着玩偶和自己说话，他假装自己就是他们。想到这里，镜子魔女起身走向米偌的房间，那里还存放着许多米偌亲手制作的木偶。在找到唤醒米偌的方法之前，或许她可以通过这些木偶暂时的缓解思念的苦涩。",
		level_6 = 0,
		record = "绝对、绝对不要触碰她宿舍里的那些手工木偶！更不要直视她的镜子超过三秒，否则你可能会忘记自己是谁。"
	},
	[221420] = {
		soulid = 221420,
		valuation = "皇后伊缇露丝拥有夜莺一族的优雅和极高的战场统治力。然而，她的精神状态存在较大波动，其力量源泉和战斗意志高度绑定于对国王弥达斯的执念，是一位需要谨慎引导的高傲战力。",
		file_1 = "在大众视野里，伊缇露丝始终保持着高傲冷艳的皇后姿态。她在学院里习惯用命令的口吻与人交谈，日常热衷于要求学院提供最奢华的红茶与点心，并对礼仪有着近乎苛刻的要求。这种充满上位者威压的行为模式，让不少学员对她望而生畏。",
		level_3 = 0,
		level_4 = 0,
		resume = "为了获得人类的身体，伊缇露丝与洞穴怪物做交易，用纯粹的魔法力量换取了人形，并如愿成为弥达斯的皇后。由于时空乱流的席卷，她所在的童话王国发生了剧变。在寻找失散国王的过程中，傲慢的皇后为了借助学院庞大的情报网，不得不以屈尊的姿态加入了组织，成为高贵的战力。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "她极其在意皇室的威严。若能够以正式的臣属礼仪向其觐见，或主动协助她搜集关于失散国王弥达斯的情报，这位高傲的皇后虽然表面依然冷酷，内心却会极为认可和赞赏。",
		file_3 = "伊缇露丝的过去交织着牺牲与禁锢。她曾是魔法世界的夜莺，能够消耗羽毛用歌声治愈伤痛。因悲悯暴虐国王弥达斯并为其歌唱，却被其因执念而囚禁于纯金鸟笼中。令人难以置信的是，她竟然不可救药地在歌唱中爱上了囚禁她的国王。为了获得能够拥抱他的肉身，她甚至不惜舍弃了所有纯粹魔法。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "伊缇露丝化人形后虽得偿所愿，但其力量已发生了质变。她的核心目的是通过组织的力量重新找到国王弥达斯，并永恒地守护他。她与洞穴怪物的未完交易、以及夜莺一族被消耗的宿命，仍是她身上未解的伏笔。她正试图在异变中，为她与国王弥达斯寻找一个真正摆脱囚笼的完美结局。",
		level_6 = 0,
		record = "皇后殿下自尊心极强，在与其交流时，请务必保持适当的礼貌与尊重，绝对不要用命令的口吻。如果她在自言自语中提到“弥达斯”，请勿轻易打扰。"
	},
	[221520] = {
		soulid = 221520,
		valuation = "爱丽丝虽然看起来是一个柔弱、调皮的小女孩，但学院对其评估等级极高。她拥有从月之神殿窃取的红色月亮，掌握了极其罕见的穿越时空之力。但其体内潜藏的血月诅咒，随时有失控风险，必须进行严密监测。",
		file_1 = "在日常生活中，爱丽丝展现出大众视野里典型的小恶魔形象：调皮、任性、热爱各种恶作剧…这个描述似乎也能套用在另一位鲁比特家族大小姐身上，不禁让人怀疑，是不是爱丽丝这个名字有什么魔力？",
		level_3 = 0,
		level_4 = 0,
		resume = "由于窃取了禁忌的月亮，爱丽丝遭到几乎所有时空的古老月神的联合追捕。在血月即将升起的危急关头，为了躲避月神并寻找保守秘密的伙伴，她跨越时空裂缝降临到了学院。本着协助其压制血月诅咒以及研究时空魔法的共同目的，学院将其收容并允许她以合作成员的身份留住。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "对于亲近的伙伴，爱丽丝会展现出极度的信任和占有欲，甚至会主动展示她引以为傲的“宝物”——那枚禁忌的红月，并调皮地声称这是“共同的秘密”。然而，她那只兔子玩偶似乎有着不为人知的秘密，爱丽丝经常会跟玩偶进行极其拟人化的对话，甚至会因为玩偶的一句话而改变决定。",
		file_3 = "爱丽丝任性性格的背后，是一段荒诞而危险的童年往事。她曾天真地发问“为什么月亮不能只属于我”，并在会说话的兔子玩偶的纵容下，设法从月之神殿窃取了那枚禁忌的红色月亮。虽然这赋予了她穿梭时空的上古伟力，但也让她幼小的身躯沦为了盛装血月诅咒的容器，承受着常人无法想象的痛苦。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "每当血月升起，古老的月神就会强行控制爱丽丝的身体。“现在，几乎所有时空的月神都来到了这个世界，来寻找这枚失窃的月亮！我希望你能替我保守这个秘密。”女孩朝你调皮地眨了眨眼睛，“毕竟，血月马上就要升起来了……”",
		level_6 = 0,
		record = "如果发现学院里的时钟突然倒转，或者食堂的包子变成了炸弹，不用怀疑，多半是爱丽丝的得意之作。"
	},
	[221620] = {
		soulid = 221620,
		valuation = "美人鱼爱丽儿拥有极其惊人的声音亲和力，其“人鱼之歌”是海洋赐予人鱼的伟大礼物。学院测定，她的歌声具有极其强大的精神共鸣与辅助治愈能力。但在温和的表象下，由于其灵魂深处残留着永恒梦境重启的悲伤与愤怒，她在激发深海大合唱时，会展现出令敌人胆寒的海洋潮汐毁灭之力。",
		file_1 = "在日常的大众视野中，爱丽儿展现出对陆地生活极高的新奇与渴望。她日常喜欢观察陆地上的一切，比如微风、花草等与海底截然不同的风光，坚信陆地上的人类大多“善良又温柔”。她性格极其温柔温顺，喜欢静静地歌唱，用姐姐教给她的古老歌谣为同伴们带去心灵上的安宁与慰藉。",
		level_3 = 0,
		level_4 = 0,
		resume = "怀揣着对陆地世界以及青春校园生活的向往，美人鱼爱丽儿决定暂时离开深海。她希望用自己那具有治愈魔力的歌声，为并肩作战的同学们抚平伤痛、带来勇气，同时也想在这里好好体验一次期待已久的校园青春。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "美人鱼同学的治愈歌声让医疗室的工作量减少了将近八成。不过，鉴于她在学院训练3000米跑中因为不太习惯陆地，不小心摔倒了五次，体育组强烈建议她后续的训练课程调整为水上运动项目。",
		file_3 = "爱丽儿的背后是一段极其凄惨的悲剧。她曾天真地为了爱情，用自己的同理心向海洋女巫交换了双腿，却惨遭王子的背叛和杀害。而更深的创伤在于，当她无数次在梦境中醒来时，发现深爱她的姐姐艾丽娅为了替她复仇，不惜使用禁忌魔法将两人双双禁锢在由绝望和荆棘织成的复仇牢笼中。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "随着梦境第五次重启，爱丽儿终于拼凑出了惊人的真相：那个在梦境中微笑迎接王子的“自己”，其实只是姐姐用魔法凝聚在赴死瞬间的幻影。她的终极目的是唤醒并拯救彻底坠入复仇深渊的姐姐艾丽娅。她加入了学院，期望借由陆地的温暖与新力量，彻底打破永恒梦境，给姐姐一个真正的解脱。",
		level_6 = 0,
		record = "爱丽儿的歌声能调和同伴的情绪，但当她低吟歌谣时，表明其体内的悲伤正在泛滥。"
	},
	[221920] = {
		soulid = 221920,
		valuation = "华伞舞姬能把魂能铺成花瓣状伞幕，并用舞步让伞阵依次开合。展开的伞影可以削弱冲击，旋转的伞柄则会牵引来袭飞行物偏离队友。她的魂武更擅长控场与保护，只有在队伍跟上节拍时，伞阵才能发挥完整的力量。",
		file_1 = "艾莉西亚喜欢站在舞台中央，她用精心练习的笑容和从容的伞舞博取阵阵掌声。但只有在真正信任的人面前，才会承认自己也会害怕冷场。",
		level_3 = 0,
		level_4 = 0,
		resume = "幼年在灾变后的临时剧场学习伞舞。一次演出遭到袭击，她以礼仪伞护住观众并觉醒魂能，进入魂器学院后与魂武华伞舞姬建立连接。她接受魂能控制、阵型掩护和污染环境适应训练，负责为队友创造安全的输出环境。",
		level_1 = 0,
		level_5 = 0,
		file_2 = "华伞舞姬会放大使用者对观众的感知。艾莉西亚越在意他人的目光，伞阵就越容易追逐每一个人的位置，消耗魂能并变得难以控制。她需要学习的不是更完美的舞步，而是在失误后坦然面对的勇气。",
		file_3 = "她曾在一次训练中为了维持漂亮的连续旋转，错过了队伍发出的撤退信号。虽然没有人受伤，她却把那套舞服收进柜子里再也没穿过。",
		level_7 = 0,
		level_2 = 0,
		file_4 = "“石桥南北路，行客湿沾衣。借得油纸伞，遮却雨霏霏。”艾莉西亚正是如此会不惜余力地为队友遮风挡雨的人。",
		level_6 = 0,
		record = "艾莉西亚的训练记录里有一项特殊备注：每次演练结束，她都会先确认自己有没有弄乱发饰。"
	}
}
